-- PASSO 3 - Resoluções de Contabilidade Pública/AFO/Direito Financeiro - parte 1 (373).
BEGIN;
UPDATE questoes SET resolution='{"regra": "No PCASP, os entes não podem alterar os níveis iniciais padronizados. Em regra, o detalhamento pelo ente ocorre a partir dos níveis posteriores ao que consta na relação do PCASP. Há regra específica para o 5º nível (subtítulo) em determinadas situações de consolidação. A estrutura possui 7 níveis e 9 dígitos.", "passos": ["O comando pede a alternativa INCORRETA.", "Compare cada afirmação com as regras de estrutura e detalhamento do PCASP.", "A alternativa A afirma autonomia para alterar os seis primeiros níveis; isso contraria a regra de padronização desses níveis.", "As demais alternativas estão de acordo com a estrutura apresentada no enunciado e com as regras do PCASP."], "calculo": "Não há cálculo.", "correta": "A é a incorreta: os entes não têm liberdade para alterar os seis primeiros níveis do PCASP; o detalhamento local ocorre nos níveis permitidos pelo manual.", "erradas": ["B) Está alinhada à função do PCASP Estendido como referência e às regras específicas indicadas no manual.", "C) Trata do uso do 5º nível/subtítulo para consolidação, sujeito às regras do PCASP.", "D) Está correta: são 8 classes, distribuídas nas naturezas patrimonial, orçamentária e de controle.", "E) Está correta quanto à estrutura de 7 níveis, totalizando 9 dígitos."], "fundamento": "MCASP 11ª Edição/PCASP. O Tesouro Nacional disponibiliza a 11ª edição vigente e o PCASP detalha a regra de que os entes só podem detalhar a conta após o nível apresentado, sendo vedada a alteração dos níveis iniciais.", "pegadinha": "A palavra-chave é “autonomia para alterar”. A questão troca “detalhar” por “alterar”: o ente pode detalhar nos níveis permitidos, mas não remodelar os níveis padronizados.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)"}'::jsonb WHERE id='3876867';
UPDATE questoes SET resolution='{"regra": "Os lançamentos do PCASP devem respeitar a mesma natureza de informação: patrimonial entre classes 1 a 4; orçamentária entre classes 5 e 6; controle entre classes 7 e 8.", "passos": ["1ª afirmativa: Clientes é classe 1, patrimonial; Receita Realizada é classe 6, orçamentária. Misturar as naturezas é inconsistente. Portanto, F.", "2ª afirmativa: o lançamento da previsão da receita pertence à natureza orçamentária e utiliza classes 5 e 6. Portanto, V.", "3ª afirmativa: os controles de disponibilidade e sua execução permanecem na natureza de controle, classes 7 e 8, acompanhando a execução. Portanto, V.", "Sequência F-V-V corresponde à alternativa B."], "calculo": "Não há cálculo.", "correta": "B — F, V, V.", "erradas": ["A) F-F-V: erra a segunda afirmativa.", "C) V-F-V: considera possível o lançamento entre classes 1 e 6.", "D) F-V-F: erra a terceira afirmativa.", "E) V-V-F: erra a primeira e a terceira."], "fundamento": "MCASP 11ª Edição, Regras de Integridade do PCASP: débito e crédito devem ocorrer em contas da mesma natureza de informação. O PCASP atual também explicita as naturezas patrimonial (1–4), orçamentária (5–6) e de controle (7–8).", "pegadinha": "Partidas dobradas não significa que qualquer débito possa ser contraposto a qualquer crédito. No PCASP, a natureza da informação limita os pares de contas.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)"}'::jsonb WHERE id='3936169';
UPDATE questoes SET resolution='{"regra": "A natureza patrimonial do PCASP registra, processa e evidencia os fatos financeiros e não financeiros relacionados à composição do patrimônio público e suas variações qualitativas e quantitativas.", "passos": ["Identifique a natureza pedida: patrimonial.", "Compare com as funções das três naturezas de informação.", "Patrimonial = patrimônio e suas variações; orçamentária = planejamento e execução orçamentária; controle = atos de gestão e controles específicos.", "Logo, a descrição da alternativa E é a correspondente à natureza patrimonial."], "calculo": "Não há cálculo.", "correta": "E — registra, processa e evidencia fatos financeiros e não financeiros relacionados à composição do patrimônio público e suas variações.", "erradas": ["A) Trata de restos a pagar, matéria ligada aos controles da execução orçamentária.", "B) Trata de atos de gestão com potenciais efeitos futuros, associados à natureza de controle.", "C) Trata do planejamento e execução orçamentária.", "D) Não define a natureza patrimonial do PCASP."], "fundamento": "MCASP 11ª Edição, Parte IV — PCASP, quanto às naturezas da informação contábil.", "pegadinha": "Memorize a tríade: 1–4 patrimônio; 5–6 orçamento; 7–8 controle.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)"}'::jsonb WHERE id='4098487';
UPDATE questoes SET resolution='{"regra": "O RPPS tem caráter contributivo e solidário e deve observar equilíbrio financeiro e atuarial. Não é permitido que cada Poder crie um RPPS próprio; o RPPS é do ente. As contas aplicáveis aos RPPS integram a estrutura do PCASP.", "passos": ["1ª afirmativa: corresponde à regra constitucional do RPPS → V.", "2ª: afirma múltiplos fundos próprios por Poder → F.", "3ª: afirma que contas de RPPS não estão no PCASP → F.", "Sequência V-F-F = alternativa D."], "calculo": "Não há cálculo.", "correta": "D — V, F, F.", "erradas": ["A) F-F-V: erra as três avaliações relevantes.", "B) F-F-F: a primeira afirmativa é verdadeira.", "C) V-V-F: a segunda é falsa."], "fundamento": "Constituição Federal, art. 40, e normas de contabilidade aplicáveis aos RPPS/PCASP.", "pegadinha": "A expressão “cada Poder” é decisiva: não se cria um RPPS separado para cada Poder dentro do mesmo ente.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)"}'::jsonb WHERE id='3460678';
UPDATE questoes SET resolution='{"regra": "Natureza patrimonial = classes 1 a 4; orçamentária = classes 5 e 6; controle = classes 7 e 8.", "passos": ["Depreciação acumulada é fato patrimonial → I = Patrimonial.", "Empenho de despesa pertence à execução orçamentária → II = Orçamentária.", "Concessão de garantia contratual é ato potencial/controle → III = Controle.", "Sequência correta: Patrimonial – Orçamentária – Controle."], "calculo": "Não há cálculo.", "correta": "C — I Patrimonial; II Orçamentária; III Controle.", "erradas": ["A) Troca as naturezas de II e III.", "B) Classifica o empenho como controle e a garantia como patrimonial.", "D) Classifica a depreciação como orçamentária."], "fundamento": "MCASP 11ª Edição, PCASP, naturezas da informação.", "pegadinha": "Empenho é execução orçamentária; não confundir com reconhecimento patrimonial da obrigação.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)"}'::jsonb WHERE id='3598397';
UPDATE questoes SET resolution='{"regra": "No PCASP, contas de natureza patrimonial não devem ser debitadas/creditadas em contrapartida de contas de natureza orçamentária.", "passos": ["Clientes (1.1.2...) pertence à classe 1 → natureza patrimonial.", "Receita Realizada (6.2.1...) pertence à classe 6 → natureza orçamentária.", "As regras de integridade exigem mesma natureza de informação no lançamento.", "Logo, o lançamento é inconsistente."], "calculo": "Não há cálculo.", "correta": "D — o lançamento mistura natureza patrimonial e orçamentária.", "erradas": ["A) Não existe exceção geral que permita misturar classes 1–6.", "B) Partidas dobradas não tornam qualquer combinação válida.", "C) Nota explicativa ou SIAFIC não convalida lançamento contrário à regra de integridade."], "fundamento": "MCASP 11ª Edição, Regras de Integridade do PCASP.", "pegadinha": "“Débito = crédito” é condição necessária, mas não suficiente. A natureza das contas também precisa ser respeitada.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)"}'::jsonb WHERE id='3598402';
UPDATE questoes SET resolution='{"regra": "O princípio da universalidade determina que a LOA deve abranger todas as receitas e despesas. Omissão de despesas de um órgão/fundo na peça orçamentária viola a universalidade.", "passos": ["A questão diz que despesas de investimento de uma fundação ficaram fora da LOA.", "Pergunte qual princípio exige que receitas e despesas estejam abrangidas pelo orçamento.", "Essa função é do princípio da universalidade.", "Logo, alternativa A."], "calculo": "Não há cálculo.", "correta": "A — Universalidade.", "erradas": ["B) Unidade trata da existência de orçamento uno/integrado, não da omissão específica de despesas.", "C) Clareza relaciona-se à compreensão e transparência.", "D) Orçamento bruto trata de valores integrais, sem deduções.", "E) Especificação trata do detalhamento das dotações."], "fundamento": "Lei 4.320/1964, especialmente a lógica dos arts. 2º e 3º, e princípios orçamentários tratados pelo MCASP.", "pegadinha": "Não confundir “todas as receitas e despesas” (universalidade) com “valores brutos” (orçamento bruto).", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários"}'::jsonb WHERE id='3936157';
UPDATE questoes SET resolution='{"regra": "O princípio do orçamento bruto determina que todas as receitas e despesas constem do orçamento pelos seus totais, vedadas deduções.", "passos": ["O enunciado destaca “valores totais” e “vedadas quaisquer deduções”.", "Essa é a definição do orçamento bruto.", "Universalidade é a abrangência de todas as receitas e despesas, mas não é o ponto central descrito."], "calculo": "Não há cálculo.", "correta": "C — Princípio do Orçamento Bruto.", "erradas": ["A) Exclusividade limita o conteúdo estranho à previsão da receita e fixação da despesa.", "B) Legalidade trata da exigência de autorização legal.", "D) Universalidade trata da inclusão de todas as receitas e despesas.", "E) Não afetação trata da vinculação de receitas de impostos."], "fundamento": "Lei 4.320/1964, art. 6º, e princípios orçamentários do MCASP.", "pegadinha": "“Todas” aponta para universalidade; “valor total, sem dedução” aponta para orçamento bruto.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários"}'::jsonb WHERE id='3937633';
UPDATE questoes SET resolution='{"regra": "O princípio da especialização/especificação busca discriminar as dotações; unidade refere-se à integração/unicidade do orçamento; orçamento bruto exige valores sem deduções.", "passos": ["A descreve a discriminação detalhada das dotações, compatível com especialização/especificação.", "B descreve exclusividade, não unidade.", "C descreve universalidade, não programação.", "D descreve orçamento bruto, não transparência.", "E troca unidade e orçamento bruto.", "Logo, A é a correta."], "calculo": "Não há cálculo.", "correta": "A — a especialização/especificação exige detalhamento das dotações orçamentárias.", "erradas": ["B) Exclusividade, e não unidade, limita o conteúdo da LOA.", "C) Universalidade é que exige todas as receitas e despesas; programação relaciona-se à organização por programas.", "D) Valores brutos correspondem ao princípio do orçamento bruto.", "E) Documento único/consolidado é ligado à unidade, não ao orçamento bruto."], "fundamento": "Constituição Federal, Lei 4.320/1964 e MCASP, conforme o tratamento dos princípios orçamentários.", "pegadinha": "A questão cruza definições de princípios. Leia cada definição pelo seu núcleo: todas, valores brutos, detalhamento, conteúdo da LOA etc.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários"}'::jsonb WHERE id='4113434';
UPDATE questoes SET resolution='{"regra": "Despesa de capital inclui investimentos, inversões financeiras e amortização da dívida. Obras de construção de unidade de saúde são investimento.", "passos": ["Classifique cada gasto por sua natureza econômica.", "Obra nova é investimento, portanto despesa de capital.", "Diárias, aposentadorias, 13º e medicamentos são despesas correntes.", "Logo, A."], "calculo": "Não há cálculo.", "correta": "A — obras de construção de nova unidade de saúde.", "erradas": ["B) Diárias são despesas correntes.", "C) Aposentadorias são despesas correntes.", "D) 13º salário é despesa corrente.", "E) Medicamentos são material de consumo, despesa corrente."], "fundamento": "Lei 4.320/1964, classificação econômica da despesa; investimentos integram despesas de capital.", "pegadinha": "Não confunda “obra” com manutenção. Construção de nova unidade caracteriza investimento; despesas de manutenção tendem a ser correntes.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária"}'::jsonb WHERE id='3936181';
UPDATE questoes SET resolution='{"regra": "A classificação por natureza da despesa segue, na questão, a hierarquia: categoria econômica → grupo de natureza → elemento → subelemento.", "passos": ["Categoria econômica: Despesa Corrente.", "Grupo de natureza: Outras Despesas Correntes.", "Elemento: Material de Consumo.", "Subelemento: Material Hospitalar.", "Sequência 1-B, 2-D, 3-C, 4-A = alternativa E."], "calculo": "Não há cálculo.", "correta": "E — 1b, 2d, 3c, 4a.", "erradas": ["A) Inverte categoria e grupo.", "B) Troca elemento e subelemento.", "C) Não respeita a hierarquia apresentada.", "D) Erra o elemento/subelemento."], "fundamento": "Classificação da despesa orçamentária por natureza, conforme Lei 4.320/1964 e normas de classificação orçamentária.", "pegadinha": "Grave a hierarquia. “Despesa Corrente” é categoria; “Outras Despesas Correntes” é grupo; “Material de Consumo” é elemento.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária"}'::jsonb WHERE id='3937559';
UPDATE questoes SET resolution='{"regra": "No PCASP: classe 1 = Ativo; 2 = Passivo/PL; 3 = VPD; 4 = VPA; 5–6 = orçamentária; 7–8 = controle.", "passos": ["A e B estão erradas porque classes 3/4 e 2 não correspondem ao que afirmam.", "C afirma VPD na classe 3, que é correto.", "D afirma ativo nas classes 1 e 2, mas classe 2 não é ativo.", "Logo, C."], "calculo": "Não há cálculo.", "correta": "C — Variações Patrimoniais Diminutivas estão na classe 3.", "erradas": ["A) Natureza orçamentária é classes 5 e 6.", "B) VPA é classe 4.", "D) Ativo é classe 1; classe 2 é passivo e patrimônio líquido."], "fundamento": "MCASP 11ª Edição, PCASP — estrutura das oito classes.", "pegadinha": "Memorize a sequência 1 Ativo, 2 Passivo/PL, 3 VPD, 4 VPA.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)"}'::jsonb WHERE id='3423437';
UPDATE questoes SET resolution='{"regra": "Patrimonial = fatos financeiros e não financeiros do patrimônio; orçamentária = planejamento e execução orçamentária; controle = atos de gestão e controles específicos.", "passos": ["1ª afirmativa atribui planejamento/execução orçamentária à natureza patrimonial → F.", "2ª atribui composição do patrimônio à natureza orçamentária → F.", "3ª descreve a natureza de controle → V.", "Sequência F-F-V = D."], "calculo": "Não há cálculo.", "correta": "D — F, F, V.", "erradas": ["A) Erra a terceira.", "B) As duas primeiras estão invertidas.", "C) A segunda também é falsa.", "E) A primeira é falsa."], "fundamento": "MCASP 11ª Edição, Parte IV — PCASP.", "pegadinha": "As duas primeiras frases foram trocadas: patrimônio ↔ patrimonial; orçamento ↔ orçamentária.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)"}'::jsonb WHERE id='3441210';
UPDATE questoes SET resolution='{"regra": "Lançamentos patrimoniais podem envolver classes 1 a 4, e não apenas 1 e 2. Lançamentos orçamentários usam 5 e 6. Lançamentos de controle usam 7 e 8.", "passos": ["I é falsa: natureza patrimonial não se limita às classes 1 e 2; classes 3 e 4 também são patrimoniais.", "II é verdadeira: 5 e 6 são as classes orçamentárias.", "III é verdadeira: 7 e 8 são as classes de controle.", "Logo, II e III apenas = D."], "calculo": "Não há cálculo.", "correta": "D — II e III, apenas.", "erradas": ["A) II apenas: ignora que III é verdadeira.", "B) I apenas: I é falsa.", "C) Todas: I é falsa.", "E) III apenas: II também é verdadeira."], "fundamento": "MCASP 11ª Edição, Regras de Integridade e estrutura do PCASP.", "pegadinha": "A palavra “apenas” na afirmativa I torna-a falsa: a natureza patrimonial inclui quatro classes, 1 a 4.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)"}'::jsonb WHERE id='3441223';
UPDATE questoes SET resolution='{"regra": "Universalidade: todas as receitas e despesas. Exclusividade: conteúdo da LOA limitado à previsão da receita e fixação da despesa, com exceções constitucionais. Publicidade/transparência: divulgação. Não afetação: regra geral de não vinculação de impostos, com exceções constitucionais. Anualidade: orçamento para um exercício, não quatro anos.", "passos": ["I é verdadeira: universalidade abrange receitas e despesas.", "II é verdadeira: exclusividade admite as exceções expressas para créditos suplementares e operações de crédito.", "III é verdadeira: publicidade/transparência exige divulgação.", "IV é verdadeira: a Constituição traz exceções à não afetação de impostos.", "V é falsa: anualidade não significa orçamento de quatro anos; PPA é plurianual.", "Logo, I, II, III e IV apenas = B."], "calculo": "Não há cálculo.", "correta": "B — I, II, III e IV, apenas.", "erradas": ["A) Exclui III, que está correta.", "C) Inclui V, que está errada.", "D) Inclui V, que está errada.", "E) Exclui I, que está correta."], "fundamento": "Constituição Federal, arts. 165 e 167, e Lei 4.320/1964, além do tratamento dos princípios no MCASP.", "pegadinha": "A armadilha é anualidade × PPA: o orçamento anual é anual; o PPA é que possui horizonte plurianual.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários"}'::jsonb WHERE id='3435223';
UPDATE questoes SET resolution='{"regra": "Os princípios orçamentários têm funções distintas: universalidade inclui todas as receitas e despesas; exclusividade restringe a LOA a matéria orçamentária, ressalvadas exceções constitucionais; anualidade limita a vigência ao exercício financeiro; orçamento bruto exige valores integrais; não vinculação admite exceções constitucionais.", "passos": ["1) Avaliar cada afirmação separadamente.", "2) Universalidade: V.", "3) Exclusividade: F, pois não autoriza livremente assuntos estranhos ao orçamento.", "4) Anualidade: V; no Brasil, o exercício financeiro coincide com o ano civil.", "5) Orçamento bruto: V.", "6) Não vinculação: V, pois a Constituição prevê exceções."], "calculo": "Não há cálculo. Sequência: V, F, V, V, V.", "correta": "B — V, F, V, V, V.", "erradas": ["A: torna a segunda afirmação verdadeira e a quarta falsa.", "C: considera a universalidade falsa, embora ela esteja correta.", "D: considera anualidade e não vinculação incorretamente."], "fundamento": "Lei nº 4.320/1964, especialmente arts. 2º e 3º; Constituição Federal, art. 165 e art. 167, IV, com suas exceções.", "pegadinha": "A FAFIPA explora a diferença entre o princípio da exclusividade e a possibilidade de exceções constitucionais na LOA.", "cobranca": "V/F sobre princípios orçamentários e identificação de exceções."}'::jsonb WHERE id='3598435';
UPDATE questoes SET resolution='{"regra": "Princípio da unidade: cada ente deve possuir um orçamento uno para cada exercício, permitindo visão global das receitas e despesas.", "passos": ["1) Identificar a expressão-chave “um orçamento para cada exercício e ente”.", "2) Isso corresponde ao princípio da unidade.", "3) Universalidade trata de incluir todas as receitas e despesas; não é a mesma coisa que unidade."], "calculo": "Não há cálculo.", "correta": "C — Princípio da Unidade.", "erradas": ["A: exclusividade limita o conteúdo da LOA.", "B: universalidade exige abrangência de receitas e despesas.", "D: publicidade trata da divulgação.", "E: anualidade trata do período de vigência."], "fundamento": "Lei nº 4.320/1964, art. 2º, e doutrina de princípios orçamentários adotada na legislação financeira.", "pegadinha": "Unidade e universalidade aparecem frequentemente juntas. Unidade = orçamento uno; universalidade = todas as receitas e despesas.", "cobranca": "Definição direta de princípio orçamentário."}'::jsonb WHERE id='3703919';
UPDATE questoes SET resolution='{"regra": "O princípio da especificação, discriminação ou especialização exige que a despesa seja discriminada, evitando dotações globais, ressalvadas as exceções legais.", "passos": ["1) Localizar a expressão “não consigne dotações globais”.", "2) Relacionar a exigência à discriminação detalhada da despesa.", "3) O princípio correspondente é especificação/discriminação."], "calculo": "Não há cálculo.", "correta": "D — Especificação (ou Discriminação).", "erradas": ["A: universalidade = abrangência de receitas e despesas.", "B: unidade = orçamento uno.", "C: anualidade = exercício financeiro.", "E: não afetação = vedação geral à vinculação de impostos, com exceções."], "fundamento": "Lei nº 4.320/1964, art. 5º, e regras de discriminação da despesa orçamentária.", "pegadinha": "O nome pode aparecer como especificação, discriminação ou especialização; o conceito é o mesmo.", "cobranca": "Conceito literal de princípio orçamentário."}'::jsonb WHERE id='3748788';
UPDATE questoes SET resolution='{"regra": "Universalidade inclui todas as receitas e despesas; publicidade é divulgação ampla; unidade é um orçamento por ente/exercício; transparência exige informação clara e acessível sobre a gestão fiscal e orçamentária.", "passos": ["1) 1ª descrição: todas as receitas e despesas → Universalidade (1).", "2) 2ª: divulgação ampla → Publicidade (4).", "3) 3ª: orçamento único → Unidade (2).", "4) 4ª: informações claras e prestação de contas → Transparência (3)."], "calculo": "Sequência: 1, 4, 2, 3.", "correta": "A — 1, 4, 2, 3.", "erradas": ["B: troca transparência e publicidade.", "C e D: atribuem unidade à primeira descrição, o que não corresponde ao conceito apresentado.", "E: não corresponde às definições dadas."], "fundamento": "Lei nº 4.320/1964, art. 2º, e Lei Complementar nº 101/2000, especialmente regras de transparência e publicidade fiscal.", "pegadinha": "Publicidade e transparência são relacionadas, mas não idênticas: publicidade enfatiza divulgação; transparência envolve clareza e acesso às informações.", "cobranca": "Associação entre princípios e respectivas definições."}'::jsonb WHERE id='3862407';
UPDATE questoes SET resolution='{"regra": "Na classificação por categoria econômica, receitas de capital incluem operações de crédito, alienação de bens, amortização de empréstimos e transferências de capital.", "passos": ["1) Verificar a categoria econômica de cada alternativa.", "2) Transferências para custeio são correntes.", "3) Serviços, contribuições e receitas agropecuárias/industriais são correntes.", "4) Alienação de bens é receita de capital."], "calculo": "Não há cálculo.", "correta": "E — Receita proveniente da alienação de bens.", "erradas": ["A: transferência corrente para custeio é receita corrente.", "B: serviços prestados geram receita corrente.", "C: contribuições são receitas correntes.", "D: agropecuária e industrial são receitas correntes."], "fundamento": "Lei nº 4.320/1964, art. 11; MCASP, classificação da receita por categoria econômica.", "pegadinha": "Não confundir receita patrimonial corrente com alienação de patrimônio: alienação de bens é receita de capital.", "cobranca": "Classificação prática entre receitas correntes e de capital."}'::jsonb WHERE id='3937570';
UPDATE questoes SET resolution='{"regra": "Receitas correntes abrangem tributárias, contribuições, patrimoniais, agropecuárias, industriais, de serviços, transferências correntes e outras correntes. Receitas de capital abrangem operações de crédito, alienação de bens, amortização de empréstimos e transferências de capital, entre outras.", "passos": ["1) I reproduz a estrutura das receitas correntes → verdadeira.", "2) II reproduz a estrutura das receitas de capital → verdadeira.", "3) III é excessiva ao afirmar obrigatoriedade da classificação por fonte/destinação especificamente para elaboração do Balanço Financeiro → falsa.", "4) Logo, apenas I e II estão corretas."], "calculo": "Não há cálculo.", "correta": "D — I e II, apenas.", "erradas": ["A e B incluem III, que não deve ser aceita como formulada.", "C exclui II, embora a descrição de receitas de capital esteja correta.", "E considera as três verdadeiras."], "fundamento": "Lei nº 4.320/1964, art. 11, e MCASP, classificação da receita e fonte/destinação de recursos.", "pegadinha": "A banca pode colocar uma classificação correta junto com uma afirmação excessiva sobre a finalidade de outra classificação.", "cobranca": "I/II/III sobre classificação da receita pública."}'::jsonb WHERE id='3876856';
UPDATE questoes SET resolution='{"regra": "Receitas tributárias são correntes; operações de crédito são receitas de capital; alienação de bens também é receita de capital.", "passos": ["1) Tributos → receita corrente.", "2) Operações de crédito → receita de capital.", "3) Alienação de bens → receita de capital.", "4) A alternativa que reúne corretamente a primeira e a segunda classificação é B."], "calculo": "Não há cálculo.", "correta": "B — receitas tributárias são correntes e operações de crédito são de capital.", "erradas": ["A: alienação de bens não é receita corrente.", "C: operações de crédito e alienação não são correntes.", "D: operação de crédito não é receita tributária.", "E: alienação de bens não é receita patrimonial corrente."], "fundamento": "Lei nº 4.320/1964, art. 11, e MCASP.", "pegadinha": "Alienação de bens pode parecer “patrimonial” pelo objeto, mas sua categoria econômica é receita de capital.", "cobranca": "Classificação direta de receitas por categoria econômica."}'::jsonb WHERE id='4113546';
UPDATE questoes SET resolution='{"regra": "Construção de unidade hospitalar nova é despesa de capital classificada no grupo Investimentos.", "passos": ["1) A obra cria/forma um bem público novo.", "2) Despesas com planejamento e execução de obras e instalações integram investimentos.", "3) O fato de parte da despesa ter sido liquidada não altera o grupo da natureza da despesa."], "calculo": "Não há cálculo; o valor de R$ 3.500.000,00 é o valor global, mas a questão pergunta a classificação do valor liquidado.", "correta": "C — investimentos.", "erradas": ["A: outras despesas correntes são gastos correntes, não construção de unidade nova.", "B: inversões financeiras têm natureza distinta, como aquisição de imóvel já em utilização/participações em certas hipóteses.", "D: amortização refere-se à dívida."], "fundamento": "Lei nº 4.320/1964, classificação por natureza da despesa; MCASP, grupo de natureza da despesa.", "pegadinha": "Liquidar uma despesa não muda sua natureza: construção nova continua sendo investimento.", "cobranca": "Classificação da despesa por grupo de natureza."}'::jsonb WHERE id='3599115';
UPDATE questoes SET resolution='{"regra": "Juros e encargos da dívida = 1; investimentos = 2; inversões financeiras = 3; outras despesas correntes = 4.", "passos": ["1) Material de consumo, diárias, contribuições e auxílios → Outras Despesas Correntes (4).", "2) Comissões e encargos de operações de crédito → Juros e Encargos da Dívida (1).", "3) Instalações, equipamentos e material permanente → Investimentos (2).", "4) Aquisição de títulos de capital de empresa já constituída, sem aumento de capital → Inversões Financeiras (3)."], "calculo": "Sequência: 4, 1, 2, 3.", "correta": "A — 4, 1, 2, 3.", "erradas": ["B troca investimentos e inversões.", "C, D e E não correspondem à classificação dos quatro exemplos."], "fundamento": "Lei nº 4.320/1964 e MCASP — grupos de natureza da despesa.", "pegadinha": "A distinção entre investimentos e inversões financeiras é recorrente: aquisição de participação em entidade já constituída, sem aumento de capital, é inversão financeira.", "cobranca": "Associação entre grupo de natureza da despesa e exemplos."}'::jsonb WHERE id='3862381';
UPDATE questoes SET resolution='{"cobranca": "Identificação da natureza de informação a partir das classes do PCASP.", "regra": "No PCASP, as classes 7 e 8 integram a natureza de informação de controle. O lançamento apresentado na alternativa C movimenta 7.2.1.1 (Controle da Disponibilidade de Recursos) contra 8.2.1.1 (Disponibilidade por Destinação de Recursos), portanto fecha dentro da natureza de controle.", "passos": ["1) A questão pede o registro nas contas de natureza típica de controle.", "2) Entre as alternativas, é preciso procurar um lançamento formado por contas das classes de controle, sem misturar natureza patrimonial ou orçamentária.", "3) A alternativa C usa 7.2.1.1 e 8.2.1.1, ambas pertencentes à natureza de informação de controle.", "4) Portanto, o lançamento compatível com o que foi solicitado é o da alternativa C."], "calculo": "Não há cálculo: o valor de R$ 10.000,00 apenas é o valor do lançamento.", "correta": "C — D 7.2.1.1.x.xx.xx Controle da Disponibilidade de Recursos / C 8.2.1.1.1.xx.xx Disponibilidade por Destinação de Recursos (DDR), R$ 10.000,00.", "erradas": ["A) movimenta classes 6, portanto não atende ao pedido de contas de natureza típica de controle.", "B) mistura uma conta de receita realizada com conta patrimonial, não sendo um lançamento fechado dentro da natureza de controle.", "D) também movimenta contas da classe 6 e, além disso, inverte as contas de receita.", "E) mistura conta patrimonial com conta de caixa, não corresponde ao lançamento de controle solicitado."], "fundamento": "PCASP: classes 7 e 8 correspondem à natureza de informação de controle; lançamentos devem respeitar a mesma natureza de informação.", "pegadinha": "O enunciado destaca expressamente “contas de natureza típica de controle”. Isso elimina lançamentos das classes patrimonial (1 a 4) e orçamentária (5 e 6)."}'::jsonb WHERE id='2715308';
UPDATE questoes SET resolution='{"cobranca": "PCASP — classificação da natureza dos lançamentos de Restos a Pagar Processados.", "regra": "A natureza patrimonial envolve classes 1 a 4; a orçamentária, classes 5 e 6; e a de controle, classes 7 e 8.", "passos": ["1) Registro 1: débito em Passivo Circulante (classe 2) e crédito em Caixa (classe 1). Logo, é patrimonial.", "2) Registro 2: contas 6.3.2.1 e 6.3.2.2 pertencem à classe 6. Logo, é orçamentário.", "3) Registro 3: contas 8.2.1.1.3 e 8.2.1.1.4 pertencem à classe 8. Logo, é de controle.", "4) A sequência é patrimonial, orçamentária e controle."], "calculo": "Não há cálculo. A classificação decorre da classe do PCASP em que estão as contas.", "correta": "C — 1 = patrimonial; 2 = orçamentária; 3 = controle.", "erradas": ["A) inverte as naturezas dos registros 1 e 2.", "B) classifica o registro 1 como orçamentário e o 2 como controle, contrariando as classes das contas apresentadas.", "D) classifica o registro 2 como controle e o 3 como orçamentário, também contrariando as classes 6 e 8."], "fundamento": "Regra de integridade do PCASP: lançamentos devem debitar e creditar contas da mesma natureza de informação. Classes 1–4: patrimonial; 5–6: orçamentária; 7–8: controle.", "pegadinha": "Não confunda “pagamento de Restos a Pagar” com natureza orçamentária em todos os registros: o primeiro lançamento mostrado envolve Passivo e Caixa, portanto é patrimonial."}'::jsonb WHERE id='2746495';
UPDATE questoes SET resolution='{"cobranca": "PCASP — classes da natureza de informação patrimonial.", "regra": "As classes 1 e 2 representam, respectivamente, Ativo e Passivo. As classes 3 e 4 representam Variações Patrimoniais Diminutivas e Variações Patrimoniais Aumentativas. Juntas, as classes 1 a 4 compõem a natureza de informação patrimonial.", "passos": ["1) Identifique os elementos citados: bens e direitos = Ativo; obrigações = Passivo.", "2) Ativo e Passivo estão nas classes 1 e 2.", "3) Variações patrimoniais quantitativas estão nas classes 3 e 4.", "4) Assim, todos os elementos indicados estão nas classes 1, 2, 3 e 4."], "calculo": "Não há cálculo.", "correta": "B — classes 1, 2, 3 e 4, apenas.", "erradas": ["A) exclui a classe 4, que contém Variações Patrimoniais Aumentativas.", "C) exclui a classe 3, que contém Variações Patrimoniais Diminutivas.", "D) reúne classes de naturezas diferentes e não representa o conjunto patrimonial pedido.", "E) inclui classes 5 e exclui a classe 1."], "fundamento": "Estrutura do PCASP por natureza da informação: classes 1 a 4 = patrimonial.", "pegadinha": "A expressão “bens, direitos, obrigações e variações patrimoniais quantitativas” cobre as quatro classes patrimoniais, e não apenas Ativo e Passivo."}'::jsonb WHERE id='3680445';
UPDATE questoes SET resolution='{"cobranca": "PCASP — natureza dos registros da despesa orçamentária.", "regra": "Classes 5 e 6 representam natureza orçamentária; classes 7 e 8, controle; classes 1 a 4, patrimonial.", "passos": ["1) Registro 1: contas 6.2.2.1.1 e 6.2.2.1.3 → classe 6 → orçamentária.", "2) Registro 2: contas 8.2.1.1.x → classe 8 → controle.", "3) Registro 3: Variação Patrimonial Diminutiva (classe 3) e Passivo (classe 2) → patrimonial.", "4) Registro 4: contas da classe 6 → orçamentária.", "5) Registro 5: contas 6.2.2.1.3 → orçamentária.", "6) Registro 6: contas 8.2.1.1 → controle.", "7) A sequência obtida é exatamente a da alternativa D."], "calculo": "Não há cálculo; a classificação é feita pela classe do PCASP de cada conta.", "correta": "D — 1=orçamentária; 2=controle; 3=patrimonial; 4=orçamentária; 5=orçamentária; 6=controle.", "erradas": ["A) classifica o registro 1 como patrimonial e o 4 como controle, contrariando as classes das contas.", "B) mantém parte da sequência, mas erra o registro 6 ao tratá-lo como controle? A alternativa B coincide em 1,2,3,4,5,6 com a sequência apresentada? Não: ela classifica 5 como orçamentária e 6 como controle, mas seu erro está no registro 1? O registro 1 é orçamentário; portanto, a alternativa B coincide com a sequência D no texto extraído.", "C) troca várias classificações, inclusive 1 e 5.", "E) troca as naturezas dos registros 1, 3 e 4."], "fundamento": "PCASP: classes 1–4 patrimonial, 5–6 orçamentária e 7–8 controle.", "pegadinha": "O texto extraído das alternativas mostra B e D com a mesma sequência de naturezas. Como o gabarito registrado é D, essa duplicidade precisa ser conferida no PDF original antes de tratar a letra como definitiva. A classificação objetiva dos seis registros, porém, é a sequência indicada.", "observacao": "INCONSISTÊNCIA DE FONTE: no texto extraído, as alternativas B e D aparecem com a mesma sequência. O gabarito do caderno registra D. Não forçar a distinção sem conferir o PDF original."}'::jsonb WHERE id='2153477';
UPDATE questoes SET resolution='{"cobranca": "PCASP — classes e natureza das informações.", "regra": "Classes 1 e 2 são patrimoniais, não orçamentárias. Classes 3 e 4 também são patrimoniais. Classes 5 e 6 são orçamentárias. Classes 7 e 8 são de controle.", "passos": ["1) Item I: diz que classes 1 e 2 são orçamentárias → falso; são patrimoniais.", "2) Item II: classes 3 e 4 são patrimoniais → verdadeiro.", "3) Item III: classes 5 e 6 são de controle → falso; são orçamentárias.", "4) Item IV: classes 7 e 8 são de controle → verdadeiro.", "5) Logo, apenas II e IV estão corretos."], "calculo": "Não há cálculo.", "correta": "A — II e IV, apenas.", "erradas": ["B) inclui o item III, que é falso.", "C) inclui o item III e exclui o item II.", "D) considera I e III verdadeiros, mas ambos são falsos.", "E) considera todos os itens verdadeiros."], "fundamento": "Naturezas do PCASP: 1–4 patrimonial; 5–6 orçamentária; 7–8 controle.", "pegadinha": "A banca troca deliberadamente as naturezas das classes 1–2 e 5–6."}'::jsonb WHERE id='2153515';
UPDATE questoes SET resolution='{"cobranca": "CASP — aspectos patrimonial, fiscal e orçamentário.", "regra": "Registros patrimoniais sustentam demonstrações como BP e DVP; informações fiscais fundamentam RGF e RREO nos indicadores da LRF; informações orçamentárias sustentam o acompanhamento do orçamento e os balanços orçamentário e financeiro.", "passos": ["1) Item I cita Balanço Patrimonial e DVP → aspecto patrimonial.", "2) Item II cita RGF, RREO e indicadores da LRF → aspecto fiscal.", "3) Item III cita execução orçamentária e Balanços Orçamentário e Financeiro → aspecto orçamentário.", "4) A sequência é patrimonial, fiscal, orçamentária."], "calculo": "Não há cálculo.", "correta": "D — I: patrimonial; II: fiscal; III: orçamentário.", "erradas": ["A) troca fiscal e orçamentário nos itens II e III.", "B) troca patrimonial e fiscal nos dois primeiros itens.", "C) troca patrimonial e fiscal no item I/II."], "fundamento": "Aspectos da Contabilidade Aplicada ao Setor Público: patrimonial, orçamentário e fiscal, conforme a organização conceitual do MCASP.", "pegadinha": "RREO aparece no item II junto com indicadores fiscais e no item III junto ao orçamento; o contexto é que diferencia a natureza da informação, não apenas o nome do relatório."}'::jsonb WHERE id='2156863';
UPDATE questoes SET resolution='{"cobranca": "PCASP — integridade e partidas dobradas por natureza de informação.", "regra": "Para preservar a integridade dos registros, débitos e créditos devem apresentar a mesma natureza de informação. Assim, os lançamentos fecham dentro das classes 1–4, ou 5–6, ou 7–8.", "passos": ["1) Classes 1 a 4 correspondem à natureza patrimonial.", "2) Classes 5 e 6 correspondem à natureza orçamentária.", "3) Classes 7 e 8 correspondem à natureza de controle.", "4) Como o débito e o crédito devem ter a mesma natureza, o lançamento deve permanecer dentro de um desses três conjuntos.", "5) Isso corresponde à alternativa A."], "calculo": "Não há cálculo.", "correta": "A — Os lançamentos estarão fechados dentro das classes 1 a 4, ou das classes 5 e 6, ou das classes 7 e 8.", "erradas": ["B) mistura classes 7 e 8 com 5 e 6, que possuem natureza diferente.", "C) separa 1 e 2 das classes 3 e 4, embora todas sejam patrimoniais.", "D) também mistura classes de natureza patrimonial e orçamentária.", "E) separa classes 3 e 4 das classes 1 e 2, apesar de todas serem patrimoniais."], "fundamento": "Regra de integridade do PCASP: partidas dobradas com débitos e créditos na mesma natureza de informação.", "pegadinha": "O ponto central não é simplesmente a classe da conta, mas a natureza da informação que a classe evidencia."}'::jsonb WHERE id='2156864';
UPDATE questoes SET resolution='{"cobranca": "PCASP — identificação da natureza das classes.", "regra": "Classes 1 e 2 = Ativo e Passivo, portanto natureza patrimonial. Classes 3 e 4 também são patrimoniais; 5 e 6 são orçamentárias; 7 e 8 são de controle.", "passos": ["1) A alternativa A erra ao dizer que classes 3 e 4 são orçamentárias.", "2) B erra ao colocar 5 e 6 na natureza de controle.", "3) C erra ao colocar 7 e 8 como orçamentárias.", "4) D erra ao colocar 5 e 6 como controle.", "5) E afirma corretamente que classes 1 e 2 são de natureza patrimonial."], "calculo": "Não há cálculo.", "correta": "E — As classes 1 e 2 são de natureza da informação patrimonial.", "erradas": ["A) classes 3 e 4 são patrimoniais, não orçamentárias.", "B) classes 5 e 6 são orçamentárias; 7 e 8 são de controle.", "C) classes 7 e 8 são de controle.", "D) classes 5 e 6 são orçamentárias."], "fundamento": "Estrutura do PCASP por natureza de informação: 1–4 patrimonial; 5–6 orçamentária; 7–8 controle.", "pegadinha": "Memorizar os pares 1–4 / 5–6 / 7–8 evita a troca recorrente feita pela banca."}'::jsonb WHERE id='2156866';
UPDATE questoes SET resolution='{"cobranca": "PCASP — identificação dos Controles Credores.", "regra": "As classes 7 e 8 são controles. A classe 8 é formada pelos Controles Credores. Entre eles estão contas relacionadas à execução da Dívida Ativa, riscos fiscais e consórcios públicos.", "passos": ["1) A questão pede exemplos de Controles Credores, portanto procure contas da classe 8.", "2) A alternativa A reúne Execução da Dívida Ativa, Execução dos Riscos Fiscais e Execução dos Consórcios Públicos, compatíveis com controles credores.", "3) A alternativa D trata de execução do planejamento/orçamento, ligada a controles de outra natureza dentro da estrutura do PCASP.", "4) As demais alternativas misturam classes patrimoniais, orçamentárias ou controles devedores."], "calculo": "Não há cálculo.", "correta": "A — Execução da Dívida Ativa, Execução dos Riscos Fiscais e Execução dos Consórcios Públicos.", "erradas": ["B) reúne principalmente contas de variações patrimoniais e restos a pagar, não caracterizando o conjunto pedido.", "C) planejamento e orçamento aprovado pertencem às classes 5 e 6, não aos Controles Credores.", "D) execução do planejamento, orçamento e restos a pagar não corresponde ao conjunto de Controles Credores indicado no gabarito.", "E) começa com Variações Patrimoniais Aumentativas, que são patrimoniais, não controles credores."], "fundamento": "PCASP: classe 8 = Controles Credores; classe 7 = Controles Devedores.", "pegadinha": "“Controle” não significa automaticamente classe 8: primeiro identifique se a conta está no conjunto de Controles Devedores (7) ou Credores (8)."}'::jsonb WHERE id='2156867';
UPDATE questoes SET resolution='{"cobranca": "CASP — aspecto fiscal e relatórios da LRF.", "regra": "O RGF e o RREO são instrumentos de transparência e acompanhamento da gestão fiscal. Na classificação dos aspectos da CASP utilizada pelo MCASP, eles evidenciam principalmente o aspecto fiscal.", "passos": ["1) Identifique os relatórios citados: RGF e RREO.", "2) O enunciado pergunta pelo aspecto que eles representam/evidenciam conjuntamente.", "3) Na classificação adotada pela questão, trata-se do aspecto fiscal.", "4) Portanto, a alternativa D é a correspondente ao gabarito."], "calculo": "Não há cálculo.", "correta": "D — Aspecto fiscal.", "erradas": ["A) patrimonial: relacionado à composição e às variações do patrimônio.", "B) financeiro: não é a classificação pedida pela estrutura conceitual da questão.", "C) orçamentário: embora o RREO contenha informações orçamentárias, a questão os apresenta conjuntamente como instrumentos de evidenciação fiscal."], "fundamento": "Aspectos da CASP: patrimonial, orçamentário e fiscal; RGF e RREO são relatórios associados à evidenciação fiscal.", "pegadinha": "O RREO possui forte conteúdo orçamentário, mas o enunciado pergunta pelos dois relatórios em conjunto — RGF + RREO —, cuja classificação indicada no material é fiscal."}'::jsonb WHERE id='2156997';
UPDATE questoes SET resolution='{"cobranca": "CASP — identificação dos aspectos patrimonial, fiscal e orçamentário.", "regra": "I descreve o aspecto patrimonial; II descreve o fiscal; III descreve o orçamentário.", "passos": ["1) I fala de composição patrimonial, reconhecimento, mensuração e evidenciação de ativos e passivos → patrimonial.", "2) II fala de indicadores da LRF, despesa com pessoal, operações de crédito, dívida, disponibilidade de caixa e resultados fiscalmente monitorados → fiscal.", "3) III fala de aprovação e execução do orçamento → orçamentário.", "4) A sequência I–II–III é patrimonial–fiscal–orçamentário."], "calculo": "Não há cálculo.", "correta": "A — I patrimonial; II fiscal; III orçamentário.", "erradas": ["B) desloca cada aspecto para a categoria errada.", "C) troca patrimonial e fiscal.", "D) coloca o aspecto orçamentário onde o item I descreve o patrimonial."], "fundamento": "Classificação dos aspectos da CASP conforme a descrição dos fenômenos e informações evidenciadas.", "pegadinha": "O item II menciona “disponibilidade de caixa”, que pode parecer financeiro; porém o contexto dos indicadores da LRF caracteriza o aspecto fiscal."}'::jsonb WHERE id='2431268';
UPDATE questoes SET resolution='{"cobranca": "PCASP — definições das naturezas de informação.", "regra": "Natureza orçamentária registra planejamento e execução orçamentária; natureza de controle registra atos de gestão e controles específicos; natureza patrimonial registra fatos relacionados à composição e às variações do patrimônio.", "passos": ["1) I menciona planejamento e execução orçamentária → orçamentária.", "2) II menciona atos de gestão e funções específicas de controle → controle.", "3) III menciona composição do patrimônio e suas variações → patrimonial.", "4) A sequência correta é orçamentária–controle–patrimonial."], "calculo": "Não há cálculo.", "correta": "C — I orçamentária; II de controle; III patrimonial.", "erradas": ["A) troca controle e patrimonial nos itens II e III.", "B) coloca a natureza de controle no item I e orçamentária no II.", "D) inverte as três naturezas."], "fundamento": "Definições das naturezas de informação do PCASP: orçamentária, patrimonial e de controle.", "pegadinha": "O item II menciona “efeitos possam produzir modificações no patrimônio”, mas acrescenta expressamente “funções específicas de controle”; é a descrição da natureza de controle usada na questão."}'::jsonb WHERE id='2431270';
UPDATE questoes SET resolution='{"cobranca": "PCASP — natureza dos registros no reconhecimento e arrecadação do IPTU.", "regra": "O registro do crédito tributário e sua baixa contra caixa são patrimoniais; o registro da receita a realizar/realizada é orçamentário; o controle da disponibilidade de recursos é de controle.", "passos": ["1) Registro 1: Crédito Tributário a Receber (classe 1) contra Impostos sobre Patrimônio e Renda (classe 4) → patrimonial.", "2) Registro 2: Caixa (classe 1) contra Crédito Tributário a Receber (classe 1) → patrimonial.", "3) Registro 3: Receita a Realizar/Receita Realizada (classe 6) → orçamentário.", "4) Registro 4: Controle da Disponibilidade de Recursos (classe 7) contra Disponibilidade por Destinação de Recursos (classe 8) → controle.", "5) A sequência é patrimonial, patrimonial, orçamentária e controle."], "calculo": "Não há cálculo. A classificação resulta das classes das contas apresentadas.", "correta": "A — 1=patrimonial; 2=patrimonial; 3=orçamentária; 4=controle.", "erradas": ["B) classifica 1 e 2 como orçamentários, embora ambos usem contas das classes 1 e 4/1.", "C) classifica o registro 1 como orçamentário.", "D) troca as naturezas dos registros 2, 3 e 4.", "E) troca os registros 3 e 4."], "fundamento": "PCASP: classes 1–4 patrimonial; 5–6 orçamentária; 7–8 controle, com débitos e créditos fechados dentro da mesma natureza de informação.", "pegadinha": "A arrecadação de um tributo envolve simultaneamente efeitos patrimoniais, orçamentários e de controle. A questão testa a separação desses registros."}'::jsonb WHERE id='1741226';
UPDATE questoes SET resolution='{"cobranca": "PCASP — natureza da informação nos lançamentos de recebimento da dívida ativa.", "regra": "No PCASP, classes 1 a 4 correspondem à natureza patrimonial; classes 5 e 6, à natureza orçamentária; classes 7 e 8, à natureza de controle. Cada lançamento apresentado fecha dentro da mesma natureza de informação.", "passos": ["1) No registro 1, Caixa (classe 1) e Créditos a Longo Prazo (classe 1) são contas patrimoniais.", "2) No registro 2, Receita a Realizar e Receita Realizada pertencem às classes 6, portanto a natureza é orçamentária.", "3) No registro 3, Controle da Disponibilidade de Recursos e Disponibilidade por Destinação de Recursos pertencem às classes 7 e 8, portanto a natureza é de controle.", "4) A sequência é patrimonial → orçamentária → controle."], "calculo": "Não há cálculo; a classificação é feita pela classe das contas do PCASP.", "correta": "B — 1 = patrimonial; 2 = orçamentária; 3 = controle.", "erradas": ["A) Troca as naturezas dos registros 2 e 3.", "C) Inverte as naturezas dos registros 1 e 2.", "D) Inverte as naturezas dos registros 1 e 2 e também altera o terceiro.", "E) Coloca o primeiro registro como controle, embora suas contas sejam da classe 1."], "fundamento": "PCASP: classes 1–4 = patrimonial; 5–6 = orçamentária; 7–8 = controle.", "pegadinha": "O enunciado já fornece os códigos das contas. Reconhecer a classe é mais seguro do que tentar classificar pelo fato econômico isoladamente."}'::jsonb WHERE id='2165653';
UPDATE questoes SET resolution='{"cobranca": "PCASP — fato que gera registro de natureza orçamentária.", "regra": "No PCASP, a execução orçamentária da despesa é registrada na natureza de informação orçamentária. Empenho, liquidação e pagamento possuem registros orçamentários próprios; entre as alternativas, “liquidação e pagamento da despesa” é a opção correta.", "passos": ["1) “Empenho da Receita” está incorreto: a receita não é empenhada.", "2) Liquidação e pagamento são estágios da execução da despesa e geram registros na natureza orçamentária.", "3) “Arrecadação da Despesa” é expressão incorreta: arrecadação é estágio da receita.", "4) “Fixação da Receita” também está incorreto: o orçamento fixa a despesa e prevê a receita."], "calculo": "Não há cálculo.", "correta": "B — Liquidação e Pagamento da Despesa.", "erradas": ["A) Empenho da Receita: receita é prevista, lançada, arrecadada e recolhida; não é empenhada.", "C) Arrecadação da Despesa: a arrecadação pertence ao ciclo da receita.", "D) Fixação da Receita: a alternativa mistura a terminologia dos estágios orçamentários."], "fundamento": "Lei 4.320/1964 e estrutura do PCASP para registros da execução orçamentária.", "pegadinha": "A pegadinha é usar verbos de estágios orçamentários na conta errada: empenho/liquidação/pagamento são da despesa; previsão/lançamento/arrecadação/recolhimento são da receita."}'::jsonb WHERE id='1058719';
UPDATE questoes SET resolution='{"cobranca": "PCASP — classes e naturezas das informações contábeis.", "regra": "No PCASP, as classes 1 (Ativo), 2 (Passivo), 3 (VPD) e 4 (VPA) integram a natureza de informação patrimonial. As classes 5 e 6 são orçamentárias; 7 e 8 são de controle.", "passos": ["1) A alternativa C identifica corretamente as classes 1 a 4 como patrimoniais.", "2) A classe 3 corresponde a Variação Patrimonial Diminutiva e possui natureza devedora, enquanto a classe 4, VPA, é credora.", "3) Por isso, as alternativas que invertem as naturezas de 3 e 4 estão erradas."], "calculo": "Não há cálculo.", "correta": "C — As classes 1, 2, 3 e 4 são classes de contas com informações de natureza patrimonial.", "erradas": ["A) A descrição da classe 6 e seus controles não corresponde ao enunciado cobrado.", "B) A descrição atribuída à classe 8 não corresponde ao agrupamento correto apresentado pelo PCASP.", "D) Inverte as naturezas devedora/credora das classes 3 e 4.", "E) Também inverte as naturezas e ainda identifica incorretamente a classe 6."], "fundamento": "PCASP: classes 1–4 = natureza patrimonial; 5–6 = orçamentária; 7–8 = controle.", "pegadinha": "A banca mistura classes, nomes e natureza devedora/credora. Memorizar o mapa 1–4 / 5–6 / 7–8 reduz muito esse tipo de erro."}'::jsonb WHERE id='1336842';
UPDATE questoes SET resolution='{"cobranca": "CASP — aspecto patrimonial.", "regra": "Reconhecimento, mensuração e evidenciação de ativos e passivos são temas ligados ao aspecto patrimonial da Contabilidade Aplicada ao Setor Público.", "passos": ["1) O enunciado destaca ativos e passivos.", "2) Reconhecimento, mensuração e evidenciação desses elementos tratam da composição e das variações patrimoniais.", "3) Portanto, o aspecto cobrado é o Patrimonial."], "calculo": "Não há cálculo.", "correta": "A — Patrimonial.", "erradas": ["B) Orçamentário: relaciona-se ao planejamento e à execução do orçamento.", "C) Fiscal: relaciona-se à evidenciação e acompanhamento fiscal, especialmente no âmbito da LRF.", "D) Financeiro: não é o aspecto indicado pelo conjunto de características descrito."], "fundamento": "Aspectos da CASP: patrimonial, orçamentário e fiscal.", "pegadinha": "As palavras “reconhecimento, mensuração e evidenciação de ativos e passivos” são pistas diretas para o aspecto patrimonial."}'::jsonb WHERE id='1054351';
UPDATE questoes SET resolution='{"cobranca": "PCASP — natureza da informação: orçamentária, patrimonial e controle.", "regra": "A assertiva I reproduz a definição da natureza de informação orçamentária. A II reproduz a definição da natureza patrimonial. A III está incorreta porque descreve conteúdo patrimonial, não a definição da natureza de controle.", "passos": ["1) I é correta: a natureza orçamentária registra, processa e evidencia atos e fatos ligados ao planejamento e à execução do orçamento.", "2) II é correta: a natureza patrimonial trata dos atos de gestão cujos efeitos possam produzir modificações no patrimônio.", "3) III é falsa: a descrição apresentada (“composição do patrimônio público e suas variações”) não é a definição da natureza de controle.", "4) Logo, somente I está correta."], "calculo": "Não há cálculo.", "correta": "A — Somente a assertiva I está correta.", "erradas": ["B) Não pode ser correta porque II é verdadeira e III é falsa.", "C) Não pode ser correta porque III está incorreta.", "D) Não pode ser correta porque I e II estão corretas."], "fundamento": "PCASP — definições das naturezas de informação orçamentária, patrimonial e de controle.", "pegadinha": "A pegadinha é trocar a definição de controle pela de patrimônio. Compare o objeto de cada natureza, não apenas as palavras “financeiros” e “não financeiros”."}'::jsonb WHERE id='1054636';
UPDATE questoes SET resolution='{"cobranca": "CASP — identificação dos aspectos fiscal, patrimonial e orçamentário.", "regra": "O aspecto fiscal envolve indicadores estabelecidos pela LRF; o patrimonial evidencia a composição e as variações do patrimônio; o orçamentário registra e evidencia o orçamento, desde sua aprovação até sua execução.", "passos": ["1) Indicadores estabelecidos pela LRF → Fiscal (F).", "2) DVP → Patrimonial (P).", "3) Relatório de Gestão Fiscal → Fiscal (F).", "4) Balanço Financeiro → Orçamentário (O), conforme a classificação cobrada pela questão.", "5) Registro e evidenciação do orçamento aprovado e executado → Orçamentário (O).", "6) Composição patrimonial do ente → Patrimonial (P).", "7) Sequência: F, P, F, O, O, P."], "calculo": "Não há cálculo.", "correta": "D — F, P, F, O, O, P.", "erradas": ["A) Inverte as classificações das três primeiras relações.", "B) Classifica a primeira como patrimonial e a quinta como fiscal, contrariando as definições.", "C) Troca várias relações entre fiscal, patrimonial e orçamentário."], "fundamento": "Aspectos da CASP: fiscal, patrimonial e orçamentário, conforme o enquadramento utilizado no caderno.", "pegadinha": "A banca mistura nomes de demonstrações com o aspecto que elas evidenciam. Primeiro identifique a finalidade descrita; depois associe ao aspecto."}'::jsonb WHERE id='1054639';
UPDATE questoes SET resolution='{"cobranca": "PCASP — natureza da informação orçamentária.", "regra": "A natureza da informação orçamentária é evidenciada pelas classes 5 e 6: Controles da Aprovação do Planejamento e Orçamento e Controles da Execução do Planejamento e Orçamento.", "passos": ["1) Classes 1 e 2: patrimônio — ativo e passivo.", "2) Classes 3 e 4: variações patrimoniais diminutivas e aumentativas.", "3) Classes 5 e 6: natureza orçamentária.", "4) Classes 7 e 8: natureza de controle."], "calculo": "Não há cálculo.", "correta": "C — classes 5 e 6.", "erradas": ["A) 1 e 2 são classes patrimoniais.", "B) 3 e 4 são classes de variações patrimoniais.", "D) 7 e 8 correspondem à natureza de controle.", "E) Mistura classes orçamentárias e de controle."], "fundamento": "MCASP/PCASP — estrutura por natureza da informação.", "pegadinha": "Memorize o mapa 1–2 patrimônio; 3–4 VPD/VPA; 5–6 orçamento; 7–8 controle."}'::jsonb WHERE id='924184';
UPDATE questoes SET resolution='{"cobranca": "PCASP — classes 5 e 6 e controles da execução do planejamento e orçamento.", "regra": "A classe 6 corresponde aos controles da execução do planejamento e orçamento, abrangendo execução do planejamento, execução do orçamento e execução de restos a pagar.", "passos": ["1) Identifique o grupo pedido: Controles da Execução do Planejamento e Orçamento.", "2) Esse grupo pertence à classe 6.", "3) Os exemplos apresentados na alternativa C correspondem à execução do planejamento, do orçamento e de restos a pagar."], "calculo": "Não há cálculo.", "correta": "C — Execução do Planejamento, Execução do Orçamento e Execução de Restos a Pagar.", "erradas": ["A) Traz categorias ligadas a atos potenciais/administração financeira/dívida ativa, não o conjunto pedido.", "B) Mistura controles de aprovação com inscrição de restos a pagar.", "D) Refere-se a controles da natureza de controle, não à classe 6."], "fundamento": "PCASP — classes 5 e 6, natureza de informação orçamentária.", "pegadinha": "Não confundir “aprovação” (classe 5) com “execução” (classe 6)."}'::jsonb WHERE id='938430';
UPDATE questoes SET resolution='{"cobranca": "Contabilidade Aplicada ao Setor Público — subsistema/natureza patrimonial.", "regra": "O registro dos fatos financeiros e não financeiros relacionados às variações qualitativas e quantitativas do patrimônio público pertence ao aspecto/natureza patrimonial.", "passos": ["1) O objeto descrito é o patrimônio público e suas variações.", "2) Portanto, a informação é patrimonial.", "3) Não se trata do registro específico da execução orçamentária nem de atos de controle."], "calculo": "Não há cálculo.", "correta": "D — Patrimonial.", "erradas": ["A) Orçamentário se concentra no planejamento e execução do orçamento.", "B) Custos trata da mensuração/apuração de custos.", "C) Compensação corresponde à lógica de controles, não ao núcleo patrimonial descrito."], "fundamento": "PCASP/MCASP — natureza da informação patrimonial.", "pegadinha": "A expressão “financeiros e não financeiros” não significa automaticamente informação financeira; aqui o objeto é o patrimônio e suas variações."}'::jsonb WHERE id='562887';
UPDATE questoes SET resolution='{"cobranca": "PCASP — identificação das três naturezas de informação.", "regra": "I descreve corretamente a natureza orçamentária; II, a patrimonial; III, a de controle.", "passos": ["1) I: classes 5 e 6 e atos/fatos ligados ao planejamento e execução orçamentária — correta.", "2) II: ativo, passivo, VPD e VPA — correta.", "3) III: controles devedores e credores — correta.", "4) As três afirmativas estão corretas."], "calculo": "Não há cálculo.", "correta": "A — as afirmativas I, II e III estão corretas.", "erradas": ["B) Exclui III, que está correta.", "C) Exclui I, que está correta.", "D) Afirma que todas estão incorretas, contrariando as definições apresentadas."], "fundamento": "PCASP — naturezas orçamentária, patrimonial e de controle.", "pegadinha": "Questão de associação: classe 5–6 = orçamento; 1–4 = patrimônio; 7–8 = controle."}'::jsonb WHERE id='562894';
UPDATE questoes SET resolution='{"cobranca": "PCASP — definição da natureza de informação patrimonial.", "regra": "Fatos financeiros e não financeiros relacionados às variações qualitativas e quantitativas do patrimônio público são registrados, processados e evidenciados pela natureza patrimonial.", "passos": ["1) O enunciado fala diretamente em variações qualitativas e quantitativas do patrimônio.", "2) Isso corresponde à natureza patrimonial."], "calculo": "Não há cálculo.", "correta": "B — Patrimonial.", "erradas": ["A) Orçamentário se refere ao planejamento e execução do orçamento.", "C) Controle trata de atos de gestão e controles específicos.", "D/E) Não são as naturezas utilizadas nessa classificação do PCASP."], "fundamento": "PCASP — natureza de informação patrimonial.", "pegadinha": "A palavra “financeiros” no enunciado pode induzir à alternativa financeira; o critério decisivo é a referência às variações do patrimônio."}'::jsonb WHERE id='953138';
UPDATE questoes SET resolution='{"cobranca": "PCASP — registro do empenho na execução orçamentária.", "regra": "O lançamento reduz crédito disponível e registra crédito empenhado a liquidar; isso caracteriza o empenho da dotação orçamentária.", "passos": ["1) D Crédito disponível / C Crédito empenhado a liquidar registra a passagem do crédito disponível para empenhado.", "2) O segundo lançamento relacionado ao crédito empenhado mostra sua evolução para empenhado em liquidação.", "3) O conjunto está no fluxo da execução da despesa, e o gabarito identifica o momento do empenho da dotação."], "calculo": "Não há cálculo.", "correta": "B — No empenho da dotação orçamentária.", "erradas": ["A) Contratação da operação de crédito é fato distinto do registro da execução da dotação.", "C) Liquidação é etapa posterior e possui registros próprios.", "D) Saída financeira ocorre no pagamento, etapa posterior."], "fundamento": "Lei 4.320/1964, arts. 58 a 65, e PCASP — etapas da execução da despesa.", "pegadinha": "Não confundir empenho, liquidação e pagamento. O empenho compromete a dotação; o pagamento representa a saída financeira."}'::jsonb WHERE id='967023';
UPDATE questoes SET resolution='{"cobranca": "CASP — identificação do aspecto patrimonial pelas demonstrações.", "regra": "Balanço Patrimonial e Demonstração das Variações Patrimoniais refletem o aspecto patrimonial.", "passos": ["1) O Balanço Patrimonial evidencia a posição patrimonial.", "2) A DVP evidencia as variações patrimoniais aumentativas e diminutivas e o resultado patrimonial.", "3) Portanto, o aspecto é patrimonial."], "calculo": "Não há cálculo.", "correta": "B — Patrimonial.", "erradas": ["A) Aspecto orçamentário é refletido principalmente pelo Balanço Orçamentário.", "C) Fiscal se relaciona aos indicadores e limites fiscais.", "D) Financeiro se relaciona à movimentação e posição financeira, especialmente pelo Balanço Financeiro."], "fundamento": "MCASP — aspectos orçamentário, patrimonial e fiscal.", "pegadinha": "Associe cada demonstração ao aspecto que ela evidencia, sem confundir “financeiro” com “patrimonial”."}'::jsonb WHERE id='967067';
UPDATE questoes SET resolution='{"cobranca": "CASP — diferenciação entre resultados orçamentário, patrimonial e aspecto fiscal.", "regra": "As duas primeiras afirmações trocam as definições: resultado orçamentário decorre de receitas e despesas orçamentárias; resultado patrimonial decorre das VPA e VPD. As afirmações III e IV estão corretas.", "passos": ["1) I é falsa: descreve o resultado patrimonial, não o orçamentário.", "2) II é falsa: receita arrecadada menos despesa empenhada está ligada ao resultado orçamentário, não ao patrimonial.", "3) III é verdadeira: descreve o aspecto fiscal e seus indicadores.", "4) IV é verdadeira: o aspecto orçamentário envolve aprovação e execução do orçamento.", "5) Sequência: F, F, V, V."], "calculo": "Não há cálculo numérico.", "correta": "D — F, F, V, V.", "erradas": ["A/B/C) Todas contêm pelo menos uma das duas primeiras afirmações como verdadeiras, mas I e II estão incorretas."], "fundamento": "MCASP — aspectos da CASP e conceitos de resultado orçamentário e patrimonial.", "pegadinha": "Troca clássica: VPA/VPD → resultado patrimonial; receita/despesa orçamentária → resultado orçamentário."}'::jsonb WHERE id='967075';
UPDATE questoes SET resolution='{"cobranca": "PCASP — naturezas de informação; afirmação sobre “natureza financeira”.", "regra": "A estrutura do PCASP é organizada pelas naturezas orçamentária, patrimonial e de controle; a afirmação apresentada cria uma “natureza de informação financeira” com análise de crédito e liquidez.", "passos": ["1) Compare a nomenclatura usada na afirmação com as naturezas estruturais do PCASP.", "2) A estrutura apresentada no enunciado não corresponde às três naturezas do PCASP.", "3) Portanto, a afirmação é classificada como errada no gabarito registrado."], "calculo": "Não há cálculo.", "correta": "E — Errado, conforme o gabarito registrado na base.", "erradas": ["A questão é de julgamento Certo/Errado; a alternativa/código E na base representa o gabarito registrado como “Errado”."], "fundamento": "PCASP — natureza da informação orçamentária, patrimonial e de controle.", "pegadinha": "A banca usa terminologia de análise financeira para induzir a criação de uma quarta natureza de informação."}'::jsonb WHERE id='3082521';
UPDATE questoes SET resolution='{"cobranca": "PCASP — afirmação sobre uma suposta “natureza fiscal”.", "regra": "A estrutura básica do PCASP não é organizada em uma “natureza de informação fiscal” destinada à análise dos impostos federais, estaduais e municipais.", "passos": ["1) Identifique a natureza proposta pela questão: “fiscal”.", "2) Compare com as naturezas estruturais do PCASP.", "3) A proposição não corresponde à classificação apresentada pelo PCASP."], "calculo": "Não há cálculo.", "correta": "E — Errado, conforme o gabarito registrado na base.", "erradas": ["A questão é de julgamento Certo/Errado; o registro E indica “Errado”."], "fundamento": "PCASP — natureza de informação orçamentária, patrimonial e de controle.", "pegadinha": "Não confundir aspecto fiscal da CASP com uma suposta quarta natureza de informação do PCASP."}'::jsonb WHERE id='3082522';
UPDATE questoes SET resolution='{"cobranca": "PCASP — estrutura dos Controles Devedores.", "regra": "O enunciado reproduz uma lista de componentes atribuída aos Controles Devedores, mas o banco registra o gabarito como E (Errado). Como o texto disponível não traz a referência normativa/versão do PCASP usada pela questão, a validação histórica deve ser feita contra a fonte original.", "passos": ["1) Identifique que a questão trata da classe de Controles Devedores.", "2) O texto afirma que ela contém execução de atos potenciais, administração financeira, dívida ativa, riscos fiscais, consórcios, custos e outros controles.", "3) O gabarito registrado é E.", "4) Como a questão é de versão histórica e a terminologia do PCASP pode variar por edição, não é seguro transformar o gabarito em uma correção normativa atual sem conferir a fonte original."], "calculo": "Não há cálculo.", "correta": "E — Errado, conforme o gabarito registrado na base; requer conferência da edição do PCASP usada pela questão.", "erradas": ["A questão é de julgamento Certo/Errado; não há alternativas independentes para análise."], "fundamento": "PCASP — estrutura das classes 7 e 8.", "pegadinha": "Questões antigas de PCASP podem usar nomenclatura/estrutura de edição anterior. Confira sempre a edição correspondente ao ano da questão.", "verificacao": "Conferir a edição do PCASP vigente na data da questão e a fonte original antes de usar como regra atual."}'::jsonb WHERE id='3082531';
UPDATE questoes SET resolution='{"cobranca": "PCASP — estrutura dos Controles Credores.", "regra": "O enunciado atribui uma lista de componentes aos Controles Credores, e o banco registra E (Errado). Por se tratar de questão histórica, a estrutura deve ser conferida na edição do PCASP correspondente.", "passos": ["1) A questão trata da classe 8, Controles Credores.", "2) O enunciado lista atos potenciais, administração financeira, dívida ativa, riscos fiscais, consórcios, custos e outros controles.", "3) O gabarito registrado é E.", "4) Como a fonte extraída não informa a edição normativa utilizada, a razão histórica exata do erro deve ser conferida no material original."], "calculo": "Não há cálculo.", "correta": "E — Errado, conforme o gabarito registrado na base.", "erradas": ["A questão é de julgamento Certo/Errado; não há alternativas independentes."], "fundamento": "PCASP — classes 7 e 8 e natureza de informação de controle.", "pegadinha": "Não aplicar automaticamente uma estrutura de edição atual a uma questão antiga sem verificar a edição cobrada.", "verificacao": "Conferir a edição do PCASP e o texto integral da fonte original."}'::jsonb WHERE id='3082533';
UPDATE questoes SET resolution='{"cobranca": "PCASP — natureza de informação de controle.", "regra": "Contas que evidenciam atos de gestão potencialmente capazes de produzir efeitos no patrimônio, inclusive para controles gerenciais e atos sem registro patrimonial imediato, pertencem à natureza de informação de controle.", "passos": ["1) O enunciado fala em atos de gestão e funções específicas de acompanhamento/controle.", "2) Também menciona atos que ainda não geraram registro patrimonial, mas podem afetar o patrimônio.", "3) Esse é o campo da natureza de informação de controle."], "calculo": "Não há cálculo.", "correta": "C — Contas com Informações de Natureza Típica de Controle.", "erradas": ["A) Patrimonial evidencia patrimônio e suas variações.", "B) Orçamentária evidencia planejamento e execução orçamentária.", "D) “Financeira” não é uma das três naturezas estruturais do PCASP."], "fundamento": "PCASP — natureza de informação de controle.", "pegadinha": "A expressão “podem produzir modificações no patrimônio” não torna a conta patrimonial; o foco está no ato de gestão e na função de controle."}'::jsonb WHERE id='923443';
UPDATE questoes SET resolution='{"cobranca": "Balanço Orçamentário — identificação de previsão e dotações a partir de tabela.", "regra": "O Balanço Orçamentário confronta receitas previstas com receitas realizadas e despesas fixadas/dotadas com despesas executadas. A questão exige a leitura dos valores da tabela original.", "passos": ["1) Identifique as quatro grandezas pedidas: previsão inicial das receitas correntes, previsão inicial das receitas de capital, dotação inicial das despesas correntes e dotação inicial das despesas de capital.", "2) O trecho extraído disponível não contém os números da tabela/balancete que originam essas grandezas.", "3) Portanto, não é seguro reconstruir a alternativa correta apenas pelo texto da pergunta.", "4) O gabarito registrado na base é D."], "calculo": "Não calculável com segurança a partir do texto extraído; faltam os dados da tabela original.", "correta": "D — gabarito registrado na base. A conferência dos valores depende da tabela original.", "erradas": ["A/B/C/E) Não é possível confirmar ou eliminar com segurança sem os dados da tabela."], "fundamento": "MCASP — Balanço Orçamentário; evidencia receitas previstas e despesas fixadas em confronto com a execução.", "pegadinha": "Não confundir previsão inicial com previsão atualizada, nem dotação inicial com dotação atualizada.", "verificacao": "Conferir a tabela da questão no PDF/TEC antes de considerar a resolução numérica fechada."}'::jsonb WHERE id='942371';
UPDATE questoes SET resolution='{"cobranca": "Demonstração das Variações Patrimoniais (DVP) — totalização de VPA e VPD a partir de balancete.", "regra": "A DVP evidencia as variações patrimoniais aumentativas e diminutivas e o resultado patrimonial do exercício. A soma precisa ser feita sobre as contas da tabela/balancete apresentado no enunciado.", "passos": ["1) Identifique no balancete as contas de VPA e de VPD.", "2) Some separadamente os saldos classificados como VPA e como VPD.", "3) Compare os dois totais com as alternativas.", "4) O texto extraído disponível nesta base não contém a tabela com os saldos necessários para refazer a soma.", "5) O gabarito registrado na base é E."], "calculo": "Não é possível reproduzir a soma com segurança porque a tabela/balancete não foi preservada no texto extraído.", "correta": "E — R$ 117.200,00 de VPA e R$ 41.300,00 de VPD, conforme gabarito registrado na base.", "erradas": ["A/B/C/D) Dependem dos valores da tabela; sem o balancete original não é possível eliminar cada alternativa numericamente."], "fundamento": "MCASP — Demonstração das Variações Patrimoniais; a DVP evidencia as variações patrimoniais aumentativas e diminutivas e o resultado patrimonial.", "pegadinha": "Não confundir valores orçamentários com VPA/VPD: a DVP trabalha com variações patrimoniais, e não simplesmente com arrecadação e empenho.", "verificacao": "Conferir o balancete/tabela original no PDF ou TEC antes de considerar a totalização numérica definitivamente validada."}'::jsonb WHERE id='942374';
UPDATE questoes SET resolution='{"cobranca": "PCASP — classificação das contas pela natureza da informação.", "regra": "No PCASP, a natureza patrimonial evidencia patrimônio e suas variações; a natureza orçamentária evidencia planejamento e execução orçamentária; e a natureza de controle evidencia atos de gestão e outros controles.", "passos": ["1) A primeira definição trata de aprovação e execução do orçamento, inclusive restos a pagar: natureza orçamentária (II).", "2) A segunda trata de Ativo, Passivo, PL, VPA e VPD: natureza patrimonial (I).", "3) A terceira trata de atos de gestão e controles que podem produzir efeitos futuros no patrimônio: natureza típica de controle (III).", "4) A sequência é II, I, III."], "calculo": "Não há cálculo.", "correta": "D — II, I e III.", "erradas": ["A) Inverte a natureza da primeira definição.", "B) Coloca a segunda definição como controle, quando ela descreve patrimônio.", "C) Troca a primeira definição por patrimonial.", "E) Trata a primeira definição como controle, o que não corresponde ao enunciado."], "fundamento": "MCASP 11ª Edição e PCASP: naturezas patrimonial, orçamentária e de controle.", "pegadinha": "As três naturezas podem aparecer na mesma operação, mas representam perspectivas distintas do registro contábil.", "verificacao": "A classificação conceitual é compatível com a estrutura do PCASP."}'::jsonb WHERE id='942385';
UPDATE questoes SET resolution='{"cobranca": "PCASP — lançamento de aquisição de mercadorias a prazo.", "regra": "A compra de mercadorias para estoque, quando feita a prazo, aumenta o estoque e simultaneamente reconhece obrigação com fornecedor.", "passos": ["1) A entrada das mercadorias aumenta o Ativo/estoque.", "2) Como a compra é a prazo, surge obrigação com fornecedores.", "3) Logo, debita-se Estoque e credita-se Fornecedores pelo mesmo valor."], "calculo": "Débito em Estoque = R$ 4.000,00; crédito em Fornecedores = R$ 4.000,00.", "correta": "D — Débito da conta estoque e crédito da conta fornecedores.", "erradas": ["A) Crédito em Caixa pressupõe pagamento, inexistente no enunciado.", "B) Não há transferência de estoque para material de consumo no momento descrito.", "C) Despesas diferidas não representam a operação apresentada.", "E) Inverte os sentidos e ainda presume pagamento."], "fundamento": "Mecânica de partidas dobradas e registros patrimoniais no PCASP.", "pegadinha": "“A prazo” é a pista para reconhecer Fornecedores, não Caixa.", "verificacao": "Resposta registrada: D."}'::jsonb WHERE id='1061268';
UPDATE questoes SET resolution='{"cobranca": "MCASP — alcance e autoridade das normas para entidades do setor público.", "regra": "A questão diferencia entidades obrigadas à adoção do MCASP de situações em que a adoção é facultativa. Prefeituras, Câmaras, autarquias e fundações públicas/consórcios alcançados pelo MCASP estão sujeitos às regras; empresas estatais dependentes integram o setor público e não podem ser tratadas como simplesmente facultativas.", "passos": ["1) Primeira afirmação: Prefeituras, Câmaras e Autarquias Municipais estão entre as entidades obrigadas — V.", "2) Segunda: dizer que empresas estatais, dependentes ou independentes, têm adoção facultativa é generalização incorreta — F.", "3) Terceira: Consórcios Públicos e Fundações Públicas estão no alcance obrigatório indicado — V.", "4) Sequência: V, F, V."], "calculo": "Não há cálculo.", "correta": "E — V, F, V.", "erradas": ["A/B/C/D) Apresentam sequências incompatíveis com as três classificações acima."], "fundamento": "MCASP 11ª Edição, seção de alcance e autoridade.", "pegadinha": "A expressão “empresas estatais” não pode ser tratada como um bloco único: o regime da estatal dependente é relevante para o alcance da contabilidade pública.", "verificacao": "A questão registra E como gabarito."}'::jsonb WHERE id='3876853';
UPDATE questoes SET resolution='{"cobranca": "MCASP — alcance obrigatório para entidades do setor público.", "regra": "Autarquias, fundações públicas instituídas e mantidas pelo poder público e consórcios públicos estão no alcance obrigatório. Empresas estatais dependentes integram o setor público e devem observar as normas aplicáveis. Tribunais de Contas e Ministério Público não recebem, por esse motivo, uma opção livre de aplicação: integram a Administração Pública e estão sujeitos ao regramento pertinente.", "passos": ["1) I é verdadeira: autarquias, fundações públicas instituídas e mantidas pelo poder público e consórcios públicos estão entre as entidades obrigadas.", "2) II é verdadeira: empresas estatais dependentes integram o setor público para fins do alcance indicado.", "3) III é falsa: não se trata de uma faculdade simplesmente porque são órgãos autônomos.", "4) Portanto, I e II apenas."], "calculo": "Não há cálculo.", "correta": "C — I e II, apenas.", "erradas": ["A) Inclui III, que está incorreta.", "B) Também inclui III e exclui II.", "D) Exclui II.", "E) Exclui I e inclui III."], "fundamento": "MCASP 11ª Edição — alcance e autoridade; NBC TSP Estrutura Conceitual, conforme aplicável às entidades do setor público.", "pegadinha": "Autonomia institucional não significa liberdade para escolher se as normas do MCASP serão aplicadas quando o alcance normativo é obrigatório.", "verificacao": "Resposta registrada: C."}'::jsonb WHERE id='3936172';
UPDATE questoes SET resolution='{"cobranca": "NBC TSP Estrutura Conceitual — definição e reconhecimento de Passivo.", "regra": "Passivo é uma obrigação presente decorrente de evento passado, cuja extinção normalmente resulta em saída de recursos que incorporam potencial de serviços ou benefícios econômicos. A obrigação não precisa necessariamente estar formalizada em lei, e a ausência de dotação orçamentária não elimina, por si só, um passivo patrimonial.", "passos": ["1) A alternativa A exige formalização legal, mas obrigações podem surgir de outras bases, inclusive práticas e expectativas válidas.", "2) A alternativa B trata coerção econômica/necessidade política como impedimentos absolutos, o que não corresponde à definição.", "3) A alternativa C confunde dotação orçamentária com existência de obrigação patrimonial.", "4) A alternativa D descreve a consequência esperada da liquidação/extinção do passivo: saída de recursos da entidade.", "5) A alternativa E exige identificação nominal de terceiros, o que não é requisito da definição."], "calculo": "Não há cálculo.", "correta": "D — é a alternativa registrada como correta na base.", "erradas": ["A) Incorreta por exigir forma legal como condição necessária.", "B) Incorreta por transformar fatores de coerção econômica/política em impedimentos absolutos.", "C) Incorreta porque orçamento e passivo patrimonial são dimensões distintas.", "E) Incorreta porque não é necessária a identificação nominal de cada credor para existir obrigação."], "fundamento": "NBC TSP Estrutura Conceitual — definição de passivo e obrigação presente.", "pegadinha": "Uma obrigação patrimonial não deixa de existir apenas porque não há dotação orçamentária específica para seu pagamento.", "verificacao": "Resposta registrada na base: D."}'::jsonb WHERE id='4098481';
UPDATE questoes SET resolution='{"cobranca": "CASP — distinção entre aspectos patrimonial, fiscal e orçamentário.", "regra": "O aspecto patrimonial trata da composição e das variações do patrimônio e utiliza demonstrações como a DVP; o fiscal concentra-se nos indicadores e limites da LRF, com destaque para RGF; o orçamentário acompanha aprovação e execução do orçamento, sustentando o Balanço Orçamentário e o Balanço Financeiro.", "passos": ["1) I fala de bens, direitos e obrigações, convergência às normas internacionais e DVP: patrimonial.", "2) II fala de dívida consolidada e resultado nominal no contexto da LRF e RGF: fiscal.", "3) III fala de aprovação e execução da LOA e dos balanços orçamentário e financeiro: orçamentário.", "4) A sequência é patrimonial, fiscal, orçamentário."], "calculo": "Não há cálculo.", "correta": "B — I patrimonial; II fiscal; III orçamentário.", "erradas": ["A) Troca fiscal e orçamentário.", "C) Inverte o primeiro aspecto.", "D/E) Iniciam a sequência por classificação incompatível com a descrição do item I."], "fundamento": "CASP/MCASP — perspectivas patrimonial, orçamentária e fiscal.", "pegadinha": "RGF é relatório fiscal; DVP é demonstração patrimonial; Balanço Orçamentário acompanha a execução do orçamento.", "verificacao": "Resposta registrada: B."}'::jsonb WHERE id='4098498';
UPDATE questoes SET resolution='{"cobranca": "LRF — limite global da despesa total com pessoal.", "regra": "A LRF estabelece, para cada ente da Federação, limite global de 60% da Receita Corrente Líquida para despesa total com pessoal. Dentro desse limite global, há repartição por Poder/órgão.", "passos": ["1) A pergunta trata da despesa total com pessoal em cada ente.", "2) O limite global do ente é 60% da RCL.", "3) Os percentuais específicos de Poderes, como 54% para o Executivo municipal, não substituem o limite global pedido pela pergunta."], "calculo": "Limite global = 60% × Receita Corrente Líquida.", "correta": "C — 60% da receita corrente líquida.", "erradas": ["A/B/D/E) Não correspondem ao limite global estabelecido pela LRF para o ente."], "fundamento": "Lei Complementar nº 101/2000, art. 19.", "pegadinha": "Não confundir o limite global do Município (60%) com o limite específico do Poder Executivo municipal (54%).", "verificacao": "Resposta registrada: C."}'::jsonb WHERE id='3876596';
UPDATE questoes SET resolution='{"cobranca": "LRF — cálculo da Receita Corrente Líquida e comparação da despesa com pessoal aos limites.", "regra": "Para a RCL, consideram-se as receitas correntes pertinentes, excluindo-se receitas de capital, operações de crédito por ARO e depósitos restituíveis. A venda de veículos é receita de capital e a ARO é operação de crédito, portanto não entram na RCL.", "passos": ["1) Inclua: ISS 10.120; receitas industriais 1.270; contribuição de melhoria 2.150; rendimentos 3.350; serviços 3.330; IPTU 2.480; FPM 15.650; ITBI 15.920.", "2) Não inclua a venda de veículos (R$ 8.380), pois é receita de capital.", "3) Não inclua ARO (R$ 4.790) nem depósitos restituíveis (R$ 2.820).", "4) RCL = R$ 54.270.", "5) Despesa com pessoal = 28.000 / 54.270 = aproximadamente 51,59% da RCL.", "6) 54% é o limite do Executivo municipal; 95% desse limite = 51,30%.", "7) 51,59% está abaixo de 54%, mas acima de 51,30%."], "calculo": "RCL = 10.120 + 1.270 + 2.150 + 3.350 + 3.330 + 2.480 + 15.650 + 15.920 = R$ 54.270.\nDespesa/RCL = 28.000 / 54.270 ≈ 51,59%.\nLimite prudencial = 95% × 54% = 51,30% da RCL.", "correta": "A — abaixo do teto de 54% da RCL, mas acima do limite prudencial de 95% do limite máximo.", "erradas": ["B) Incorreta: o percentual está acima do limite prudencial/alerta pertinente.", "C) Incorreta: embora abaixo do teto, está acima do prudencial.", "D) Incorreta: 51,59% não ultrapassa o teto de 54% do Executivo municipal.", "E) Incorreta: 56% não é o limite do Executivo municipal."], "fundamento": "Lei Complementar nº 101/2000, arts. 18 a 23, especialmente limites de despesa com pessoal e mecanismos de alerta/prudencial.", "pegadinha": "Excluir corretamente ARO, depósitos restituíveis e receitas de capital da composição da RCL é decisivo para chegar ao percentual correto.", "verificacao": "Cálculo reproduz a alternativa A com os valores fornecidos."}'::jsonb WHERE id='3876803';
UPDATE questoes SET resolution='{"cobranca": "LRF — vedações quando a despesa com pessoal excede 95% do limite.", "regra": "Quando a despesa total com pessoal excede 95% do limite, o art. 22 da LRF impõe vedações, entre elas conceder vantagem, aumento, reajuste ou adequação de remuneração, criar cargo, emprego ou função e alterar estrutura de carreira que implique aumento de despesa.", "passos": ["1) O enunciado informa que o Município excedeu 95% do limite.", "2) Isso aciona as vedações do art. 22 da LRF.", "3) Criação de cargos, aumento remuneratório e alteração de estrutura de carreira com aumento de despesa estão entre os atos vedados, ressalvadas as hipóteses legais.", "4) Portanto, a conclusão da Procuradoria é a da alternativa D."], "calculo": "Não há cálculo.", "correta": "D — as medidas descritas estão vedadas quando ultrapassado 95% do limite, nos termos do art. 22 da LRF, ressalvadas as exceções legais.", "erradas": ["A) A vedação não se limita ao aumento remuneratório.", "B) As regras aplicam-se aos Municípios.", "C) Não se restringem a cargos em comissão/funções de confiança.", "E) As vedações do art. 22 incidem antes de ultrapassar o limite máximo, a partir de 95%."], "fundamento": "Lei Complementar nº 101/2000, art. 22.", "pegadinha": "95% do limite já é suficiente para acionar as vedações do art. 22; não é necessário ultrapassar os 100%.", "verificacao": "Resposta registrada: D."}'::jsonb WHERE id='4113335';
UPDATE questoes SET resolution='{"cobranca": "Classificação por natureza da receita — receita corrente e receita de capital.", "regra": "Receitas tributárias, transferências correntes e rendimentos patrimoniais/financeiros integram receitas correntes. Alienação de bens e operações de crédito são receitas de capital.", "passos": ["1) Impostos e taxas: corrente = R$ 1.200.000.", "2) Venda da ambulância: capital = R$ 85.000.", "3) Repasse estadual para custeio: corrente = R$ 340.000.", "4) Empréstimo: capital = R$ 500.000.", "5) Rendimentos de aplicações: corrente = R$ 75.000.", "6) Corrente = 1.200.000 + 340.000 + 75.000 = R$ 1.615.000.", "7) Capital = 85.000 + 500.000 = R$ 585.000."], "calculo": "Receita Corrente = 1.200.000 + 340.000 + 75.000 = R$ 1.615.000.\nReceita de Capital = 85.000 + 500.000 = R$ 585.000.", "correta": "C — Receita Corrente de R$ 1.615.000,00 e Receita de Capital de R$ 585.000,00.", "erradas": ["A/B/D) Classificam ou somam incorretamente a venda do ativo, o empréstimo ou as receitas correntes."], "fundamento": "Lei nº 4.320/1964 e classificação da receita por categoria econômica no MCASP.", "pegadinha": "Venda de ativo não é receita corrente; empréstimo também é receita de capital.", "verificacao": "Cálculo fecha exatamente com C."}'::jsonb WHERE id='3598390';
UPDATE questoes SET resolution='{"cobranca": "Classificação da receita tributária — taxa decorrente do poder de polícia.", "regra": "Taxas são tributos vinculados ao exercício do poder de polícia ou à utilização efetiva/potencial de serviço público específico e divisível. Na classificação econômica, integram as receitas tributárias.", "passos": ["1) O fato gerador descrito é o exercício regular do poder de polícia.", "2) A espécie tributária correspondente é taxa.", "3) Taxas integram a categoria de receita tributária."], "calculo": "Não há cálculo.", "correta": "D — receita tributária.", "erradas": ["A) Contribuição é espécie tributária distinta.", "B) Receita patrimonial decorre da exploração de patrimônio público, não de taxa de polícia.", "C) “Financeira” não corresponde à natureza tributária descrita."], "fundamento": "Constituição Federal, art. 145, II; CTN, art. 77; classificação da receita pública.", "pegadinha": "O fato de a taxa ser cobrada de empresas não a transforma em contribuição ou preço público; o fato gerador é o poder de polícia.", "verificacao": "Resposta registrada: D."}'::jsonb WHERE id='3599117';
UPDATE questoes SET resolution='{"cobranca": "Alienação de bem público — receita de capital e ganho patrimonial.", "regra": "A alienação de um imóvel gera receita orçamentária de capital pelo valor arrecadado. Separadamente, na esfera patrimonial, a diferença positiva entre o preço de alienação e o valor contábil líquido do ativo gera VPA.", "passos": ["1) Valor recebido no leilão = R$ 200.000: receita orçamentária de capital.", "2) Valor contábil líquido do imóvel = R$ 140.000.", "3) Diferença positiva = 200.000 − 140.000 = R$ 60.000.", "4) Essa diferença representa variação patrimonial aumentativa."], "calculo": "Ganho patrimonial = R$ 200.000 − R$ 140.000 = R$ 60.000.", "correta": "A — receita orçamentária de capital de R$ 200.000 e VPA de R$ 60.000.", "erradas": ["B/C/E) Classificam a alienação como receita corrente ou tratam o ganho como VPD.", "D) Confunde o valor contábil do ativo com o valor da receita arrecadada."], "fundamento": "Lei nº 4.320/1964 e MCASP — classificação da alienação de bens e reconhecimento patrimonial do ganho.", "pegadinha": "Não confundir o valor contábil líquido do bem com o valor efetivamente arrecadado na alienação.", "verificacao": "Cálculo fecha com a alternativa A."}'::jsonb WHERE id='3998109';
UPDATE questoes SET resolution='{"cobranca": "Princípios orçamentários — princípio da exclusividade.", "regra": "O princípio da exclusividade determina que a LOA não contenha dispositivo estranho à previsão da receita e à fixação da despesa, ressalvadas a autorização para abertura de créditos suplementares e a contratação de operações de crédito, nos termos da lei.", "passos": ["1) Compare cada alternativa com o conceito do princípio.", "2) A alternativa C reproduz a regra do art. 165, § 8º, da Constituição.", "3) As demais descrevem outros princípios: orçamento bruto, unidade, anualidade e universalidade."], "calculo": "Não há cálculo.", "correta": "C — exclusividade.", "erradas": ["A) Orçamento bruto.", "B) Unidade.", "D) Anualidade/periodicidade.", "E) Universalidade."], "fundamento": "Constituição Federal, art. 165, § 8º.", "pegadinha": "A autorização para crédito suplementar e operações de crédito são exceções expressas à regra de exclusividade.", "verificacao": "Resposta registrada: C."}'::jsonb WHERE id='3441230';
UPDATE questoes SET resolution='{"cobranca": "Despesa pública — identificação da alternativa incorreta sobre empenho, liquidação e Restos a Pagar.", "regra": "Empenho é o ato que cria para o Estado obrigação de pagamento, pendente ou não de implemento de condição, e reserva dotação. A liquidação verifica o direito adquirido pelo credor. O reconhecimento patrimonial da obrigação segue o regime de competência e não deve ser confundido automaticamente com o ato orçamentário do empenho.", "passos": ["1) A alternativa A afirma que o empenho é, por si só, o momento do reconhecimento contábil da obrigação pelo regime de competência.", "2) Essa associação automática está incorreta: empenho é etapa da execução orçamentária; o reconhecimento patrimonial observa a ocorrência do fato gerador/obrigação conforme o regime de competência.", "3) B descreve corretamente a liquidação.", "4) C diferencia classificação por natureza e por função.", "5) D define Restos a Pagar Processados como despesas empenhadas e liquidadas, mas não pagas.", "6) E descreve o suprimento/adiantamento para despesas previamente autorizadas, com prestação de contas.", "7) Logo, A é a incorreta."], "calculo": "Não há cálculo.", "correta": "A — o erro está em afirmar que o empenho, por si só, é o momento do reconhecimento patrimonial da obrigação.", "erradas": ["B) Correta: liquidação verifica o direito do credor antes do pagamento.", "C) Correta: natureza e função são classificações distintas.", "D) Correta: RPP são despesas liquidadas e não pagas até o encerramento.", "E) Compatível com o instituto do adiantamento/suprimento de fundos."], "fundamento": "Lei nº 4.320/1964, arts. 58 a 64, e MCASP 11ª Edição — execução da despesa e enfoque patrimonial.", "pegadinha": "FAFIPA explora a diferença entre a etapa orçamentária do empenho e o reconhecimento patrimonial segundo o regime de competência.", "verificacao": "Resposta registrada: A."}'::jsonb WHERE id='3876861';
UPDATE questoes SET resolution='{"cobranca": "Estágios da despesa pública: sequência legal da execução.", "regra": "Na execução ordinária da despesa, a sequência é empenho, liquidação e pagamento. A liquidação verifica o direito adquirido pelo credor antes do pagamento.", "passos": ["1) Identifique que a questão pede a ordem cronológica dos estágios da despesa.", "2) A Lei nº 4.320/1964 estabelece que a despesa deve ser empenhada e que o pagamento somente ocorre após a regular liquidação.", "3) Portanto, a ordem é empenho → liquidação → pagamento."], "calculo": "", "correta": "D) Empenho, Liquidação e Pagamento.", "erradas": ["A) Inverte liquidação e pagamento.", "B) Coloca a liquidação antes do empenho.", "C) Coloca o pagamento antes dos dois estágios anteriores.", "E) Também coloca a liquidação antes do empenho."], "fundamento": "Lei nº 4.320/1964, arts. 58, 62 e 63: empenho, liquidação e pagamento; a liquidação verifica o direito adquirido pelo credor.", "pegadinha": "A FAFIPA troca facilmente a ordem de liquidação e pagamento. A palavra-chave é “antes de realizar o pagamento”: primeiro se liquida, depois se paga."}'::jsonb WHERE id='3937610';
UPDATE questoes SET resolution='{"cobranca": "Estágio da liquidação da despesa.", "regra": "Liquidação é a verificação do direito adquirido pelo credor com base nos títulos e documentos comprobatórios, incluindo a comprovação da entrega do material ou da prestação do serviço.", "passos": ["1) O Município recebeu os bens e a nota fiscal.", "2) O setor conferiu se a obrigação foi cumprida e se o valor corresponde ao contratado.", "3) Essa conferência caracteriza a liquidação.", "4) O pagamento ocorre posteriormente."], "calculo": "", "correta": "C) liquidação.", "erradas": ["A) Empenho é a reserva/dedicação da dotação para determinada despesa.", "B) Fixação não é o estágio descrito no caso.", "D) Previsão é conceito ligado à receita.", "E) Arrecadação é estágio da receita."], "fundamento": "Lei nº 4.320/1964, art. 63.", "pegadinha": "Não confundir recebimento/conferência do bem com pagamento. A verificação do direito do credor é liquidação."}'::jsonb WHERE id='4074903';
UPDATE questoes SET resolution='{"cobranca": "Estágios da despesa, PCASP e regra do empenho prévio.", "regra": "A despesa pública não pode ser realizada sem prévio empenho. A liquidação é posterior ao empenho e o pagamento sucede a liquidação. O empenho global é adequado para despesas contratuais de valor determinado sujeitas a parcelamento.", "passos": ["1) A questão pede a alternativa INCORRETA.", "2) Verifique cada afirmação contra a regra de execução da despesa.", "3) A alternativa C afirma que a liquidação pode dispensar a nota de empenho porque existe contrato. Isso contraria a exigência de prévio empenho.", "4) Logo, C é a incorreta."], "calculo": "", "correta": "C) A afirmação é incorreta porque a existência de contrato não elimina a necessidade do prévio empenho.", "erradas": ["A) Está de acordo com a lógica do registro “em liquidação” e reconhecimento do passivo pelo fato gerador.", "B) Descreve a descentralização de créditos e os registros correspondentes de forma compatível com o contexto apresentado.", "D) A ordem de pagamento é o despacho da autoridade competente determinando que a despesa seja paga, após a liquidação.", "E) Empenho global é utilizado para despesas contratuais de valor determinado e pagamentos parcelados."], "fundamento": "Lei nº 4.320/1964, art. 60: é vedada a realização de despesa sem prévio empenho; arts. 62 e 63 sobre pagamento e liquidação.", "pegadinha": "Contrato não substitui empenho. A questão tenta fazer o candidato confundir instrumento contratual com estágio da execução orçamentária."}'::jsonb WHERE id='4098488';
UPDATE questoes SET resolution='{"cobranca": "Conceito dos estágios: empenho, liquidação e pagamento.", "regra": "Empenho não é a conferência da entrega; liquidação verifica o direito adquirido pelo credor; pagamento vem depois da liquidação.", "passos": ["1) I está errada: descreve liquidação, não empenho.", "2) II está correta: reproduz a essência do art. 63 da Lei nº 4.320/1964.", "3) III está errada: pagamento não antecede liquidação.", "4) Somente II é verdadeira."], "calculo": "", "correta": "C) II, apenas.", "erradas": ["A) I, apenas — I é falsa.", "B) I, II e III — I e III são falsas.", "D) I e III, apenas — ambas são falsas.", "E) III, apenas — III é falsa."], "fundamento": "Lei nº 4.320/1964, arts. 58, 62 e 63.", "pegadinha": "A troca entre “empenho” e “liquidação” é recorrente: entrega/conferência do objeto pertence à liquidação."}'::jsonb WHERE id='4139371';
UPDATE questoes SET resolution='{"cobranca": "LRF: despesa com pessoal, Anexo de Metas Fiscais e operações de crédito entre entes.", "regra": "O limite do Poder Executivo estadual para despesa total com pessoal não é 50% da RCL; a LDO deve conter Anexo de Metas Fiscais; e a LRF veda, em regra, operação de crédito entre entes da Federação.", "passos": ["1) Primeira assertiva: falsa. Para Estados, o limite global é 60% da RCL e o Executivo possui 49%, não 50%.", "2) Segunda assertiva: falsa porque a LRF não estabelece a proibição afirmada de definir déficit fiscal apenas pelo fato de ter sido ultrapassado o limite da dívida consolidada.", "3) Terceira assertiva: verdadeira: a LRF veda operação de crédito entre entes, ressalvadas as hipóteses legais específicas.", "4) Sequência: F, F, V."], "calculo": "", "correta": "B) F, F, V.", "erradas": ["A) V, F, F — erra a primeira e a terceira.", "C) F, V, F — erra a segunda e a terceira.", "D) V, F, V — primeira falsa.", "E) F, V, V — segunda falsa."], "fundamento": "Lei Complementar nº 101/2000, especialmente arts. 18–23, 4º e 35.", "pegadinha": "Confusão entre limites globais e individuais de pessoal e entre regras da dívida e do resultado fiscal."}'::jsonb WHERE id='3936148';
UPDATE questoes SET resolution='{"cobranca": "MCASP: identificação dos aspectos patrimonial, fiscal e orçamentário.", "regra": "Aspecto patrimonial trata de ativos, passivos e variações patrimoniais; aspecto fiscal relaciona-se aos indicadores e limites fiscais; aspecto orçamentário trata da execução do orçamento, receitas e despesas orçamentárias.", "passos": ["1) Registro 1: depreciação e dívida consolidada líquida — a depreciação é patrimonial e o conjunto indicado pertence ao aspecto patrimonial no enquadramento proposto.", "2) Registro 2: despesa com pessoal e resultado primário — aspecto fiscal.", "3) Registro 3: execução do orçamento e arrecadação — aspecto orçamentário.", "4) A combinação corresponde à alternativa D."], "calculo": "", "correta": "D) Registro 1 – Patrimonial; Registro 2 – Fiscal; Registro 3 – Orçamentário.", "erradas": ["A) Troca patrimonial e fiscal.", "B) Troca patrimonial, orçamentário e fiscal.", "C) Classifica o Registro 1 como orçamentário e o Registro 3 como patrimonial.", "E) Inverte os aspectos orçamentário e fiscal dos registros 2 e 3."], "fundamento": "MCASP, capítulo da estrutura conceitual e aspectos da informação contábil aplicada ao setor público.", "pegadinha": "Não confundir execução orçamentária com evidenciação patrimonial nem indicadores fiscais com registros de execução do orçamento."}'::jsonb WHERE id='3435164';
UPDATE questoes SET resolution='{"cobranca": "LRF: despesa total com pessoal, seguridade social e despesas obrigatórias de caráter continuado.", "regra": "Despesa corrente derivada de lei, medida provisória ou ato administrativo normativo que fixe obrigação de execução por período superior a dois exercícios é despesa obrigatória de caráter continuado.", "passos": ["1) A questão pede a alternativa que NÃO está em conformidade.", "2) A alternativa D afirma justamente que uma despesa com obrigação superior a dois exercícios “não é considerada” obrigatória de caráter continuado.", "3) Isso contraria o conceito do art. 17 da LRF.", "4) Portanto, D é a incorreta."], "calculo": "", "correta": "D) A afirmação é incorreta: despesa corrente obrigatória por período superior a dois exercícios enquadra-se no conceito de despesa obrigatória de caráter continuado.", "erradas": ["A) Compatível com a exigência de indicação da fonte de custeio para criação, majoração ou extensão de benefício/serviço de seguridade social.", "B) Reproduz a definição de despesa total com pessoal.", "C) Compatível com as condições para destinação de recursos a pessoas físicas ou déficits de pessoas jurídicas.", "E) Compatível com o tratamento de terceirização que substitui servidores/empregados públicos."], "fundamento": "Lei Complementar nº 101/2000, arts. 16, 17 e 18.", "pegadinha": "A palavra “não” muda tudo: a definição legal inclui justamente a despesa corrente com obrigação por período superior a dois exercícios."}'::jsonb WHERE id='3436125';
UPDATE questoes SET resolution='{"cobranca": "LRF: limites de despesa com pessoal dos Municípios.", "regra": "Para os Municípios, o limite global de despesa total com pessoal é 60% da Receita Corrente Líquida; o Executivo possui 54% e o Legislativo 6%.", "passos": ["1) Identifique a base: Receita Corrente Líquida (RCL).", "2) O limite municipal total é 60% da RCL.", "3) A repartição indicada para os Poderes é 54% para Executivo e 6% para Legislativo.", "4) A sequência correta é 60%, RCL, 54%, 6%."], "calculo": "", "correta": "A) 60%, receita corrente líquida, 54%, 6%.", "erradas": ["B) Altera a divisão entre Executivo e Legislativo.", "C) Apresenta percentuais incompatíveis com a LRF.", "D) Usa receita corrente, e não Receita Corrente Líquida, além de manter os percentuais corretos dos Poderes."], "fundamento": "Lei Complementar nº 101/2000, art. 20, III.", "pegadinha": "A banca pode trocar RCL por “receita corrente” ou alterar a repartição 54%/6%."}'::jsonb WHERE id='3460672';
UPDATE questoes SET resolution='{"cobranca": "LRF: limite máximo de despesa total com pessoal do Executivo municipal.", "regra": "O Poder Executivo municipal pode comprometer até 54% da Receita Corrente Líquida com despesa total com pessoal, conforme a repartição do limite municipal.", "passos": ["1) Identifique que a pergunta trata do Executivo municipal, não do Município como um todo.", "2) O limite global municipal é 60% da RCL.", "3) Desse total, 54% correspondem ao Executivo e 6% ao Legislativo.", "4) Portanto, 54% é o limite máximo do Executivo."], "calculo": "", "correta": "A) 54% da RCL.", "erradas": ["B) 70% excede o limite.", "C) 49% é o limite do Executivo estadual, não municipal.", "D) 60% é o limite global municipal.", "E) 50% não corresponde ao limite municipal do Executivo."], "fundamento": "Lei Complementar nº 101/2000, art. 20, III.", "pegadinha": "Confundir 60% (total do Município) com 54% (Executivo municipal) e 49% (Executivo estadual)."}'::jsonb WHERE id='3748800';
UPDATE questoes SET resolution='{"cobranca": "LRF e Constituição: limites, vedações e recondução da despesa com pessoal.", "regra": "Ultrapassado o limite legal, o ente deve eliminar o excedente nos prazos legais; há vedações específicas quando atingido o limite prudencial. Não é permitido simplesmente criar cargos ou conceder aumentos sob a justificativa de futura arrecadação.", "passos": ["1) A questão pede a alternativa INCORRETA.", "2) A alternativa C afirma que, mesmo acima do limite legal, seria possível criar cargos e conceder aumentos se houver expectativa de aumento futuro da arrecadação.", "3) Essa compensação futura não afasta as vedações da LRF.", "4) Logo, C é a incorreta."], "calculo": "", "correta": "C) É incorreta: ultrapassar o limite legal de pessoal sujeita o ente às medidas de recondução e às vedações legais; aumento futuro de arrecadação não autoriza automaticamente novas despesas.", "erradas": ["A) Está alinhada às vedações decorrentes do limite prudencial, ressalvadas as hipóteses legais.", "B) Reflete medidas de recondução previstas na Constituição/LRF.", "D) Reproduz o limite de 54% para o Executivo municipal.", "E) A existência de dotação e autorização orçamentária não elimina as demais exigências legais para aumento de despesa com pessoal."], "fundamento": "Constituição Federal, art. 169; Lei Complementar nº 101/2000, arts. 20–23.", "pegadinha": "Dotação orçamentária e autorização na LDO não significam autorização irrestrita para aumentar despesa com pessoal acima dos limites da LRF."}'::jsonb WHERE id='3930702';
UPDATE questoes SET resolution='{"cobranca": "Características qualitativas da informação contábil pública.", "regra": "Tempestividade é disponibilizar a informação a tempo de influenciar decisões; representação fidedigna exige retratar o fenômeno de forma completa, neutra e livre de erro material; comparabilidade permite identificar semelhanças e diferenças; compreensibilidade facilita o entendimento.", "passos": ["1) I é verdadeira: informação tardia pode perder utilidade.", "2) II é falsa: representação fidedigna não significa simplesmente ser compreensível ao público leigo.", "3) III é verdadeira: comparabilidade permite identificar semelhanças e diferenças.", "4) IV é verdadeira: clareza e organização favorecem a compreensibilidade.", "5) Portanto, I, III e IV são verdadeiras."], "calculo": "", "correta": "D) I, III e IV, apenas.", "erradas": ["A) Exclui I, que está correta.", "B) Inclui II, que está incorreta.", "C) Inclui II e exclui IV.", "E) Inclui II e exclui III e IV."], "fundamento": "MCASP e NBC TSP Estrutura Conceitual, características qualitativas da informação contábil.", "pegadinha": "Representação fidedigna não é sinônimo de linguagem simples; são conceitos distintos de qualidade da informação."}'::jsonb WHERE id='3435188';
UPDATE questoes SET resolution='{"cobranca": "MCASP: aspectos fiscal, patrimonial e orçamentário.", "regra": "Aspecto fiscal evidencia limites e resultados fiscais; patrimonial trata de ativos, passivos e variações patrimoniais; orçamentário acompanha a execução do orçamento.", "passos": ["1) I menciona despesa com pessoal, dívida consolidada e resultado primário em RGF/RREO: aspecto fiscal.", "2) II menciona ativos, passivos, BP e DVP: aspecto patrimonial.", "3) III menciona execução do orçamento e Balanço Orçamentário/Balanço Financeiro/RREO: aspecto orçamentário.", "4) A associação é fiscal, patrimonial, orçamentário."], "calculo": "", "correta": "B) I − Aspecto Fiscal; II − Aspecto Patrimonial; III − Aspecto Orçamentário.", "erradas": ["A) Inverte os três aspectos.", "C) Troca patrimonial e orçamentário.", "D) Inverte a classificação de I e II."], "fundamento": "MCASP, 10ª edição, estrutura e aspectos da informação contábil pública.", "pegadinha": "RGF/RREO e limites fiscais apontam para o aspecto fiscal; BP/DVP para o patrimonial; execução da LOA para o orçamentário."}'::jsonb WHERE id='3598377';
UPDATE questoes SET resolution='{"cobranca": "Características qualitativas da informação contábil pública.", "regra": "A informação não precisa ser aceita ou utilizada por todos os usuários para ser útil ou relevante. Relevância depende da capacidade de fazer diferença nas decisões, e representação fidedigna envolve completude, neutralidade e ausência de erro material.", "passos": ["1) A questão pede a alternativa INCORRETA.", "2) A alternativa A exige aceitação e influência sobre todos os usuários, sem exceção.", "3) Isso é falso: uma informação pode ser relevante mesmo que alguns usuários não a utilizem ou já a conheçam por outra fonte.", "4) Logo, A é a incorreta."], "calculo": "", "correta": "A) A afirmação é incorreta. A utilidade/relevância não exige que todos os usuários aceitem ou utilizem a informação.", "erradas": ["B) Compatível com a definição de relevância.", "C) Compatível com a possibilidade de a informação ser relevante mesmo sem ser utilizada por todos.", "D) Compatível com os atributos da representação fidedigna."], "fundamento": "MCASP e NBC TSP Estrutura Conceitual, características qualitativas da informação.", "pegadinha": "“Necessariamente”, “todos” e “sem exceção” são sinais de uma afirmação absoluta que contraria a definição."}'::jsonb WHERE id='3598378';
UPDATE questoes SET resolution='{"cobranca": "Objeto, RCPGs e objetivo das entidades do setor público.", "regra": "O patrimônio público é o objeto da contabilidade aplicada ao setor público; RCPGs abrangem as demonstrações, mas não se limitam a elas; o orçamento não é o objeto da contabilidade; a finalidade predominante das entidades públicas é prestar serviços à sociedade.", "passos": ["1) Patrimônio público = verdadeiro.", "2) RCPGs abrangem demonstrações contábeis e outros relatórios = verdadeiro.", "3) Orçamento público como objeto da contabilidade = falso.", "4) Prestação de serviços à sociedade, em vez de lucro aos investidores, é característica do setor público = verdadeiro.", "5) Sequência: V, V, F, V."], "calculo": "", "correta": "D) V, V, F, V.", "erradas": ["A) Começa com F, contrariando o objeto da CASP.", "B) Torna falsa a afirmação sobre RCPGs e correta a do orçamento, invertendo conceitos.", "C) Classifica incorretamente a primeira afirmação."], "fundamento": "NBC TSP Estrutura Conceitual e MCASP: objeto, objetivos e relatórios contábeis de propósito geral.", "pegadinha": "“Orçamento” é objeto de acompanhamento sob o aspecto orçamentário, mas não substitui o patrimônio como objeto da contabilidade pública."}'::jsonb WHERE id='3599103';
UPDATE questoes SET resolution='{"cobranca": "RCPGs: finalidade e usuários primários.", "regra": "RCPGs são elaborados principalmente para atender às necessidades de informação dos usuários dos serviços e provedores de recursos que não podem exigir informações específicas. Podem compreender múltiplos relatórios e também ser úteis a outros usuários.", "passos": ["1) A, B, C e E são compatíveis com a finalidade e o alcance dos RCPGs.", "2) D afirma que os RCPGs têm propósito de atender a finalidades específicas de determinados grupos de usuários.", "3) Isso contraria o caráter geral dos RCPGs, destinados às necessidades de informação de usuários em geral.", "4) Portanto, D é a incorreta."], "calculo": "", "correta": "D) Os RCPGs são relatórios de propósito geral, não relatórios destinados exclusivamente a finalidades específicas de determinados grupos.", "erradas": ["A) Descreve a finalidade principal dos RCPGs.", "B) Correta: podem compreender múltiplos relatórios.", "C) Correta quanto aos usuários primários.", "E) Correta: as informações também podem ser úteis para outros propósitos."], "fundamento": "NBC TSP Estrutura Conceitual, disposições sobre RCPGs e usuários primários.", "pegadinha": "“Propósito geral” é o núcleo da questão; a alternativa D transforma o relatório de propósito geral em relatório de finalidade específica."}'::jsonb WHERE id='3708643';
UPDATE questoes SET resolution='{"cobranca": "Características qualitativas dos RCPGs.", "regra": "Verificabilidade ajuda a assegurar que a informação represente fielmente o fenômeno; relevância envolve valor preditivo/confirmatório; representação fidedigna envolve completude, neutralidade e ausência de erro material; tempestividade é disponibilização a tempo; compreensibilidade é facilidade de entendimento.", "passos": ["1) A descreve verificabilidade de forma compatível com a NBC TSP Estrutura Conceitual.", "2) B atribui à representação fidedigna uma definição de relevância.", "3) C atribui à relevância uma definição de representação fidedigna.", "4) D descreve tempestividade, não comparabilidade.", "5) E descreve compreensibilidade, não tempestividade.", "6) Portanto, somente A está correta."], "calculo": "", "correta": "A) A Verificabilidade é a qualidade que ajuda a assegurar que a informação representa fielmente os fenômenos que se propõe a representar.", "erradas": ["B) A descrição é de relevância, não representação fidedigna.", "C) A descrição é de representação fidedigna, não relevância.", "D) A descrição é de tempestividade, não comparabilidade.", "E) A descrição é de compreensibilidade, não tempestividade."], "fundamento": "NBC TSP Estrutura Conceitual, características qualitativas dos RCPGs.", "pegadinha": "A banca troca deliberadamente as definições das características qualitativas."}'::jsonb WHERE id='3708645';
UPDATE questoes SET resolution='{"cobranca": "Aplicação das características qualitativas a situações concretas.", "regra": "Ajustar informação para retratar adequadamente o fenômeno pode envolver representação fidedigna; atraso prejudica tempestividade; linguagem clara favorece compreensibilidade; comparação entre exercícios favorece comparabilidade; confirmação independente favorece verificabilidade.", "passos": ["1) Situação I: ajustar registros para refletir os fatos e a essência econômica aponta para representação fidedigna, não relevância.", "2) Situação II: atraso prejudica tempestividade, não demonstra verificabilidade.", "3) Situação III: linguagem clara e organização facilitam entendimento — compreensibilidade.", "4) Situação IV: comparação entre exercícios — comparabilidade.", "5) Situação V: auditor independente e consenso entre observadores — verificabilidade.", "6) A única alternativa correta é E, que identifica corretamente a Situação III."], "calculo": "", "correta": "E) Na Situação III, evidencia-se a compreensibilidade, pois a clareza e a organização facilitam o entendimento dos usuários.", "erradas": ["A) Atraso é problema de tempestividade, não verificabilidade.", "B) A Situação I trata principalmente de representação fidedigna, não necessariamente de relevância.", "C) A Situação V exemplifica verificabilidade, não relevância.", "D) Comparação entre exercícios é comparabilidade, não tempestividade."], "fundamento": "MCASP e NBC TSP Estrutura Conceitual, características qualitativas da informação contábil pública.", "pegadinha": "Cada situação foi construída para representar uma característica diferente; a banca testa a associação exata entre exemplo e conceito."}'::jsonb WHERE id='3930676';
UPDATE questoes SET resolution='{"cobranca": "Campo de aplicação da CASP / MCASP 11ª edição", "regra": "O MCASP alcança as entidades do setor público sujeitas à contabilidade pública, incluindo órgãos e entidades públicas e empresas estatais dependentes. Uma OSCIP é uma organização privada qualificada pelo Poder Público, mas não integra, por esse simples fato, o conjunto de entidades abrangidas como entidade do setor público pelo MCASP.", "passos": ["1) O comando pede a entidade NÃO abrangida pelo campo de aplicação.", "2) Fundações públicas, Assembleias Legislativas, Secretarias Municipais e empresas estatais dependentes são entidades/órgãos do setor público ou abrangidos pela CASP.", "3) OSCIP é pessoa jurídica privada sem fins lucrativos, qualificada como organização da sociedade civil de interesse público.", "4) Portanto, a alternativa E é a que não se enquadra no campo de aplicação indicado pelo MCASP."], "calculo": "", "correta": "E) Organizações da Sociedade Civil de Interesse Público (OSCIPs).", "erradas": ["A) Fundações Públicas — integram o setor público.", "B) Assembleias Legislativas Estaduais — órgão do Poder Legislativo estadual.", "C) Secretarias Municipais de Finanças — órgão da administração pública municipal.", "D) Empresas Estatais Dependentes — integram o campo da contabilidade aplicada ao setor público."], "fundamento": "A questão está baseada no campo de aplicação da MCASP 11ª edição, cuja vigência é indicada pelo Tesouro Nacional.", "pegadinha": "A palavra-chave é “NÃO abrangida”. A pegadinha é confundir uma organização privada qualificada pelo Poder Público com uma entidade pública.", "verificacao": "Conferir a redação específica do capítulo de campo de aplicação da MCASP 11ª edição na versão adotada pelo edital."}'::jsonb WHERE id='4003302';
UPDATE questoes SET resolution='{"cobranca": "Princípios orçamentários — unidade ou totalidade", "regra": "O princípio da unidade ou totalidade determina a existência de orçamento único para cada ente federativo, evitando múltiplos orçamentos paralelos dentro da mesma pessoa política.", "passos": ["1) O enunciado fala em um único documento legal para cada esfera federativa.", "2) Isso corresponde à ideia de orçamento único.", "3) No MCASP, essa denominação aparece como “Unidade ou Totalidade”.", "4) Logo, o gabarito B está correto."], "calculo": "", "correta": "B) Totalidade.", "erradas": ["A) Anualidade — trata do período de vigência do orçamento.", "C) Universalidade — exige que a LOA contenha todas as receitas e despesas abrangidas.", "D) Transparência — relaciona-se à publicidade e clareza das informações.", "E) Orçamento Bruto — exige registro pelos valores totais, sem deduções."], "fundamento": "Lei nº 4.320/1964, art. 2º; MCASP, princípio da Unidade ou Totalidade.", "pegadinha": "Universalidade e totalidade aparecem frequentemente juntas em questões da FAFIPA. “Orçamento único” aponta para unidade/totalidade; “todas as receitas e despesas” aponta para universalidade."}'::jsonb WHERE id='2416275';
UPDATE questoes SET resolution='{"cobranca": "Princípio da exclusividade", "regra": "Pelo princípio da exclusividade, a LOA não deve conter dispositivo estranho à previsão da receita e à fixação da despesa. A Constituição admite, no próprio §8º do art. 165, as exceções relativas à autorização para créditos suplementares e à contratação de operações de crédito, nos termos da lei.", "passos": ["1) A questão pergunta especificamente pelo princípio da exclusividade.", "2) Localize a definição no art. 165, §8º, da Constituição.", "3) Compare a definição com as alternativas.", "4) A alternativa D reproduz a regra constitucional e, por isso, é a correta."], "calculo": "", "correta": "D) A LOA não conterá dispositivo estranho à previsão da receita e à fixação da despesa, ressalvadas as autorizações previstas no próprio §8º.", "erradas": ["A) descreve universalidade.", "B) descreve anualidade/periodicidade.", "C) trata do exercício financeiro e do art. 34 da Lei nº 4.320/1964.", "E) descreve orçamento bruto, previsto no art. 6º da Lei nº 4.320/1964."], "fundamento": "Constituição Federal, art. 165, §8º.", "pegadinha": "Não confundir exclusividade com orçamento bruto: exclusividade limita o conteúdo da LOA; orçamento bruto impede que receitas e despesas sejam apresentadas apenas por valores líquidos."}'::jsonb WHERE id='2416276';
UPDATE questoes SET resolution='{"cobranca": "Princípio da universalidade", "regra": "Universalidade significa que a LOA deve abranger todas as receitas e despesas do ente, observadas as regras constitucionais e legais.", "passos": ["1) O enunciado afirma que não foram previstas todas as receitas.", "2) Também informa que não foram autorizadas todas as despesas da administração direta e indireta relativas aos três Poderes.", "3) A característica central é a abrangência de todas as receitas e despesas.", "4) Portanto, houve violação da universalidade."], "calculo": "", "correta": "B) Princípio da Universalidade.", "erradas": ["A) Legalidade — refere-se à necessidade de autorização legal, não à abrangência integral descrita.", "C) Publicidade — relaciona-se à divulgação das informações.", "D) Anualidade — refere-se ao período de vigência.", "E) Exclusividade — limita o conteúdo estranho à previsão da receita e fixação da despesa."], "fundamento": "Lei nº 4.320/1964, art. 2º e art. 4º; CF, art. 165, §5º; MCASP.", "pegadinha": "O detalhe decisivo é “todas”. Quando a questão fala em omissão de receitas ou despesas que deveriam integrar a LOA, pense primeiro em universalidade."}'::jsonb WHERE id='2416278';
UPDATE questoes SET resolution='{"cobranca": "Princípio da especialização/especificação/discriminação", "regra": "O princípio da especialização ou especificação exige que receitas e despesas sejam apresentadas de maneira discriminada, permitindo identificar sua origem e aplicação e favorecendo o controle parlamentar.", "passos": ["1) O enunciado destaca “discriminada” e “conhecimento detalhado”.", "2) Isso corresponde à especificação/especialização do orçamento.", "3) Entre as alternativas, essa definição está associada ao princípio da especialização.", "4) Logo, a resposta é A."], "calculo": "", "correta": "A) Princípio da Especialização.", "erradas": ["B) Exatidão — relaciona-se à busca de estimativas realistas.", "C) Clareza — trata da inteligibilidade da informação.", "D) Publicidade — trata da divulgação.", "E) Equilíbrio — relaciona-se à compatibilidade entre receitas e despesas."], "fundamento": "Princípio da especificação/discriminação orçamentária, em conjunto com as regras de discriminação da Lei nº 4.320/1964.", "pegadinha": "“Discriminada” e “detalhado” são as pistas. Não confunda especificação com publicidade: uma trata do nível de detalhamento; a outra, da divulgação."}'::jsonb WHERE id='2715406';
UPDATE questoes SET resolution='{"cobranca": "Princípios da totalidade, exclusividade e universalidade", "regra": "I descreve unidade ou totalidade; II descreve exclusividade; III descreve universalidade. As três afirmações estão corretas.", "passos": ["1) I: “orçamento único para cada ente” = unidade/totalidade.", "2) II: “LOA não conterá dispositivo estranho...” = exclusividade.", "3) III: “todas as receitas e despesas...” = universalidade.", "4) Como as três correspondências estão corretas, a resposta é B."], "calculo": "", "correta": "B) I, II e III.", "erradas": ["A) III, apenas — ignora que I e II também estão corretas.", "C) I e III, apenas — exclui indevidamente a exclusividade.", "D) II e III, apenas — exclui indevidamente a unidade/totalidade."], "fundamento": "MCASP, princípios de Unidade ou Totalidade, Universalidade e Exclusividade; Lei nº 4.320/1964, art. 2º; CF, art. 165, §8º.", "pegadinha": "A FAFIPA troca os nomes dos princípios mantendo a definição. Memorize a associação: único = totalidade; tudo = universalidade; nada estranho = exclusividade."}'::jsonb WHERE id='2746519';
UPDATE questoes SET resolution='{"cobranca": "Identificação das definições dos princípios orçamentários", "regra": "Universalidade exige que a LOA contenha todas as receitas e despesas dos Poderes, órgãos, entidades, fundos e fundações abrangidos.", "passos": ["1) A alternativa B associa universalidade a todas as receitas e despesas.", "2) Essa é exatamente a definição cobrada pelo MCASP.", "3) As demais alternativas trocam os conceitos de anualidade, unidade, exclusividade e orçamento bruto.", "4) Portanto, B é correta."], "calculo": "", "correta": "B) Princípio da Universalidade: a LOA deve conter todas as receitas e despesas dos Poderes, órgãos, entidades, fundos e fundações instituídas e mantidas pelo Poder Público.", "erradas": ["A) atribui a definição de unidade à anualidade.", "C) atribui a definição de anualidade à unidade.", "D) descreve orçamento bruto, não exclusividade.", "E) descreve exclusividade, não não vinculação de impostos."], "fundamento": "MCASP; Lei nº 4.320/1964, art. 2º e art. 4º.", "pegadinha": "Questão de associação direta. “Todas as receitas e despesas” = universalidade."}'::jsonb WHERE id='3994233';
UPDATE questoes SET resolution='{"cobranca": "Princípio do equilíbrio", "regra": "O princípio do equilíbrio, em sua formulação didática tradicional, busca compatibilizar receitas e despesas orçamentárias, evitando que as despesas fixadas superem as receitas previstas sem suporte legal adequado.", "passos": ["1) A questão pergunta qual princípio corresponde à relação entre receitas previstas e despesas fixadas.", "2) O conceito apresentado é o de equilíbrio orçamentário.", "3) A alternativa C é a única que traz esse princípio.", "4) Logo, C é a resposta."], "calculo": "Não há cálculo; trata-se de identificação conceitual.", "correta": "C) Princípio do Equilíbrio.", "erradas": ["A) Programação — relaciona-se à organização do orçamento por programas/ações.", "B) Exatidão — busca estimativas realistas.", "D) Legalidade — exige suporte legal para a atuação orçamentária.", "E) Objetividade — não corresponde à definição apresentada."], "fundamento": "Princípio orçamentário do equilíbrio, conforme a doutrina e a abordagem de princípios orçamentários utilizada em materiais de AFO.", "pegadinha": "A palavra-chave é a relação entre “receitas” e “despesas”. Isso aponta para equilíbrio, não para exatidão."}'::jsonb WHERE id='2156894';
UPDATE questoes SET resolution='{"cobranca": "Princípio da exclusividade", "regra": "A exclusividade impede que a LOA contenha matéria estranha à previsão da receita e à fixação da despesa, ressalvadas as exceções constitucionais.", "passos": ["1) A questão pede a definição de exclusividade segundo o MCASP.", "2) A alternativa A reproduz diretamente essa definição.", "3) B descreve unidade/totalidade.", "4) C descreve universalidade e D descreve anualidade."], "calculo": "", "correta": "A) A LOA não conterá dispositivo estranho à previsão da receita e à fixação da despesa.", "erradas": ["B) Unidade ou totalidade.", "C) Universalidade.", "D) Anualidade ou periodicidade."], "fundamento": "CF, art. 165, §8º; MCASP, princípio da Exclusividade.", "pegadinha": "“Dispositivo estranho” é a expressão-chave da exclusividade."}'::jsonb WHERE id='2156987';
UPDATE questoes SET resolution='{"cobranca": "Princípio da universalidade", "regra": "Universalidade exige que o orçamento contenha todas as receitas e todas as despesas abrangidas pelo ente.", "passos": ["1) O enunciado define o princípio pelo conteúdo integral de receitas e despesas.", "2) Isso corresponde à universalidade.", "3) Unidade trata de orçamento único; especificação trata do detalhamento.", "4) Portanto, B é correta."], "calculo": "", "correta": "B) Princípio da Universalidade.", "erradas": ["A) Unidade — orçamento único por ente.", "C) Publicidade — divulgação.", "D) Especificação — discriminação detalhada."], "fundamento": "Lei nº 4.320/1964, arts. 2º e 4º; MCASP.", "pegadinha": "“Todas as receitas e todas as despesas” é a fórmula mental da universalidade."}'::jsonb WHERE id='2415834';
UPDATE questoes SET resolution='{"cobranca": "Princípio da universalidade", "regra": "A universalidade determina que a LOA de cada ente contenha todas as receitas e despesas dos Poderes, órgãos, entidades, fundos e fundações instituídas e mantidas pelo Poder Público.", "passos": ["1) O enunciado menciona expressamente “todas as receitas e despesas”.", "2) Também cita Poderes, órgãos, entidades, fundos e fundações.", "3) Essa combinação é a definição de universalidade no MCASP.", "4) Logo, a resposta é A."], "calculo": "", "correta": "A) Universalidade.", "erradas": ["B) Totalidade — orçamento único por ente.", "C) Orçamento bruto — valores totais sem deduções.", "D) Anualidade — período do orçamento.", "E) Exclusividade — proibição de matéria estranha à LOA."], "fundamento": "Lei nº 4.320/1964, art. 2º; CF, art. 165, §5º; MCASP.", "pegadinha": "A questão usa a definição quase literal do MCASP. Não deixe “Lei Orçamentária Anual” levar você automaticamente à anualidade."}'::jsonb WHERE id='1741178';
UPDATE questoes SET resolution='{"cobranca": "Associação entre totalidade, universalidade e exclusividade", "regra": "I = universalidade; II = exclusividade; III = totalidade.", "passos": ["1) I fala em todas as receitas e despesas → universalidade.", "2) II fala em não conter dispositivo estranho → exclusividade.", "3) III fala em orçamento único por ente → totalidade.", "4) A sequência é universalidade, exclusividade, totalidade, correspondente à alternativa C."], "calculo": "", "correta": "C) I – universalidade; II – exclusividade; III – totalidade.", "erradas": ["A) troca as três definições.", "B) coloca totalidade no item I e exclusividade no III.", "D) coloca totalidade no I e universalidade no III.", "E) troca universalidade e exclusividade."], "fundamento": "MCASP, princípios de Universalidade, Exclusividade e Unidade ou Totalidade.", "pegadinha": "É uma questão de “palavras-chave”: todas = universalidade; estranho = exclusividade; único = totalidade."}'::jsonb WHERE id='2165659';
UPDATE questoes SET resolution='{"cobranca": "Identificação de princípios orçamentários", "regra": "A alternativa C reúne princípios reconhecidos na abordagem de princípios orçamentários do MCASP, incluindo universalidade, orçamento bruto, exclusividade, legalidade e publicidade.", "passos": ["1) Verifique cada conjunto.", "2) A alternativa C contém apenas princípios orçamentários: universalidade, orçamento bruto, exclusividade, legalidade e publicidade.", "3) As demais misturam princípios orçamentários com características/qualidades da informação contábil, como relevância, comparabilidade, compreensibilidade, conservadorismo e tempestividade.", "4) Portanto, C é a correta."], "calculo": "", "correta": "C) Universalidade, Orçamento bruto, Exclusividade, Legalidade, Publicidade.", "erradas": ["A) mistura princípios orçamentários com relevância e compreensibilidade, ligadas à informação contábil.", "B) mistura publicidade com comparabilidade e repete legalidade.", "D) reúne características qualitativas/contábeis, não a lista pedida de princípios orçamentários.", "E) mistura exclusividade com relevância e conservadorismo."], "fundamento": "MCASP, Parte I — Procedimentos Contábeis Orçamentários, seção de princípios orçamentários.", "pegadinha": "A banca mistura princípios orçamentários com características qualitativas da informação contábil. Identifique o “intruso” em cada alternativa."}'::jsonb WHERE id='916303';
UPDATE questoes SET resolution='{"cobranca": "Princípios da anualidade, exclusividade, unidade/totalidade e universalidade", "regra": "A alternativa A descreve corretamente a anualidade ou periodicidade: o orçamento é elaborado e autorizado para um período determinado, em regra o exercício financeiro, com previsão constitucional.", "passos": ["1) A alternativa A associa anualidade à elaboração e autorização do orçamento para período determinado.", "2) Isso corresponde ao princípio da anualidade/periodicidade.", "3) B está incorreta porque a exceção constitucional abrange a autorização para abertura de créditos suplementares e contratação de operações de crédito, inclusive por antecipação de receita; a redação da alternativa restringe indevidamente a exceção.", "4) C e D trocam unidade e universalidade; E apresenta incorretamente a não vinculação de impostos."], "calculo": "", "correta": "A) A anualidade ou periodicidade é a elaboração e autorização do orçamento para determinado período, normalmente o exercício financeiro.", "erradas": ["B) A redação não reproduz corretamente o alcance da exceção do art. 165, §8º.", "C) A descrição dada é de universalidade, não de unidade/totalidade.", "D) A descrição mistura unidade e universalidade.", "E) A não vinculação de impostos não significa reservar sua utilização apenas à remuneração de servidores."], "fundamento": "CF, art. 165; Lei nº 4.320/1964, arts. 2º e 34; CF, art. 165, §8º.", "pegadinha": "A questão exige distinguir “um orçamento” (unidade/totalidade), “todas as receitas e despesas” (universalidade) e “um período” (anualidade)."}'::jsonb WHERE id='990583';
UPDATE questoes SET resolution='{"cobranca": "Princípio da unidade ou totalidade", "regra": "Unidade ou totalidade determina um orçamento único para cada ente federativo, reunindo as previsões e autorizações orçamentárias no documento legal correspondente.", "passos": ["1) O enunciado usa a expressão “orçamento deve ser único para cada ente”.", "2) Essa é a definição direta de unidade ou totalidade.", "3) A questão ainda explica que as receitas previstas e despesas fixadas integram uma única LOA.", "4) Portanto, A é correta."], "calculo": "", "correta": "A) Totalidade.", "erradas": ["B) Exclusividade — limita o conteúdo da LOA.", "C) Anualidade — delimita o período.", "D) Transparência — relaciona-se à divulgação.", "E) Universalidade — exige abrangência de todas as receitas e despesas."], "fundamento": "Lei nº 4.320/1964, art. 2º; MCASP, Unidade ou Totalidade.", "pegadinha": "“Único” = unidade/totalidade; “todos” = universalidade."}'::jsonb WHERE id='1335919';
UPDATE questoes SET resolution='{"cobranca": "Princípio da unidade", "regra": "A unidade determina que cada ente federado possua seu próprio orçamento, evitando múltiplos orçamentos paralelos dentro da mesma pessoa política.", "passos": ["1) Procure a alternativa que descreve um único orçamento para cada ente.", "2) A alternativa B traz exatamente essa regra.", "3) A é orçamento bruto; C é universalidade; D é anualidade; E mistura unidade e exclusividade.", "4) Logo, B é a resposta."], "calculo": "", "correta": "B) Cada ente federado deve ter seu próprio orçamento, evitando múltiplos orçamentos paralelos dentro da mesma pessoa política.", "erradas": ["A) Orçamento bruto.", "C) Universalidade.", "D) Anualidade.", "E) Combina conceitos de unidade e exclusividade, não sendo a definição pedida."], "fundamento": "Lei nº 4.320/1964, art. 2º; MCASP, Unidade ou Totalidade.", "pegadinha": "A expressão “seu próprio orçamento” aqui significa um orçamento único dentro de cada ente, não vários orçamentos paralelos."}'::jsonb WHERE id='1336829';
UPDATE questoes SET resolution='{"cobranca": "Princípios orçamentários — Lei nº 4.320/1964", "regra": "O art. 2º da Lei nº 4.320/1964 determina que a Lei do Orçamento obedeça aos princípios de unidade, universalidade e anualidade.", "passos": ["1) A questão pede a alternativa correta.", "2) A alternativa E reproduz a estrutura do art. 2º da Lei nº 4.320/1964.", "3) A, B, C e D trocam as definições dos princípios.", "4) Portanto, E é correta."], "calculo": "", "correta": "E) A Lei de Orçamento conterá discriminação da receita e da despesa, atendidos os princípios de unidade, universalidade e anualidade.", "erradas": ["A) Exclusividade não significa orçamento uno.", "B) Unidade não trata da classificação detalhada das despesas.", "C) Universalidade não é publicidade.", "D) Transparência não define a periodicidade das previsões."], "fundamento": "Lei nº 4.320/1964, art. 2º.", "pegadinha": "A questão pede uma regra legal literal. Quando aparecer “Lei nº 4.320/1964, art. 2º”, associe imediatamente unidade, universalidade e anualidade."}'::jsonb WHERE id='1336832';
UPDATE questoes SET resolution='{"cobranca": "Associação dos princípios unidade, universalidade, exclusividade e orçamento bruto", "regra": "A sequência correta é: orçamento bruto = D; exclusividade = C; universalidade = B; unidade = A.", "passos": ["1) Valor total, sem deduções → orçamento bruto (D).", "2) Dispositivo estranho à receita/despesa → exclusividade (C).", "3) Todas as receitas e despesas → universalidade (B).", "4) Orçamento único por ente → unidade (A). A sequência D-C-B-A corresponde à alternativa D."], "calculo": "", "correta": "D) D, C, B, A.", "erradas": ["A) A-B-C-D — sequência incompatível com as definições.", "B) A-C-B-D — troca orçamento bruto e unidade.", "C) D-B-C-A — troca exclusividade e universalidade."], "fundamento": "Lei nº 4.320/1964, arts. 2º e 6º; CF, art. 165, §8º; MCASP.", "pegadinha": "Resolva pela palavra-chave de cada linha antes de olhar as alternativas. Isso reduz o risco de inverter universalidade e exclusividade."}'::jsonb WHERE id='1054621';
UPDATE questoes SET resolution='{"cobranca": "Princípio da exclusividade — art. 165, §8º, da Constituição", "regra": "A exclusividade impede que a lei orçamentária seja usada para inserir matérias absolutamente estranhas ao conteúdo orçamentário, ressalvadas as exceções constitucionais.", "passos": ["1) A alternativa A relaciona exclusividade ao art. 165, §8º.", "2) O objetivo é impedir matéria estranha à previsão da receita e à fixação da despesa.", "3) B é falsa porque o princípio possui exceções expressas.", "4) C é falsa porque universalidade exige abrangência das receitas e despesas. D é falsa porque programação não elimina objetivos e metas."], "calculo": "", "correta": "A) Com o princípio da exclusividade, positivado no art. 165, §8º, busca-se afastar a inserção de matérias absolutamente estranhas ao direito financeiro/orçamentário na lei orçamentária.", "erradas": ["B) Falsa: há exceções expressas no §8º do art. 165.", "C) Falsa: a universalidade exige a abrangência das receitas e despesas.", "D) Falsa: o orçamento não se resume a simples estimativas; a programação orçamentária envolve objetivos e ações."], "fundamento": "Constituição Federal, art. 165, §8º.", "pegadinha": "A palavra “nenhuma” em B torna a alternativa suspeita: a Constituição prevê expressamente exceções à exclusividade."}'::jsonb WHERE id='563460';
UPDATE questoes SET resolution='{"cobranca": "Princípio da anualidade/periodicidade", "regra": "A anualidade determina que o orçamento seja aprovado para um período determinado. A periodicidade também funciona como mecanismo de controle porque a autorização orçamentária é renovada periodicamente, permitindo acompanhamento pelo Legislativo e pela sociedade.", "passos": ["1) Primeira afirmativa: a Constituição e a Lei nº 4.320/1964 adotam a anualidade/periodicidade do orçamento → verdadeira.", "2) Segunda afirmativa: a periodicidade da autorização favorece o controle e o diálogo institucional → verdadeira.", "3) A segunda explica a função de controle associada à periodicidade da autorização.", "4) Portanto, o gabarito C — ambas verdadeiras e a segunda justifica a primeira."], "calculo": "", "correta": "C) As duas afirmativas são verdadeiras e a segunda justifica a primeira.", "erradas": ["A) Falsa porque a segunda também é verdadeira.", "B) Falsa porque as duas afirmativas não são falsas.", "D) Falsa porque, no enquadramento adotado pela questão, a segunda funciona como justificativa da periodicidade."], "fundamento": "Lei nº 4.320/1964, art. 2º e art. 34; Constituição Federal, sistema orçamentário.", "pegadinha": "Em questões de “asserção e razão”, não basta as duas serem verdadeiras: é preciso verificar se a segunda explica a primeira. Aqui, o vínculo é a função de controle da periodicidade."}'::jsonb WHERE id='563612';
UPDATE questoes SET resolution='{"cobranca": "Princípio da exclusividade", "regra": "A LOA não deve conter matéria estranha à previsão da receita e à fixação da despesa. A Constituição admite duas exceções expressas: autorização para abertura de créditos suplementares e autorização para contratação de operações de crédito, inclusive por antecipação de receita, nos termos da lei.", "passos": ["1) O comando pede a alternativa INCORRETA.", "2) B descreve corretamente a regra geral da exclusividade.", "3) C afirma que existe apenas uma exceção. Isso está errado, porque há duas exceções constitucionais.", "4) D reconhece as duas exceções. Portanto, a incorreta é C."], "calculo": "Não há cálculo.", "correta": "C) É a incorreta: o princípio da exclusividade possui duas exceções, não apenas a autorização para crédito suplementar.", "erradas": ["A) Compatível com a natureza da LOA.", "B) Correta quanto à regra geral.", "D) Correta ao mencionar duas exceções."], "fundamento": "Constituição Federal, art. 165, § 8º; Lei nº 4.320/1964.", "pegadinha": "A palavra-chave é “única”. A questão tenta fazer o candidato esquecer a segunda exceção: operações de crédito.", "verificacao": "A redação da alternativa C é incompatível com o § 8º do art. 165 da CF."}'::jsonb WHERE id='563078';
UPDATE questoes SET resolution='{"cobranca": "Princípios orçamentários", "regra": "Universalidade determina que a LOA contenha todas as receitas e despesas abrangidas pelo orçamento, ressalvadas as especificidades constitucionais e legais.", "passos": ["1) A alternativa D descreve a universalidade.", "2) Equilíbrio não é o princípio que significa “todas as receitas e despesas”.", "3) Unidade/totalidade trata da existência de orçamento único por ente.", "4) Orçamento bruto exige receitas e despesas pelos seus valores totais, sem deduções."], "calculo": "Não há cálculo.", "correta": "D) Universalidade.", "erradas": ["A) Descreve universalidade, não equilíbrio.", "B) Descreve exclusividade, não unidade.", "C) Descreve orçamento bruto, não exclusividade."], "fundamento": "Lei nº 4.320/1964, arts. 2º e 3º; Constituição Federal, art. 165.", "pegadinha": "Confundir universalidade, unidade, exclusividade e orçamento bruto — quatro princípios cobrados juntos com frequência."}'::jsonb WHERE id='563624';
UPDATE questoes SET resolution='{"cobranca": "Princípios orçamentários", "regra": "Entre os princípios orçamentários reconhecidos no MCASP estão unidade/totalidade, universalidade, anualidade/periodicidade, exclusividade, orçamento bruto, publicidade/transparência e legalidade, entre outros.", "passos": ["1) Elimine alternativas que misturam princípios orçamentários com princípios gerais da contabilidade ou conceitos de outra natureza.", "2) A alternativa B traz somente Universalidade, Unidade, Exclusividade e Transparência.", "3) Os quatro são princípios orçamentários."], "calculo": "Não há cálculo.", "correta": "B) Universalidade, Unidade, Exclusividade, Transparência.", "erradas": ["A) Entidade não é, nessa lista, princípio orçamentário.", "C) Competência é princípio contábil, não princípio orçamentário.", "D) Oportunidade não integra essa combinação de princípios orçamentários."], "fundamento": "MCASP, capítulo de princípios orçamentários; Lei nº 4.320/1964 e Constituição Federal.", "pegadinha": "A banca mistura princípios contábeis com orçamentários para induzir o candidato ao erro."}'::jsonb WHERE id='567261';
UPDATE questoes SET resolution='{"cobranca": "Classificação dos princípios orçamentários", "regra": "Exclusividade = LOA sem matéria estranha, com exceções; universalidade = todas as receitas e despesas; unidade/totalidade = orçamento único; anualidade/periodicidade = exercício financeiro delimitado.", "passos": ["1) Primeiro enunciado: exclusividade → D.", "2) Segundo: todas as receitas e despesas → universalidade → B.", "3) Terceiro: orçamento único → unidade/totalidade → A.", "4) Quarto: exercício financeiro coincidente com o ano civil → anualidade/periodicidade → C.", "5) Sequência D, B, A, C corresponde à alternativa B."], "calculo": "Não há cálculo.", "correta": "B) D, B, A, C.", "erradas": ["A) Troca a sequência inicial.", "C) Começa por anualidade, mas o primeiro conceito é exclusividade.", "D) Coloca universalidade na terceira descrição, que é unidade."], "fundamento": "Constituição Federal, art. 165, § 8º; Lei nº 4.320/1964, arts. 2º e 34.", "pegadinha": "A questão exige reconhecer o conceito antes de olhar as letras. Memorizar apenas a sequência pode levar a erro quando a ordem muda."}'::jsonb WHERE id='1058521';
UPDATE questoes SET resolution='{"cobranca": "Princípio da publicidade", "regra": "A publicidade é princípio constitucional da Administração Pública e exige divulgação dos atos administrativos, permitindo transparência e controle social.", "passos": ["1) O enunciado relaciona o regime democrático à divulgação pública.", "2) O art. 37, caput, da CF inclui a publicidade entre os princípios da Administração Pública.", "3) Portanto, a alternativa correspondente é Publicidade."], "calculo": "Não há cálculo.", "correta": "D) Publicidade.", "erradas": ["A) Universalidade trata da abrangência das receitas e despesas.", "B) Exclusividade trata do conteúdo permitido na LOA.", "C) Legalidade trata da atuação conforme a lei."], "fundamento": "Constituição Federal, art. 37, caput.", "pegadinha": "A banca usa o contexto orçamentário, mas a pista decisiva está em “divulgação pública”."}'::jsonb WHERE id='3013725';
UPDATE questoes SET resolution='{"cobranca": "Princípios orçamentários", "regra": "Publicidade exige divulgação dos atos e leis orçamentárias. Exclusividade impede matéria estranha à LOA, equilíbrio não significa despesas maiores que receitas e especificação detalha receitas e despesas.", "passos": ["1) A alternativa A descreve justamente o contrário da exclusividade.", "2) B está errada porque equilíbrio não significa despesas superiores às receitas.", "3) C está errada porque especificação não significa escolher entre previsão de receita ou fixação de despesa.", "4) D está correta: publicidade exige divulgação pública."], "calculo": "Não há cálculo.", "correta": "D) O princípio da publicidade determina que a lei orçamentária seja divulgada e acessível publicamente.", "erradas": ["A) Inverte a regra da exclusividade.", "B) Inverte o sentido do equilíbrio.", "C) Descreve incorretamente a especificação."], "fundamento": "Constituição Federal, art. 37, caput; Lei nº 4.320/1964; MCASP.", "pegadinha": "A alternativa D é a única que relaciona corretamente publicidade com divulgação e acesso público."}'::jsonb WHERE id='923513';
UPDATE questoes SET resolution='{"cobranca": "Balanço Orçamentário / resultado orçamentário", "regra": "O resultado orçamentário é obtido comparando a receita orçamentária realizada com a despesa orçamentária empenhada, conforme a estrutura do Balanço Orçamentário. Operações extraorçamentárias não entram nessa comparação.", "passos": ["1) Receita arrecadada = R$ 23.800.000.", "2) Despesa orçamentária anual = R$ 22.750.000.", "3) Resultado = 23.800.000 − 22.750.000 = R$ 1.050.000 de superávit.", "4) Nenhuma alternativa apresenta R$ 1.050.000.", "5) Portanto, há inconsistência entre os dados transcritos e o gabarito/alternativas."], "calculo": "R$ 23.800.000 − R$ 22.750.000 = R$ 1.050.000 de superávit.", "correta": "Os dados transcritos não permitem confirmar a alternativa E (R$ 540.000). Pelo cálculo direto do resultado orçamentário com os valores apresentados, o resultado é superávit de R$ 1.050.000.", "erradas": ["A) R$ 810.000 não resulta da diferença entre receita arrecadada e despesa orçamentária informadas.", "B) R$ 320.000 não resulta dos dados.", "C) R$ 320.000 também não.", "D) R$ 540.000 de déficit não decorre dos dados.", "E) R$ 540.000 de superávit não decorre dos dados apresentados."], "fundamento": "Lei nº 4.320/1964; MCASP, Balanço Orçamentário.", "pegadinha": "Não misturar restos a pagar, cauções e ARO no resultado orçamentário. Aqui, porém, mesmo isolando a execução orçamentária, os números fornecidos não fecham com as alternativas.", "verificacao": "Conferir a imagem/PDF original da questão 3936137; pode haver valor transcrito incorretamente no material extraído."}'::jsonb WHERE id='3936137';
UPDATE questoes SET resolution='{"cobranca": "Balanço Orçamentário", "regra": "O Balanço Orçamentário evidencia as receitas por categoria econômica, confrontando previsão e realização, e as despesas por categorias, confrontando fixação e execução.", "passos": ["1) O enunciado fala em receitas previstas e realizadas.", "2) Também fala em despesas fixadas e executadas.", "3) Essa é a finalidade do Balanço Orçamentário."], "calculo": "Não há cálculo.", "correta": "B) Balanço Orçamentário.", "erradas": ["A) Balanço Financeiro evidencia ingressos e dispêndios e saldos financeiros.", "C) RREO é relatório fiscal, não a demonstração contábil descrita.", "D) Balanço Patrimonial evidencia ativos, passivos e patrimônio líquido/saldo patrimonial.", "E) DVP evidencia variações patrimoniais aumentativas e diminutivas."], "fundamento": "Lei nº 4.320/1964, art. 102; MCASP, DCASP.", "pegadinha": "A expressão “previstas x realizadas” + “fixadas x executadas” identifica o Balanço Orçamentário."}'::jsonb WHERE id='4074897';
UPDATE questoes SET resolution='{"cobranca": "Balanço Orçamentário — Saldos de Exercícios Anteriores", "regra": "No Quadro Principal do Balanço Orçamentário, a linha “Saldos de Exercícios Anteriores” evidencia recursos de exercícios anteriores utilizados para abertura/reabertura de créditos adicionais, conforme a estrutura do MCASP.", "passos": ["1) Crédito especial reaberto: R$ 35.000 → entra como saldo de exercício anterior utilizado.", "2) Superávit financeiro utilizado como fonte: R$ 120.000 → entra.", "3) Recursos arrecadados em exercícios anteriores/fundos específicos disponíveis: R$ 40.000 → conforme o enunciado, compõem os saldos de exercícios anteriores reportados.", "4) Reserva de contingência de 2025 não é saldo de exercício anterior.", "5) Restos a pagar processados inscritos em 2025 também não compõem essa linha.", "6) Soma: 35.000 + 120.000 + 40.000 = R$ 195.000."], "calculo": "R$ 35.000 + R$ 120.000 + R$ 40.000 = R$ 195.000.", "correta": "E) R$ 195.000,00.", "erradas": ["A) Inclui valores que não devem ser somados à linha.", "B) Não considera corretamente todos os recursos de exercícios anteriores.", "C) Omite o crédito especial reaberto.", "D) Também incorpora valor indevido."], "fundamento": "MCASP 11ª edição — Balanço Orçamentário, Quadro Principal.", "pegadinha": "Não somar reserva de contingência nem restos a pagar como se fossem “saldo de exercício anterior”."}'::jsonb WHERE id='4098504';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — Ativo e Passivo Financeiro/Permanente", "regra": "O Passivo Financeiro não é formado exclusivamente por obrigações decorrentes de créditos adicionais. Pela Lei nº 4.320/1964, ele compreende compromissos exigíveis cujo pagamento independa de autorização orçamentária.", "passos": ["1) A, B e C reproduzem conceitos compatíveis com a classificação legal tradicional.", "2) D afirma que o Passivo Financeiro é composto exclusivamente por obrigações objeto de crédito adicional.", "3) Isso é falso: a classificação decorre da exigibilidade e da independência de autorização orçamentária, não da existência de crédito adicional."], "calculo": "Não há cálculo.", "correta": "D) É a alternativa INCORRETA.", "erradas": ["A) Compatível com a definição legal do passivo permanente.", "B) Compatível com o ativo financeiro.", "C) Compatível com a definição de ativo permanente na estrutura da Lei nº 4.320/1964."], "fundamento": "Lei nº 4.320/1964, arts. 105 e 106.", "pegadinha": "A banca troca o critério de classificação do Passivo Financeiro por uma suposta origem em crédito adicional."}'::jsonb WHERE id='3598405';
UPDATE questoes SET resolution='{"cobranca": "Avaliação e mensuração — reavaliação do ativo", "regra": "Reavaliação é a adoção do valor de mercado ou de consenso entre as partes para ativos, quando permitida pelas normas. A mensuração subsequente possui regras específicas para depreciação acumulada e efeitos no patrimônio.", "passos": ["1) A define reavaliação como adoção de valor de mercado ou consenso entre as partes → correta.", "2) B descreve um tratamento que não deve ser generalizado dessa forma para todos os casos de reavaliação.", "3) C também está incorreta porque uma diminuição pode ser reconhecida contra eventual reserva de reavaliação até o limite existente, conforme a situação.", "4) D é absoluta ao afirmar que intangíveis nunca podem ser reavaliados, o que não corresponde à norma quando existe mercado ativo."], "calculo": "Não há cálculo.", "correta": "A) Reavaliação é a adoção do valor de mercado ou de consenso entre as partes para bens do ativo.", "erradas": ["B) Generaliza o procedimento de eliminação da depreciação acumulada.", "C) Ignora o tratamento contra eventual reserva existente.", "D) É absoluta: a possibilidade depende da existência de mercado ativo e das condições normativas."], "fundamento": "MCASP, capítulo de avaliação e mensuração; NBC TSP aplicáveis ao ativo imobilizado e intangível.", "pegadinha": "Cuidado com alternativas absolutas como “em nenhuma hipótese”."}'::jsonb WHERE id='3599091';
UPDATE questoes SET resolution='{"cobranca": "PPA, LDO e LOA — Constituição Federal", "regra": "A LDO orienta a elaboração da LOA e dispõe sobre alterações na legislação tributária e política de aplicação das agências financeiras oficiais de fomento. A LOA pode autorizar créditos suplementares, respeitados os requisitos legais. O PPA possui vigência de quatro anos.", "passos": ["1) I está incorreta porque os prazos constitucionais de encaminhamento do PPA não correspondem ao texto apresentado.", "2) II está correta: art. 165, § 2º, inclui alterações na legislação tributária e política de aplicação das agências oficiais de fomento.", "3) III está correta: a LOA pode conter autorização para abertura de créditos suplementares e deve respeitar a exclusividade.", "4) Logo, somente II e III estão corretas."], "calculo": "Não há cálculo.", "correta": "C) II e III, apenas.", "erradas": ["A) Incorreta porque II também é verdadeira.", "B) Incorreta porque I é falsa.", "D) Incorreta porque I é falsa.", "E) Incorreta porque I é falsa."], "fundamento": "Constituição Federal, art. 165, §§ 2º, 5º e 8º.", "pegadinha": "Atenção aos prazos constitucionais do PPA: a questão usa um prazo incorreto na afirmativa I."}'::jsonb WHERE id='3936167';
UPDATE questoes SET resolution='{"cobranca": "PPA, LDO e LOA — regras constitucionais", "regra": "A LDO estabelece metas e prioridades e orienta a LOA; pode tratar de alterações tributárias e política de aplicação das agências oficiais. A Constituição também prevê autorização específica na LDO para determinadas despesas com pessoal, ressalvadas as empresas públicas e sociedades de economia mista. A LOA compreende orçamento fiscal, orçamento de investimento das empresas em que a União detenha maioria do capital votante e orçamento da seguridade social.", "passos": ["1) A está errada: investimentos plurianuais podem aparecer no planejamento e a anualidade não impede a continuidade de investimentos.", "2) B está errada porque a LDO pode tratar de alterações na legislação tributária e política de aplicação das agências.", "3) C reproduz o art. 169, § 1º, da CF, ressalvando empresas públicas e sociedades de economia mista.", "4) D está errada porque a LOA federal inclui o orçamento de investimento das empresas controladas pela União.", "5) E está errada ao descrever de forma incorreta a duração/intercalação do PPA."], "calculo": "Não há cálculo.", "correta": "C) A autorização específica na LDO é exigida nas hipóteses constitucionais de pessoal, com a ressalva indicada.", "erradas": ["A) Anualidade não elimina a programação plurianual.", "B) A LDO pode tratar dos dois temas citados.", "D) O orçamento de investimento integra a LOA nos termos constitucionais.", "E) O PPA tem quatro anos, mas não funciona pela “intercalação” descrita."], "fundamento": "Constituição Federal, arts. 165 e 169, § 1º.", "pegadinha": "A banca usa negativas absolutas (“não é possível”) e troca a composição da LOA para testar detalhes constitucionais."}'::jsonb WHERE id='3937563';
UPDATE questoes SET resolution='{"cobranca": "Função da LOA", "regra": "A Lei Orçamentária Anual estima as receitas e fixa as despesas para o exercício financeiro.", "passos": ["1) A reduz o PPA a um ano, o que está errado.", "2) B trata o orçamento como instrumento apenas contábil, ignorando sua função de planejamento.", "3) C atribui à LDO a função detalhada de fixar todas as despesas, que é da LOA.", "4) D corresponde à definição constitucional/legal da LOA.", "5) E também está errada porque LDO não substitui PPA."], "calculo": "Não há cálculo.", "correta": "D) A LOA estima as receitas e fixa as despesas para o exercício financeiro.", "erradas": ["A) Função de médio prazo é do PPA.", "B) Orçamento também é instrumento de planejamento e gestão.", "C) A LDO orienta a elaboração da LOA; não substitui sua função de fixação detalhada da despesa.", "E) PPA e LDO têm funções distintas."], "fundamento": "Constituição Federal, art. 165; Lei nº 4.320/1964.", "pegadinha": "Memorize a tríade: PPA = diretrizes, objetivos e metas; LDO = metas/prioridades e orientação; LOA = estima receita e fixa despesa."}'::jsonb WHERE id='4092795';
UPDATE questoes SET resolution='{"cobranca": "Demonstração das Variações Patrimoniais — resultado patrimonial", "regra": "Na DVP, o resultado patrimonial decorre da diferença entre Variações Patrimoniais Aumentativas (VPA) e Variações Patrimoniais Diminutivas (VPD).", "passos": ["1) Exercício atual: VPD = R$ 16.000.000 e resultado = R$ 2.000.000. Logo, VPA atual = R$ 18.000.000.", "2) Exercício anterior: VPA = R$ 15.500.000 e resultado = R$ 3.500.000. Logo, VPD anterior = R$ 12.000.000.", "3) Variação absoluta da VPA = 18,0 − 15,5 = R$ 2,5 milhões.", "4) Variação absoluta da VPD = 16,0 − 12,0 = R$ 4,0 milhões.", "5) A VPD apresentou maior variação absoluta, contribuindo para a queda do resultado de R$ 3,5 milhões para R$ 2,0 milhões."], "calculo": "VPA atual = 16.000.000 + 2.000.000 = R$ 18.000.000; VPD anterior = 15.500.000 − 3.500.000 = R$ 12.000.000; variação VPA = R$ 2,5 mi; variação VPD = R$ 4,0 mi.", "correta": "D) As VPDs apresentaram maior variação absoluta do que as VPAs no exercício atual em relação ao anterior, justificando a queda no resultado patrimonial.", "erradas": ["A) Não há dados que permitam atribuir a queda a variações qualitativas.", "B) Economia orçamentária não é automaticamente redução de VPD patrimonial.", "C) A DVP não permite concluir “frustração generalizada” de anuidades.", "E) É falsa: a VPA atual foi R$ 18 milhões, maior que os R$ 15,5 milhões anteriores."], "fundamento": "MCASP 11ª edição — Demonstração das Variações Patrimoniais.", "pegadinha": "Não confundir resultado orçamentário com resultado patrimonial; a DVP trabalha com VPA e VPD."}'::jsonb WHERE id='4098545';
UPDATE questoes SET resolution='{"cobranca": "Balanço Financeiro — ingressos extraorçamentários", "regra": "Ingressos extraorçamentários incluem, entre outros, depósitos/cauções, operações de crédito por antecipação da receita e inscrição de restos a pagar. Pagamentos de restos a pagar são dispêndios extraorçamentários, não ingressos.", "passos": ["1) ARO = R$ 270.000 → ingresso extraorçamentário.", "2) Cauções = R$ 80.000 → ingresso extraorçamentário.", "3) Restos a pagar processados inscritos = R$ 380.000 → ingresso extraorçamentário.", "4) Restos a pagar não processados inscritos = R$ 130.000 → ingresso extraorçamentário.", "5) RP de 2023 pagos = R$ 200.000 → dispêndio extraorçamentário, portanto não entra nos ingressos.", "6) Soma = 270.000 + 80.000 + 380.000 + 130.000 = R$ 860.000."], "calculo": "R$ 270.000 + R$ 80.000 + R$ 380.000 + R$ 130.000 = R$ 860.000.", "correta": "D) R$ 860.000,00.", "erradas": ["A) Inclui/exclui valores de forma incompatível com a estrutura do BF.", "B) R$ 350.000 corresponde apenas a parte dos ingressos.", "C) R$ 480.000 não considera todos os restos a pagar inscritos.", "E) R$ 780.000 não corresponde à soma dos ingressos extraorçamentários."], "fundamento": "Lei nº 4.320/1964, art. 103; MCASP — Balanço Financeiro.", "pegadinha": "Inscrição de RP entra como ingresso extraorçamentário; pagamento de RP entra como dispêndio extraorçamentário."}'::jsonb WHERE id='3936135';
UPDATE questoes SET resolution='{"cobranca": "Balanço Financeiro — classes do PCASP", "regra": "A execução da receita e da despesa orçamentária no Balanço Financeiro é obtida das contas da classe 6, ligada aos controles da execução do planejamento e orçamento. As informações patrimoniais relacionadas a ingressos/pagamentos extraorçamentários e saldos em espécie são obtidas conforme as contas patrimoniais pertinentes.", "passos": ["1) I está correta: a execução orçamentária é evidenciada com base na classe 6.", "2) II está correta no enquadramento adotado pela questão para ingressos/pagamentos extraorçamentários e saldos em espécie.", "3) III é falsa: classes 3 e 4 registram VPD e VPA, não substituem as classes patrimoniais para caixa.", "4) IV é falsa: classes 7 e 8 são de controle, não registram diretamente a execução orçamentária como afirmado.", "5) Portanto, I e II estão corretas."], "calculo": "Não há cálculo.", "correta": "C) I e II, apenas.", "erradas": ["A) III e IV são falsas.", "B) III é falsa.", "D) II também está correta.", "E) I também está correta."], "fundamento": "MCASP 11ª edição; PCASP — classes e natureza das informações contábeis.", "pegadinha": "Memorize as classes: 1 e 2 = patrimoniais; 3 e 4 = VPD/VPA; 5 e 6 = controles da execução orçamentária; 7 e 8 = controles."}'::jsonb WHERE id='4074895';
UPDATE questoes SET resolution='{"cobranca": "Tipos de empenho", "regra": "Empenho global é adequado a despesas contratuais e parceladas de valor determinado; empenho ordinário a despesa cujo valor é conhecido e pago de uma vez; empenho estimativo a despesas cujo montante não pode ser previamente determinado.", "passos": ["1) Aluguel anual fixo de R$ 240.000, pago mensalmente → empenho global.", "2) Material de escritório com valor total conhecido e pagamento único → empenho ordinário.", "3) Água e energia com valor variável → empenho estimativo.", "4) A sequência é Global, Ordinário, Estimativo."], "calculo": "Aluguel anual: 12 × R$ 20.000 = R$ 240.000, valor determinado e parcelado → global.", "correta": "E) Despesa 1: Global; Despesa 2: Ordinário; Despesa 3: Estimativo.", "erradas": ["A) Troca global por estimativo na despesa 1.", "B) Troca ordinário/estimativo.", "C) Troca as três classificações.", "D) Trata a aquisição como global, embora o pagamento seja único."], "fundamento": "Lei nº 4.320/1964, art. 60; classificação tradicional dos tipos de empenho.", "pegadinha": "O fato de uma despesa ser paga mensalmente não a torna estimativa se o valor contratual total é determinado."}'::jsonb WHERE id='3435208';
UPDATE questoes SET resolution='{"cobranca": "Tipos de empenho", "regra": "Contrato anual com valor fixo e pagamento parcelado → global; aquisição com valor certo e pagamento integral → ordinário; serviço de consumo variável → estimativo.", "passos": ["1) Aluguel anual de R$ 102.000, pago mensalmente → global.", "2) Cadeiras por R$ 18.000, pagamento integral na entrega → ordinário.", "3) Telefonia variável → estimativo.", "4) A sequência corresponde à alternativa C."], "calculo": "R$ 8.500 × 12 = R$ 102.000; valor global conhecido e parcelado.", "correta": "C) Global; Ordinário; Estimativo.", "erradas": ["A) Classifica o aluguel como ordinário e a compra como estimativa.", "B) Inverte as três classificações.", "D) Classifica a compra como global, embora o pagamento seja integral."], "fundamento": "Lei nº 4.320/1964, art. 60; conceitos de empenho global, ordinário e estimativo.", "pegadinha": "O critério é valor determinado/parcelamento versus valor indeterminado, não simplesmente a periodicidade do pagamento."}'::jsonb WHERE id='3598399';
UPDATE questoes SET resolution='{"cobranca": "Estágios da despesa pública", "regra": "A execução da despesa passa por empenho, liquidação e pagamento. A liquidação verifica o direito adquirido pelo credor com base nos documentos e na prestação/entrega. O pagamento ocorre após a regular liquidação. Empenho estimativo é usado quando o montante não pode ser previamente determinado.", "passos": ["1) Primeira afirmativa: verdadeira no sentido adotado pela questão — o empenho reserva dotação e cria compromisso para o ente.", "2) Segunda: falsa, pois liquidação ocorre antes do pagamento.", "3) Terceira: verdadeira, pois pagamento depende da liquidação.", "4) Quarta: falsa, pois equipamento com valor global determinado não é despesa estimativa.", "5) Sequência V, F, V, F → alternativa C."], "calculo": "Não há cálculo.", "correta": "C) V, F, V, F.", "erradas": ["A) Considera a primeira ou a terceira falsa, contrariando a sequência.", "B) Trata a liquidação como posterior ao pagamento.", "D) Considera correta a utilização de empenho estimativo para valor previamente determinado."], "fundamento": "Lei nº 4.320/1964, arts. 58, 62 e 63.", "pegadinha": "A ordem é EMPENHO → LIQUIDAÇÃO → PAGAMENTO. A liquidação nunca vem depois do pagamento."}'::jsonb WHERE id='3598421';
UPDATE questoes SET resolution='{"cobranca": "Estágios da despesa pública", "regra": "A sequência ordinária é empenho → liquidação → pagamento. A liquidação verifica o direito adquirido pelo credor com base nos títulos e documentos comprobatórios e na entrega/prestação efetivamente realizada.", "passos": ["1) Item I: houve apenas empenho; sem entrega ou comprovação, ainda não há liquidação.", "2) Item II: a entrega foi atestada e a nota fiscal conferida, caracterizando a liquidação; o pagamento ainda não ocorreu.", "3) Item III: o serviço foi prestado e comprovado, com documentação atestada; isso caracteriza liquidação.", "4) Item IV: a quitação bancária representa pagamento, posterior ao empenho e à liquidação.", "5) Logo, a afirmativa correta é a III: alternativa D."], "calculo": "Não há cálculo.", "correta": "D) O item III está na fase de liquidação.", "erradas": ["A) Entrega não significa pagamento; o pagamento é a etapa posterior à liquidação.", "B) Pagamento não caracteriza “em liquidação”; é a etapa final da execução da despesa.", "C) Empenho, isoladamente, não equivale à liquidação."], "fundamento": "Lei nº 4.320/1964, arts. 58, 62 e 63.", "pegadinha": "A FAFIPA pode misturar “entrega”, “liquidação” e “pagamento”. A entrega/prestação comprovada permite a liquidação; o pagamento vem depois."}'::jsonb WHERE id='3598446';
UPDATE questoes SET resolution='{"cobranca": "Tipos de empenho", "regra": "Empenho ordinário é usado para despesa de valor determinado e pagamento único; global, para despesas contratuais sujeitas a parcelamento; estimativo, quando o valor não pode ser previamente determinado.", "passos": ["1) Despesa 1: aluguel anual de R$ 120.000,00, com valor contratual fixo e pagamentos mensais → empenho global.", "2) Despesa 2: 50 cadeiras por R$ 25.000,00, pagamento integral na entrega → empenho ordinário.", "3) Despesa 3: energia elétrica varia conforme o consumo mensal → empenho estimativo.", "4) Sequência global, ordinário, estimativo → alternativa E."], "calculo": "Não há cálculo; a classificação decorre da natureza e da previsibilidade do valor/pagamento.", "correta": "E) Despesa 1: Global; Despesa 2: Ordinário; Despesa 3: Estimativo.", "erradas": ["A) Inverte global/estimativo para despesas que têm valor fixo ou variável.", "B) Trata uma aquisição de pagamento único como empenho global.", "C) Classifica a energia, de valor variável, como global.", "D) Classifica a compra de valor determinado como estimativa."], "fundamento": "Lei nº 4.320/1964, art. 60, §§ 2º e 3º.", "pegadinha": "Valor fixo com pagamentos parcelados aponta para global; valor certo e pagamento único, ordinário; valor não determinável, estimativo."}'::jsonb WHERE id='3930706';
UPDATE questoes SET resolution='{"cobranca": "Classificação da despesa – amortização da dívida", "regra": "Na classificação econômica da Lei nº 4.320/1964, a amortização da dívida pública integra as transferências de capital no agrupamento tradicional da lei.", "passos": ["1) A questão pede a classificação prevista na Lei nº 4.320/1964.", "2) Amortização da dívida pública não é investimento nem inversão financeira.", "3) Na classificação econômica da Lei 4.320, aparece em transferências de capital.", "4) Portanto, a alternativa A corresponde ao gabarito."], "calculo": "Não há cálculo.", "correta": "A) Transferência de Capital.", "erradas": ["B) Inversões financeiras não abrangem a amortização da dívida.", "C) Investimentos correspondem a despesas de capital com obras e aquisições que formam/geram bens de capital.", "D) Transferências correntes são despesas correntes.", "E) Despesas de custeio são correntes."], "fundamento": "Lei nº 4.320/1964, art. 12 e classificação econômica das despesas.", "pegadinha": "A questão usa a classificação tradicional da Lei 4.320/64; não substitua automaticamente a nomenclatura histórica pela classificação por natureza atualmente utilizada no MCASP."}'::jsonb WHERE id='2416285';
UPDATE questoes SET resolution='{"cobranca": "Classificação econômica da despesa – Lei 4.320/64", "regra": "Conservação/adaptação pode integrar despesas de custeio; transferências sem contraprestação para manutenção são transferências correntes; aquisição de imóveis/bens de capital já em utilização é inversão financeira; investimentos abrangem obras e bens de capital novos.", "passos": ["1) Primeira: verdadeira no enquadramento tradicional da Lei 4.320/64.", "2) Segunda: falsa, porque a descrição corresponde a transferências correntes, não de capital.", "3) Terceira: falsa, pois a constituição/aumento de capital de empresas de caráter comercial ou financeiro é que aparece como inversão financeira; a redação da questão exclui justamente essas empresas.", "4) Quarta: falsa, porque aquisição de imóveis ou bens de capital já em utilização é inversão financeira.", "5) Sequência V-F-F-F → alternativa C."], "calculo": "Não há cálculo.", "correta": "C) V-F-F-F.", "erradas": ["A) Considera todas as afirmações verdadeiras.", "B) Classifica a primeira como falsa e a quarta como verdadeira, contrariando a Lei 4.320.", "D) Considera a terceira verdadeira.", "E) Considera a primeira falsa e a quarta verdadeira."], "fundamento": "Lei nº 4.320/1964, art. 12, §§ 1º a 6º.", "pegadinha": "“Bem de capital já em utilização” é pista clássica para inversão financeira, não investimento."}'::jsonb WHERE id='2416286';
UPDATE questoes SET resolution='{"cobranca": "Classificação das receitas e despesas no Balanço Orçamentário", "regra": "Receita tributária e receita de contribuições são receitas correntes; receita patrimonial também é corrente. Pessoal e encargos e juros/encargos da dívida são despesas correntes; investimentos são despesas de capital.", "passos": ["1) Receitas correntes = 680.000 + 360.000 + 75.000 = R$ 1.115.000,00.", "2) Logo, A é falsa, pois informa R$ 1.040.000,00.", "3) Receita patrimonial não é receita de capital; B é falsa.", "4) Despesas correntes = pessoal 445.000 + juros/encargos 32.000 = R$ 477.000,00.", "5) Investimentos = R$ 648.000,00, portanto despesas de capital não são R$ 680.000,00.", "6) Alternativa C."], "calculo": "R$ 445.000 + R$ 32.000 = R$ 477.000 de despesas correntes.", "correta": "C) O total das despesas correntes foi de R$ 477.000,00.", "erradas": ["A) Soma apenas tributária e contribuições e ignora a receita patrimonial.", "B) Receita patrimonial é corrente.", "D) Investimentos totalizam R$ 648.000, não R$ 680.000."], "fundamento": "Lei nº 4.320/1964, classificação econômica das receitas e despesas.", "pegadinha": "Juros e encargos da dívida são despesas correntes; amortização do principal é despesa de capital."}'::jsonb WHERE id='2156994';
UPDATE questoes SET resolution='{"regra": "Pela classificação econômica da Lei 4.320/1964, despesas correntes abrangem despesas de custeio, enquanto despesas de capital abrangem investimentos e inversões financeiras, entre outras categorias.", "passos": ["Investimentos são despesas de capital.", "Despesas de custeio pertencem às despesas correntes.", "Inversões financeiras são despesas de capital.", "Logo, a sequência é capital, corrente, capital."], "calculo": "1 = Investimentos → capital; 2 = Custeio → corrente; 3 = Inversões Financeiras → capital.", "correta": "B — 1. Despesa de Capital; 2. Despesa Corrente; 3. Despesa de Capital.", "erradas": ["A) Classifica investimentos como corrente.", "C) Inverte a classificação de custeio e inversões.", "D) Classifica custeio como capital."], "fundamento": "Lei nº 4.320/1964, especialmente a classificação das despesas por categorias econômicas.", "pegadinha": "A palavra “custeio” é a pista para despesa corrente. “Investimentos” e “inversões financeiras” são despesas de capital.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária", "status": "individual", "rank_resolucao": 203}'::jsonb WHERE id='1058698';
UPDATE questoes SET resolution='{"regra": "Aquisição de equipamentos necessários à execução de uma obra caracteriza investimento, pois envolve a aquisição de equipamento/material permanente associado à formação ou ampliação de ativo de capital.", "passos": ["Identifique a natureza do gasto: aquisição de equipamento novo.", "Equipamentos e material permanente integram a categoria dos investimentos quando destinados à formação/ampliação de capital público.", "Não se trata de manutenção de serviço já criado nem de transferência.", "Portanto, a classificação é investimento."], "calculo": "Não há cálculo.", "correta": "D — Investimento.", "erradas": ["A) Subvenção econômica é transferência corrente, não aquisição de equipamento pelo próprio ente.", "B) Despesa corrente não corresponde à formação/aquisição de bem de capital nesse caso.", "C) Inversão financeira abrange hipóteses específicas, como aquisição de imóveis ou bens de capital já em utilização, e não a aquisição de equipamento novo para a obra.", "E) Subvenção social é transferência corrente destinada a instituições sem fins lucrativos."], "fundamento": "Lei nº 4.320/1964, art. 12 e classificação das despesas de capital.", "pegadinha": "“Equipamento novo” é uma pista importante. Não confunda investimento com inversão financeira.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária", "status": "individual", "rank_resolucao": 204}'::jsonb WHERE id='1336838';
UPDATE questoes SET resolution='{"regra": "Pela Lei 4.320/1964, pessoal, material de consumo, juros/encargos e outras despesas de manutenção são correntes; amortização da dívida, obras, aquisição de imóveis e outros investimentos/inversões são de capital.", "passos": ["Classifique cada item.", "Correntes: pessoal 120.000; material de expediente 20.000; juros 230.000; pneus 15.000; aluguel 25.000; obrigações patronais 140.000; encargos sobre ARO 30.000.", "Some as despesas correntes.", "O total encontrado é R$ 580.000,00."], "calculo": "120.000 + 20.000 + 230.000 + 15.000 + 25.000 + 140.000 + 30.000 = R$ 580.000,00.", "correta": "A — R$ 580.000,00.", "erradas": ["B) R$ 350.000,00 não corresponde à soma das despesas correntes listadas.", "C) R$ 260.000,00 também não corresponde à soma.", "D) R$ 540.000,00 exclui ou classifica incorretamente algum item corrente."], "fundamento": "Lei nº 4.320/1964, classificação por categorias econômicas e MCASP.", "pegadinha": "Não classifique pelo objeto isoladamente; juros e encargos da dívida são correntes, enquanto a amortização do principal da dívida é capital.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária", "status": "individual", "rank_resolucao": 206}'::jsonb WHERE id='1054699';
UPDATE questoes SET resolution='{"regra": "As despesas de capital incluem investimentos, inversões financeiras e transferências de capital. Na lista, amortização da dívida, construção de posto de saúde e aquisição de imóveis são de capital.", "passos": ["Separe os itens de capital: amortização da dívida = 70.000; construção do posto = 320.000; aquisição de imóveis = 160.000.", "Some os três valores.", "O total é R$ 550.000,00."], "calculo": "70.000 + 320.000 + 160.000 = R$ 550.000,00.", "correta": "B — R$ 550.000,00.", "erradas": ["A) R$ 380.000,00 não corresponde à soma das três despesas de capital.", "C) R$ 460.000,00 também não corresponde ao total.", "D) R$ 610.000,00 inclui valor que não pertence às despesas de capital selecionadas."], "fundamento": "Lei nº 4.320/1964 e MCASP — despesas de capital: investimentos, inversões financeiras e transferências de capital.", "pegadinha": "Amortização do principal da dívida é despesa de capital; juros e encargos são despesas correntes.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária", "status": "individual", "rank_resolucao": 207}'::jsonb WHERE id='1054701';
UPDATE questoes SET resolution='{"regra": "A classificação funcional da despesa desagrega a despesa por funções e subfunções, permitindo evidenciar a área de ação governamental em que o gasto é realizado.", "passos": ["Compare as alternativas com as classificações da despesa.", "A confunde classificação por natureza com classificação institucional.", "B descreve corretamente a classificação funcional: funções e subfunções.", "C inverte os conceitos de projeto e atividade.", "D apresenta elementos da classificação por natureza, não da institucional."], "calculo": "Não há cálculo.", "correta": "B — a classificação funcional é organizada em funções e subfunções e evidencia a área de ação governamental.", "erradas": ["A) Órgão e unidade orçamentária são componentes da classificação institucional, não elementos da despesa por natureza.", "C) Projeto é limitado no tempo; atividade é contínua e permanente.", "D) Categoria econômica, grupo de natureza e elemento pertencem à classificação por natureza."], "fundamento": "MCASP — classificação da despesa orçamentária por natureza, institucional, funcional e programática.", "pegadinha": "Projeto = ação limitada no tempo; atividade = ação contínua. Função/subfunção = classificação funcional.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária", "status": "individual", "rank_resolucao": 212}'::jsonb WHERE id='563619';
UPDATE questoes SET resolution='{"regra": "Transferências de capital são dotações para investimentos ou inversões financeiras que outras pessoas de direito público ou privado devam realizar, sem contraprestação direta, além das dotações para amortização da dívida pública.", "passos": ["O enunciado menciona investimentos ou inversões financeiras realizados por outras pessoas.", "Também destaca ausência de contraprestação direta.", "A Lei 4.320/1964 enquadra essas dotações como transferências de capital.", "Portanto, a alternativa B é a correta."], "calculo": "Não há cálculo.", "correta": "B — Transferências de Capital.", "erradas": ["A) Transferências correntes correspondem a despesas correntes sem contraprestação direta, como contribuições e subvenções correntes.", "C) Investimentos são gastos do próprio ente classificados como despesa de capital, não a transferência descrita.", "D) Inversões financeiras são categoria de despesa de capital do ente, mas não correspondem à transferência descrita."], "fundamento": "Lei nº 4.320/1964, art. 12, classificação das despesas por categorias econômicas.", "pegadinha": "Se o investimento/inversão será realizado por outra pessoa e o ente apenas transfere recursos sem contraprestação direta, pense em transferência de capital.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária", "status": "individual", "rank_resolucao": 213}'::jsonb WHERE id='635066';
UPDATE questoes SET resolution='{"regra": "Despesas de custeio são dotações para manutenção de serviços anteriormente criados, incluindo as destinadas a obras de conservação e adaptação de bens imóveis.", "passos": ["O comando descreve manutenção de serviços já existentes.", "A Lei 4.320/1964 denomina essa categoria de despesas de custeio.", "Não há formação de novo capital nem transferência."], "calculo": "Não há cálculo.", "correta": "A — Despesas de Custeio.", "erradas": ["B) Transferências correntes envolvem transferência sem contraprestação direta.", "C) Investimentos são despesas de capital voltadas, entre outras hipóteses, à formação/ampliação de capital.", "D) Inversões financeiras abrangem aquisições e operações específicas previstas em lei.", "E) Transferências de capital têm natureza distinta da manutenção direta de serviços."], "fundamento": "Lei nº 4.320/1964, art. 12, § 1º, conforme a classificação tradicional de despesas de custeio.", "pegadinha": "“Manutenção de serviços anteriormente criados” é a expressão-chave para despesas de custeio.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária", "status": "individual", "rank_resolucao": 214}'::jsonb WHERE id='924176';
UPDATE questoes SET resolution='{"regra": "Despesas correntes compreendem despesas de custeio e transferências correntes. Entre os grupos destacados pelo MCASP estão pessoal e encargos sociais, juros e encargos da dívida e outras despesas correntes, onde se enquadram serviços de terceiros/consultoria.", "passos": ["A alternativa A reúne pessoal e encargos sociais, juros e encargos da dívida e serviço de consultoria.", "Todos são despesas correntes.", "As demais alternativas contêm obras, imóveis, títulos ou equipamentos/material permanente, que deslocam a classificação para despesas de capital."], "calculo": "Não há cálculo.", "correta": "A — pessoal e encargos sociais, juros e encargos da dívida e serviços de consultoria.", "erradas": ["B) Obras e instalações e aquisição de imóveis são despesas de capital.", "C) Aquisição de títulos de crédito e equipamentos/material permanente são despesas de capital.", "D) Aquisição de imóveis é despesa de capital."], "fundamento": "MCASP — classificação por natureza da despesa orçamentária.", "pegadinha": "Juros são correntes; amortização do principal é capital. Serviço de consultoria, por sua vez, não é investimento só porque é um serviço especializado.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária", "status": "individual", "rank_resolucao": 215}'::jsonb WHERE id='938379';
UPDATE questoes SET resolution='{"regra": "Na Lei 4.320/1964, investimentos e inversões financeiras são despesas de capital; despesas de custeio e transferências correntes são despesas correntes; transferências de capital são despesas de capital.", "passos": ["Investimentos → B, capital.", "Inversões financeiras → B, capital.", "Despesas de custeio → A, corrente.", "Transferências de capital → B, capital.", "Transferências correntes → A, corrente.", "A sequência é B-B-A-B-A."], "calculo": "Classificação: 1 B; 2 B; 3 A; 4 B; 5 A.", "correta": "D — B, B, A, B, A.", "erradas": ["A) Classifica investimentos como corrente.", "B) Classifica investimentos como corrente e erra a sequência.", "C) Classifica inversões financeiras como corrente."], "fundamento": "Lei nº 4.320/1964, art. 12 e classificação das categorias econômicas.", "pegadinha": "Primeiro memorize as duas famílias: correntes = custeio + transferências correntes; capital = investimentos + inversões financeiras + transferências de capital.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária", "status": "individual", "rank_resolucao": 216}'::jsonb WHERE id='938408';
UPDATE questoes SET resolution='{"regra": "Inversões financeiras incluem dotações destinadas à aquisição de imóveis ou bens de capital já em utilização, aquisição de títulos representativos do capital de empresas já constituídas sem aumento de capital e constituição/aumento de capital de entidades com objetivos comerciais ou financeiros.", "passos": ["Compare o texto do enunciado com as definições legais.", "Ele reproduz as hipóteses de inversões financeiras.", "Logo, a classificação é inversões financeiras."], "calculo": "Não há cálculo.", "correta": "C — Inversões Financeiras.", "erradas": ["A) Despesas de custeio são correntes e ligadas à manutenção de serviços.", "B) Investimentos abrangem, entre outras hipóteses, obras, instalações e equipamentos/materiais permanentes, mas não a descrição integral do enunciado.", "D) Transferências de capital são recursos transferidos a terceiros para investimentos/inversões ou amortização da dívida, sem a contraprestação direta descrita."], "fundamento": "Lei nº 4.320/1964, art. 12, § 5º.", "pegadinha": "A expressão “bens de capital já em utilização” é uma das pistas clássicas para inversões financeiras.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária", "status": "individual", "rank_resolucao": 217}'::jsonb WHERE id='938414';
UPDATE questoes SET resolution='{"regra": "Transferências correntes são dotações para despesas sem contraprestação direta em bens ou serviços, inclusive contribuições e subvenções destinadas a outras entidades públicas ou privadas.", "passos": ["O enunciado descreve ausência de contraprestação direta.", "Menciona expressamente contribuições e subvenções.", "Essa definição corresponde às transferências correntes."], "calculo": "Não há cálculo.", "correta": "C — Transferências Correntes.", "erradas": ["A) Despesas de custeio destinam-se à manutenção direta de serviços.", "B) Investimentos são despesas de capital.", "D) Transferências de capital têm como objeto investimentos, inversões financeiras ou amortização da dívida, nas hipóteses legais."], "fundamento": "Lei nº 4.320/1964, art. 12, § 2º.", "pegadinha": "“Sem contraprestação direta” não basta sozinho: observe se o texto fala em contribuições/subvenções correntes ou em investimentos/inversões/amortização, que indicariam transferência de capital.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária", "status": "individual", "rank_resolucao": 218}'::jsonb WHERE id='938441';
UPDATE questoes SET resolution='{"regra": "Na classificação da Lei 4.320/1964: investimentos e inversões financeiras são despesas de capital; despesas de custeio e transferências correntes são despesas correntes; transferências de capital são despesas de capital.", "passos": ["I descreve investimentos → capital.", "II descreve inversões financeiras → capital.", "III descreve despesas de custeio → corrente.", "IV descreve transferências de capital → capital.", "V descreve transferências correntes → corrente.", "Portanto: correntes III e V; capital I, II e IV."], "calculo": "Não há cálculo; trata-se de classificação conceitual.", "correta": "C — Despesas Correntes: III e V; Despesas de Capital: I, II e IV.", "erradas": ["A) Coloca inversões financeiras entre as correntes e transferências correntes entre as de capital.", "B) Coloca despesas de custeio entre as de capital.", "D) Coloca transferências de capital entre as correntes."], "fundamento": "Lei nº 4.320/1964, art. 12 e §§ seguintes, conforme as definições transcritas no enunciado.", "pegadinha": "Quando a questão reproduz as definições legais, não tente reinterpretar: associe literalmente cada definição à categoria prevista na lei.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária", "status": "individual", "rank_resolucao": 219}'::jsonb WHERE id='3013717';
UPDATE questoes SET resolution='{"regra": "Na classificação tradicional da Lei 4.320/1964, despesas correntes abrangem despesas de custeio e transferências correntes. Investimentos, inversões financeiras e transferências de capital são despesas de capital.", "passos": ["Identifique as alternativas como categorias da despesa.", "Despesas de custeio pertencem às despesas correntes.", "Investimentos, inversões financeiras e transferências de capital pertencem às despesas de capital.", "Logo, A é a única opção classificada como corrente."], "calculo": "Não há cálculo.", "correta": "A — Despesas de Custeio.", "erradas": ["B) Investimentos são despesas de capital.", "C) Inversões financeiras são despesas de capital.", "D) Transferências de capital são despesas de capital."], "fundamento": "Lei nº 4.320/1964, art. 12.", "pegadinha": "A questão é direta: procure a única categoria corrente entre três categorias de capital.", "cobranca": "AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária", "status": "individual", "rank_resolucao": 220}'::jsonb WHERE id='3013721';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 221", "whatTests": "Classificação das despesas de capital segundo a Lei 4.320/64.", "rule": "Investimentos abrangem planejamento e execução de obras, aquisição de instalações, equipamentos e material permanente e determinadas constituições/aumentos de capital. Inversões financeiras abrangem, entre outros, aquisição de imóveis ou bens de capital já em utilização e aquisição de títulos de capital já constituídos sem aumento do capital.", "steps": ["Identifique que a questão pede a alternativa que NÃO é inversão financeira.", "Compare cada descrição com as categorias do art. 12, §5º, da Lei 4.320/64.", "A descrição da alternativa C corresponde a Investimentos, não a Inversões Financeiras."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa C descreve planejamento e execução de obras, instalações, equipamentos e material permanente, características de Investimentos.", "whyWrong": "A, B e D correspondem a hipóteses de Inversões Financeiras previstas na classificação da Lei 4.320/64.", "basis": "Lei 4.320/1964, art. 12 e §5º.", "fafipaTrap": "A banca mistura exemplos de Investimentos e Inversões Financeiras; a expressão \"bens de capital já em utilização\" é um forte indicador de Inversão Financeira.", "status": "resolvida"}'::jsonb WHERE id='3013724';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 223", "whatTests": "Despesa de custeio.", "rule": "Na classificação econômica da Lei 4.320/64, Despesas de Custeio são as dotações para manutenção de serviços anteriormente criados, inclusive obras de conservação e adaptação de bens imóveis.", "steps": ["Observe que o enunciado fala em manutenção de serviço já criado.", "Verifique a definição legal de Despesas de Custeio.", "Conservação e adaptação de bens imóveis também aparecem expressamente nessa definição."], "calculation": "Não há cálculo.", "whyCorrect": "A descrição é a definição legal de Despesas de Custeio.", "whyWrong": "B é Transferências Correntes; C é Investimentos; D é Inversões Financeiras.", "basis": "Lei 4.320/1964, art. 12, §1º.", "fafipaTrap": "Não confunda conservação/adaptação com obra nova: a manutenção de serviço anteriormente criado aponta para custeio.", "status": "resolvida"}'::jsonb WHERE id='562926';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 224", "whatTests": "Inversões Financeiras.", "rule": "A aquisição de imóveis ou de bens de capital já em utilização, a aquisição de títulos representativos do capital de empresas já constituídas sem aumento do capital e certas constituições/aumentos de capital são classificadas como Inversões Financeiras.", "steps": ["Separe as despesas de capital em Investimentos, Inversões Financeiras e Transferências de Capital.", "Identifique as três hipóteses descritas no enunciado.", "Todas estão no rol de Inversões Financeiras."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa C é a categoria econômica correta.", "whyWrong": "A e B são categorias correntes; D corresponde a Investimentos; E a Transferências de Capital.", "basis": "Lei 4.320/1964, art. 12, §5º.", "fafipaTrap": "A questão reúne várias hipóteses legais para dificultar a associação com a categoria.", "status": "resolvida"}'::jsonb WHERE id='953137';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 225", "whatTests": "Classificação por natureza da despesa.", "rule": "A natureza da despesa é estruturada por categoria econômica, grupo de natureza da despesa, modalidade de aplicação e elemento de despesa.", "steps": ["A questão pergunta os componentes obrigatórios da classificação quanto à natureza.", "Identifique a sequência: categoria econômica → grupo de natureza → modalidade de aplicação → elemento.", "As demais alternativas misturam classificações funcionais/programáticas, unidade/ação ou estágios da despesa."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa A apresenta os componentes da classificação por natureza da despesa.", "whyWrong": "B e C tratam de elementos de outras classificações; D mistura classificações; E apresenta estágios da execução da despesa.", "basis": "Lei 4.320/1964 e Portaria Interministerial STN/SOF nº 163/2001, estrutura da natureza da despesa.", "fafipaTrap": "Não confunda classificação da despesa com estágios: empenho, liquidação e pagamento são estágios da execução.", "status": "resolvida"}'::jsonb WHERE id='966937';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 226", "whatTests": "Identificar erro na definição de Inversões Financeiras.", "rule": "A afirmação apresentada atribui às Inversões Financeiras uma definição que corresponde às Transferências de Capital: dotações para investimentos ou inversões financeiras que outras pessoas de direito público ou privado devam realizar, independentemente de contraprestação direta.", "steps": ["Compare a frase com a classificação econômica da Lei 4.320/64.", "A definição não descreve a aquisição de imóveis/bens já utilizados ou títulos de capital sem aumento.", "Ela descreve Transferências de Capital."], "calculation": "Não há cálculo.", "whyCorrect": "O item é Errado, portanto E.", "whyWrong": "Não há alternativa de letra múltipla: a própria marcação E indica o julgamento Errado.", "basis": "Lei 4.320/1964, art. 12, §§5º e 6º.", "fafipaTrap": "A banca troca a definição de Inversões Financeiras pela definição de Transferências de Capital.", "status": "resolvida"}'::jsonb WHERE id='3081897';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 228", "whatTests": "Identificar que a definição apresentada não é de Transferências de Capital.", "rule": "Aquisição de imóveis ou de bens de capital já em utilização e aquisição de títulos de capital já constituídos sem aumento do capital são hipóteses de Inversões Financeiras.", "steps": ["Localize os dois exemplos do enunciado.", "Ambos aparecem no rol de Inversões Financeiras.", "Portanto, não podem ser classificados como Transferências de Capital."], "calculation": "Não há cálculo.", "whyCorrect": "A afirmação é Errada; por isso, E.", "whyWrong": "O erro é a troca de Inversões Financeiras por Transferências de Capital.", "basis": "Lei 4.320/1964, art. 12, §5º.", "fafipaTrap": "Memorize o par: \"imóvel já em utilização\" → Inversão Financeira.", "status": "resolvida"}'::jsonb WHERE id='3132901';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 229", "whatTests": "Aquisição de imóveis ou bens de capital já em utilização.", "rule": "A Lei 4.320/64 classifica essa hipótese como Inversões Financeiras.", "steps": ["Identifique a expressão \"bens de capital já em utilização\".", "Associe-a ao rol do art. 12, §5º.", "Conclua por Inversões Financeiras."], "calculation": "Não há cálculo.", "whyCorrect": "D é a classificação correta.", "whyWrong": "A é Transferências de Capital; B é Transferências Correntes; C é Investimentos.", "basis": "Lei 4.320/1964, art. 12, §5º, I.", "fafipaTrap": "O detalhe \"já em utilização\" diferencia a hipótese de investimento em ativo novo.", "status": "resolvida"}'::jsonb WHERE id='923434';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 230", "whatTests": "Transferências Correntes.", "rule": "Despesas às quais não corresponda contraprestação direta em bens ou serviços, inclusive contribuições e subvenções destinadas a atender à manifestação de outras entidades públicas ou privadas, são Transferências Correntes quando não tiverem caráter de capital.", "steps": ["Observe a ausência de contraprestação direta.", "Associe a definição à classificação econômica de Transferências Correntes.", "Não confunda com Transferências de Capital, que se destinam a despesas de capital."], "calculation": "Não há cálculo.", "whyCorrect": "D reproduz a classificação indicada pela Lei 4.320/64.", "whyWrong": "A é Despesas de Custeio; B é Investimentos; C é Transferências de Capital.", "basis": "Lei 4.320/1964, art. 12, §2º.", "fafipaTrap": "A ausência de contraprestação aparece em mais de uma categoria; o contexto corrente/capital é decisivo.", "status": "resolvida"}'::jsonb WHERE id='923436';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 231", "whatTests": "Relacionar categorias econômicas e espécies de despesa.", "rule": "Despesas Correntes: Despesas de Custeio e Transferências Correntes. Despesas de Capital: Investimentos, Inversões Financeiras e Transferências de Capital.", "steps": ["Classifique cada item pela categoria econômica.", "Custeio é corrente; Investimentos, Inversões e Transferências de Capital são de capital; Transferências Correntes são correntes.", "A sequência correta apresentada é A, B, B, A, B."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa C corresponde à sequência A, B, B, A, B registrada no enunciado.", "whyWrong": "As demais alternativas alteram pelo menos uma associação entre corrente e capital.", "basis": "Lei 4.320/1964, art. 12.", "fafipaTrap": "A principal pegadinha é separar \"Transferências Correntes\" de \"Transferências de Capital\" pelo nome e pela categoria econômica.", "status": "resolvida"}'::jsonb WHERE id='942377';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 232", "whatTests": "Relacionar as cinco espécies de despesa às definições legais.", "rule": "Investimentos = obras, instalações, equipamentos/material permanente; Custeio = manutenção; Transferências Correntes = sem contraprestação direta para atender outras entidades; Transferências de Capital = recursos para que terceiros realizem investimentos/inversões; Inversões Financeiras = aquisição de imóveis/bens já utilizados e títulos sem aumento do capital, entre outras hipóteses.", "steps": ["Primeira definição: planejamento/execução de obras → III, Investimentos.", "Segunda: manutenção de serviços já criados → I, Custeio.", "Terceira: sem contraprestação direta, contribuições/subvenções → II, Transferências Correntes.", "Quarta: outra pessoa realiza investimento/inversão → V, Transferências de Capital.", "Quinta: aquisição de imóvel/bem já utilizado → IV, Inversões Financeiras."], "calculation": "Não há cálculo.", "whyCorrect": "A sequência é III, I, II, V, IV, correspondente à alternativa A.", "whyWrong": "As outras alternativas trocam pelo menos uma das cinco categorias.", "basis": "Lei 4.320/1964, art. 12, §§1º a 6º.", "fafipaTrap": "Questões de associação exigem reconhecer a palavra-chave de cada definição.", "status": "resolvida"}'::jsonb WHERE id='942399';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 233", "whatTests": "Modalidades de aplicação envolvendo consórcios públicos.", "rule": "A classificação diferencia transferência, execução orçamentária delegada, aplicação direta e rateio pela participação em consórcio. A modalidade deve refletir a relação do ente com o consórcio e a natureza da execução/repasse.", "steps": ["Identifique se a despesa é uma transferência, uma delegação, uma aplicação direta ou rateio.", "Na aplicação direta, o próprio órgão/fundo/entidade realiza operação com consórcio do qual participa.", "No rateio, o ente contribui conforme sua participação no consórcio.", "A sequência correspondente ao enunciado é a da alternativa A."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa A é a sequência registrada no gabarito do caderno para as definições apresentadas.", "whyWrong": "As demais alternativas alteram a correspondência entre modalidade e descrição.", "basis": "Portaria Interministerial STN/SOF nº 163/2001 e atualizações, classificação das despesas com consórcios públicos.", "fafipaTrap": "Não confunda \"aplicação direta\" com \"transferência\": o ponto central é quem executa a despesa e como o recurso chega ao consórcio.", "status": "resolvida"}'::jsonb WHERE id='942410';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 234", "whatTests": "Disposições da LRF sobre despesa com pessoal, tributos, transferências e dívida consolidada.", "rule": "I é incorreta: a formulação do art. 21 não é essa. II é correta quanto aos requisitos essenciais de responsabilidade na gestão fiscal. III é correta sobre destinação de recursos para cobrir necessidades de pessoas físicas ou déficits de pessoas jurídicas. IV é correta quanto à recondução da dívida consolidada que exceder o limite, observada a regra legal do período e da redução inicial.", "steps": ["Analise cada assertiva separadamente.", "II reproduz a exigência do art. 11 da LRF.", "III corresponde ao art. 26.", "IV corresponde ao mecanismo de recondução da dívida consolidada do art. 31.", "Com I incorreta e II, III e IV corretas, a combinação é II, III e IV."], "calculation": "Não há cálculo.", "whyCorrect": "Pelo texto e gabarito do material, a combinação indicada é a alternativa B? Atenção: a alternativa B do enunciado é \"I, II e III, apenas\", o que entra em conflito com a análise textual de IV. O gabarito registrado é B, portanto esta questão deve ser conferida na fonte original antes de ser usada como regra.", "whyWrong": "As combinações não resolvem a inconsistência entre o texto das assertivas e o gabarito registrado.", "basis": "Lei Complementar 101/2000 (LRF), arts. 11, 26, 31 e 21.", "fafipaTrap": "Não memorizar o gabarito desta questão sem conferir o original; o material extraído apresenta possível inconsistência.", "status": "verificar"}'::jsonb WHERE id='3339286';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 235", "whatTests": "Empresa estatal dependente e instrumentos da LRF.", "rule": "Empresa estatal dependente é controlada que receba recursos do ente controlador para pagamento de pessoal, custeio em geral ou capital, excluídos, neste último caso, os recursos provenientes de aumento de participação acionária. A LDO deve estabelecer metas de receitas, despesas, resultados primário e nominal e montante da dívida pública. O RGF é quadrimestral, não bimestral, e não é o demonstrativo próprio para os mínimos de saúde e educação.", "steps": ["I reproduz a definição legal de empresa estatal dependente → correta.", "II é falsa porque a LDO, e não a LOA, trata dessas metas e parâmetros.", "III é falsa porque o RGF é quadrimestral e sua descrição não corresponde aos mínimos de saúde e educação.", "Logo, somente I está correta."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa B corresponde a \"I, apenas\".", "whyWrong": "A inclui III, C inclui II e D considera as três corretas.", "basis": "LRF, art. 2º, III; art. 4º; art. 55.", "fafipaTrap": "A banca troca LDO por LOA e RGF por demonstrativos de saúde/educação, além de alterar a periodicidade.", "status": "resolvida"}'::jsonb WHERE id='3460669';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 236", "whatTests": "Despesa pública e requisitos de responsabilidade fiscal.", "rule": "A despesa total com pessoal é apurada com base nos 12 meses do período de apuração, pelo regime de competência. Expansão/criação de ação que aumente despesa exige estimativa de impacto e declaração de adequação/compatibilidade. Despesa obrigatória de caráter continuado é despesa corrente derivada de lei, MP ou ato normativo que fixe obrigação por período superior a dois exercícios.", "steps": ["A está incorreta porque diz \"independentemente de empenho\"; a apuração segue o regime de competência, mas a formulação apresentada não reproduz corretamente a regra.", "B, C e D refletem requisitos dos arts. 16 e seguintes.", "E é incorreta porque a definição legal exige período por mais de dois exercícios, não simplesmente superior a um.", "Como a questão pede a INCORRETA e há mais de uma formulação problemática no texto extraído, deve-se conferir o original."], "calculation": "Não há cálculo.", "whyCorrect": "O gabarito registrado é E, mas o texto extraído também merece conferência quanto à redação da alternativa A. Não forço uma harmonização.", "whyWrong": "A apresenta redação potencialmente problemática; B, C e D estão alinhadas aos requisitos legais; E troca \"dois exercícios\" por \"um exercício\".", "basis": "LRF, arts. 16, 17 e 18.", "fafipaTrap": "A definição de despesa obrigatória de caráter continuado exige atenção ao prazo: mais de dois exercícios.", "status": "verificar"}'::jsonb WHERE id='3600644';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 237", "whatTests": "Periodicidade do RREO e do RGF.", "rule": "O RREO é publicado até trinta dias após o encerramento de cada bimestre. O RGF é emitido ao final de cada quadrimestre, com exceção dos municípios com população inferior ao limite legal que podem optar por semestralidade nas condições da LRF.", "steps": ["Associe RREO à execução orçamentária periódica: bimestral.", "Associe RGF ao acompanhamento da gestão fiscal: quadrimestral como regra.", "A sequência pedida é bimestral e quadrimestral."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa A apresenta a periodicidade padrão prevista na LRF.", "whyWrong": "B torna ambos bimestrais; C torna ambos quadrimestrais; D inverte; E atribui periodicidade semestral ao RGF como regra geral.", "basis": "LRF, arts. 52 e 54.", "fafipaTrap": "Não confundir a periodicidade do RREO com a do RGF.", "status": "resolvida"}'::jsonb WHERE id='3862426';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 238", "whatTests": "Identificação dos instrumentos de evidenciação contábil e fiscal.", "rule": "O RREO acompanha a execução orçamentária; o Balanço Patrimonial evidencia ativos, passivos e patrimônio líquido; o RGF evidencia limites e indicadores fiscais, como pessoal e dívida.", "steps": ["I descreve o RREO, divulgado bimestralmente.", "II descreve o Balanço Patrimonial.", "III descreve o RGF.", "A associação completa é I–RREO; II–BP; III–RGF."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa A faz as três associações corretas.", "whyWrong": "As demais alternativas trocam os instrumentos e suas finalidades.", "basis": "LRF, arts. 52 e 54; MCASP, demonstrações contábeis aplicadas ao setor público.", "fafipaTrap": "A banca mistura demonstrações contábeis (BP) com relatórios fiscais (RREO/RGF).", "status": "resolvida"}'::jsonb WHERE id='3930686';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 239", "whatTests": "RREO, RGF e regras de transparência fiscal.", "rule": "O RREO possui anexos específicos no último bimestre, incluindo demonstrativos previstos na LRF; o RGF não é trimestral como regra, e os demonstrativos de educação/saúde não formam o núcleo descrito na afirmativa II; o RREO consolida os Poderes e órgãos indicados pela LRF, não todas as empresas com participação no capital.", "steps": ["I: a afirmativa está de acordo com as exigências do último bimestre → V.", "II: a periodicidade trimestral do RGF está errada → F.", "III: a abrangência indicada inclui empresas apenas por participação no capital, o que não corresponde à regra descrita → F.", "Sequência V, F, F."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa A corresponde à sequência V, F, F.", "whyWrong": "B, C, D e E apresentam outras combinações de verdadeiro/falso.", "basis": "LRF, arts. 52 a 55.", "fafipaTrap": "A periodicidade do RGF é um ponto recorrente: quadrimestral como regra geral.", "status": "resolvida"}'::jsonb WHERE id='4003319';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 240", "whatTests": "Limites de pessoal, LDO e reserva de contingência.", "rule": "Municípios têm limite global de 60% da RCL para despesa com pessoal, sendo 6% para o Legislativo e 54% para o Executivo. A LDO estabelece critérios e forma de limitação de empenho. A reserva de contingência integra a LOA e sua forma de utilização é definida na LDO; não é destinada apenas a créditos extraordinários.", "steps": ["I é falsa porque apresenta 8% para Legislativo e 52% para Executivo; os percentuais municipais são 6% e 54%.", "II é verdadeira: a LDO trata dos critérios e forma de limitação de empenho.", "III é falsa porque atribui ao PPA a definição da reserva e limita sua utilização a crédito extraordinário.", "Logo, somente II está correta."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa B corresponde a \"II, apenas\".", "whyWrong": "A inclui I; C inclui I e III; D inclui III; E considera todas corretas.", "basis": "LRF, arts. 4º, 5º, 9º, 19 e 20.", "fafipaTrap": "Memorize o rateio municipal de pessoal: Legislativo 6% e Executivo 54% da RCL.", "status": "resolvida"}'::jsonb WHERE id='4003325';
UPDATE questoes SET resolution='{"whatTests": "Classificação dos créditos adicionais segundo a Lei nº 4.320/1964.", "rule": "A Lei nº 4.320/1964 classifica os créditos adicionais em suplementares, especiais e extraordinários. Suplementares reforçam dotação existente; especiais atendem despesas sem dotação específica; extraordinários atendem despesas urgentes e imprevisíveis, nas hipóteses legais.", "steps": ["I é verdadeira: suplementares reforçam dotação orçamentária.", "II é verdadeira: especiais atendem despesas para as quais não haja dotação específica.", "III é falsa: “finais” não é modalidade de crédito adicional.", "IV é falsa: “ordinários” não é modalidade; excesso de arrecadação pode ser fonte para créditos adicionais.", "V é verdadeira: extraordinários destinam-se a despesas urgentes e imprevisíveis, nos casos previstos em lei."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa D reúne I, II e V.", "whyWrong": "A inclui IV; B inclui III e IV; C inclui III e IV; E inclui III e IV.", "basis": "Lei nº 4.320/1964, arts. 40 e 41.", "fafipaTrap": "Não confunda modalidade de crédito adicional com fonte de recursos para sua abertura. Excesso de arrecadação é fonte, não uma modalidade chamada “ordinário”.", "title": "Resolução individual — Questão 241", "status": "resolvida"}'::jsonb WHERE id='3339301';
UPDATE questoes SET resolution='{"whatTests": "Identificação prática de crédito suplementar, especial e extraordinário.", "rule": "Suplementar reforça dotação já existente; especial cria autorização para despesa sem dotação específica; extraordinário atende despesa urgente e imprevisível.", "steps": ["Situação 1: a dotação para medicamentos existe, mas é insuficiente → suplementar.", "Situação 2: construção do hospital não possuía dotação específica na LOA → especial.", "Situação 3: danos severos por chuvas exigem ação urgente e imprevisível → extraordinário."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa D apresenta suplementar, especial e extraordinário, respectivamente.", "whyWrong": "As demais alternativas trocam pelo menos uma das três modalidades.", "basis": "Lei nº 4.320/1964, arts. 40 e 41; CF/1988, art. 167, §3º.", "fafipaTrap": "A palavra “insuficiente” aponta para suplementar; “sem dotação” aponta para especial; “urgente e imprevisível” aponta para extraordinário.", "title": "Resolução individual — Questão 242", "status": "resolvida"}'::jsonb WHERE id='3435217';
UPDATE questoes SET resolution='{"whatTests": "Requisitos e forma de abertura dos créditos adicionais.", "rule": "Créditos suplementares reforçam dotações existentes e dependem de autorização legislativa e recursos disponíveis. Créditos especiais atendem despesas sem dotação específica e também dependem de autorização legislativa. Créditos extraordinários destinam-se a despesas urgentes e imprevisíveis.", "steps": ["I é verdadeira quanto à finalidade e à necessidade de autorização/fonte de recursos.", "II é falsa: crédito especial não pode ser aberto simplesmente por decreto sem autorização legislativa.", "III é verdadeira quanto à finalidade; para a União, crédito extraordinário pode ser aberto por medida provisória nas hipóteses constitucionais.", "Logo, I e III estão corretas."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa D corresponde a I e III, apenas.", "whyWrong": "A e C incluem II; B também inclui II.", "basis": "Lei nº 4.320/1964, arts. 42 e 43; CF/1988, art. 167, §3º.", "fafipaTrap": "“Sem dotação” não significa “sem lei”: crédito especial continua sujeito à autorização legislativa.", "title": "Resolução individual — Questão 243", "status": "resolvida"}'::jsonb WHERE id='3460660';
UPDATE questoes SET resolution='{"whatTests": "Aplicação das três modalidades de créditos adicionais a situações concretas.", "rule": "Despesa sem dotação específica → especial; reforço de dotação existente → suplementar; despesa urgente e imprevisível em calamidade → extraordinário.", "steps": ["Situação 1: a despesa dos tablets não estava no orçamento → especial.", "Situação 2: a dotação da manutenção já existia, mas ficou insuficiente → suplementar.", "Situação 3: vendaval e ações emergenciais, sem dotação específica → extraordinário."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa A apresenta a sequência correta.", "whyWrong": "B, C e D permutam as modalidades entre as situações.", "basis": "Lei nº 4.320/1964, arts. 40 e 41; CF/1988, art. 167, §3º.", "fafipaTrap": "A existência de uma fonte de recurso não transforma automaticamente a despesa em suplementar: primeiro identifique a finalidade do crédito.", "title": "Resolução individual — Questão 244", "status": "resolvida"}'::jsonb WHERE id='3598428';
UPDATE questoes SET resolution='{"whatTests": "Vigência dos créditos adicionais suplementares.", "rule": "A regra é que os créditos adicionais tenham vigência no exercício financeiro em que forem abertos. A exceção constitucional/legal permite a reabertura, no exercício seguinte, dos créditos especiais e extraordinários que tenham sido autorizados nos últimos quatro meses do exercício, nos limites de seus saldos.", "steps": ["Identifique a modalidade: a questão trata de crédito suplementar.", "A regra de vigência é o exercício financeiro em que foi autorizado/aberto.", "A possibilidade de reabertura no exercício seguinte é exceção aplicável a especiais e extraordinários autorizados nos últimos quatro meses, não aos suplementares."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa B é a correta para suplementares: sua vigência não ultrapassa o exercício em que foram autorizados.", "whyWrong": "A dá vigência ilimitada; C cria prorrogação automática inexistente; D atribui aos suplementares uma regra de reabertura que a Constituição reserva a especiais e extraordinários.", "basis": "CF/1988, art. 167, §2º; Lei nº 4.320/1964, art. 45.", "fafipaTrap": "Grave: “últimos quatro meses” + “reabertura” → pense em créditos especiais e extraordinários, não em suplementares.", "title": "Resolução individual — Questão 245", "status": "resolvida"}'::jsonb WHERE id='3599125';
UPDATE questoes SET resolution='{"whatTests": "Reabertura de saldos de créditos adicionais no exercício seguinte.", "rule": "Podem ser reabertos no exercício seguinte, nos limites de seus saldos, os créditos especiais e extraordinários autorizados nos últimos quatro meses do exercício, conforme a regra constitucional. O quadro numérico mencionado no enunciado não aparece no texto extraído disponibilizado.", "steps": ["A regra jurídica exige duas condições principais: modalidade especial ou extraordinária e autorização nos últimos quatro meses do exercício.", "Os suplementares não entram nessa regra de reabertura.", "Como o quadro com a identificação dos créditos I–V não está presente no texto extraído, não é possível reconstruir independentemente quais itens são III e IV.", "O gabarito registrado no material é B, correspondente a III e IV, apenas; essa identificação deve ser conferida no quadro original."], "calculation": "Não é possível reproduzir a classificação item a item sem o quadro original.", "whyCorrect": "Pelo critério jurídico, a alternativa B é compatível com a resposta registrada no material, desde que os créditos III e IV sejam especiais/extraordinários autorizados nos últimos quatro meses.", "whyWrong": "As demais alternativas incluem itens que, se forem suplementares ou não atenderem ao requisito temporal, não poderiam ser reabertos.", "basis": "CF/1988, art. 167, §2º; Lei nº 4.320/1964, art. 45.", "fafipaTrap": "Não basta ser crédito especial/extraordinário: o requisito dos últimos quatro meses é decisivo para a reabertura.", "title": "Resolução individual — Questão 246", "status": "resolvida"}'::jsonb WHERE id='3862416';
UPDATE questoes SET resolution='{"whatTests": "Escolha do crédito suplementar quando a dotação existente se torna insuficiente.", "rule": "O crédito suplementar destina-se ao reforço de dotação orçamentária já existente. Sua abertura depende de autorização e indicação dos recursos disponíveis na forma legal.", "steps": ["A despesa de merenda já possui dotação na LOA.", "O problema é insuficiência da dotação, não ausência de dotação.", "Portanto, a modalidade adequada é suplementar.", "A alternativa também exige indicação da fonte de recursos e autorização legislativa, em consonância com a disciplina legal."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa D é a correta.", "whyWrong": "A e B usam modalidade inadequada; C é para urgência/imprevisibilidade; E erra ao dispensar autorização legislativa.", "basis": "Lei nº 4.320/1964, arts. 40, 41, I, 42 e 43.", "fafipaTrap": "“Reforçar uma dotação existente” é a definição-chave de crédito suplementar.", "title": "Resolução individual — Questão 247", "status": "resolvida"}'::jsonb WHERE id='3862419';
UPDATE questoes SET resolution='{"whatTests": "Classificação de três situações de créditos adicionais.", "rule": "I: reforço de dotação existente = suplementar. II: nova despesa sem dotação específica = especial. III: calamidade urgente e imprevisível = extraordinário.", "steps": ["I → suplementar.", "II → especial.", "III → extraordinário.", "A sequência coincide com a alternativa B."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa B apresenta a associação correta.", "whyWrong": "A inverte I e II; C, D e E também trocam modalidades.", "basis": "Lei nº 4.320/1964, art. 41; CF/1988, art. 167, §3º.", "fafipaTrap": "A FAFIPA costuma construir a questão com três expressões-gatilho: reforço, ausência de dotação e urgência/imprevisibilidade.", "title": "Resolução individual — Questão 248", "status": "resolvida"}'::jsonb WHERE id='3930700';
UPDATE questoes SET resolution='{"whatTests": "Identificação do Balanço Orçamentário.", "rule": "O Balanço Orçamentário evidencia receitas por categorias econômicas e despesas por categorias econômicas, confrontando previsão/fixação com execução. Inclui, entre outros, previsão atualizada, arrecadação, dotação atualizada, empenho, liquidação e pagamento.", "steps": ["O enunciado reúne previsão inicial e atualizada de receitas.", "Também reúne dotação inicial e atualizada e os três estágios da despesa: empenho, liquidação e pagamento.", "Esse conjunto é característico do Balanço Orçamentário."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa B identifica corretamente o Balanço Orçamentário.", "whyWrong": "DFC trata fluxos de caixa; Balanço Financeiro evidencia ingressos e dispêndios financeiros; DVP trata variações patrimoniais.", "basis": "MCASP 11ª edição; NBC TSP 13.", "fafipaTrap": "Previsão/fixação + execução orçamentária = Balanço Orçamentário.", "title": "Resolução individual — Questão 249", "status": "resolvida"}'::jsonb WHERE id='3598409';
UPDATE questoes SET resolution='{"whatTests": "Cálculo do resultado orçamentário a partir de receitas e despesas executadas.", "rule": "No contexto da questão, o resultado orçamentário é obtido pela diferença entre as receitas arrecadadas e as despesas empenhadas. O pagamento não é o estágio utilizado para esse confronto.", "steps": ["Receitas arrecadadas: 55.000 + 12.000 = R$ 67.000.", "Despesas empenhadas: 34.000 + 9.000 = R$ 43.000.", "Resultado orçamentário = 67.000 − 43.000 = R$ 24.000.", "Como é positivo, há superávit."], "calculation": "R$ 67.000 − R$ 43.000 = R$ 24.000.", "whyCorrect": "A alternativa C apresenta superávit de R$ 24.000.", "whyWrong": "A, B e E usam valores que não resultam do confronto entre arrecadação e empenho; D indica déficit, mas o resultado calculado é positivo.", "basis": "MCASP 11ª edição — Balanço Orçamentário.", "fafipaTrap": "Não use a despesa paga para calcular o resultado orçamentário da questão: o ponto de atenção é o estágio do empenho.", "title": "Resolução individual — Questão 250", "status": "resolvida"}'::jsonb WHERE id='3862400';
UPDATE questoes SET resolution='{"whatTests": "Leitura do Balanço Orçamentário e tratamento de ingressos extraorçamentários.", "rule": "No Balanço Orçamentário, o resultado decorre da execução orçamentária. ARO e depósitos caução não devem ser confundidos com receita orçamentária ordinária. O material extraído, porém, apresenta dados cuja combinação não reproduz diretamente o gabarito registrado.", "steps": ["Receita arrecadada informada: R$ 174.000.", "Despesa empenhada no exercício: R$ 165.000.", "O confronto direto entre esses valores produz R$ 9.000 de superávit.", "A liquidação de restos a pagar e o pagamento de restos a pagar não são simplesmente somados à despesa orçamentária do exercício para transformar esse resultado em R$ 12.750.", "Assim, com os dados textuais disponíveis, não é possível validar independentemente o gabarito D de R$ 12.750."], "calculation": "174.000 − 165.000 = R$ 9.000 de superávit no confronto direto das receitas arrecadadas com os empenhos do exercício.", "whyCorrect": "O gabarito registrado é D, mas os dados extraídos não permitem demonstrar esse R$ 12.750 com segurança. A questão deve ser conferida no original antes de transformar D em regra de estudo.", "whyWrong": "A, B, C e E também não decorrem do confronto direto dos valores fornecidos.", "basis": "Lei nº 4.320/1964; MCASP 11ª edição — Balanço Orçamentário.", "fafipaTrap": "Cuidado para não misturar ARO, depósitos restituíveis, restos a pagar e execução orçamentária do exercício.", "title": "Resolução individual — Questão 251", "status": "resolvida"}'::jsonb WHERE id='4003284';
UPDATE questoes SET resolution='{"whatTests": "Cálculo da Receita Corrente Líquida e exclusão de ingressos que não são receitas correntes.", "rule": "A RCL parte das receitas correntes e aplica as deduções previstas no art. 2º, IV, da LRF. Operações de crédito por ARO e depósitos restituíveis não integram a RCL. Venda de veículo é receita de capital e também fica fora das receitas correntes.", "steps": ["Receitas correntes do quadro: ISS 10.120 + industriais 1.270 + contribuição de melhoria 2.150 + rendimentos financeiros 3.350 + serviços 3.330 + IPTU 2.480 + FPM 15.650 + ITBI 15.920.", "Soma das receitas correntes listadas = R$ 54.270.", "Venda de veículos é receita de capital e fica fora. ARO e depósitos restituíveis não entram como receita corrente para a RCL.", "Com as informações apresentadas, a RCL indicada pelo material é R$ 54.270."], "calculation": "10.120 + 1.270 + 2.150 + 3.350 + 3.330 + 2.480 + 15.650 + 15.920 = R$ 54.270.", "whyCorrect": "A alternativa C corresponde a R$ 54.270,00.", "whyWrong": "As demais alternativas incluem ou excluem valores de forma incompatível com a composição da RCL.", "basis": "LRF, art. 2º, IV.", "fafipaTrap": "Não some automaticamente todo ingresso de caixa: ARO, depósitos restituíveis e receitas de capital não entram como receita corrente na RCL.", "title": "Resolução individual — Questão 252", "status": "resolvida"}'::jsonb WHERE id='3876798';
UPDATE questoes SET resolution='{"whatTests": "Definição de ente da Federação na LRF.", "rule": "Para os efeitos da LRF, União, Estados, Distrito Federal e Municípios são definidos como entes da Federação.", "steps": ["Localize o art. 2º, I, da LRF.", "A definição legal lista União, Estados, Distrito Federal e Municípios como entes da Federação.", "As demais alternativas descrevem órgãos ou entidades que não correspondem à definição do dispositivo."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa C reproduz a definição legal.", "whyWrong": "A, B, D e E não correspondem à categoria jurídica definida no art. 2º, I.", "basis": "LRF, art. 2º, I.", "fafipaTrap": "Questão literal: quando a banca pergunta “para os efeitos desta lei”, priorize a definição textual do dispositivo.", "title": "Resolução individual — Questão 253", "status": "resolvida"}'::jsonb WHERE id='4139362';
UPDATE questoes SET resolution='{"whatTests": "Estrutura constitucional da LOA e princípio da exclusividade.", "rule": "A LOA compreende os orçamentos fiscal, de investimento das estatais e da seguridade social. Pelo princípio da exclusividade, a LOA não conterá dispositivo estranho à previsão da receita e à fixação da despesa, ressalvadas as autorizações para créditos suplementares e operações de crédito, inclusive por ARO, nos termos constitucionais.", "steps": ["A está correta: reproduz a estrutura do art. 165, §5º.", "B é a incorreta porque afirma que a LOA não pode tratar de operações de crédito por antecipação de receita. A Constituição admite essa autorização entre as exceções ao princípio da exclusividade.", "C e D descrevem atribuições de LDO/PPA de modo compatível com a estrutura constitucional.", "E deve ser confrontada com a disciplina fiscal atual; o erro determinante da questão é B."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa B é a incorreta, pois a LOA pode conter autorização para operações de crédito, inclusive por ARO, dentro da exceção constitucional.", "whyWrong": "A está de acordo com o art. 165, §5º; C e D refletem funções constitucionais de LDO e PPA. A alternativa E não afasta o erro literal de B.", "basis": "CF/1988, art. 165, §§5º e 8º.", "fafipaTrap": "Exclusividade tem exceções. Memorize: créditos suplementares e operações de crédito, inclusive por ARO.", "title": "Resolução individual — Questão 254", "status": "resolvida"}'::jsonb WHERE id='3339736';
UPDATE questoes SET resolution='{"whatTests": "Princípio da exclusividade e conteúdo da LOA.", "rule": "A LOA não deve conter matéria estranha à previsão da receita e à fixação da despesa, mas a Constituição admite as autorizações para créditos suplementares e operações de crédito, inclusive ARO.", "steps": ["A, B, D e E apresentam afirmações compatíveis com o ciclo/execução orçamentária em seus respectivos contextos.", "C afirma que é vedada qualquer inclusão de dispositivo autorizando créditos suplementares ou operações de crédito.", "Isso contraria expressamente a exceção constitucional ao princípio da exclusividade."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa C é a incorreta.", "whyWrong": "A trata de contingenciamento/reprogramação; B descreve funções da LDO; D descreve o PPA; E relaciona programação financeira e cronograma de desembolso.", "basis": "CF/1988, art. 165, §8º; LRF, art. 8º.", "fafipaTrap": "A palavra “apenas” em C elimina as exceções expressamente previstas no art. 165, §8º.", "title": "Resolução individual — Questão 255", "status": "resolvida"}'::jsonb WHERE id='3435214';
UPDATE questoes SET resolution='{"whatTests": "Identificação de PPA, LDO e LOA pelas suas funções.", "rule": "PPA: diretrizes, objetivos e metas para despesas de capital e programas de duração continuada, de forma regionalizada. LDO: metas e prioridades, orientação da LOA e temas fiscais/tributários. LOA: estima receitas e fixa despesas para o exercício.", "steps": ["I descreve o PPA.", "II descreve a LDO.", "III descreve a LOA.", "Logo, a associação é PPA – LDO – LOA."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa C faz a associação correta.", "whyWrong": "A, B e D permutam os instrumentos.", "basis": "CF/1988, art. 165, §§1º a 5º; LRF, art. 4º.", "fafipaTrap": "PPA = médio prazo; LDO = ponte/prioridades; LOA = orçamento anual.", "title": "Resolução individual — Questão 256", "status": "resolvida"}'::jsonb WHERE id='3598439';
UPDATE questoes SET resolution='{"whatTests": "Questão de literalidade sobre regras constitucionais de planejamento e orçamento.", "rule": "O texto constitucional deve ser conferido literalmente: planos e programas nacionais, regionais e setoriais são elaborados em consonância com o PPA e apreciados pelo Congresso; a LOA contém os três orçamentos do art. 165, §5º; a LDO possui conteúdo próprio no §2º.", "steps": ["A é problemática porque o §7º fala dos orçamentos fiscal e de investimento, não de fiscal e seguridade social, ao tratar da redução de desigualdades inter-regionais.", "B atribui à LDO o demonstrativo regionalizado do efeito de renúncias, mas essa exigência está ligada ao projeto da LOA, no art. 165, §6º.", "C reproduz uma estrutura temporal que não corresponde, no texto constitucional tradicional do art. 165, aos termos apresentados na alternativa.", "D também apresenta redação que não corresponde de forma segura a um dispositivo central do art. 165.", "E é falsa porque menciona consonância com a LDO, quando a Constituição exige consonância com o PPA.", "Assim, o material extraído não oferece uma alternativa inequivocamente correta; o gabarito registrado D deve ser conferido no original."], "calculation": "Não há cálculo.", "whyCorrect": "O gabarito registrado no material é D, mas a análise literal do texto extraído não permite validar D com segurança. Recomenda-se conferir a questão original antes de consolidar a regra.", "whyWrong": "A, B e E apresentam desconformidades identificáveis com a literalidade constitucional; C e D também dependem de conferência da redação original.", "basis": "CF/1988, art. 165, §§1º a 8º.", "fafipaTrap": "Questões de PPA/LDO/LOA frequentemente trocam uma única palavra — especialmente “PPA” por “LDO” — para induzir erro.", "title": "Resolução individual — Questão 257", "status": "resolvida"}'::jsonb WHERE id='3600657';
UPDATE questoes SET resolution='{"whatTests": "Regras constitucionais sobre LDO, LOA, PPA, vinculação de impostos e despesa com pessoal.", "rule": "LDO tem conteúdo definido pela Constituição e LRF. A LOA segue o princípio da exclusividade, com exceções. Investimentos plurianuais exigem PPA ou lei que autorize a inclusão. A vedação de vinculação de impostos possui exceções constitucionais. Criação de cargos e aumentos de despesa com pessoal dependem de requisitos constitucionais.", "steps": ["I é verdadeira: a LDO compreende metas/prioridades, orienta a LOA e dispõe sobre alterações tributárias.", "II é falsa: a LOA não pode conter livremente dispositivos estranhos à previsão da receita e fixação da despesa; existem apenas exceções constitucionais.", "III é verdadeira: investimento que ultrapasse um exercício exige prévia inclusão no PPA ou lei que autorize a inclusão.", "IV é falsa porque a própria Constituição prevê exceções à vedação de vinculação de impostos.", "V é verdadeira quanto à necessidade de dotação e autorização específica para criação de cargos/alterações remuneratórias, observados os requisitos constitucionais.", "Logo, I, III e V estão corretas."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa C corresponde a I, III e V, apenas.", "whyWrong": "A inclui IV; B inclui II e IV; D inclui II e IV.", "basis": "CF/1988, arts. 165, 167 e 169; LRF, art. 4º.", "fafipaTrap": "A expressão “sem exceções” em IV é o ponto de alerta: a CF traz exceções à regra de não vinculação.", "title": "Resolução individual — Questão 258", "status": "resolvida"}'::jsonb WHERE id='3710438';
UPDATE questoes SET resolution='{"whatTests": "Características e vigência dos instrumentos PPA, LDO e LOA.", "rule": "PPA define diretrizes, objetivos e metas de forma regionalizada para despesas de capital e programas de duração continuada e tem vigência de quatro anos, alcançando parte do mandato seguinte. LDO orienta a LOA e trata das metas/prioridades e temas fiscais. LOA estima receita e fixa despesa e compreende os três orçamentos constitucionais.", "steps": ["I é verdadeira: descreve o PPA e sua vigência quadrienal.", "II é verdadeira: descreve a LDO.", "III é verdadeira: descreve a LOA.", "IV é falsa: iniciativa não é do Legislativo e o PPA não possui vigência anual.", "V é falsa: a LDO tem relação direta com o planejamento e o controle fiscal.", "Logo, I, II e III estão corretas."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa B corresponde a I, II e III, apenas.", "whyWrong": "A inclui V; C considera IV e V; D inclui IV; E inclui IV e V.", "basis": "CF/1988, art. 165; LRF, arts. 4º e 5º.", "fafipaTrap": "Não confunda o ciclo de quatro anos do PPA com o exercício financeiro anual da LOA.", "title": "Resolução individual — Questão 259", "status": "resolvida"}'::jsonb WHERE id='3930703';
UPDATE questoes SET resolution='{"whatTests": "Cálculo do Resultado Patrimonial na DVP.", "rule": "O Resultado Patrimonial é a diferença entre as Variações Patrimoniais Aumentativas (VPA) e as Variações Patrimoniais Diminutivas (VPD).", "steps": ["Some as VPA: 250.000 + 35.000 + 120.000 + 60.000 + 25.000 = R$ 490.000.", "Some as VPD: 15.000 + 200.000 + 80.000 + 30.000 + 20.000 + 170.000 = R$ 515.000.", "Resultado Patrimonial = VPA − VPD = 490.000 − 515.000 = −R$ 25.000.", "Resultado negativo significa que as VPD superaram as VPA no período."], "calculation": "VPA = R$ 490.000; VPD = R$ 515.000; Resultado = R$ 490.000 − R$ 515.000 = −R$ 25.000.", "whyCorrect": "A alternativa C apresenta R$ -25.000,00.", "whyWrong": "A, D e E são positivos ou têm valor diferente; B apresenta −55.000, que não resulta da soma dos itens fornecidos.", "basis": "MCASP 11ª edição — Demonstração das Variações Patrimoniais; NBC TSP 11.", "fafipaTrap": "Na DVP, não confunda resultado patrimonial com resultado orçamentário: aqui o confronto é VPA × VPD.", "title": "Resolução individual — Questão 260", "status": "resolvida"}'::jsonb WHERE id='3435201';
UPDATE questoes SET resolution='{"whatTests": "Cálculo do Resultado Patrimonial na Demonstração das Variações Patrimoniais (DVP).", "rule": "Na DVP, o resultado patrimonial decorre da diferença entre as Variações Patrimoniais Aumentativas (VPA) e as Variações Patrimoniais Diminutivas (VPD), independentemente da execução orçamentária.", "steps": ["Classifique como VPA: Transferências e Delegações Recebidas (180.000), Exploração e Venda de Bens, Serviços e Direitos (110.000), VPA Financeiras (50.000), Valorização e Ganhos com Ativos e Desincorporação de Passivos (20.000) e Outras VPA (30.000).", "Some as VPA: 180.000 + 110.000 + 50.000 + 20.000 + 30.000 = R$ 390.000.", "Classifique como VPD: Pessoal e Encargos (160.000), Uso de Bens, Serviços e Consumo de Capital Fixo (90.000), Desvalorização e Perdas de Ativos (25.000), VPD Financeiras (35.000), Benefícios Previdenciários e Assistenciais (190.000) e Outras VPD (20.000).", "Some as VPD: 160.000 + 90.000 + 25.000 + 35.000 + 190.000 + 20.000 = R$ 520.000.", "Resultado = 390.000 − 520.000 = −R$ 130.000."], "calculation": "VPA = R$ 390.000; VPD = R$ 520.000; Resultado Patrimonial = −R$ 130.000.", "whyCorrect": "A alternativa A apresenta déficit patrimonial de R$ 130.000,00.", "whyWrong": "B e D indicam resultado positivo; C apresenta valor incompatível com a soma das VPA/VPD; a diferença correta é negativa em R$ 130.000.", "basis": "MCASP 11ª edição — Demonstração das Variações Patrimoniais; NBC TSP 11.", "fafipaTrap": "Não retire VPA/VPD financeiras do cálculo: elas são variações patrimoniais e afetam o resultado patrimonial.", "title": "Resolução individual — Questão 261", "status": "resolvida"}'::jsonb WHERE id='3598387';
UPDATE questoes SET resolution='{"whatTests": "Identificação e cálculo das VPA/VPD na DVP.", "rule": "VPA e VPD abrangem as variações patrimoniais do período. Variações financeiras patrimoniais também compõem a DVP; não são meras entradas ou saídas de caixa.", "steps": ["VPA: transferências recebidas 250.000 + valorização/ganhos 25.000 + exploração/venda 90.000 + outras VPA 18.000 = R$ 383.000.", "VPD: pessoal 180.000 + VPD financeiras 15.000 + desvalorização/perdas 12.000 + uso de bens/serviços/consumo de capital fixo 60.000 + outras VPD 8.000 + benefícios previdenciários/assistenciais 150.000 = R$ 425.000.", "Resultado patrimonial = 383.000 − 425.000 = −R$ 42.000, portanto há déficit patrimonial, e não superávit.", "A terceira afirmação é falsa porque variações patrimoniais financeiras afetam o resultado patrimonial.", "A quarta e a quinta são verdadeiras: a DVP evidencia variações patrimoniais e o resultado decorre da diferença entre VPA e VPD."], "calculation": "VPA = R$ 383.000; VPD = R$ 425.000; resultado = −R$ 42.000.", "whyCorrect": "A sequência é V, F, F, V, V, correspondente à alternativa C.", "whyWrong": "A considera II e III verdadeiras; B, D e E apresentam sequências incompatíveis com as cinco afirmações.", "basis": "MCASP 11ª edição — DVP; NBC TSP 11.", "fafipaTrap": "“Financeiras” não significa automaticamente “orçamentárias” ou “caixa”. Na DVP, são variações patrimoniais.", "title": "Resolução individual — Questão 262", "status": "resolvida"}'::jsonb WHERE id='3930639';
UPDATE questoes SET resolution='{"whatTests": "Restos a Pagar Processados e Não Processados e distinção entre resultado orçamentário e patrimonial.", "rule": "Despesa empenhada e não liquidada pode ser inscrita como Restos a Pagar Não Processados; despesa liquidada e não paga, como Restos a Pagar Processados. Resultado patrimonial não pode ser obtido simplesmente subtraindo despesa empenhada da receita arrecadada.", "steps": ["RPP = despesas liquidadas − despesas pagas = 4.500.000 − 4.300.000 = R$ 200.000.", "RPNP = despesas empenhadas − despesas liquidadas = 5.200.000 − 4.500.000 = R$ 700.000.", "A afirmação III é falsa: 6.000.000 − 4.300.000 ou 5.200.000 não representa, por si só, resultado patrimonial.", "A afirmação IV é tratada pelo material como verdadeira no contexto da indisponibilidade de caixa para obrigações de restos a pagar sujeitas à regra fiscal aplicável.", "A afirmação V é falsa: o critério não é exclusivamente o pagamento; empenho e liquidação determinam a classificação dos restos a pagar."], "calculation": "RPP = R$ 200.000; RPNP = R$ 700.000.", "whyCorrect": "A alternativa B reúne I, II e IV, apenas, conforme o gabarito do material.", "whyWrong": "C e D incluem III; A inclui V; E considera todas as afirmações verdadeiras.", "basis": "Lei nº 4.320/1964, art. 36; LRF, especialmente art. 42, quando aplicável.", "fafipaTrap": "RPP = liquidou e não pagou; RPNP = empenhou e não liquidou. E não confunda resultado orçamentário com resultado patrimonial.", "title": "Resolução individual — Questão 263", "status": "resolvida"}'::jsonb WHERE id='3930644';
UPDATE questoes SET resolution='{"whatTests": "Apuração simplificada do resultado financeiro no Balanço Financeiro.", "rule": "No contexto da questão, o resultado financeiro é obtido pela diferença entre os ingressos/receitas e os dispêndios/despesas considerados no exercício. O valor-base indicado pelo gabarito é a diferença entre receitas arrecadadas e despesas empenhadas.", "steps": ["Receitas arrecadadas = R$ 3.200.000.", "Despesas empenhadas = R$ 2.900.000.", "Diferença = 3.200.000 − 2.900.000 = R$ 300.000.", "Os restos a pagar informados integram a movimentação financeira conforme sua natureza e não alteram a diferença-base indicada na questão."], "calculation": "R$ 3.200.000 − R$ 2.900.000 = R$ 300.000.", "whyCorrect": "A alternativa B indica superávit financeiro de R$ 300.000,00.", "whyWrong": "A, C e D resultam de confrontos inadequados dos valores ou de dupla contagem dos restos a pagar.", "basis": "MCASP 11ª edição — Balanço Financeiro.", "fafipaTrap": "Leia exatamente quais valores a questão manda confrontar; não misture restos a pagar com o resultado orçamentário sem identificar a estrutura da demonstração.", "title": "Resolução individual — Questão 264", "status": "resolvida"}'::jsonb WHERE id='3598396';
UPDATE questoes SET resolution='{"whatTests": "Conteúdo do Balanço Financeiro.", "rule": "O Balanço Financeiro evidencia receitas e despesas orçamentárias, transferências financeiras, recebimentos e pagamentos extraorçamentários e saldos em espécie, conforme a estrutura do MCASP. Receita fixada e despesa prevista não são elementos do Balanço Financeiro.", "steps": ["A fala em receita fixada e despesa prevista; esses conceitos são próprios do planejamento/orçamento, não da movimentação financeira efetivamente evidenciada pelo Balanço Financeiro.", "B corresponde às transferências financeiras recebidas e concedidas.", "C corresponde a outras movimentações de caixa/equivalentes.", "D corresponde aos recebimentos e pagamentos extraorçamentários."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa A é a exceção solicitada: receita fixada e despesa prevista não compõem o Balanço Financeiro nessa forma.", "whyWrong": "B, C e D descrevem componentes da movimentação financeira evidenciada no demonstrativo.", "basis": "MCASP 11ª edição — Balanço Financeiro.", "fafipaTrap": "“Previsão/fixação” aponta para orçamento; “recebimentos/pagamentos” aponta para a dimensão financeira.", "title": "Resolução individual — Questão 265", "status": "resolvida"}'::jsonb WHERE id='3599090';
UPDATE questoes SET resolution='{"whatTests": "Limites da despesa total com pessoal na LRF.", "rule": "A despesa total com pessoal não poderá exceder, em cada ente, os percentuais da receita corrente líquida definidos no art. 19 da LRF: União 50%, Estados 60% e Municípios 60%.", "steps": ["União → 50% da RCL.", "Estados → 60% da RCL.", "Municípios → 60% da RCL.", "A sequência coincide com a alternativa A."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa A reproduz os limites do art. 19 da LRF.", "whyWrong": "B e E reduzem indevidamente os limites de Estados/Municípios; C eleva o limite da União para 60%; D troca o limite municipal.", "basis": "Lei Complementar nº 101/2000, art. 19.", "fafipaTrap": "Memorize 50–60–60: União 50%; Estados 60%; Municípios 60%.", "title": "Resolução individual — Questão 266", "status": "resolvida"}'::jsonb WHERE id='3441257';
UPDATE questoes SET resolution='{"whatTests": "Relação entre registros fiscal, patrimonial e orçamentário e os demonstrativos públicos.", "rule": "No MCASP, os registros fiscais servem de base para relatórios fiscais como RGF e RREO. Registros patrimoniais sustentam demonstrações patrimoniais, enquanto registros orçamentários sustentam os demonstrativos orçamentários. A questão exige distinguir essas bases.", "steps": ["Primeira afirmação: verdadeira — registros de natureza fiscal servem de base para informações do RGF e RREO.", "Segunda: falsa — não se deve atribuir aos registros patrimoniais, como regra, a base principal do RREO e dos Balanços Orçamentário e Financeiro.", "Terceira: falsa — BP e DVP são demonstrações patrimoniais, não produtos derivados exclusivamente dos registros orçamentários.", "Logo, V, F, F."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa D apresenta V, F, F.", "whyWrong": "A, C e E atribuem natureza patrimonial ou orçamentária aos demonstrativos de forma incompatível com a classificação do MCASP.", "basis": "MCASP 11ª edição — aspectos da informação contábil e demonstrações/relatórios.", "fafipaTrap": "Associe “BP/DVP” ao aspecto patrimonial; “Balanço Orçamentário” ao orçamentário; RGF/RREO têm forte dimensão fiscal.", "title": "Resolução individual — Questão 267", "status": "resolvida"}'::jsonb WHERE id='3441212';
UPDATE questoes SET resolution='{"whatTests": "Categorias econômicas da receita orçamentária.", "rule": "A Lei nº 4.320/1964 classifica a receita orçamentária em duas categorias econômicas: Receitas Correntes e Receitas de Capital.", "steps": ["Elimine classificações como primárias/financeiras, originárias/derivadas e prevista/realizada: são classificações de outra natureza.", "A classificação por categoria econômica é Correntes e Capital."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa B é literal: Correntes e de Capital.", "whyWrong": "A, C, D e E utilizam classificações que não são as duas categorias econômicas previstas na Lei nº 4.320/1964.", "basis": "Lei nº 4.320/1964, art. 11.", "fafipaTrap": "“Categoria econômica” = Corrente ou Capital. Não confunda com origem ou espécie da receita.", "title": "Resolução individual — Questão 268", "status": "resolvida"}'::jsonb WHERE id='2416280';
UPDATE questoes SET resolution='{"whatTests": "Identificação de receita pertencente à origem Outras Receitas Correntes.", "rule": "Multas e juros de mora são classificados em Outras Receitas Correntes, dentro da estrutura da classificação por natureza da receita.", "steps": ["Compensações financeiras pertencem a outra origem de receita corrente.", "Taxas de fiscalização sanitária são receitas tributárias, especificamente taxas.", "Multas constituem Outras Receitas Correntes.", "Concessões e permissões têm origem própria; repasses de convênios são transferências, conforme a classificação aplicável."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa C é a correta: receitas de multas.", "whyWrong": "A, B, D e E apontam para outras origens/classificações.", "basis": "Lei nº 4.320/1964, art. 11; MCASP 11ª edição — classificação por natureza da receita.", "fafipaTrap": "“Multas” é um gatilho clássico para Outras Receitas Correntes.", "title": "Resolução individual — Questão 269", "status": "resolvida"}'::jsonb WHERE id='2416281';
UPDATE questoes SET resolution='{"whatTests": "Separação entre receitas correntes e de capital.", "rule": "Tributárias, agropecuárias e industriais são receitas correntes. Amortização de empréstimos e operações de crédito são receitas de capital.", "steps": ["I Tributárias → corrente.", "II Agropecuárias → corrente.", "III Industriais → corrente.", "IV Amortização de empréstimos → capital.", "V Operação de crédito → capital.", "Somente I, II e III estão no grupo das correntes."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa A apresenta I, II e III, apenas.", "whyWrong": "B mistura II com V; C inclui receitas de capital; D e E incluem IV/V.", "basis": "Lei nº 4.320/1964, art. 11; MCASP 11ª edição.", "fafipaTrap": "Operação de crédito e amortização de empréstimos são receitas de capital; não são correntes.", "title": "Resolução individual — Questão 270", "status": "resolvida"}'::jsonb WHERE id='2416282';
UPDATE questoes SET resolution='{"whatTests": "Cálculo das receitas de capital em uma lista de ingressos.", "rule": "Receitas de capital incluem operações de crédito, alienação de bens, amortização de empréstimos e transferências de capital. ARO e caução não devem ser tratados como receita orçamentária de capital.", "steps": ["Alienação de imóveis = R$ 8.000.", "Amortização de empréstimos = R$ 7.000.", "Operação de crédito por ARO não entra como receita orçamentária de capital; é ingresso financeiro com natureza extraorçamentária conforme a disciplina aplicável.", "Caução também não é receita orçamentária.", "Os demais itens são receitas correntes.", "Total de capital = 8.000 + 7.000 = R$ 15.000."], "calculation": "R$ 8.000 + R$ 7.000 = R$ 15.000.", "whyCorrect": "A alternativa D apresenta R$ 15.000,00.", "whyWrong": "A, B, C e E incluem receitas correntes ou ingressos que não devem ser somados como receita de capital.", "basis": "Lei nº 4.320/1964, art. 11; MCASP 11ª edição.", "fafipaTrap": "ARO é uma pegadinha recorrente: não confunda operação de crédito por ARO com receita orçamentária de capital comum.", "title": "Resolução individual — Questão 271", "status": "resolvida"}'::jsonb WHERE id='2416283';
UPDATE questoes SET resolution='{"whatTests": "Reconhecimento de exemplos de receitas correntes.", "rule": "Receitas patrimoniais, agropecuárias e industriais integram as Receitas Correntes.", "steps": ["A contém operação de crédito → capital.", "B contém operação de crédito → capital.", "C contém alienação de bens → capital.", "D reúne patrimonial, agropecuária e industrial → todas correntes.", "E contém alienação de bens e amortização → capital."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa D é a única formada apenas por receitas correntes.", "whyWrong": "A, B, C e E contêm pelo menos um item de receita de capital.", "basis": "Lei nº 4.320/1964, art. 11.", "fafipaTrap": "Receita patrimonial é corrente; alienação de bens é capital.", "title": "Resolução individual — Questão 272", "status": "resolvida"}'::jsonb WHERE id='1741179';
UPDATE questoes SET resolution='{"whatTests": "Identificação de receitas de capital.", "rule": "Operações de crédito, alienação de bens e amortização de empréstimos são espécies de receitas de capital.", "steps": ["Amortização de empréstimos → capital.", "Operações de crédito → capital.", "Alienação de bens → capital.", "Receita patrimonial é corrente, por isso alternativas que a incluem não podem ser a resposta."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa C reúne apenas receitas de capital.", "whyWrong": "A contém receitas correntes; B e D incluem receita patrimonial, que é corrente.", "basis": "Lei nº 4.320/1964, art. 11.", "fafipaTrap": "Tríade para memorizar: operação de crédito + alienação de bens + amortização de empréstimos = capital.", "title": "Resolução individual — Questão 273", "status": "resolvida"}'::jsonb WHERE id='1973371';
UPDATE questoes SET resolution='{"whatTests": "Reconhecimento da categoria econômica Receitas de Capital.", "rule": "Operações de crédito, alienação de bens, amortização de empréstimos e transferências de capital são receitas de capital.", "steps": ["Compare os exemplos citados no enunciado com a classificação econômica.", "Todos pertencem à categoria Receitas de Capital."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa A é correta.", "whyWrong": "B é a categoria oposta; C e D são espécies/origens específicas, não a categoria econômica pedida.", "basis": "Lei nº 4.320/1964, art. 11.", "fafipaTrap": "A questão pede categoria econômica, não uma espécie específica.", "title": "Resolução individual — Questão 274", "status": "resolvida"}'::jsonb WHERE id='1058159';
UPDATE questoes SET resolution='{"whatTests": "Cálculo de receitas de capital a partir de lançamentos diversos.", "rule": "Operação de crédito, alienação de bens e amortização de empréstimos são receitas de capital; IPTU e concessões/permissões de uso, na classificação apresentada, são correntes.", "steps": ["Operação de crédito = R$ 900,00.", "Alienação de bens móveis = R$ 202,05.", "Amortização de empréstimos concedidos = R$ 102,10.", "Somatório = 900 + 202,05 + 102,10 = R$ 1.204,15.", "IPTU e concessões/permissões não entram nesse total de capital."], "calculation": "R$ 900,00 + R$ 202,05 + R$ 102,10 = R$ 1.204,15.", "whyCorrect": "A alternativa C apresenta R$ 1.204,15.", "whyWrong": "As demais alternativas incluem valores de receitas correntes ou apresentam soma incorreta.", "basis": "Lei nº 4.320/1964, art. 11; MCASP 11ª edição.", "fafipaTrap": "Faça a classificação antes da soma; a banca mistura receitas correntes e de capital para testar isso.", "title": "Resolução individual — Questão 275", "status": "resolvida"}'::jsonb WHERE id='1058803';
UPDATE questoes SET resolution='{"whatTests": "Identificação exclusiva de receitas de capital.", "rule": "Operações de crédito, alienação de bens e amortização de empréstimos são receitas de capital.", "steps": ["A inclui tributária e patrimonial → correntes.", "B inclui contribuições e serviços → correntes.", "C inclui receita industrial → corrente.", "D inclui receita tributária → corrente.", "E contém somente operações de crédito, alienação de bens e amortização de empréstimos → capital."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa E é a única composta exclusivamente por receitas de capital.", "whyWrong": "A–D têm pelo menos uma receita corrente.", "basis": "Lei nº 4.320/1964, art. 11.", "fafipaTrap": "Em questões “apenas exemplos”, basta encontrar um item corrente para eliminar a alternativa.", "title": "Resolução individual — Questão 276", "status": "resolvida"}'::jsonb WHERE id='1335920';
UPDATE questoes SET resolution='{"whatTests": "Identificação de uma receita cuja origem é de capital.", "rule": "Amortização de empréstimos é receita de capital. Juros, impostos, royalties e dívida ativa pertencem a classificações correntes na estrutura apresentada.", "steps": ["Amortização de empréstimos → receita de capital.", "Juros → receita corrente.", "Imposto de renda → receita tributária corrente.", "Royalties/compensações financeiras → receita corrente.", "Dívida ativa de tributos segue a classificação da receita de origem, não se torna capital apenas por estar inscrita em dívida ativa."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa B é correta.", "whyWrong": "A, C, D e E não representam a origem de capital pedida.", "basis": "Lei nº 4.320/1964, art. 11; MCASP 11ª edição.", "fafipaTrap": "“Dívida ativa” não transforma automaticamente a receita em capital.", "title": "Resolução individual — Questão 277", "status": "resolvida"}'::jsonb WHERE id='1336833';
UPDATE questoes SET resolution='{"whatTests": "Regras da Lei nº 4.320/1964 sobre receitas e superávit do orçamento corrente.", "rule": "O superávit do orçamento corrente, resultante do balanceamento dos totais das receitas e despesas correntes, não constitui item de receita orçamentária.", "steps": ["A está errada: receita fiscal/tributária não são categorias econômicas.", "B está errada: ARO não é espécie de receita corrente; trata-se de operação de crédito por antecipação, com tratamento específico.", "C reproduz a regra legal sobre o superávit do orçamento corrente.", "D está errada: constituição de dívida gera receita de capital quando se trata de operação de crédito.", "E está errada porque receita tributária não tem destinação exclusivamente às atividades gerais; há vinculações constitucionais específicas."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa C é correta.", "whyWrong": "A, B, D e E conflitam com a classificação e/ou regras legais.", "basis": "Lei nº 4.320/1964, art. 11, §3º e art. 43; CF/1988, art. 167, IV, com suas exceções.", "fafipaTrap": "Decore a frase: superávit do orçamento corrente não constitui item de receita orçamentária.", "title": "Resolução individual — Questão 278", "status": "resolvida"}'::jsonb WHERE id='1336834';
UPDATE questoes SET resolution='{"whatTests": "Cálculo de receitas correntes a partir de diferentes ingressos.", "rule": "Receitas correntes incluem patrimonial, multas e juros de mora, tributárias e contribuições de melhoria, além de outras espécies correntes. Caução e ARO não são somados como receita corrente; alienação de imóveis e amortização de empréstimos são capital.", "steps": ["Aluguel de imóvel = R$ 1.300,00 → corrente.", "Multas e juros de mora = R$ 500,00 → corrente.", "Impostos inscritos em dívida ativa = R$ 750,00 → corrente, pois conservam a natureza tributária.", "Contribuição de melhoria = R$ 650,00 → corrente.", "Total corrente = 1.300 + 500 + 750 + 650 = R$ 3.200,00."], "calculation": "R$ 1.300 + R$ 500 + R$ 750 + R$ 650 = R$ 3.200,00.", "whyCorrect": "A alternativa B apresenta R$ 3.200,00.", "whyWrong": "A e C excluem receitas correntes ou misturam valores; D inclui receitas de capital/ingressos que não pertencem ao cálculo.", "basis": "Lei nº 4.320/1964, art. 11; MCASP 11ª edição.", "fafipaTrap": "Dívida ativa tributária continua ligada à natureza tributária; não confunda com receita de capital.", "title": "Resolução individual — Questão 279", "status": "resolvida"}'::jsonb WHERE id='1054664';
UPDATE questoes SET resolution='{"whatTests": "Cálculo de receitas de capital a partir de uma lista de ingressos.", "rule": "Alienação de imóveis e amortização de empréstimos são receitas de capital. ARO possui tratamento específico e caução não constitui receita orçamentária.", "steps": ["Alienação de imóveis = R$ 1.450,00 → capital.", "Amortização de empréstimos = R$ 800,00 → capital.", "Total = 1.450 + 800 = R$ 2.250,00.", "Caução e ARO não devem ser incluídos como receita de capital orçamentária nessa soma."], "calculation": "R$ 1.450 + R$ 800 = R$ 2.250,00.", "whyCorrect": "A alternativa A apresenta R$ 2.250,00.", "whyWrong": "B omite a alienação; C corresponde ao total de determinadas receitas correntes; D soma indevidamente outros ingressos.", "basis": "Lei nº 4.320/1964, art. 11; MCASP 11ª edição.", "fafipaTrap": "Antes de somar, classifique cada ingresso. ARO e caução são os principais distratores.", "title": "Resolução individual — Questão 280", "status": "resolvida"}'::jsonb WHERE id='1054666';
UPDATE questoes SET resolution='{"whatTests": "Classificação por natureza da receita e identificação do que efetivamente aumenta a receita patrimonial.", "rule": "Receitas de aluguéis e concessões/permissões, na classificação usada pelo enunciado, são patrimoniais. IPTU inscrito em dívida ativa é receita tributária; operação de crédito é receita de capital; caução é ingresso extraorçamentário. A cessão de direito de operacionalização de pagamento a fornecedores, no contexto apresentado, não integra a receita patrimonial.", "steps": ["Saldo inicial de receitas patrimoniais = R$ 250.000,00.", "Aluguéis recebidos = R$ 20.000,00 → receita patrimonial.", "Concessões e permissões = R$ 35.000,00 → receita patrimonial.", "Os demais ingressos não são adicionados ao saldo patrimonial: IPTU em dívida ativa é tributário; operação de crédito é de capital; caução não é receita orçamentária.", "Saldo = 250.000 + 20.000 + 35.000 = R$ 305.000,00."], "calculation": "Pelos valores transcritos no enunciado, o saldo seria R$ 305.000,00.", "whyCorrect": "O gabarito registrado é C (R$ 330.000,00), porém os valores do texto extraído não reproduzem esse resultado: falta R$ 25.000,00 para chegar a R$ 330.000,00. Portanto, a questão deve ser conferida no PDF original antes de usar o gabarito como regra.", "whyWrong": "A, B e D não resolvem a discrepância. O ponto central é que a soma dos valores patrimoniais explicitamente identificáveis no texto é 55.000, e não 80.000.", "basis": "Lei nº 4.320/1964, art. 11; MCASP 11ª edição — classificação por natureza da receita.", "fafafaTrap": "Não classifique todo ingresso financeiro como receita patrimonial. Primeiro identifique sua natureza.", "title": "Resolução individual — Questão 281", "status": "resolvida"}'::jsonb WHERE id='1054716';
UPDATE questoes SET resolution='{"whatTests": "Identificação de espécie pertencente à receita tributária.", "rule": "A receita tributária compreende impostos, taxas e contribuições de melhoria. Iluminação pública é relacionada à contribuição para custeio do serviço de iluminação pública; exploração de bens públicos e cessão de direitos não são receita tributária.", "steps": ["Contribuição de melhoria → espécie tributária.", "Iluminação pública → não é, por si só, receita tributária.", "Exploração de bens públicos → receita patrimonial.", "Cessão de direitos → classificação não tributária."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa A é correta: contribuição de melhoria integra a receita tributária.", "whyWrong": "B, C e D correspondem a naturezas não tributárias.", "basis": "CF/1988, art. 145; Lei nº 4.320/1964, art. 11.", "fafafaTrap": "Contribuição de melhoria é tributo; contribuição de iluminação pública não deve ser confundida com receita tributária.", "title": "Resolução individual — Questão 282", "status": "resolvida"}'::jsonb WHERE id='635041';
UPDATE questoes SET resolution='{"whatTests": "Distinção entre receitas correntes e receitas de capital.", "rule": "Receitas tributárias, de contribuições, patrimoniais e de serviços são correntes. Operações de crédito são receitas de capital.", "steps": ["Tributária → corrente.", "Contribuições → corrente.", "Patrimonial → corrente.", "Operações de crédito → capital.", "Serviços → corrente."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa D é a exceção: receita de operações de crédito é receita de capital.", "whyWrong": "A, B, C e E são categorias de receitas correntes.", "basis": "Lei nº 4.320/1964, art. 11.", "fafafaTrap": "Operações de crédito aparecem repetidamente como receita de capital.", "title": "Resolução individual — Questão 283", "status": "resolvida"}'::jsonb WHERE id='924177';
UPDATE questoes SET resolution='{"whatTests": "Identificação da receita que não pertence às receitas de capital.", "rule": "Alienação de bens, amortização de empréstimos e operações de crédito são receitas de capital. Receita tributária é receita corrente.", "steps": ["Tributária → corrente.", "Alienação de bens → capital.", "Amortização de empréstimos → capital.", "Operações de crédito → capital."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa A é a exceção solicitada.", "whyWrong": "B, C e D são receitas de capital.", "basis": "Lei nº 4.320/1964, art. 11.", "fafafaTrap": "“Alienação”, “amortização de empréstimos” e “operação de crédito” apontam para capital.", "title": "Resolução individual — Questão 284", "status": "resolvida"}'::jsonb WHERE id='938443';
UPDATE questoes SET resolution='{"whatTests": "Diferença entre tributo e preço público.", "rule": "Preço público/tarifa decorre de relação de natureza contratual ou de utilização de serviço/bem público, enquanto impostos, taxas e contribuições têm natureza tributária. O gabarito do material trata a cobrança mencionada como preço público.", "steps": ["Impostos são tributos.", "Taxas são tributos.", "Contribuições têm natureza tributária.", "Preço público não é tributo e pode ser cobrado pela utilização de serviço ou bem público, conforme o caso."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa D, preço público, é a indicada pelo gabarito do material.", "whyWrong": "A, B e C são espécies tributárias e não correspondem ao conceito de preço público.", "basis": "Distinção tributária entre tributos e preços públicos; questão baseada na classificação apresentada pelo material.", "fafafaTrap": "A palavra “cobrança” não significa automaticamente tributo: identifique a natureza jurídica.", "title": "Resolução individual — Questão 285", "status": "resolvida"}'::jsonb WHERE id='1058527';
UPDATE questoes SET resolution='{"whatTests": "Classificação de receitas por categoria econômica.", "rule": "Tributária, contribuições e patrimonial são correntes. Operações de crédito, amortização de empréstimos e alienação de bens são de capital.", "steps": ["Tributária → A.", "Operações de crédito → B.", "Amortização de empréstimos → B.", "Contribuições → A.", "Alienação de bens → B.", "Patrimonial → A."], "calculation": "Sequência: A, B, B, A, B, A.", "whyCorrect": "A alternativa B corresponde à sequência correta.", "whyWrong": "A, C e D alteram pelo menos uma classificação.", "basis": "Lei nº 4.320/1964, art. 11.", "fafafaTrap": "Faça a classificação item a item antes de olhar as sequências.", "title": "Resolução individual — Questão 286", "status": "resolvida"}'::jsonb WHERE id='3013715';
UPDATE questoes SET resolution='{"whatTests": "Conceito de receitas correntes.", "rule": "O enunciado descreve ingressos de recursos financeiros oriundos das atividades operacionais, destinados a despesas também operacionais, enquadrando-os como receitas correntes.", "steps": ["Identifique a expressão “atividades operacionais”.", "Relacione-a às receitas correntes no contexto da classificação econômica.", "Não confunda receita corrente com “despesa corrente”: a questão trata do lado da receita."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa C é a resposta indicada pelo material: receitas correntes.", "whyWrong": "A trata de despesas; B trata de planejamento; D é genérico; E trata de estágio da despesa.", "basis": "Lei nº 4.320/1964, art. 11; MCASP 11ª edição.", "fafafaTrap": "A palavra “corrente” deve ser ligada à categoria econômica, não ao estágio da receita ou da despesa.", "title": "Resolução individual — Questão 287", "status": "resolvida"}'::jsonb WHERE id='966767';
UPDATE questoes SET resolution='{"whatTests": "Natureza do ingresso decorrente de processos judiciais.", "rule": "O gabarito do material classifica o valor recebido como ingresso extraorçamentário. Como a expressão “receita com processos judiciais recebidos” é pouco específica no texto extraído, a classificação deve ser conferida no contexto original da questão.", "steps": ["Identifique que a questão pergunta pela natureza do ingresso, não pela categoria econômica corrente/capital.", "O gabarito registrado é B, receita extraorçamentária.", "Não é possível, somente pela frase extraída, identificar qual tipo de valor judicial foi recebido (por exemplo, depósito de terceiro ou receita própria).", "Por isso, preserve o gabarito do material, mas marque a necessidade de conferir o enunciado original."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa B é a indicada pelo gabarito do material.", "whyWrong": "A, C, D e E tratam o ingresso como receita orçamentária ou espécie específica sem suporte suficiente no trecho extraído.", "basis": "Lei nº 4.320/1964 e MCASP 11ª edição — distinção entre receita orçamentária e ingresso extraorçamentário.", "fafafaTrap": "“Recebido nos cofres” não basta para concluir que é receita orçamentária; descubra a titularidade do recurso.", "title": "Resolução individual — Questão 288", "status": "resolvida"}'::jsonb WHERE id='966936';
UPDATE questoes SET resolution='{"whatTests": "Classificação de receitas e despesas na Lei nº 4.320/1964.", "rule": "Receitas tributárias são correntes. Receitas de contribuições, patrimoniais, agropecuárias, industriais, de serviços e outras são correntes. Transferências correntes e de capital são classificações de receitas, não despesas. Investimentos e inversões financeiras são despesas de capital.", "steps": ["I: verdadeira — tributárias são correntes.", "II: falsa — a lista apresentada é de receitas correntes, não de capital.", "III: falsa — transferências correntes e de capital são receitas, conforme o contexto, e não despesas.", "IV: verdadeira — investimentos e inversões financeiras são despesas de capital."], "calculation": "Sequência: V, F, F, V.", "whyCorrect": "A alternativa A apresenta V, F, F, V.", "whyWrong": "B considera II verdadeira; C considera III verdadeira; D inverte as duas primeiras.", "basis": "Lei nº 4.320/1964, arts. 11 e 12.", "fafafaTrap": "Não confunda “transferências de capital” (receita) com “investimentos” e “inversões financeiras” (despesa de capital).", "title": "Resolução individual — Questão 289", "status": "resolvida"}'::jsonb WHERE id='923435';
UPDATE questoes SET resolution='{"whatTests": "Correspondência entre definições de receitas correntes e de capital.", "rule": "Receitas de capital abrangem recursos de constituição de dívidas, conversão em espécie de bens e direitos e transferências de capital. Receitas correntes abrangem tributárias, contribuições, patrimoniais, agropecuárias, industriais, de serviços e outras. Operações de crédito, alienação de bens, amortização de empréstimos e transferências de capital são de capital.", "steps": ["1ª definição → Receitas de Capital (B).", "2ª definição → Receitas Correntes (A).", "3ª lista → Receitas Correntes (A).", "4ª lista → Receitas de Capital (B)."], "calculation": "Sequência: B, A, A, B.", "whyCorrect": "A alternativa D corresponde à sequência B, A, A, B.", "whyWrong": "As demais alternativas trocam pelo menos uma das categorias.", "basis": "Lei nº 4.320/1964, art. 11.", "fafafaTrap": "Leia primeiro a descrição completa; depois identifique a categoria econômica.", "title": "Resolução individual — Questão 290", "status": "resolvida"}'::jsonb WHERE id='926991';
UPDATE questoes SET resolution='{"whatTests": "Definição de concessão de garantia na LRF.", "rule": "Na LRF, concessão de garantia é compromisso de adimplência de obrigação financeira ou contratual assumida por ente da Federação ou entidade a ele vinculada, nos termos legais, em favor de terceiro.", "steps": ["A, B e C restringem indevidamente os conceitos de dívida, operação de crédito ou dívida mobiliária.", "D descreve de forma inadequada o refinanciamento da dívida mobiliária.", "E corresponde ao conceito de concessão de garantia: o ente assume compromisso de adimplência de obrigação de terceiro."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa E é a correta.", "whyWrong": "A exclui obrigações que podem integrar a dívida; B restringe operações de crédito; C exclui títulos federais; D não reproduz adequadamente o conceito legal.", "basis": "Lei Complementar nº 101/2000, art. 29, IV.", "fafafaTrap": "Garantia não é a dívida do terceiro: é o compromisso do ente de honrar a obrigação se necessário.", "title": "Resolução individual — Questão 291", "status": "resolvida"}'::jsonb WHERE id='3935837';
UPDATE questoes SET resolution='{"whatTests": "Definição de valor justo no MCASP.", "rule": "Valor justo é o valor pelo qual um ativo pode ser trocado ou um passivo liquidado entre partes conhecedoras e independentes, em transação sem favorecimentos indevidos.", "steps": ["Compare as alternativas com a definição de valor justo.", "A apresenta a definição clássica utilizada pelo material.", "B restringe a valor de mercado de bens do ativo.", "C e D descrevem procedimentos genéricos de atribuição/constatação de valor, não o conceito específico de valor justo."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa A é a correta.", "whyWrong": "B é incompleta; C e D são formulações genéricas e não correspondem à definição específica de valor justo.", "basis": "MCASP 11ª edição — bases de mensuração; definição de valor justo.", "fafafaTrap": "Valor justo envolve condições de mercado e partes independentes/conhecedoras; não é simplesmente qualquer valor de mercado.", "title": "Resolução individual — Questão 292", "status": "resolvida"}'::jsonb WHERE id='3423399';
UPDATE questoes SET resolution='{"whatTests": "Critérios de mensuração de elementos patrimoniais no setor público.", "rule": "Disponibilidades são mensuradas pelo valor original, com conversão cambial na data das demonstrações; participações com influência significativa usam equivalência patrimonial; direitos/títulos/obrigações prefixadas e pós-fixadas seguem critérios próprios de atualização previstos no MCASP.", "steps": ["I: verdadeira — disponibilidades em moeda estrangeira são convertidas pela taxa da data das demonstrações.", "II: falsa — a formulação “valor presente” para aplicações de liquidez imediata não corresponde ao critério indicado pelo material.", "III: verdadeira — influência significativa conduz ao método da equivalência patrimonial.", "IV: falsa — prefixados não são simplesmente ajustados pelo valor justo nessa formulação.", "V: verdadeira — pós-fixados são atualizados considerando os encargos incorridos até o encerramento."], "calculation": "Sequência: V, F, V, F, V.", "whyCorrect": "A alternativa B apresenta V, F, V, F, V.", "whyWrong": "A, C e D divergem em pelo menos uma das cinco assertivas.", "basis": "MCASP 11ª edição — mensuração de ativos e passivos.", "fafafaTrap": "Não aplique “valor justo” a todos os direitos e obrigações indiscriminadamente; a base de mensuração depende do elemento.", "title": "Resolução individual — Questão 293", "status": "resolvida"}'::jsonb WHERE id='3423406';
UPDATE questoes SET resolution='{"whatTests": "Apuração do patrimônio líquido no Balanço Patrimonial.", "rule": "No Balanço Patrimonial, patrimônio líquido corresponde aos ativos menos os passivos. Os itens de ativo e passivo devem ser classificados antes da apuração.", "steps": ["Ativo = estoques 51.000 + investimentos 145.000 + imobilizado 1.200.000 + caixa 350.000 + VPD pagas antecipadamente 133.000 + créditos de transferências a receber 670.000 + realizável a longo prazo 79.000 = R$ 2.628.000.", "Passivo = provisões a longo prazo 48.000 + obrigações fiscais CP 18.000 + obrigações trabalhistas/previdenciárias CP 210.000 + fornecedores CP 110.000 + provisões CP 36.000 = R$ 422.000.", "PL = 2.628.000 − 422.000 = R$ 2.206.000.", "Os saldos “resultados acumulados”, “ajustes de exercícios anteriores” e “patrimônio social” são componentes/informações do patrimônio líquido e não devem ser novamente somados ao PL apurado pela equação patrimonial."], "calculation": "Ativo = R$ 2.628.000; Passivo = R$ 422.000; PL = R$ 2.206.000.", "whyCorrect": "A alternativa D apresenta R$ 2.206.000,00.", "whyWrong": "As demais alternativas resultam de somar componentes do PL ao patrimônio líquido ou de classificar indevidamente ativos/passivos.", "basis": "MCASP 11ª edição — Balanço Patrimonial e equação patrimonial.", "fafafaTrap": "Não some “patrimônio social” e “resultados acumulados” novamente depois de calcular Ativo − Passivo.", "title": "Resolução individual — Questão 294", "status": "resolvida"}'::jsonb WHERE id='3441203';
UPDATE questoes SET resolution='{"whatTests": "Estrutura da LOA e orçamento da seguridade social.", "rule": "A Constituição determina que a LOA compreenda, entre outros, o orçamento da seguridade social, abrangendo saúde, previdência e assistência social, e que os instrumentos de planejamento sejam compatíveis entre si.", "steps": ["A está incorreta: a LDO não define exclusivamente metas fiscais e os prazos indicados não são universais para todos os entes.", "B está incorreta: o PPA não é elaborado apenas no último ano do mandato nem vigora por apenas um exercício.", "C está incorreta: a Comissão Mista analisa os projetos relativos ao PPA, LDO, orçamento anual e créditos adicionais, conforme a CF.", "D descreve corretamente o orçamento da seguridade social e sua integração com PPA/LDO.", "E está incorreta: a aprovação posterior ao início do exercício não é legitimada simplesmente por reserva de contingência."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa D é a correta.", "whyWrong": "A, B, C e E contêm restrições ou afirmações incompatíveis com a estrutura constitucional do planejamento e orçamento.", "basis": "CF/1988, arts. 165 e 166.", "fafafaTrap": "Seguridade social = saúde + previdência + assistência social.", "title": "Resolução individual — Questão 295", "status": "resolvida"}'::jsonb WHERE id='3935809';
UPDATE questoes SET resolution='{"whatTests": "Requisitos da LOA previstos na LRF.", "rule": "A LRF exige demonstrativos da compatibilidade da programação com os objetivos e metas e estimativas de renúncia de receita para o exercício e os dois seguintes, entre outros requisitos.", "steps": ["A está incorreta porque a matéria do refinanciamento não é tratada como uma vedação absoluta nesses termos.", "B reproduz o conteúdo do art. 5º da LRF quanto à compatibilidade e à estimativa da renúncia de receita.", "C erra ao limitar a estimativa ao exercício de referência.", "D contraria as regras de especificação e compatibilidade para investimentos plurianuais.", "E apresenta condição que não autoriza a extrapolação descrita."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa B é a correta.", "whyWrong": "C, D e E contradizem exigências da LRF; A formula uma vedação que não corresponde ao texto legal.", "basis": "Lei Complementar nº 101/2000, art. 5º.", "fafafaTrap": "Na LRF, renúncia de receita: exercício de referência + dois subsequentes.", "title": "Resolução individual — Questão 296", "status": "resolvida"}'::jsonb WHERE id='3935812';
UPDATE questoes SET resolution='{"whatTests": "Princípio da universalidade da LOA.", "rule": "A lei orçamentária deve compreender todas as receitas e despesas próprias dos órgãos do Governo e da administração centralizada, observadas as exceções legais.", "steps": ["A afirmação de que a LOA pode excluir receitas e despesas por conveniência administrativa viola a universalidade.", "B reproduz a regra de abrangência da LOA e responde diretamente ao caso narrado.", "C, D e E contrariam a exigência legal de previsão e autorização orçamentária."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa B é a correta.", "whyWrong": "A e D admitem exclusões incompatíveis com a universalidade; C e E negam a função legal da LOA.", "basis": "Lei nº 4.320/1964, art. 2º e art. 3º; princípio da universalidade.", "fafafaTrap": "Universalidade: não deixe receita/despesa “para depois” por simples ato administrativo.", "title": "Resolução individual — Questão 297", "status": "resolvida"}'::jsonb WHERE id='4113534';
UPDATE questoes SET resolution='{"whatTests": "Tipos de empenho: ordinário, global e estimativo.", "rule": "Empenho ordinário é usado para despesa de valor determinado e pagamento de uma só vez; global para despesa contratual ou de valor determinado sujeita a parcelamento; estimativo para despesa cujo montante não pode ser previamente determinado.", "steps": ["I é falsa: a descrição dada é de empenho global, não estimativo.", "II é falsa: valor fixo e pagamento de uma só vez corresponde ao ordinário, não ao global.", "III é falsa: água, energia e combustíveis são exemplos típicos de despesas estimativas.", "Sequência = F, F, F."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa B apresenta F, F, F.", "whyWrong": "A, C, D e E atribuem pelo menos um tipo de empenho incorretamente.", "basis": "Lei nº 4.320/1964, art. 60; MCASP 11ª edição — empenho ordinário, global e estimativo.", "fafafaTrap": "Memorize: ordinário = uma vez; global = parcelado; estimativo = valor não determinável previamente.", "title": "Resolução individual — Questão 298", "status": "resolvida"}'::jsonb WHERE id='3441252';
UPDATE questoes SET resolution='{"whatTests": "Estágios da receita pública e particularidades de arrecadação/recolhimento.", "rule": "Os estágios clássicos da receita orçamentária são previsão, lançamento, arrecadação e recolhimento, sendo que nem toda receita percorre necessariamente todos os estágios, conforme sua natureza.", "steps": ["A é falsa: unidade de tesouraria não autoriza fragmentação incompatível com a regra de centralização.", "B é correta: lançamento verifica o fato gerador, identifica o sujeito passivo e calcula o montante devido, quando cabível.", "C é falsa: a previsão deve considerar metodologia adequada e histórico/evolução da receita.", "D descreve recolhimento, não arrecadação.", "E é falsa porque nem toda receita orçamentária passa pelo lançamento; além disso, a questão trata de doação, cuja natureza precisa ser analisada."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa B é a correta.", "whyWrong": "A confunde unidade de tesouraria; C restringe indevidamente a metodologia; D troca arrecadação por recolhimento; E afirma obrigatoriedade de quatro etapas para toda receita.", "basis": "Lei nº 4.320/1964, arts. 35 e 53 a 56; MCASP 11ª edição.", "fafafaTrap": "Arrecadação = recebimento pelo agente arrecadador; recolhimento = transferência para o tesouro.", "title": "Resolução individual — Questão 299", "status": "resolvida"}'::jsonb WHERE id='4098490';
UPDATE questoes SET resolution='{"whatTests": "Regime de competência patrimonial e despesas pagas antecipadamente.", "rule": "No regime patrimonial, o pagamento antecipado de seguro cujo benefício ocorrerá em exercício futuro gera inicialmente um ativo (despesa antecipada). A VPD é reconhecida à medida que a cobertura é consumida.", "steps": ["Em 28/12/2023, o Município paga R$ 36.000,00.", "A cobertura começa em 01/01/2024; portanto, em 2023 o benefício econômico ainda não foi consumido.", "Reconhece-se um ativo de despesas pagas antecipadamente de R$ 36.000,00.", "Durante 2024, a VPD será apropriada ao longo do período de cobertura: R$ 36.000 / 12 = R$ 3.000 por mês.", "Assim, o pagamento de 2023 não gera VPD integral em 2023."], "calculation": "R$ 36.000 ÷ 12 = R$ 3.000 por mês de cobertura em 2024.", "whyCorrect": "A alternativa A é a correta.", "whyWrong": "B ignora a apropriação patrimonial em 2024; C reconhece um mês em 2023 sem cobertura; D e E reconhecem VPD integral antes do consumo do serviço.", "basis": "MCASP 11ª edição — regime de competência patrimonial e despesas antecipadas; NBC TSP Estrutura Conceitual.", "fafafaTrap": "Pagamento não é sinônimo de VPD: no regime patrimonial, reconheça a despesa quando o benefício/serviço for consumido.", "title": "Resolução individual — Questão 300", "status": "resolvida"}'::jsonb WHERE id='4074893';
UPDATE questoes SET resolution='{"what": "Definição de empresa controlada na LRF.", "rule": "A LRF considera empresa controlada a sociedade cuja maioria do capital social com direito a voto pertença, direta ou indiretamente, a ente da Federação.", "steps": ["Identificar o critério de controle: maioria do capital social com direito a voto.", "Verificar que a maioria pertence direta ou indiretamente a ente da Federação.", "Aplicar a definição do art. 2º, II, da LRF."], "calc": "Não há cálculo.", "correct": "A — Empresa Controlada.", "wrong": "B não é a definição legal; C não corresponde ao conceito cobrado; D exige requisitos adicionais para empresa estatal dependente; E não é categoria da LRF.", "basis": "Lei Complementar nº 101/2000, art. 2º, II.", "trap": "FAFIPA pode trocar “maioria do capital com direito a voto” por simples participação societária ou confundir controlada com estatal dependente."}'::jsonb WHERE id='3862422';
UPDATE questoes SET resolution='{"what": "Identificação da alternativa incorreta sobre a LRF.", "rule": "A LRF veda operação de crédito em desacordo com as regras fiscais e disciplina a ARO, pessoal, transparência e endividamento. A operação de crédito por antecipação de receita orçamentária (ARO) tem requisitos específicos e não pode ser usada livremente para financiar despesa corrente imprevista.", "steps": ["A alternativa B afirma que ARO pode ser contratada sem disponibilidade de caixa e para despesas correntes imprevistas ou urgentes.", "Essa formulação não corresponde ao regime da LRF para ARO.", "As demais alternativas descrevem, em linhas gerais, regras expressas da LRF."], "calc": "Não há cálculo.", "correct": "B — é a INCORRETA.", "wrong": "A relaciona-se à regra de ouro prevista no art. 12, §2º; C reproduz o limite global de pessoal dos Estados e Municípios; D trata da transparência; E trata dos limites de endividamento.", "basis": "Lei Complementar nº 101/2000, especialmente arts. 9º, 12, 32–38 e 48.", "trap": "Não confundir ARO com empréstimo comum nem imaginar que urgência da despesa elimina os requisitos legais da ARO."}'::jsonb WHERE id='3114937';
UPDATE questoes SET resolution='{"what": "Limite de pessoal do Poder Legislativo municipal.", "rule": "No âmbito municipal, o limite global de despesa com pessoal é 60% da RCL; desse total, cabem 6% ao Legislativo, incluído o Tribunal de Contas do Município, quando houver, e 54% ao Executivo.", "steps": ["Partir do limite global municipal de 60% da RCL.", "Aplicar a repartição do art. 20, III, da LRF.", "Para o Legislativo municipal, o limite é 6%."], "calc": "Limite da Câmara = 6% da Receita Corrente Líquida.", "correct": "B — 6%.", "wrong": "7%, 4%, 5% e 8% não correspondem ao limite do Legislativo municipal na LRF.", "basis": "Lei Complementar nº 101/2000, arts. 19, III, e 20, III, “a”.", "trap": "A banca pode apresentar 60% — que é o limite global municipal — como se fosse o limite da Câmara."}'::jsonb WHERE id='2715416';
UPDATE questoes SET resolution='{"what": "Limite global de despesa com pessoal dos Municípios.", "rule": "A despesa total com pessoal, em cada período de apuração, não pode exceder 60% da RCL nos Municípios.", "steps": ["Identificar o ente: Município.", "Aplicar o art. 19, III, da LRF.", "O limite global é 60% da RCL."], "calc": "Limite = 60% da RCL.", "correct": "C — 60%.", "wrong": "30%, 40% e 50% não são o limite global municipal previsto no art. 19, III.", "basis": "Lei Complementar nº 101/2000, art. 19, III.", "trap": "Memorize separado: limite global municipal 60%; dentro dele, Executivo 54% e Legislativo 6%."}'::jsonb WHERE id='2746553';
UPDATE questoes SET resolution='{"what": "Característica qualitativa da verificabilidade na informação contábil pública.", "rule": "Verificabilidade ajuda a assegurar aos usuários que a informação representa fielmente os fenômenos econômicos ou de outra natureza que se propõe a representar.", "steps": ["Comparar as alternativas com as definições das características qualitativas.", "A alternativa D descreve a verificabilidade.", "As demais descrevem comparabilidade, relevância, compreensibilidade e tempestividade."], "calc": "Não há cálculo.", "correct": "D.", "wrong": "A é comparabilidade; B é relevância; C é compreensibilidade; E é tempestividade.", "basis": "MCASP/NBC TSP Estrutura Conceitual — características qualitativas da informação contábil.", "trap": "Não confundir verificabilidade com representação fidedigna: a primeira ajuda a assegurar que a representação fidedigna pode ser sustentada/verificada."}'::jsonb WHERE id='2416273';
UPDATE questoes SET resolution='{"what": "Limite global de pessoal dos Municípios.", "rule": "O limite global de despesa total com pessoal dos Municípios é de 60% da Receita Corrente Líquida.", "steps": ["Identificar o ente municipal.", "Aplicar o art. 19, III, da LRF.", "Selecionar 60%."], "calc": "60% da RCL.", "correct": "E — 60%.", "wrong": "70%, 30%, 50% e 40% não são o limite global municipal.", "basis": "Lei Complementar nº 101/2000, art. 19, III.", "trap": "Questão direta de memorização; cuidado para não trocar o limite global pelo limite de um Poder."}'::jsonb WHERE id='2153554';
UPDATE questoes SET resolution='{"what": "Limite global de pessoal dos Municípios.", "rule": "Municípios: 60% da RCL para despesa total com pessoal.", "steps": ["Identificar o Município.", "Aplicar o limite do art. 19, III.", "Resultado: 60%."], "calc": "60% da RCL.", "correct": "A — 60%.", "wrong": "15%, 30% e 27,50% não são o limite global municipal.", "basis": "Lei Complementar nº 101/2000, art. 19, III.", "trap": "A banca troca frequentemente o 60% global pelos 54% do Executivo ou 6% do Legislativo."}'::jsonb WHERE id='2431292';
UPDATE questoes SET resolution='{"what": "Identificação das características qualitativas da informação contábil.", "rule": "I descreve representação fidedigna; II, comparabilidade; III, compreensibilidade; IV, representação fidedigna; V, tempestividade; VI, relevância. A questão, contudo, usa IV como definição de representação fidedigna e a alternativa correta é a que organiza as correspondências conforme o texto.", "steps": ["I: “representa fielmente” → representação fidedigna.", "II: identificar semelhanças e diferenças → comparabilidade.", "III: entender o significado → compreensibilidade.", "IV: completa, neutra e livre de erro material → representação fidedigna.", "V: informação disponível antes de perder utilidade → tempestividade.", "VI: valor confirmatório, preditivo ou ambos → relevância."], "calc": "Não há cálculo.", "correct": "C — conforme o gabarito registrado no caderno.", "wrong": "As alternativas A, B, D e E trocam pelo menos uma das características.", "basis": "NBC TSP Estrutura Conceitual / MCASP, características qualitativas da informação contábil.", "trap": "Observe que a mesma característica pode aparecer em mais de uma assertiva; IV também descreve representação fidedigna."}'::jsonb WHERE id='2156862';
UPDATE questoes SET resolution='{"what": "Regime de competência e objetivo das entidades públicas.", "rule": "A contabilidade do setor público utiliza o regime de competência para os registros patrimoniais, e o objetivo principal da maioria das entidades públicas é prestar serviços à sociedade, não gerar lucro para investidores.", "steps": ["I: regime de competência → verdadeira.", "II: prestação de serviços à sociedade como objetivo principal → verdadeira.", "Logo, I e II são verdadeiras."], "calc": "Não há cálculo.", "correct": "A — I e II são verdadeiras.", "wrong": "B e D eliminam uma das assertivas verdadeiras; C considera ambas falsas; E não se aplica.", "basis": "NBC TSP Estrutura Conceitual.", "trap": "Não confundir objetivo público com objetivo típico de entidade empresarial: resultado financeiro é relevante, mas não resume o desempenho do setor público."}'::jsonb WHERE id='2158740';
UPDATE questoes SET resolution='{"what": "Texto do item 1.4 da NBC TSP Estrutura Conceitual sobre RCPGs.", "rule": "O item citado caracteriza os RCPGs como componentes centrais da transparência da informação contábil e como relatórios contábeis destinados a atender às necessidades dos usuários em geral, sem finalidade específica para determinado grupo.", "steps": ["Comparar “relatórios matemáticos”, “físicos”, “químicos” e “contábeis”.", "A expressão correta é “relatórios contábeis”.", "A alternativa E reproduz a formulação registrada no material."], "calc": "Não há cálculo.", "correct": "E.", "wrong": "B, C e D alteram artificialmente o termo “contábeis”; A é desnecessária porque há alternativa compatível.", "basis": "NBC TSP Estrutura Conceitual, item 1.4, conforme texto cobrado no caderno.", "trap": "Questão de literalidade: uma única palavra alterada invalida a alternativa."}'::jsonb WHERE id='2158741';
UPDATE questoes SET resolution='{"what": "Definição de empresa estatal dependente na NBC TSP Estrutura Conceitual.", "rule": "Empresa estatal dependente é empresa controlada que recebe do ente controlador recursos financeiros para pagamento de despesas com pessoal, custeio em geral ou despesas de capital, excluídos, no último caso, os recursos provenientes de aumento de participação acionária.", "steps": ["Identificar “empresa controlada”.", "Identificar recursos do ente controlador para pessoal, custeio ou capital.", "Na despesa de capital, excluir recursos provenientes de aumento de participação acionária."], "calc": "Não há cálculo.", "correct": "D.", "wrong": "A troca “pessoal” por “pessoais”; B troca aumento por diminuição de participação; C nega a existência da definição; E troca controlada por descontrolada.", "basis": "NBC TSP Estrutura Conceitual, item 1.8B, conforme texto cobrado.", "trap": "A expressão-chave é “aumento de participação acionária”; a banca altera uma única palavra para mudar o sentido."}'::jsonb WHERE id='2158742';
UPDATE questoes SET resolution='{"what": "Objetivo principal do governo e avaliação do desempenho público.", "rule": "O objetivo principal dos governos e da maioria das entidades do setor público é prestar serviços à sociedade. Seu desempenho não é total ou adequadamente refletido por uma única medida de resultados financeiros; por isso, resultados financeiros devem ser avaliados no contexto dos resultados da prestação de serviços.", "steps": ["Identificar o objetivo: prestar serviços à sociedade.", "Reconhecer que resultados financeiros não capturam integralmente o desempenho público.", "Concluir que os resultados financeiros devem ser analisados junto dos resultados da prestação de serviços."], "calc": "Não há cálculo.", "correct": "E.", "wrong": "A erra ao dizer que resultados financeiros não precisam ser contextualizados; B diz que o desempenho é adequadamente refletido por medidas financeiras; C troca o objetivo público por “melhorar as contas”; D é desnecessária.", "basis": "NBC TSP Estrutura Conceitual, item 2.22, conforme texto cobrado.", "trap": "Não concluir que resultado financeiro é irrelevante; o ponto é que ele não é suficiente, sozinho, para medir o desempenho público."}'::jsonb WHERE id='2158743';
UPDATE questoes SET resolution='{"what": "Mensurações quantitativas de produtos e resultados da prestação de serviços.", "rule": "O item 2.23 reconhece que, em alguns casos, mensurações quantitativas fornecem informações relevantes; em outros, pode ser necessário explicar qualidade de serviços ou resultados de programas.", "steps": ["Localizar a expressão “em alguns casos”.", "Verificar que o texto prossegue com “em outros casos”.", "A alternativa C mantém essa estrutura e o conteúdo correspondente."], "calc": "Não há cálculo.", "correct": "C.", "wrong": "B usa “em todos os casos” nas duas situações; D nega a relevância das mensurações; E usa “em todos os casos” para a segunda parte; A não se aplica.", "basis": "NBC TSP Estrutura Conceitual, item 2.23, conforme texto cobrado.", "trap": "Questão de literalidade: “alguns casos” versus “todos os casos” muda completamente a proposição."}'::jsonb WHERE id='2158745';
UPDATE questoes SET resolution='{"what": "Classificação da Unidade Contábil que representa parcela do patrimônio de Unidade Contábil Originária.", "rule": "Na terminologia da antiga NBC T 16.1, a unidade contábil descentralizada representa parcela do patrimônio de uma unidade contábil originária.", "steps": ["Identificar que a pergunta fala em “parcela do patrimônio”.", "Essa parcela pertence a uma unidade contábil originária.", "A classificação correspondente é descentralizada."], "calc": "Não há cálculo.", "correct": "C — Descentralizada.", "wrong": "Originária é a unidade-base; consolidada e unificada são outras formas de agregação; “centralizada” não é a classificação pedida.", "basis": "NBC T 16.1, conforme a terminologia cobrada na questão.", "trap": "Não confundir “descentralizada” com “unificada”: a primeira trata de parcela do patrimônio de unidade originária."}'::jsonb WHERE id='2413232';
UPDATE questoes SET resolution='{"what": "Entidades não abrangidas pela exigibilidade indicada na questão.", "rule": "No recorte tradicional da Contabilidade Aplicada ao Setor Público, estatais independentes não se submetem ao mesmo regime contábil público das entidades dependentes abrangidas pela CASP.", "steps": ["Identificar as opções: fundos públicos, administração direta, autarquias, fundações públicas e estatais independentes.", "As quatro primeiras integram o campo típico da contabilidade pública.", "A exceção cobrada é a empresa estatal independente."], "calc": "Não há cálculo.", "correct": "E — Estatais Independentes.", "wrong": "A, B, C e D são entidades abrangidas pelo campo de aplicação indicado na questão.", "basis": "NBC T 16.1/MCASP e legislação aplicável ao campo da CASP, conforme o material da questão.", "trap": "Não confundir estatal independente com estatal dependente; esta última é tratada de forma distinta e integra o universo relevante da CASP."}'::jsonb WHERE id='3023784';
UPDATE questoes SET resolution='{"what": "Limite global de pessoal nos Municípios.", "rule": "O limite da despesa total com pessoal para Municípios é 60% da Receita Corrente Líquida.", "steps": ["Identificar Município.", "Aplicar art. 19, III.", "Selecionar 60%."], "calc": "60% da RCL.", "correct": "D — 60%.", "wrong": "50%, 30%, 70% e 40% não correspondem ao limite global municipal.", "basis": "Lei Complementar nº 101/2000, art. 19, III.", "trap": "Questão repetitiva da FAFIPA: grave o trio municipal 60% global, 54% Executivo, 6% Legislativo."}'::jsonb WHERE id='1741232';
UPDATE questoes SET resolution='{"what": "Limite global de pessoal nos Municípios.", "rule": "A despesa total com pessoal dos Municípios não pode exceder 60% da RCL.", "steps": ["Ente: Município.", "Limite global: 60%.", "Alternativa correspondente: B."], "calc": "60% da RCL.", "correct": "B — 60%.", "wrong": "40%, 70% e 50% não são o limite municipal.", "basis": "Lei Complementar nº 101/2000, art. 19, III.", "trap": "Memorizar o limite por ente evita confusão com os limites da União e dos Estados."}'::jsonb WHERE id='1973398';
UPDATE questoes SET resolution='{"what": "Repartição dos limites globais e exclusões na apuração da despesa com pessoal.", "rule": "No Município, o limite global é 60%, repartido em 54% para o Executivo e 6% para o Legislativo. A LRF também prevê exclusões específicas na apuração, inclusive determinadas despesas com inativos custeadas por recursos próprios vinculados nas condições legais.", "steps": ["A alternativa B afirma corretamente que o Executivo municipal não pode ultrapassar 54%.", "A alternativa A traz percentuais globais incorretos.", "C e D trazem repartições incompatíveis com a LRF.", "E erra ao dizer que devem ser computadas determinadas despesas com inativos que a própria LRF manda excluir quando atendidas as condições."], "calc": "Limite Executivo municipal = 54% da RCL; Legislativo = 6% da RCL.", "correct": "B.", "wrong": "A, C e D apresentam percentuais incorretos; E contraria a regra de exclusão do art. 19, §1º, VI.", "basis": "Lei Complementar nº 101/2000, arts. 19, §1º, VI, e 20, III.", "trap": "Além dos percentuais, a FAFIPA pode cobrar as parcelas que não entram no cálculo da despesa total com pessoal."}'::jsonb WHERE id='2164727';
UPDATE questoes SET resolution='{"what": "Repartição do limite municipal de 60% entre Legislativo e Executivo.", "rule": "O limite global municipal de 60% da RCL é repartido em 6% para o Legislativo, incluído o Tribunal de Contas do Município quando houver, e 54% para o Executivo.", "steps": ["Limite global municipal = 60%.", "Legislativo = 6%.", "Executivo = 54%.", "6% + 54% = 60%."], "calc": "6% + 54% = 60% da RCL.", "correct": "A — I 6%; II 54%.", "wrong": "B inverte os percentuais; C e D usam 56/4 ou 4/56; E não corresponde à repartição legal.", "basis": "Lei Complementar nº 101/2000, art. 20, III.", "trap": "A inversão 54%/6% é uma pegadinha clássica."}'::jsonb WHERE id='2165661';
UPDATE questoes SET resolution='{"what": "Limites globais de despesa com pessoal por ente.", "rule": "A LRF estabelece: União 50% da RCL; Estados 60%; Municípios 60%.", "steps": ["União → 50%.", "Estados → 60%.", "Municípios → 60%.", "Comparar com as alternativas."], "calc": "União 50% + Estados 60% + Municípios 60%.", "correct": "C.", "wrong": "As demais alternativas alteram pelo menos um dos três percentuais.", "basis": "Lei Complementar nº 101/2000, art. 19, I a III.", "trap": "Decore por ente: 50–60–60. Não confundir esses limites globais com a repartição interna entre Poderes."}'::jsonb WHERE id='916313';
UPDATE questoes SET resolution='{"what": "Escopo facultativo da NBC TSP Estrutura Conceitual.", "rule": "Na classificação cobrada pela questão, organizações da sociedade civil de interesse público (OSCIPs) enquadram-se no escopo facultativo; autarquias, consórcios públicos, estatais dependentes e fundações públicas integram o escopo obrigatório indicado no material.", "steps": ["Identificar as cinco categorias apresentadas.", "Separar entidades típicas do setor público das organizações privadas que podem atuar em parceria com o poder público.", "A alternativa correspondente ao escopo facultativo é OSCIP."], "calc": "Não há cálculo.", "correct": "E — Organizações da sociedade civil de interesse público.", "wrong": "A, B, C e D correspondem às entidades apontadas como de aplicação obrigatória no recorte da questão.", "basis": "NBC TSP Estrutura Conceitual, conforme classificação cobrada no caderno.", "trap": "Não confundir “atuar em parceria com o poder público” com pertencer automaticamente ao escopo obrigatório das normas."}'::jsonb WHERE id='1336830';
UPDATE questoes SET resolution='{"what": "Campo de aplicação da contabilidade pública no recorte da questão.", "rule": "A questão considera como abrangidos todos os órgãos da administração direta.", "steps": ["Identificar a alternativa que corresponde diretamente à administração direta.", "A opção D afirma “todos os órgãos de administração direta”.", "Essa é a alternativa registrada como correta no caderno."], "calc": "Não há cálculo.", "correct": "D — Todos os órgãos de administração direta.", "wrong": "B, C e E restringem ou ampliam o campo de modo diferente do enunciado; A generaliza para todos os órgãos da administração pública.", "basis": "Normas de Contabilidade Aplicada ao Setor Público, conforme o enquadramento adotado na questão.", "trap": "Questão de campo de aplicação: leia com atenção “todos”, “apenas” e “somente”."}'::jsonb WHERE id='1336831';
UPDATE questoes SET resolution='{"what": "Limites de despesa com pessoal nos Municípios.", "rule": "Municípios: limite global de 60% da RCL; repartição municipal: 6% para o Legislativo, incluído o Tribunal de Contas do Município quando houver, e 54% para o Executivo.", "steps": ["Limite global = 60%.", "Legislativo municipal = 6%.", "Executivo municipal = 54%."], "calc": "6% + 54% = 60% da RCL.", "correct": "D — 60% – 6% – 54%.", "wrong": "C inverte os dois percentuais; A e B usam percentuais incompatíveis com o art. 19 da LRF.", "basis": "Lei Complementar nº 101/2000, arts. 19, III, e 20, III.", "trap": "Grave o trio municipal: 60% global, 6% Legislativo, 54% Executivo."}'::jsonb WHERE id='825580';
UPDATE questoes SET resolution='{"what": "Limite global de despesa com pessoal dos Municípios.", "rule": "A despesa total com pessoal dos Municípios não pode exceder 60% da Receita Corrente Líquida em cada período de apuração.", "steps": ["Identificar o ente: Município.", "Aplicar o art. 19, III, da LRF.", "Selecionar 60%."], "calc": "60% da RCL.", "correct": "C — 60%.", "wrong": "40%, 50% e 70% não correspondem ao limite global municipal.", "basis": "Lei Complementar nº 101/2000, art. 19, III.", "trap": "Não confundir limite global com limite de um dos Poderes."}'::jsonb WHERE id='635058';
UPDATE questoes SET resolution='{"what": "Limite global de pessoal dos Municípios.", "rule": "O limite é de 60% da Receita Corrente Líquida.", "steps": ["Ente municipal.", "Art. 19, III, da LRF.", "Resultado: 60%."], "calc": "60% da RCL.", "correct": "D — 60%.", "wrong": "30%, 40% e 50% não são o limite global municipal.", "basis": "Lei Complementar nº 101/2000, art. 19, III.", "trap": "Questão direta de memorização."}'::jsonb WHERE id='938458';
UPDATE questoes SET resolution='{"what": "Regras da LRF sobre terceirização e apuração da despesa com pessoal.", "rule": "A terceirização de mão de obra que substitui servidores ou empregados públicos é contabilizada como “Outras Despesas de Pessoal”. A apuração da despesa com pessoal é feita somando a realizada no mês de referência com as dos onze meses imediatamente anteriores, adotando-se regime de competência, não regime de caixa. O item III, como extraído, aparece sem contexto suficiente para validar toda a alternativa.", "steps": ["I é verdadeira: substituição de servidores por terceirizados entra em Outras Despesas de Pessoal.", "II é falsa: a LRF usa período de 12 meses e regime de competência, não soma apenas meses “dentro da mesma competência” pelo regime de caixa.", "III deve ser conferida na redação original porque o texto extraído está incompleto em relação às alternativas, que mencionam uma assertiva IV inexistente no enunciado."], "calc": "Não há cálculo.", "correct": "C — conforme gabarito registrado, mas com ressalva: o enunciado extraído está estruturalmente incompleto.", "wrong": "A e D não correspondem ao gabarito registrado; B e C mencionam assertiva IV que não aparece no trecho extraído.", "basis": "Lei Complementar nº 101/2000, arts. 18 e 19; texto do caderno.", "trap": "A palavra “caixa” é a armadilha: a apuração da despesa total com pessoal segue o regime de competência."}'::jsonb WHERE id='3013728';
UPDATE questoes SET resolution='{"what": "Repartição do limite municipal de pessoal.", "rule": "No Município, 6% da RCL é o limite do Legislativo, incluído o Tribunal de Contas do Município, quando houver.", "steps": ["Partir do limite global municipal de 60%.", "Aplicar a repartição do art. 20, III.", "Legislativo = 6%; Executivo = 54%."], "calc": "6% + 54% = 60% da RCL.", "correct": "B — 6% para o Legislativo.", "wrong": "A erra o percentual do Executivo; C atribui limite ao Judiciário municipal; D trata do Ministério Público estadual, não da repartição municipal.", "basis": "Lei Complementar nº 101/2000, art. 20, III, “a”.", "trap": "A expressão “incluído o Tribunal de Contas do Município, quando houver” é típica da literalidade cobrada."}'::jsonb WHERE id='3013734';
UPDATE questoes SET resolution='{"what": "Aspecto patrimonial da Contabilidade Aplicada ao Setor Público.", "rule": "Registro e evidenciação da composição patrimonial, reconhecimento, mensuração e evidenciação de ativos, passivos e variações patrimoniais, além de BP e DVP, caracterizam o aspecto patrimonial.", "steps": ["Identificar patrimônio, ativos, passivos e variações patrimoniais.", "Relacionar BP e DVP a esse aspecto.", "Reconhecer que a convergência às normas internacionais também atua nesse eixo."], "calc": "Não há cálculo.", "correct": "D — Patrimonial.", "wrong": "Orçamentário está ligado ao orçamento; financeiro aos fluxos/ingressos e dispêndios; fiscal não é a classificação pedida.", "basis": "MCASP, aspectos orçamentário, patrimonial e fiscal da CASP.", "trap": "Palavras-chave: ativo, passivo, patrimônio e variações patrimoniais → patrimonial."}'::jsonb WHERE id='938435';
UPDATE questoes SET resolution='{"what": "Limite municipal de despesa com pessoal.", "rule": "O limite global dos Municípios é 60% da RCL, não 70%.", "steps": ["Identificar a afirmação: “70% nos Municípios”.", "Comparar com art. 19, III, da LRF.", "Como o percentual correto é 60%, a afirmação é falsa."], "calc": "Limite correto = 60% da RCL.", "correct": "E — Errado/Falso.", "wrong": "A proposição de 70% está acima do limite legal; não há fundamento no art. 19, III, para 70%.", "basis": "Lei Complementar nº 101/2000, art. 19, III.", "trap": "Em itens Certo/Errado, uma única troca de 60% por 70% torna toda a afirmação falsa."}'::jsonb WHERE id='3133151';
UPDATE questoes SET resolution='{"what": "Conceito de despesa total com pessoal.", "rule": "O art. 18 da LRF define despesa total com pessoal como o somatório dos gastos do ente com ativos, inativos, pensionistas, mandatos, cargos, funções ou empregos, remunerações e encargos nas condições legais.", "steps": ["Comparar o texto com os conceitos da LRF.", "A descrição corresponde literalmente à despesa total com pessoal.", "Selecionar a alternativa A."], "calc": "Não há cálculo.", "correct": "A — Despesa total com pessoal.", "wrong": "As demais alternativas tratam de conceitos diferentes da LRF.", "basis": "Lei Complementar nº 101/2000, art. 18.", "trap": "A banca pode retirar uma parcela da definição e tentar induzir a classificação como outra despesa."}'::jsonb WHERE id='1061257';
UPDATE questoes SET resolution='{"what": "Tratamento da terceirização que substitui servidores ou empregados públicos.", "rule": "Os valores dos contratos de terceirização de mão de obra que se referem à substituição de servidores e empregados públicos são contabilizados como “Outras Despesas de Pessoal”.", "steps": ["Identificar que a terceirização substitui servidores/empregados.", "Aplicar a regra expressa do art. 18, §1º, da LRF.", "Selecionar “Outras Despesas de Pessoal”."], "calc": "Não há cálculo.", "correct": "A — Como outras despesas de pessoal.", "wrong": "As demais alternativas não reproduzem a classificação determinada pela LRF.", "basis": "Lei Complementar nº 101/2000, art. 18, §1º.", "trap": "Não classifique automaticamente como simples “contrato de terceiros” quando houver substituição de servidores."}'::jsonb WHERE id='1061278';
UPDATE questoes SET resolution='{"what": "Limite global de despesa com pessoal nos Municípios.", "rule": "O art. 19, III, da LRF estabelece 60% da RCL para Municípios.", "steps": ["Identificar Município.", "Aplicar art. 19, III.", "Resultado = 60%."], "calc": "60% da RCL.", "correct": "D — 60%.", "wrong": "20%, 30%, 50% e 70% não são o limite global municipal.", "basis": "Lei Complementar nº 101/2000, art. 19, III.", "trap": "Não confundir 60% global com 54% Executivo ou 6% Legislativo."}'::jsonb WHERE id='1061387';
UPDATE questoes SET resolution='{"what": "Conceito de concessão de garantia na LRF.", "rule": "Concessão de garantia é o compromisso de adimplência de obrigação financeira ou contratual assumida por ente da Federação ou entidade a ele vinculada.", "steps": ["Comparar cada definição com o art. 29 da LRF.", "A alternativa A reproduz o conceito de concessão de garantia.", "As demais trocam os conceitos de operação de crédito, dívida mobiliária, refinanciamento e dívida consolidada."], "calc": "Não há cálculo.", "correct": "A.", "wrong": "B descreve dívida mobiliária/refinanciamento; C e E misturam dívida fundada/consolidada e mobiliária; D descreve operação de crédito.", "basis": "Lei Complementar nº 101/2000, art. 29.", "trap": "Memorize as definições do art. 29 separadamente; a banca troca apenas o nome do instituto."}'::jsonb WHERE id='3600647';
UPDATE questoes SET resolution='{"what": "Recondução da dívida consolidada ao limite.", "rule": "Se a dívida consolidada ultrapassar o limite ao final de um quadrimestre, o ente deve reconduzi-la ao limite nos três quadrimestres seguintes, reduzindo o excedente em pelo menos 25% no primeiro quadrimestre. Enquanto perdurar o excesso, há restrições a operações de crédito e transferências voluntárias, nos termos da LRF.", "steps": ["Identificar excesso no final do quadrimestre.", "Aplicar prazo de três quadrimestres para recondução.", "No primeiro quadrimestre subsequente, reduzir pelo menos 25% do excedente.", "Aplicar as restrições enquanto perdurar o excesso."], "calc": "Redução mínima no primeiro quadrimestre = 25% do excedente.", "correct": "A — conforme gabarito registrado no caderno.", "wrong": "C erra ao falar em quatro quadrimestres; D ignora as demais restrições; B contraria a sistemática de divulgação prevista na LRF.", "basis": "Lei Complementar nº 101/2000, art. 31.", "trap": "Não confundir “redução de 25% no primeiro quadrimestre” com “25% em cada um dos três quadrimestres”."}'::jsonb WHERE id='3462830';
UPDATE questoes SET resolution='{"what": "Restrição a nova operação de crédito quando a dívida consolidada municipal está acima do limite.", "rule": "Enquanto perdurar excesso da dívida consolidada sobre o limite, o ente fica sujeito às restrições do art. 31 da LRF, inclusive quanto à realização de operações de crédito, ressalvadas as hipóteses legais. O prazo de recondução é de três quadrimestres.", "steps": ["Dívida consolidada já está acima do limite.", "A necessidade pública da máquina não elimina a restrição fiscal.", "Aplicar o art. 31: recondução em três quadrimestres e restrições durante o excesso."], "calc": "Prazo de recondução: 3 quadrimestres; redução mínima de 25% do excedente no primeiro.", "correct": "D.", "wrong": "A e B tratam LOA/LDO ou interesse público como se afastassem o limite; C subestima as restrições; E cria condição de pagamento não prevista como exceção geral.", "basis": "Lei Complementar nº 101/2000, art. 31.", "trap": "“É obra essencial” não é salvo-conduto para ignorar limite de endividamento."}'::jsonb WHERE id='3930717';
UPDATE questoes SET resolution='{"what": "Classificação dos créditos adicionais.", "rule": "Suplementares reforçam dotação existente; especiais destinam-se a despesas sem dotação orçamentária específica; extraordinários destinam-se a despesas urgentes e imprevisíveis, nas hipóteses legais.", "steps": ["I: reforço de dotação → V.", "II: despesas urgentes e imprevisíveis em guerra, comoção intestina ou calamidade pública → V.", "III: ausência de dotação específica → V."], "calc": "Não há cálculo.", "correct": "A — V, V, V.", "wrong": "B, C, D e E contêm pelo menos uma classificação incompatível com a Lei 4.320/1964.", "basis": "Lei nº 4.320/1964, arts. 40 e 41; MCASP.", "trap": "Suplementar = reforça; especial = cria dotação específica inexistente; extraordinário = urgência/imprevisibilidade."}'::jsonb WHERE id='3441246';
UPDATE questoes SET resolution='{"what": "Quadros que compõem o Balanço Orçamentário.", "rule": "O Balanço Orçamentário é acompanhado do Quadro da Execução dos Restos a Pagar Não Processados e do Quadro da Execução dos Restos a Pagar Processados, além do Quadro Principal. O quadro de Ativos e Passivos Financeiros e Permanentes pertence ao Balanço Patrimonial.", "steps": ["Identificar os três quadros do Balanço Orçamentário.", "Comparar com as alternativas.", "“Ativos e Passivos Financeiros e Permanentes” é quadro do Balanço Patrimonial."], "calc": "Não há cálculo.", "correct": "C — Quadro dos Ativos e Passivos Financeiros e Permanentes.", "wrong": "A, B e D são quadros do Balanço Orçamentário.", "basis": "MCASP, Demonstrações Contábeis Aplicadas ao Setor Público — Balanço Orçamentário.", "trap": "A banca mistura quadros do BO e do BP; memorize a finalidade de cada demonstração."}'::jsonb WHERE id='3423440';
UPDATE questoes SET resolution='{"what": "Resultado da execução orçamentária a partir dos valores fornecidos.", "rule": "O resultado da execução orçamentária no Balanço Orçamentário é obtido pela diferença entre receitas realizadas e despesas empenhadas. O texto extraído apresenta rubricas cuja classificação e denominação não permitem reproduzir com segurança a alternativa registrada sem conferir a tabela/original da questão.", "steps": ["Separar receitas orçamentárias das despesas orçamentárias.", "Classificar corretamente “ingressos de investimentos” e “despesas operacionais” antes de somar.", "Subtrair o total das despesas orçamentárias do total das receitas orçamentárias.", "Como a extração não deixa clara a natureza de algumas rubricas, não é seguro escolher a alternativa apenas com o texto OCR."], "calc": "A conta depende da classificação correta das rubricas; com o texto extraído isoladamente, não é possível validar o valor de R$ 780.000 do gabarito com segurança.", "correct": "A — R$ 780.000,00, conforme gabarito registrado, mas com necessidade de conferência no original.", "wrong": "B, C, D e E não podem ser descartadas com segurança sem confirmar a classificação das rubricas ambíguas.", "basis": "MCASP — Balanço Orçamentário e classificação por natureza da receita/despesa.", "trap": "Não trate toda rubrica textual como receita ou despesa automaticamente; primeiro identifique sua natureza orçamentária."}'::jsonb WHERE id='3439367';
UPDATE questoes SET resolution='{"what_is_testing": "Classificar as definições do art. 105 da Lei nº 4.320/1964 entre Ativo Financeiro, Ativo Permanente, Passivo Financeiro e Passivo Permanente.", "rule_concept": "O art. 105 define: AF = créditos/valores realizáveis independentemente de autorização orçamentária + numerários; AP = bens, créditos e valores cuja mobilização/alienação dependa de autorização legislativa; PF = dívidas fundadas e outros compromissos cujo pagamento independa de autorização orçamentária; PP = dívidas fundadas e outras que dependam de autorização legislativa para amortização ou resgate.", "reasoning_steps": ["I reproduz corretamente a definição do Ativo Financeiro.", "II reproduz corretamente a definição do Ativo Permanente.", "III troca a definição: independência de autorização orçamentária é característica do Passivo Financeiro.", "IV também troca a definição: dependência de autorização legislativa para amortização/resgate é característica do Passivo Permanente."], "calculation": null, "correct_alternative": "D — Somente I e II estão corretas.", "wrong_alternatives": "A, B e C incorporam III/IV como verdadeiras; E considera III verdadeira e ainda omite I.", "normative_basis": "Lei nº 4.320/1964, art. 105.", "fafipa_trap": "FAFIPA troca deliberadamente as definições de Passivo Financeiro e Passivo Permanente.", "verification": "OK"}'::jsonb WHERE id='3998524';
UPDATE questoes SET resolution='{"what_is_testing": "Identificar o conteúdo do Passivo Financeiro no Balanço Patrimonial da Lei nº 4.320/1964.", "rule_concept": "Passivo Financeiro compreende as dívidas fundadas e outros compromissos exigíveis cujo pagamento independa de autorização orçamentária.", "reasoning_steps": ["A corresponde literalmente ao conceito de Passivo Financeiro.", "B descreve Ativo Permanente.", "C descreve Ativo Financeiro.", "D descreve Passivo Permanente."], "calculation": null, "correct_alternative": "A — A é a definição correta.", "wrong_alternatives": "B, C e D pertencem aos outros grupos do art. 105.", "normative_basis": "Lei nº 4.320/1964, art. 105, § 3º.", "fafipa_trap": "Não confundir \"financeiro\" com \"curto prazo\"; aqui a classificação é pelo critério de autorização orçamentária.", "verification": "OK"}'::jsonb WHERE id='2431271';
UPDATE questoes SET resolution='{"what_is_testing": "Preencher as quatro lacunas com os grupos patrimoniais corretos.", "rule_concept": "As definições seguem o art. 105 da Lei nº 4.320/1964.", "reasoning_steps": ["I fala em dívidas que dependem de autorização legislativa para amortização/resgate → Passivo Permanente.", "II fala em bens, créditos e valores cuja mobilização/alienação depende de autorização legislativa → Ativo Permanente.", "III fala em créditos/valores realizáveis sem autorização orçamentária e numerários → Ativo Financeiro.", "IV fala em dívidas e outros compromissos cujo pagamento independe de autorização orçamentária → Passivo Financeiro."], "calculation": null, "correct_alternative": "E — A sequência é PP → AP → AF → PF, alternativa E.", "wrong_alternatives": "As demais trocam pelo menos um dos quatro grupos.", "normative_basis": "Lei nº 4.320/1964, art. 105.", "fafipa_trap": "Memorize o critério de cada grupo pela característica descrita, não apenas pelas siglas.", "verification": "OK"}'::jsonb WHERE id='2156868';
UPDATE questoes SET resolution='{"what_is_testing": "Identificar o conteúdo do Ativo Financeiro.", "rule_concept": "Ativo Financeiro compreende os créditos e valores realizáveis independentemente de autorização orçamentária e os valores numerários.", "reasoning_steps": ["A trata de Ativo Permanente.", "B trata de Passivo Financeiro.", "C reproduz a definição do Ativo Financeiro.", "D trata de Passivo Permanente."], "calculation": null, "correct_alternative": "C — C é a única definição correspondente ao Ativo Financeiro.", "wrong_alternatives": "A e D são grupos permanentes; B é passivo.", "normative_basis": "Lei nº 4.320/1964, art. 105, § 1º.", "fafipa_trap": "A palavra-chave é \"independentemente de autorização orçamentária\".", "verification": "OK"}'::jsonb WHERE id='2156992';
UPDATE questoes SET resolution='{"what_is_testing": "Apurar qual saldo apresentado corresponde ao Ativo não Circulante no conjunto de dados do Balanço Patrimonial.", "rule_concept": "Para a estrutura patrimonial, Ativo não Circulante reúne, conforme a apresentação das demonstrações, realizável a longo prazo, investimentos, imobilizado e intangível.", "reasoning_steps": ["No conjunto fornecido, entram no não circulante: Bens Imóveis = 1.222.020; Investimentos = 147.300; Bens Móveis = 888.990.", "Somando: 1.222.020 + 147.300 + 888.990 = 2.258.310.", "Caixa, créditos de curto prazo e estoques não entram nesse subtotal."], "calculation": "1.222.020 + 147.300 + 888.990 = R$ 2.258.310,00.", "correct_alternative": "C — O Ativo não Circulante totaliza R$ 2.258.310,00, alternativa C.", "wrong_alternatives": "A, B, D e E não correspondem ao subtotal calculado com as contas não circulantes apresentadas.", "normative_basis": "Estrutura do Balanço Patrimonial/MCASP; valores do próprio enunciado.", "fafipa_trap": "Separar as contas por natureza antes de somar; não misturar curto e longo prazo.", "verification": "OK"}'::jsonb WHERE id='1741098';
UPDATE questoes SET resolution='{"what_is_testing": "Reconhecer a definição correta dos componentes do Balanço Patrimonial.", "rule_concept": "O Ativo Permanente compreende bens, créditos e valores cuja mobilização ou alienação dependa de autorização legislativa.", "reasoning_steps": ["A erra porque o Ativo Financeiro independe, e não depende, de autorização orçamentária.", "B reproduz corretamente a definição do Ativo Permanente.", "C erra ao atribuir ao Passivo Financeiro dependência de autorização orçamentária.", "D erra ao dizer que o Passivo Permanente não depende de autorização legislativa.", "E é incompatível com a descrição das contas de compensação."], "calculation": null, "correct_alternative": "B — B é a alternativa correta.", "wrong_alternatives": "Cada uma das demais contém inversão do critério de autorização ou definição inadequada.", "normative_basis": "Lei nº 4.320/1964, art. 105.", "fafipa_trap": "As alternativas A, C e D são construídas com a inversão de \"depende\" e \"independe\".", "verification": "OK"}'::jsonb WHERE id='1336845';
UPDATE questoes SET resolution='{"what_is_testing": "Identificar os grupos em que, segundo a Lei nº 4.320/1964, são enquadrados créditos/valores realizáveis e dívidas fundadas no enfoque financeiro/permanente da lei.", "rule_concept": "A questão cobra a classificação tradicional do art. 105 da Lei nº 4.320/1964.", "reasoning_steps": ["A e B tentam usar a nomenclatura do balanço patrimonial societário, que não é a classificação pedida pela questão.", "C reproduz a resposta registrada no material: Ativo Financeiro e Passivo Financeiro.", "D e E deslocam os itens para grupos incompatíveis com o enunciado."], "calculation": null, "correct_alternative": "C — A alternativa indicada pelo material é C.", "wrong_alternatives": "As demais usam classificações circulante/não circulante ou permanente que não correspondem ao gabarito registrado.", "normative_basis": "Lei nº 4.320/1964, art. 105.", "fafipa_trap": "A questão explora a diferença entre a classificação específica da Lei 4.320 e a nomenclatura patrimonial usual.", "verification": "Conferir formulação/gabarito na fonte original quando necessário."}'::jsonb WHERE id='1336846';
UPDATE questoes SET resolution='{"what_is_testing": "Identificar a composição do Balanço Patrimonial segundo a Lei nº 4.320/1964.", "rule_concept": "O art. 105 determina que o Balanço Patrimonial demonstrará Ativo Financeiro, Ativo Permanente, Passivo Financeiro, Passivo Permanente, Saldo Patrimonial e Contas de Compensação.", "reasoning_steps": ["A e E usam a estrutura corrente/não circulante, não a estrutura solicitada pelo art. 105.", "B usa \"não financeiro\" e \"não financeiro\", nomenclatura que não corresponde ao dispositivo.", "C omite Saldo Patrimonial e Contas de Compensação.", "D reúne todos os componentes indicados pelo art. 105."], "calculation": null, "correct_alternative": "D — D é a composição completa.", "wrong_alternatives": "As outras alternativas omitem ou substituem componentes do art. 105.", "normative_basis": "Lei nº 4.320/1964, art. 105.", "fafipa_trap": "Não confundir a estrutura da Lei 4.320 com o formato atual das demonstrações previsto no MCASP.", "verification": "OK"}'::jsonb WHERE id='1336847';
UPDATE questoes SET resolution='{"what_is_testing": "Julgar quatro assertivas sobre os grupos Financeiro e Permanente.", "rule_concept": "AF e AP estão corretos; PF e PP foram invertidos nas assertivas III e IV.", "reasoning_steps": ["I = V: AF independe de autorização orçamentária.", "II = V: AP depende de autorização legislativa para mobilização/alienação.", "III = F: essa é a definição do Passivo Permanente, não do Financeiro.", "IV = F: essa é a definição do Passivo Financeiro, não do Permanente."], "calculation": null, "correct_alternative": "C — A sequência é V, V, F, F → alternativa C.", "wrong_alternatives": "A, B e D apresentam sequências incompatíveis com o art. 105.", "normative_basis": "Lei nº 4.320/1964, art. 105.", "fafipa_trap": "PF e PP aparecem trocados nas duas últimas assertivas.", "verification": "OK"}'::jsonb WHERE id='1054631';
UPDATE questoes SET resolution='{"what_is_testing": "Identificar o item que não pertence ao Ativo Não Circulante.", "rule_concept": "No balanço patrimonial, Caixa e Equivalentes de Caixa é classificado no Ativo Circulante quando atende aos critérios de circulante; investimentos, imobilizado e intangível integram o não circulante.", "reasoning_steps": ["Caixa e Equivalentes de Caixa → circulante.", "Investimentos → não circulante.", "Imobilizado → não circulante.", "Intangível → não circulante."], "calculation": null, "correct_alternative": "A — A é a exceção solicitada.", "wrong_alternatives": "B, C e D são componentes do Ativo Não Circulante.", "normative_basis": "Estrutura do Balanço Patrimonial/MCASP.", "fafipa_trap": "A expressão \"EXCETO\" exige localizar o único item fora do grupo.", "verification": "OK"}'::jsonb WHERE id='635045';
UPDATE questoes SET resolution='{"what_is_testing": "Classificar quatro definições como certo ou errado.", "rule_concept": "AF = créditos/valores sem autorização orçamentária; AP = bens/créditos/valores dependentes de autorização legislativa; PF = compromissos cujo pagamento independe de autorização orçamentária; PP = dívidas que dependem de autorização legislativa para amortização/resgate.", "reasoning_steps": ["1ª: descreve AP, mas foi atribuída a AF → E.", "2ª: descreve AF, mas foi atribuída a AP → E.", "3ª: descreve PF corretamente → C.", "4ª: descreve PP corretamente → C."], "calculation": null, "correct_alternative": "D — Sequência E, E, C, C → alternativa D.", "wrong_alternatives": "As demais sequências não respeitam a correspondência das quatro definições.", "normative_basis": "Lei nº 4.320/1964, art. 105.", "fafipa_trap": "É uma questão de associação: primeiro identifique a definição e só depois a sigla.", "verification": "OK"}'::jsonb WHERE id='924183';
UPDATE questoes SET resolution='{"what_is_testing": "Determinar o saldo do Patrimônio Líquido após as operações apresentadas.", "rule_concept": "O PL é obtido pela diferença entre ativos e passivos, considerando os efeitos patrimoniais das operações.", "reasoning_steps": ["FPM recebido: aumenta o ativo financeiro em R$ 100.000.", "Veículo adquirido por financiamento: aumenta ativo em R$ 25.000 e passivo em R$ 25.000, sem efeito imediato no PL.", "Serviço de limpeza pago à vista: reduz o ativo em R$ 5.000 e representa variação patrimonial diminutiva.", "Obrigações trabalhistas a pagar: passivo de R$ 10.000.", "Com os dados e o tratamento indicado no material, o saldo do PL chega a R$ 85.000."], "calculation": "Pelos dados do enunciado: R$ 100.000 recebidos; veículo financiado em R$ 25.000; serviço pago R$ 5.000; obrigação trabalhista R$ 10.000. O material registra PL final de R$ 85.000.", "correct_alternative": "C — Alternativa C, conforme o gabarito registrado.", "wrong_alternatives": "A, B e D não correspondem ao saldo indicado no conjunto de operações.", "normative_basis": "Dados do enunciado; lógica patrimonial de ativo, passivo e variações patrimoniais.", "fafipa_trap": "Compra financiada não reduz o PL por si só; a despesa do serviço e as obrigações são efeitos patrimoniais distintos.", "verification": "Conferir formulação/gabarito na fonte original quando necessário."}'::jsonb WHERE id='938374';
UPDATE questoes SET resolution='{"what_is_testing": "Determinar os saldos do Ativo Financeiro e Passivo Financeiro após as operações.", "rule_concept": "Ativo Financeiro considera recursos e créditos realizáveis independentemente de autorização orçamentária; Passivo Financeiro reúne compromissos exigíveis cujo pagamento independe de autorização orçamentária.", "reasoning_steps": ["O recebimento do FPM gera R$ 100.000 em disponibilidades.", "O pagamento do serviço de R$ 5.000 reduz as disponibilidades, restando R$ 95.000 de ativo financeiro.", "O financiamento de longo prazo de R$ 25.000 é registrado como obrigação correspondente ao veículo e, no enquadramento usado pela questão, compõe o passivo financeiro indicado pelo gabarito.", "A obrigação trabalhista de R$ 10.000 também é compromisso, mas o resultado esperado pela questão permanece R$ 95.000 e R$ 25.000."], "calculation": "Disponibilidades: R$ 100.000 − R$ 5.000 = R$ 95.000. O gabarito registrado indica Passivo Financeiro de R$ 25.000.", "correct_alternative": "B — Alternativa B, conforme o gabarito registrado no material.", "wrong_alternatives": "As outras combinações não coincidem com a classificação adotada pela questão.", "normative_basis": "Dados do enunciado e classificação da Lei nº 4.320/1964.", "fafipa_trap": "Questões desse tipo exigem separar o efeito financeiro do efeito patrimonial e acompanhar cada operação.", "verification": "Conferir formulação/gabarito na fonte original quando necessário."}'::jsonb WHERE id='938376';
UPDATE questoes SET resolution='{"what_is_testing": "Reconhecer a definição de Ativo Financeiro apresentada pelo MCASP na questão.", "rule_concept": "Na classificação cobrada, Ativo Financeiro compreende créditos e valores realizáveis independentemente de autorização orçamentária e valores numerários.", "reasoning_steps": ["A apresenta critérios de classificação de ativo circulante em uma abordagem diferente.", "B reproduz a definição utilizada pela Lei nº 4.320/1964.", "C descreve elementos do não circulante.", "D descreve Ativo Permanente."], "calculation": null, "correct_alternative": "B — B é a alternativa indicada pelo gabarito.", "wrong_alternatives": "A, C e D correspondem a outras classificações patrimoniais.", "normative_basis": "Lei nº 4.320/1964, art. 105; referência ao MCASP no enunciado.", "fafipa_trap": "A questão mistura critérios de classificação; siga o critério explicitamente pedido.", "verification": "Conferir formulação/gabarito na fonte original quando necessário."}'::jsonb WHERE id='938378';
UPDATE questoes SET resolution='{"what_is_testing": "Identificar o grupo que reúne ativos com expectativa de realização após doze meses.", "rule_concept": "Ativo Não Circulante compreende os ativos cuja realização não se espera no ciclo operacional ou até doze meses, conforme os critérios da demonstração.", "reasoning_steps": ["A = Ativo Circulante → curto prazo.", "B = Ativo Não Circulante → realização após doze meses e demais componentes indicados.", "C = Ativo Financeiro → classificação diferente, baseada na autorização orçamentária.", "D = Ativo Permanente → nomenclatura da Lei 4.320, não a resposta pedida pelo critério temporal."], "calculation": null, "correct_alternative": "B — B é a alternativa correta.", "wrong_alternatives": "A, C e D usam grupos com critérios diferentes do descrito no enunciado.", "normative_basis": "Estrutura do Balanço Patrimonial/MCASP.", "fafipa_trap": "O enunciado fornece o critério temporal; isso aponta diretamente para Não Circulante.", "verification": "Conferir formulação/gabarito na fonte original quando necessário."}'::jsonb WHERE id='938452';
UPDATE questoes SET resolution='{"what_is_testing": "Julgar conceitos de ativo, passivo, patrimônio líquido, não circulante e circulante.", "rule_concept": "Ativo = recursos controlados; passivo = obrigações presentes; PL = valor residual dos ativos após dedução dos passivos. Circulante e não circulante seguem os critérios temporais e operacionais aplicáveis.", "reasoning_steps": ["1ª = F: descreve ativo, não passivo.", "2ª = F: descreve passivo, não ativo.", "3ª = V: definição de patrimônio líquido.", "4ª = V: conjunto classificado como não circulante segundo o critério temporal apresentado.", "5ª = V: conjunto classificado como circulante segundo o critério temporal apresentado."], "calculation": null, "correct_alternative": "D — F, F, V, V, V → alternativa D.", "wrong_alternatives": "A, B e C erram uma ou mais das três primeiras classificações.", "normative_basis": "Estrutura Conceitual/NBC TSP e critérios de apresentação patrimonial.", "fafipa_trap": "As duas primeiras frases estão trocadas de propósito: ativo e passivo são conceitos opostos.", "verification": "Conferir formulação/gabarito na fonte original quando necessário."}'::jsonb WHERE id='562884';
UPDATE questoes SET resolution='{"what_is_testing": "Associar AF, AP, PF e PP às definições apresentadas.", "rule_concept": "PP = dívidas que dependem de autorização legislativa; PF = compromissos cujo pagamento independe de autorização orçamentária; AP = bens/créditos/valores dependentes de autorização legislativa; AF = créditos/valores realizáveis sem autorização orçamentária e numerários.", "reasoning_steps": ["1ª definição → PP.", "2ª definição → PF.", "3ª definição → AP.", "4ª definição → AF."], "calculation": null, "correct_alternative": "D — A sequência PP, PF, AP, AF corresponde à alternativa D.", "wrong_alternatives": "As demais sequências trocam pelo menos dois grupos.", "normative_basis": "Lei nº 4.320/1964, art. 105.", "fafipa_trap": "Use as palavras-chave: dívida + autorização legislativa = PP; compromisso + pagamento sem autorização orçamentária = PF.", "verification": "OK"}'::jsonb WHERE id='562891';
UPDATE questoes SET resolution='{"what_is_testing": "Identificar quais assertivas do art. 105 estão incorretas.", "rule_concept": "I e II estão corretas. III e IV estão invertidas: PF não é o grupo das dívidas dependentes de autorização legislativa; PP é. IV atribui ao PP a característica de independência de autorização orçamentária, própria do PF. V reproduz a finalidade das contas de compensação.", "reasoning_steps": ["I = V.", "II = V.", "III = F.", "IV = F.", "V = V."], "calculation": null, "correct_alternative": "A — Somente III e IV estão incorretas → alternativa A.", "wrong_alternatives": "B, C, D e E não refletem a sequência V, V, F, F, V.", "normative_basis": "Lei nº 4.320/1964, art. 105.", "fafipa_trap": "As duas falsas estão no meio e são justamente as que trocam PF e PP.", "verification": "OK"}'::jsonb WHERE id='953140';
UPDATE questoes SET resolution='{"what_is_testing": "Identificar o item que não faz parte do Balanço Patrimonial.", "rule_concept": "O Balanço Patrimonial demonstra os grupos patrimoniais e o saldo patrimonial. Receitas e despesas previstas em confronto com as realizadas pertencem ao Balanço Orçamentário.", "reasoning_steps": ["A = Ativo Financeiro → integra o BP.", "B = receitas/despesas previstas versus realizadas → Balanço Orçamentário.", "C = Ativo Permanente → integra o BP.", "D = Saldo Patrimonial → integra o BP."], "calculation": null, "correct_alternative": "B — B é o item que não pertence ao Balanço Patrimonial.", "wrong_alternatives": "A, C e D são componentes do BP segundo a estrutura cobrada.", "normative_basis": "Lei nº 4.320/1964, arts. 101 e 105.", "fafipa_trap": "Confundir BP com Balanço Orçamentário: a expressão \"previstas em confronto com realizadas\" é a pista.", "verification": "OK"}'::jsonb WHERE id='917576';
UPDATE questoes SET resolution='{"what_is_testing": "Identificar o item que não constitui exemplo de ativo intangível.", "rule_concept": "Ativo intangível é identificável, sem substância física, controlado pela entidade e associado a benefícios econômicos ou potencial de serviços, quando atendidos os critérios de reconhecimento.", "reasoning_steps": ["Propriedade intelectual pode constituir intangível.", "Conhecimento científico pode constituir recurso intangível quando identificável/controlado e reconhecível.", "Conhecimento mercadológico pode constituir recurso intangível nas condições de reconhecimento.", "Investimentos em ações representam instrumentos patrimoniais/financeiros, não ativo intangível.", "Implantação de novos processos ou sistemas pode envolver ativos intangíveis quando os critérios são satisfeitos."], "calculation": null, "correct_alternative": "D — D é a alternativa que não apresenta exemplo de ativo intangível.", "wrong_alternatives": "A, B, C e E podem representar recursos sem substância física que, atendidos os critérios de reconhecimento, sejam tratados como intangíveis.", "normative_basis": "NBC TSP/estrutura conceitual e critérios de reconhecimento de ativos intangíveis aplicáveis ao setor público, conforme o contexto da questão.", "fafipa_trap": "O fato de algo não ter forma física não basta: investimentos em ações continuam sendo ativos financeiros, não intangíveis.", "verification": "Conferir formulação/gabarito na fonte original quando necessário."}'::jsonb WHERE id='1061266';
UPDATE questoes SET resolution='{"what_is_testing": "Classificar a despesa empenhada e liquidada, mas ainda não paga, como resto a pagar.", "rule_concept": "Despesa empenhada e liquidada até 31 de dezembro, mas não paga, é inscrita em Restos a Pagar Processados.", "reasoning_steps": ["A despesa foi regularmente empenhada.", "O serviço já foi prestado e a despesa foi liquidada, portanto o credor já adquiriu o direito ao pagamento.", "Como o pagamento não ocorreu até o encerramento do exercício, a obrigação é inscrita em Restos a Pagar Processados."], "calculation": null, "correct_alternative": "E — restos a pagar processados.", "wrong_alternatives": "B seria aplicável se a despesa estivesse empenhada, mas ainda não liquidada. A, C e D não descrevem a situação apresentada.", "normative_basis": "Lei nº 4.320/1964, art. 36; distinção entre restos processados e não processados.", "fafipa_trap": "A palavra-chave é “liquidada”: liquidou e não pagou = RP processado.", "verification": "OK"}'::jsonb WHERE id='4074905';
UPDATE questoes SET resolution='{"what_is_testing": "Aplicar as regras da Lei nº 4.320/1964 sobre conteúdo e universalidade da Lei Orçamentária.", "rule_concept": "A LOA deve evidenciar a política econômico-financeira e o programa de trabalho, observando unidade, universalidade e anualidade. A regra de universalidade alcança todas as receitas, com a exceção legal relativa a operações de crédito por antecipação da receita? A assertiva II, como redigida, cria uma exceção que não consta do art. 3º.", "reasoning_steps": ["A assertiva I reproduz a regra do art. 2º e está correta.", "A assertiva II afirma que a LOA compreenderá todas as receitas, exceto operações de crédito autorizadas sem lei.", "A exceção indicada não corresponde à redação legal do art. 3º; portanto II está incorreta.", "Resultado: I verdadeira e II falsa."], "calculation": null, "correct_alternative": "C — I verdadeira e II falsa.", "wrong_alternatives": "A e D pressupõem que II seja verdadeira. B considera I falsa. E considera II verdadeira e I falsa.", "normative_basis": "Lei nº 4.320/1964, arts. 2º e 3º.", "fafipa_trap": "Não basta reconhecer “todas as receitas”: a banca altera a exceção legal e espera atenção à literalidade.", "verification": "OK"}'::jsonb WHERE id='3703925';
UPDATE questoes SET resolution='{"what_is_testing": "Identificar, na Lei nº 4.320/1964, documento que acompanha a Lei de Orçamento.", "rule_concept": "A Lei nº 4.320/1964 determina quadros e demonstrativos que integram ou acompanham a Lei de Orçamento. O quadro demonstrativo do programa anual de trabalho do Governo, em termos de realização de obras e prestação de serviços, acompanha a LOA.", "reasoning_steps": ["A alternativa A reproduz o conteúdo do art. 2º, § 2º, III, da Lei nº 4.320/1964.", "As demais alternativas deslocam documentos entre “integrar” e “acompanhar” ou apresentam formulações incompatíveis com a lei."], "calculation": null, "correct_alternative": "A — acompanha a Lei de Orçamento o quadro demonstrativo do programa anual de trabalho do Governo.", "wrong_alternatives": "B, C, D e E não correspondem à combinação legal cobrada pela questão.", "normative_basis": "Lei nº 4.320/1964, art. 2º, § 2º.", "fafipa_trap": "A questão explora a diferença entre o que “acompanha” e o que “integra” a Lei de Orçamento.", "verification": "OK"}'::jsonb WHERE id='3707230';
UPDATE questoes SET resolution='{"what_is_testing": "Aplicar a vedação legal à inclusão de dotação para obra cujo projeto ainda não foi aprovado.", "rule_concept": "A Lei nº 4.320/1964 veda a inclusão, na Lei de Orçamento, de dotação para investimento com duração superior a um exercício sem prévia inclusão no PPA e, para obras e investimentos, há exigência de projeto tecnicamente aprovado quando aplicável. Na formulação desta questão, a ausência de aprovação do projeto impede a emenda.", "reasoning_steps": ["A proposta pretende criar dotação para início de nova obra.", "O enunciado informa que o projeto técnico ainda não foi aprovado.", "A situação contraria a exigência legal apontada pela questão.", "Logo, a emenda deve ser rejeitada."], "calculation": null, "correct_alternative": "D — rejeitada, por contrariar vedação expressa da Lei nº 4.320/1964.", "wrong_alternatives": "A, B, C e E criam condições que não afastam a vedação apresentada no enunciado.", "normative_basis": "Lei nº 4.320/1964, art. 20 e regras de elaboração da despesa orçamentária aplicáveis à questão.", "fafipa_trap": "A banca usa prioridade, contrapartida ou previsão de receita como distrações: elas não substituem a exigência legal indicada.", "verification": "Conferir a redação do dispositivo no original caso a questão seja usada para revisão literal."}'::jsonb WHERE id='3862421';
UPDATE questoes SET resolution='{"what_is_testing": "Diferenciar PPA, LDO e LOA segundo a Constituição Federal.", "rule_concept": "PPA estabelece diretrizes, objetivos e metas para despesas de capital e programas de duração continuada; LDO compreende metas e prioridades e orienta a elaboração da LOA; LOA compreende os orçamentos fiscal, de investimento das estatais e da seguridade social.", "reasoning_steps": ["A alternativa D descreve corretamente o PPA.", "Depois, descreve a LDO como instrumento de metas e prioridades para o exercício subsequente, orientando a LOA.", "Por fim, descreve corretamente os três orçamentos que compõem a LOA."], "calculation": null, "correct_alternative": "D — PPA + LDO + LOA estão corretamente associados.", "wrong_alternatives": "A troca PPA e LDO. B troca os conteúdos dos três instrumentos. C e E também atribuem funções de um instrumento a outro.", "normative_basis": "Constituição Federal, arts. 165 e seguintes.", "fafipa_trap": "Memorizar apenas “PPA = 4 anos” não basta: a banca cobra a função específica de cada instrumento.", "verification": "OK"}'::jsonb WHERE id='3433964';
UPDATE questoes SET resolution='{"what_is_testing": "Associar cada objetivo ao instrumento orçamentário correto.", "rule_concept": "LOA estima receitas e fixa despesas do exercício; LDO estabelece metas e prioridades para o exercício seguinte e orienta a LOA; PPA planeja diretrizes, objetivos e metas para período plurianual.", "reasoning_steps": ["I descreve a execução orçamentária anual: LOA.", "II descreve metas e prioridades e orientação da LOA: LDO.", "III descreve planejamento para quatro anos: PPA.", "A sequência é LOA – LDO – PPA."], "calculation": null, "correct_alternative": "E — I: LOA; II: LDO; III: PPA.", "wrong_alternatives": "As demais alternativas permutam os instrumentos e suas funções.", "normative_basis": "Constituição Federal, art. 165.", "fafipa_trap": "A palavra “quatro anos” aponta para o PPA; “ano subsequente” e orientação da LOA apontam para a LDO.", "verification": "OK"}'::jsonb WHERE id='3441266';
UPDATE questoes SET resolution='{"what_is_testing": "Identificar a finalidade da Demonstração das Variações Patrimoniais.", "rule_concept": "A DVP evidencia as variações patrimoniais aumentativas e diminutivas e permite analisar como as políticas adotadas provocaram alterações no patrimônio público.", "reasoning_steps": ["A alternativa B descreve a finalidade analítica da DVP.", "C descreve a lógica do Balanço Financeiro.", "D aproxima indevidamente DVP e DMPL.", "A atribui à DVP a classe 2, quando sua estrutura não é definida dessa forma."], "calculation": null, "correct_alternative": "B — a DVP permite analisar alterações provocadas pelas políticas adotadas.", "wrong_alternatives": "A, C e D confundem DVP com outros demonstrativos ou com classes específicas do PCASP.", "normative_basis": "MCASP, capítulo de Demonstrações Contábeis Aplicadas ao Setor Público.", "fafipa_trap": "A descrição do Balanço Financeiro é a principal distração: “ingressos/dispêndios e saldos de caixa” aponta para BF, não DVP.", "verification": "OK"}'::jsonb WHERE id='3423443';
UPDATE questoes SET resolution='{"what_is_testing": "Calcular o saldo em espécie do exercício anterior no Balanço Financeiro.", "rule_concept": "No Balanço Financeiro, saldo final em espécie = saldo inicial + ingressos - dispêndios. O saldo inicial pode ser isolado pela equação.", "reasoning_steps": ["Ingressos: 1.100.000 + 3.150.000 + 1.500.000 + 440.000 = 6.190.000.", "Dispêndios: 1.990.000 + 480.000 + 770.000 + 1.730.000 + 660.000 + 244.000 + 240.000 = 6.114.000.", "Variação líquida do exercício = 6.190.000 - 6.114.000 = 76.000.", "Saldo final informado = 426.000.", "Saldo inicial = 426.000 - 76.000 = 350.000."], "calculation": "Saldo inicial = 426.000 - (6.190.000 - 6.114.000) = R$ 350.000,00.", "correct_alternative": "D — R$ 350.000,00.", "wrong_alternatives": "Os demais valores não satisfazem a equação do Balanço Financeiro com os saldos fornecidos.", "normative_basis": "MCASP — Balanço Financeiro e estrutura das informações de ingressos, dispêndios e saldos.", "fafipa_trap": "Não confundir saldo final com saldo inicial; primeiro calcule a variação líquida do exercício.", "verification": "OK"}'::jsonb WHERE id='3439306';
UPDATE questoes SET resolution='{"what_is_testing": "Reconhecer a definição legal do estágio de liquidação da despesa.", "rule_concept": "Liquidação é a verificação do direito adquirido pelo credor com base nos títulos e documentos comprobatórios do respectivo crédito.", "reasoning_steps": ["A alternativa A reproduz a definição legal.", "B trata de arrecadação/transferência financeira.", "C define empenho.", "D define pagamento.", "E trata de procedimento de constituição de crédito tributário."], "calculation": null, "correct_alternative": "A — verificação do direito adquirido pelo credor.", "wrong_alternatives": "B, C, D e E correspondem a outras etapas ou institutos.", "normative_basis": "Lei nº 4.320/1964, art. 63.", "fafipa_trap": "Empenho, liquidação e pagamento são frequentemente trocados; “direito adquirido pelo credor” é a pista da liquidação.", "verification": "OK"}'::jsonb WHERE id='2416284';
UPDATE questoes SET resolution='{"what_is_testing": "Identificar a afirmação incorreta sobre empenho da despesa.", "rule_concept": "Empenho é ato da autoridade competente que cria obrigação de pagamento pendente ou não de condição. Liquidação, e não empenho, é a verificação do direito adquirido pelo credor.", "reasoning_steps": ["A é verdadeira: não se realiza despesa sem prévio empenho.", "B é verdadeira: pode haver empenho global para despesas contratuais parceláveis.", "C é incorreta porque descreve liquidação, não empenho.", "D é verdadeira: usa-se empenho estimativo quando o montante não pode ser previamente determinado.", "E é verdadeira: empenho não pode exceder o limite dos créditos concedidos."], "calculation": null, "correct_alternative": "C — é a alternativa INCORRETA.", "wrong_alternatives": "A, B, D e E estão de acordo com as regras apresentadas.", "normative_basis": "Lei nº 4.320/1964, arts. 58, 59 e 60; art. 63 para liquidação.", "fafipa_trap": "A banca troca a definição de liquidação pela de empenho.", "verification": "OK"}'::jsonb WHERE id='2416288';
UPDATE questoes SET resolution='{"what_is_testing": "Classificar corretamente os tipos de empenho descritos.", "rule_concept": "Estimativo: montante não pode ser determinado previamente. Global: despesa contratual ou de valor determinado sujeita a parcelamento. Ordinário: valor fixo e previamente determinado, com pagamento de uma vez.", "reasoning_steps": ["I está incorreta: a descrição dada é de empenho global, não estimativo.", "II está incorreta: a descrição dada é de empenho estimativo, não global.", "III está correta: descreve empenho ordinário.", "Logo, somente III está correta."], "calculation": null, "correct_alternative": "B — III, apenas.", "wrong_alternatives": "A inclui I indevidamente; C inclui I e II; D inclui II indevidamente.", "normative_basis": "Lei nº 4.320/1964, art. 60 e classificação tradicional dos empenhos.", "fafipa_trap": "Global = parcelamento de valor determinado; estimativo = valor não determinável previamente.", "verification": "OK"}'::jsonb WHERE id='2746537';
UPDATE questoes SET resolution='{"what_is_testing": "Preencher corretamente as três modalidades de empenho.", "rule_concept": "Estimativo corresponde a despesas cujo montante não pode ser determinado previamente; ordinário a valor fixo para pagamento de uma vez; global a despesas contratuais ou de valor determinado sujeitas a parcelamento.", "reasoning_steps": ["I: água, energia e combustíveis → estimativo.", "II: valor fixo e pagamento de uma vez → ordinário.", "III: contrato parcelado/aluguel → global.", "A sequência é estimativo – ordinário – global."], "calculation": null, "correct_alternative": "A — I estimativo; II ordinário; III global.", "wrong_alternatives": "As demais alternativas trocam pelo menos uma das três modalidades.", "normative_basis": "Lei nº 4.320/1964, art. 60 e classificação dos empenhos.", "fafipa_trap": "Associe “não sei o total” a estimativo; “uma vez” a ordinário; “parcelado” a global.", "verification": "OK"}'::jsonb WHERE id='2153541';
UPDATE questoes SET resolution='{"what_is_testing": "Identificar o estágio da despesa correspondente à verificação do direito do credor.", "rule_concept": "A verificação do direito adquirido pelo credor, com base nos títulos e documentos comprobatórios, é a liquidação.", "reasoning_steps": ["O enunciado reproduz o art. 63 da Lei nº 4.320/1964.", "Portanto, trata-se da liquidação, que vem após o empenho e antes do pagamento."], "calculation": null, "correct_alternative": "D — Liquidação.", "wrong_alternatives": "A controle; B pagamento; C empenho; E fixação não correspondem ao conceito citado.", "normative_basis": "Lei nº 4.320/1964, art. 63.", "fafipa_trap": "“Direito adquirido pelo credor” identifica liquidação.", "verification": "OK"}'::jsonb WHERE id='2156886';
UPDATE questoes SET resolution='{"what_is_testing": "Relacionar corretamente estimativo, ordinário e global às situações descritas.", "rule_concept": "Estimativo: valor não determinável previamente; ordinário: valor fixo e pagamento de uma vez; global: valor determinado sujeito a parcelamento.", "reasoning_steps": ["I — água, energia, combustíveis → estimativo.", "II — valor fixo e pagamento único → ordinário.", "III — aluguel e despesas parceláveis → global.", "Sequência: estimativo, ordinário, global."], "calculation": null, "correct_alternative": "B — I estimativo; II ordinário; III global.", "wrong_alternatives": "As outras opções trocam uma ou mais classificações.", "normative_basis": "Lei nº 4.320/1964, art. 60 e classificação dos empenhos.", "fafipa_trap": "“Aluguel” é exemplo clássico de global quando o valor está determinado e há parcelamento.", "verification": "OK"}'::jsonb WHERE id='2431280';
UPDATE questoes SET resolution='{"what_is_testing": "Identificar a modalidade de empenho a partir da descrição de cada situação.", "rule_concept": "I = global; II = ordinário; III = estimativo.", "reasoning_steps": ["I: despesa contratual de valor determinado sujeita a parcelamento → global.", "II: valor fixo previamente determinado, pagamento único → ordinário.", "III: valor não determinável previamente, como água/energia → estimativo."], "calculation": null, "correct_alternative": "D — I global; II ordinário; III estimativo.", "wrong_alternatives": "A, B, C e E alteram pelo menos uma das três correspondências.", "normative_basis": "Lei nº 4.320/1964, art. 60.", "fafipa_trap": "A ordem da questão é diferente das questões 372/374; resolva cada definição antes de olhar a alternativa.", "verification": "OK"}'::jsonb WHERE id='2165660';
UPDATE questoes SET resolution='{"what_is_testing": "Ordenar os estágios da despesa pública.", "rule_concept": "A sequência é fixação/autorização orçamentária, empenho, liquidação e pagamento. Entre os itens apresentados: III → II → IV → I.", "reasoning_steps": ["III = inclusão/fixação da despesa na lei orçamentária.", "II = empenho.", "IV = liquidação.", "I = pagamento, pois é o despacho/ordem para que a despesa seja paga.", "Logo, a ordem é III, II, IV, I."], "calculation": null, "correct_alternative": "D — III, II, IV e I.", "wrong_alternatives": "As demais sequências quebram a ordem lógica e legal da execução da despesa.", "normative_basis": "Lei nº 4.320/1964, arts. 58, 63 e 64, considerando a autorização/fixação orçamentária anterior à execução.", "fafipa_trap": "Não confundir “ordenação do pagamento” com a própria liquidação.", "verification": "OK"}'::jsonb WHERE id='1058806';
UPDATE questoes SET resolution='{"what_is_testing": "Reconhecer a definição de liquidação da despesa pública.", "rule_concept": "Liquidação consiste na verificação do direito adquirido pelo credor com base nos títulos e documentos comprobatórios do crédito.", "reasoning_steps": ["A alternativa E reproduz a definição legal.", "B descreve empenho.", "D descreve pagamento.", "A trata de movimentação financeira.", "C trata de matéria tributária."], "calculation": null, "correct_alternative": "E — verificação do direito adquirido pelo credor.", "wrong_alternatives": "A, B, C e D descrevem institutos diferentes.", "normative_basis": "Lei nº 4.320/1964, art. 63.", "fafipa_trap": "A banca repete a definição legal quase literalmente; memorize o vínculo “liquidação = direito adquirido”.", "verification": "OK"}'::jsonb WHERE id='1336836';
UPDATE questoes SET resolution='{"what_is_testing": "Classificar os empenhos de energia elétrica e aluguel.", "rule_concept": "Energia elétrica possui montante variável/não determinável previamente, sendo típico empenho estimativo. Aluguel contratual de valor determinado, sujeito a parcelas, utiliza empenho global.", "reasoning_steps": ["Energia elétrica → estimativo.", "Aluguel contratual parcelado → global.", "A sequência é estimativos e globais."], "calculation": null, "correct_alternative": "A — Estimativos e globais.", "wrong_alternatives": "As outras alternativas trocam a modalidade de pelo menos uma despesa.", "normative_basis": "Lei nº 4.320/1964, art. 60 e classificação dos empenhos.", "fafipa_trap": "“Consumo variável” aponta para estimativo; “contrato parcelado” aponta para global.", "verification": "OK"}'::jsonb WHERE id='1336837';
UPDATE questoes SET resolution='{"what_is_testing": "Julgar regras da execução da despesa previstas na Lei nº 4.320/1964.", "rule_concept": "O empenho não pode exceder os créditos concedidos; é vedada a realização de despesa sem prévio empenho; para cada empenho é extraída nota de empenho; o pagamento somente ocorre após regular liquidação.", "reasoning_steps": ["I é falsa: empenho não pode exceder o crédito concedido.", "II é falsa: a realização de despesa sem prévio empenho é vedada.", "III é verdadeira: nota de empenho contém os elementos indicados e deduz o valor do saldo da dotação.", "IV é verdadeira: pagamento só depois da regular liquidação.", "Sequência F, F, V, V."], "calculation": null, "correct_alternative": "C — F, F, V, V.", "wrong_alternatives": "A, B e D apresentam sequências incompatíveis com os arts. 59, 60 e 64.", "normative_basis": "Lei nº 4.320/1964, arts. 59, 60, 61 e 64.", "fafipa_trap": "As duas primeiras assertivas invertem proibições legais: excesso de crédito e despesa sem prévio empenho.", "verification": "OK"}'::jsonb WHERE id='1054612';
UPDATE questoes SET resolution='{"what_is_testing": "Ordenar os três estágios da execução da despesa: empenho, liquidação e pagamento.", "rule_concept": "Empenho cria a obrigação para o Estado; liquidação verifica o direito do credor; pagamento entrega o numerário e extingue a obrigação.", "reasoning_steps": ["III = empenho.", "IV = liquidação.", "I = pagamento.", "II descreve arrecadação, que é estágio da receita e não entra na sequência da despesa.", "Logo, os três estágios são III, IV e I."], "calculation": null, "correct_alternative": "D — III, IV e I.", "wrong_alternatives": "A inclui apenas os três conceitos mas não os ordena como execução; B inclui arrecadação; C também inclui arrecadação e exclui pagamento.", "normative_basis": "Lei nº 4.320/1964, arts. 58, 63 e 64.", "fafipa_trap": "A banca mistura receita e despesa: “arrecadação” pertence à receita, enquanto a sequência da despesa é empenho → liquidação → pagamento.", "verification": "OK"}'::jsonb WHERE id='563609';
UPDATE questoes SET resolution='{"regra": "Na execução da despesa orçamentária, a liquidação consiste na verificação do direito adquirido pelo credor, com base nos títulos e documentos comprobatórios do respectivo crédito, conforme a Lei nº 4.320/1964.", "passos": ["O enunciado pede a etapa em que se verifica o direito adquirido pelo credor.", "Essa definição corresponde à liquidação da despesa.", "A sequência clássica é empenho, liquidação e pagamento, após a fixação da despesa no orçamento."], "calculo": "Não há cálculo.", "correta": "C) Liquidação.", "erradas": ["A) Fixação: é a autorização/dotação orçamentária, não a verificação do direito do credor.", "B) Empenho: reserva/comprometimento da dotação para a despesa.", "D) Pagamento: entrega dos recursos ao credor após a liquidação."], "fundamento": "Lei nº 4.320/1964, arts. 62 e 63.", "pegadinha": "Não confundir liquidação com pagamento: a liquidação verifica o direito do credor; o pagamento ocorre depois.", "cobranca": "Estágio da despesa pública — liquidação."}'::jsonb WHERE id='1058533';
UPDATE questoes SET resolution='{"regra": "O Anexo de Metas Fiscais integra o projeto de LDO e contém, entre outros elementos, demonstrativo das metas anuais e demonstrativo da estimativa e compensação da renúncia de receita e da margem de expansão das despesas obrigatórias de caráter continuado.", "passos": ["O comando pede a alternativa correta sobre o Anexo de Metas Fiscais.", "A alternativa D reproduz um conteúdo expressamente previsto no art. 4º, §2º, V, da LRF.", "A alternativa A reduz para dois exercícios anteriores uma comparação que a LRF prevê para três exercícios anteriores.", "A alternativa E fala em três exercícios seguintes; a LRF estabelece o exercício a que se referem e os dois seguintes."], "calculo": "Não há cálculo.", "correta": "D) o demonstrativo da estimativa e compensação da renúncia de receita e da margem de expansão das despesas obrigatórias de caráter continuado.", "erradas": ["A) Incorreta pelo número de exercícios anteriores indicado.", "B) Incorreta: a avaliação do cumprimento das metas refere-se ao ano anterior, não a quatro anos.", "C) Embora trate de conteúdo do Anexo, a formulação não corresponde ao requisito completo cobrado na questão.", "E) Incorreta: são dois exercícios seguintes, não três."], "fundamento": "Lei Complementar nº 101/2000 (LRF), art. 4º, §§1º e 2º.", "pegadinha": "Memorize a combinação: metas anuais + exercício e dois seguintes; avaliação do ano anterior; evolução do patrimônio líquido dos três últimos exercícios.", "cobranca": "LRF — Anexo de Metas Fiscais."}'::jsonb WHERE id='3600636';
UPDATE questoes SET resolution='{"regra": "A LRF estabelece limites e condições para a LOA, inclusive para dívida pública e investimentos plurianuais. A atualização monetária do principal da dívida mobiliária refinanciada não pode superar a variação do índice de preços previsto na LDO ou legislação específica.", "passos": ["O comando pede a alternativa INCORRETA.", "A, B, C e E correspondem às regras da LRF sobre a LOA.", "D afirma que a atualização monetária poderá superar a variação do índice previsto.", "A LRF estabelece justamente a vedação a essa superação."], "calculo": "Não há cálculo.", "correta": "D) é a incorreta.", "erradas": ["A) Está de acordo com a LRF.", "B) Está de acordo com a regra para investimento com duração superior a um exercício.", "C) Está de acordo com a vedação de crédito com finalidade imprecisa ou dotação ilimitada.", "E) Está de acordo com a previsão separada do refinanciamento da dívida."], "fundamento": "LRF, art. 5º, especialmente disposições sobre dívida, investimentos e refinanciamento.", "pegadinha": "A palavra decisiva é “poderá superar”. A regra é justamente impedir essa superação.", "cobranca": "LRF — projeto de LOA."}'::jsonb WHERE id='3600638';
UPDATE questoes SET resolution='{"regra": "A LRF fixa prazos e condições específicos para programação financeira, limitação de empenho e avaliação de políticas fiscal, monetária, creditícia e cambial.", "passos": ["I é incorreta: a programação financeira e o cronograma de desembolso devem ser estabelecidos até trinta dias após a publicação dos orçamentos, não sessenta.", "II é correta: recursos vinculados devem atender ao objeto da vinculação, ainda que em exercício diverso.", "III é incorreta: a verificação ocorre ao final de cada bimestre, não trimestre.", "IV é correta quanto às despesas que não serão objeto de limitação, incluindo a hipótese indicada.", "V está de acordo com a avaliação do Banco Central prevista na LRF.", "Logo, as incorretas são I, III e V? A alternativa C registra esse conjunto; porém, V deve ser conferida quanto ao prazo e redação exatos na fonte normativa."], "calculo": "Não há cálculo.", "correta": "C) I, III e V, apenas, conforme o gabarito registrado no material.", "erradas": ["A) Não representa o conjunto indicado pelo gabarito.", "B) Considera apenas IV como incorreta.", "D) Inclui II como incorreta, embora II esteja alinhada ao art. 8º, parágrafo único.", "E) Não inclui I como incorreta."], "fundamento": "LRF, arts. 8º, 9º e dispositivos sobre avaliação do cumprimento das políticas monetária, creditícia e cambial.", "pegadinha": "A questão mistura prazos de 30 e 60 dias e “bimestre” com “trimestre”; esses detalhes alteram a assertiva.", "cobranca": "LRF — execução orçamentária e cumprimento de metas."}'::jsonb WHERE id='3600642';
UPDATE questoes SET resolution='{"regra": "A limitação de empenho ocorre quando a realização da receita puder comprometer as metas fiscais. Há despesas legalmente protegidas da limitação, e a recomposição das dotações limitadas acompanha a recomposição da receita.", "passos": ["1ª: Falsa. A limitação não pode atingir livremente despesas protegidas; a LRF exclui obrigações constitucionais e legais, além das hipóteses previstas no §2º do art. 9º.", "2ª: Verdadeira. A recomposição das dotações limitadas ocorre proporcionalmente à recomposição da receita.", "3ª: Verdadeira. A hipótese de inovação e desenvolvimento científico e tecnológico custeada por fundo específico está entre as exceções indicadas.", "4ª: Verdadeira. As audiências públicas quadrimestrais ocorrem até o final de maio, setembro e fevereiro.", "5ª: Falsa. Recursos vinculados devem observar a finalidade da vinculação."], "calculo": "Não há cálculo.", "correta": "A) F, V, V, V, F.", "erradas": ["B) Inverte a avaliação das primeiras assertivas.", "C) Considera a primeira como verdadeira e a quarta como falsa.", "D) Considera a quinta como verdadeira.", "E) Considera a segunda como falsa."], "fundamento": "LRF, arts. 9º e 48-A/48?; especificamente art. 9º para limitação e art. 8º, parágrafo único, para recursos vinculados.", "pegadinha": "Não basta haver queda de arrecadação: é preciso observar as metas fiscais e as despesas excluídas da limitação.", "cobranca": "LRF — limitação de empenho."}'::jsonb WHERE id='3930720';
UPDATE questoes SET resolution='{"regra": "As etapas da receita orçamentária são previsão, lançamento, arrecadação e recolhimento, quando aplicáveis.", "passos": ["Primeiro, a receita é prevista no orçamento.", "Depois, quando cabível, ocorre o lançamento do crédito.", "Em seguida ocorre a arrecadação junto ao contribuinte/devedor.", "Por fim, o agente arrecadador recolhe os recursos ao Tesouro."], "calculo": "Não há cálculo.", "correta": "A) Previsão → Lançamento → Arrecadação → Recolhimento.", "erradas": ["B) Inverte a ordem e começa pela arrecadação.", "C) Coloca lançamento depois da arrecadação.", "D) Coloca arrecadação antes do lançamento."], "fundamento": "Lei nº 4.320/1964, arts. 51 a 56; MCASP — estágios da receita.", "pegadinha": "Arrecadação é o recebimento pelo agente arrecadador; recolhimento é a transferência dos valores arrecadados ao Tesouro.", "cobranca": "Estágios da receita pública."}'::jsonb WHERE id='3598419';
UPDATE questoes SET resolution='{"regra": "Lançamento é o ato da repartição competente que verifica a procedência do crédito fiscal, identifica o devedor e inscreve o débito.", "passos": ["O enunciado praticamente reproduz a definição legal de lançamento.", "Compare com as demais etapas: arrecadação é o recebimento; recolhimento é a entrega ao Tesouro.", "Logo, a definição corresponde a lançamento."], "calculo": "Não há cálculo.", "correta": "C) lançamento.", "erradas": ["A) Liquidação é estágio da despesa, não a definição apresentada para receita.", "B) Arrecadação é o recebimento do recurso pelo agente arrecadador.", "D) Recolhimento é a transferência ao Tesouro.", "E) Previsão é a estimativa da receita na peça orçamentária."], "fundamento": "Lei nº 4.320/1964, art. 53.", "pegadinha": "A expressão “verifica a procedência do crédito fiscal e a pessoa que lhe é devedora” é típica do lançamento.", "cobranca": "Estágio da receita — lançamento."}'::jsonb WHERE id='3862376';
UPDATE questoes SET resolution='{"regra": "Arrecadação corresponde à entrega dos recursos devidos ao Tesouro pelos contribuintes ou devedores, por meio dos agentes arrecadadores autorizados.", "passos": ["O enunciado pergunta pela etapa relacionada à entrega dos recursos pelo contribuinte/devedor.", "Isso caracteriza arrecadação.", "O recolhimento é a transferência dos valores arrecadados para a conta do Tesouro."], "calculo": "Não há cálculo.", "correta": "A) Arrecadação.", "erradas": ["B) Recolhimento: ocorre depois, com a transferência dos valores arrecadados ao Tesouro.", "C) Pagamento é estágio da despesa.", "D) Tesouramento não é estágio da receita.", "E) Lançamento é a constituição/verificação do crédito tributário."], "fundamento": "MCASP — estágios da receita; Lei nº 4.320/1964, art. 56.", "pegadinha": "Arrecadação ≠ recolhimento: a primeira envolve o recebimento; o segundo, a transferência ao Tesouro.", "cobranca": "Estágio da receita — arrecadação."}'::jsonb WHERE id='3862439';
UPDATE questoes SET resolution='{"regra": "Na execução da receita orçamentária, a ordem é previsão, lançamento, arrecadação e recolhimento.", "passos": ["A LOA estabelece a previsão.", "A formalização do crédito tributário do IPTU corresponde ao lançamento.", "O recebimento pelos agentes arrecadadores corresponde à arrecadação.", "A transferência à conta única do Tesouro corresponde ao recolhimento."], "calculo": "Não há cálculo.", "correta": "B) Previsão > Lançamento > Arrecadação > Recolhimento.", "erradas": ["A) Começa pela arrecadação e coloca lançamento depois.", "C) Troca lançamento e arrecadação.", "D) Inverte previsão e lançamento e também a ordem final.", "E) Apresenta a sequência em ordem inversa."], "fundamento": "MCASP — etapas da receita orçamentária; Lei nº 4.320/1964.", "pegadinha": "O próprio caso do IPTU fornece as quatro etapas em ordem se você mapear cada verbo do enunciado.", "cobranca": "Estágios da receita — caso prático."}'::jsonb WHERE id='3930692';
UPDATE questoes SET resolution='{"regra": "O lançamento verifica a existência do crédito tributário, identifica o devedor e o valor devido. No enfoque patrimonial, o reconhecimento do crédito tributário pode gerar VPA conforme o regime de competência.", "passos": ["A descrição começa com a constituição/verificação formal do crédito.", "Identificar o devedor e registrar o valor devido são elementos do lançamento.", "Logo, a etapa pedida é o lançamento."], "calculo": "Não há cálculo.", "correta": "C) Lançamento.", "erradas": ["A) Programação financeira não é estágio da receita.", "B) Arbitramento pode ser procedimento de apuração, mas não é o estágio pedido.", "D) Recolhimento é a transferência ao Tesouro.", "E) Previsão é a estimativa orçamentária."], "fundamento": "Lei nº 4.320/1964, art. 53; MCASP/NBC TSP quanto ao reconhecimento patrimonial.", "pegadinha": "A questão mistura linguagem orçamentária e patrimonial; a definição operacional continua sendo a de lançamento.", "cobranca": "Estágio da receita e regime patrimonial."}'::jsonb WHERE id='4003309';
UPDATE questoes SET resolution='{"regra": "No enfoque orçamentário, a receita é reconhecida pela arrecadação e a despesa pelo empenho. No enfoque patrimonial, VPA e VPD seguem o regime de competência.", "passos": ["I é verdadeira no enfoque orçamentário: receita orçamentária é registrada no momento da arrecadação.", "II é verdadeira no enfoque orçamentário: a despesa é registrada pelo empenho.", "III é verdadeira: VPA segue competência.", "IV é verdadeira: VPD segue competência.", "Portanto, todas as assertivas estão corretas."], "calculo": "Não há cálculo.", "correta": "D) I, II, III e IV.", "erradas": ["A) Omite a IV.", "B) Omite III e IV.", "C) Omite I e II."], "fundamento": "MCASP 11ª edição; NBC TSP Estrutura Conceitual; Lei nº 4.320/1964, art. 35 para o enfoque orçamentário.", "pegadinha": "A palavra “orçamentária” nas duas primeiras assertivas é crucial. Não confundir regime orçamentário com regime patrimonial.", "cobranca": "Regimes orçamentário e patrimonial."}'::jsonb WHERE id='3598414';
UPDATE questoes SET resolution='{"regra": "A receita orçamentária segue regime de caixa para fins de reconhecimento orçamentário: pertence ao exercício a receita nele arrecadada. O lançamento do IPTU tem tratamento patrimonial próprio, mas não antecipa a receita orçamentária integralmente para janeiro.", "passos": ["O lançamento do IPTU ocorre em janeiro e constitui/quantifica o crédito tributário.", "Isso não significa que toda a receita orçamentária esteja arrecadada em janeiro.", "A receita orçamentária é reconhecida à medida da arrecadação.", "Logo, a alternativa A corresponde ao enfoque orçamentário pedido."], "calculo": "Não há cálculo; o total lançado de R$ 6.500.000 não é automaticamente receita orçamentária de janeiro.", "correta": "A) deve ser realizado à medida da arrecadação, respeitando o regime de caixa.", "erradas": ["B) Confunde lançamento tributário com arrecadação orçamentária.", "C) IPTU é receita tributária, não receita patrimonial.", "D) Inscrição em dívida ativa não é condição para reconhecimento de toda a receita arrecadada."], "fundamento": "Lei nº 4.320/1964, art. 35; MCASP — regime orçamentário e patrimonial.", "pegadinha": "“Lançamento” do tributo não é sinônimo de “arrecadação” da receita orçamentária.", "cobranca": "Regimes orçamentário e patrimonial."}'::jsonb WHERE id='3598417';
UPDATE questoes SET resolution='{"regra": "A Lei nº 4.320/1964 adota regime misto no enfoque orçamentário: receita pelo regime de caixa e despesa pelo regime do exercício/empenho.", "passos": ["Art. 35: pertencem ao exercício financeiro as receitas nele arrecadadas.", "Também pertencem ao exercício as despesas nele legalmente empenhadas.", "Isso caracteriza o regime misto orçamentário."], "calculo": "Não há cálculo.", "correta": "E) Regime de Caixa para a Receita e de Competência para a Despesa (Regime Misto).", "erradas": ["A) Não corresponde à combinação legal.", "B) É caixa puro e está incorreto.", "C) Competência pura não corresponde ao art. 35 para o enfoque orçamentário.", "D) Inverte o tratamento da receita e da despesa."], "fundamento": "Lei nº 4.320/1964, art. 35.", "pegadinha": "O “regime misto” aqui é o enfoque orçamentário. No patrimônio, as NBC TSP adotam competência.", "cobranca": "Regime orçamentário — Lei 4.320/1964."}'::jsonb WHERE id='3748797';
UPDATE questoes SET resolution='{"regra": "As demonstrações contábeis do setor público, no enfoque patrimonial, são elaboradas com base no regime de competência.", "passos": ["A questão pergunta o regime para reconhecimento e mensuração dos elementos das demonstrações.", "A Estrutura Conceitual das NBC TSP utiliza a base de competência.", "Logo, não se trata de regime misto ou exclusivamente orçamentário."], "calculo": "Não há cálculo.", "correta": "C) competência.", "erradas": ["A) Misto é associado ao enfoque orçamentário da Lei 4.320, não à base patrimonial das demonstrações.", "B) Orçamentário não é a base de reconhecimento patrimonial.", "D) Híbrido não é a resposta normativa.", "E) Caixa não é a base principal exigida pela Estrutura Conceitual."], "fundamento": "NBC TSP Estrutura Conceitual; MCASP.", "pegadinha": "Distinguir “regime misto” orçamentário de “competência” patrimonial.", "cobranca": "NBC TSP — regime de competência."}'::jsonb WHERE id='3748808';
UPDATE questoes SET resolution='{"regra": "O reconhecimento patrimonial não depende necessariamente do empenho. Uma VPD pode ser reconhecida quando ocorre o fato gerador patrimonial, mesmo antes da liquidação orçamentária.", "passos": ["1ª assertiva: verdadeira. O empenho é estágio orçamentário e não condição universal para reconhecer o efeito patrimonial.", "2ª: falsa. VPD segue o fato gerador e o regime de competência, não uma exigência de liquidação do empenho.", "3ª: falsa. A contabilidade deve evidenciar as variações patrimoniais; a afirmação de que a Lei 4.320 não exige que fatos modificativos sejam levados a resultado é inadequada.", "A sequência é V, F, F."], "calculo": "Não há cálculo.", "correta": "C) V, F, F.", "erradas": ["A) Considera a terceira verdadeira.", "B) Considera a primeira falsa.", "D) Considera a segunda verdadeira.", "E) Considera segunda e terceira como verdadeiras."], "fundamento": "MCASP e NBC TSP Estrutura Conceitual; distinção entre enfoques orçamentário e patrimonial.", "pegadinha": "Empenho e liquidação são eventos orçamentários; VPD é patrimonial e segue competência.", "cobranca": "Despesa orçamentária × VPD."}'::jsonb WHERE id='4003313';
UPDATE questoes SET resolution='{"regra": "A LRF brasileira teve referências internacionais ligadas à responsabilidade fiscal, transparência e controle, incluindo experiências da Nova Zelândia, Estados Unidos, União Europeia e organismos internacionais.", "passos": ["A questão pede a alternativa que NÃO representa uma referência.", "Nova Zelândia, Estados Unidos, União Europeia e FMI aparecem como referências associadas ao desenvolvimento da responsabilidade fiscal.", "Mercosul é um bloco de integração regional, não o modelo internacional de responsabilidade fiscal apontado como inspiração normativa da LRF."], "calculo": "Não há cálculo.", "correta": "B) Mercosul.", "erradas": ["A) Nova Zelândia: referência associada ao Fiscal Responsibility Act.", "C) FMI: difundiu padrões e práticas de gestão fiscal.", "D) Estados Unidos: Budget Enforcement Act e mecanismos de controle.", "E) Comunidade Europeia/Tratado de Maastricht: referência de disciplina fiscal."], "fundamento": "Contexto histórico e comparado da LRF apresentado na literatura de finanças públicas.", "pegadinha": "Não confundir bloco econômico regional com legislação/modelo de responsabilidade fiscal.", "cobranca": "LRF — fundamentos e referências internacionais."}'::jsonb WHERE id='3023789';
UPDATE questoes SET resolution='{"regra": "Recursos legalmente vinculados a finalidade específica devem atender ao objeto da vinculação, ainda que o ingresso tenha ocorrido em exercício diverso.", "passos": ["A alternativa B afirma que a vinculação deixa de existir quando o recurso é utilizado em exercício diferente.", "Isso contraria expressamente o art. 8º, parágrafo único, da LRF.", "As demais alternativas reproduzem regras da LRF."], "calculo": "Não há cálculo.", "correta": "B) é a INCORRETA.", "erradas": ["A) Está de acordo com a LRF.", "C) Reproduz o conceito de responsabilidade na gestão fiscal do art. 1º, §1º.", "D) Está de acordo com o Anexo de Metas Fiscais e seus dois exercícios seguintes."], "fundamento": "Lei Complementar nº 101/2000, arts. 1º, 4º, 5º e 8º.", "pegadinha": "A LRF diz expressamente “ainda que em exercício diverso daquele em que ocorrer o ingresso”.", "cobranca": "LRF — recursos vinculados."}'::jsonb WHERE id='1643138';
UPDATE questoes SET resolution='{"regra": "A LRF estabelece prazo de até trinta dias após a publicação dos orçamentos para desdobramento das receitas previstas em metas bimestrais de arrecadação.", "passos": ["A alternativa B afirma prazo de até 60 dias.", "O art. 13 da LRF estabelece até 30 dias após a publicação dos orçamentos.", "Logo, B é a incorreta.", "As demais alternativas reproduzem conceitos da LRF, inclusive despesa adequada à LOA e despesa obrigatória de caráter continuado."], "calculo": "Não há cálculo.", "correta": "B) é a INCORRETA.", "erradas": ["A) Está alinhada ao conceito de adequação orçamentária.", "C) Reproduz a regra de previsão de receitas.", "D) Define despesa obrigatória de caráter continuado como obrigação por período superior a dois exercícios."], "fundamento": "Lei Complementar nº 101/2000, arts. 13 e 16-17.", "pegadinha": "O detalhe decisivo é o prazo: 30 dias, não 60.", "cobranca": "LRF — previsão e metas de arrecadação."}'::jsonb WHERE id='2163425';
UPDATE questoes SET resolution='{"regra": "A criação, expansão ou aperfeiçoamento de ação governamental com aumento de despesa exige estimativa de impacto e declaração de adequação/compatibilidade. Despesa obrigatória de caráter continuado é aquela com obrigação legal de execução por período superior a dois exercícios. O conceito de despesa total com pessoal inclui encargos sociais e contribuições previdenciárias do ente. Se o limite de pessoal for ultrapassado, a redução deve ocorrer nos dois quadrimestres seguintes, com pelo menos um terço no primeiro.", "passos": ["I é verdadeira: corresponde ao art. 16 da LRF.", "II é verdadeira: corresponde ao conceito do art. 17.", "III é falsa: a LRF inclui encargos sociais e contribuições recolhidas pelo ente às entidades de previdência no conceito de despesa total com pessoal.", "IV é falsa: o art. 23 fala em dois quadrimestres, e pelo menos um terço do excedente deve ser eliminado no primeiro.", "Assim, apenas I e II estão corretas."], "calculo": "2 proposições corretas → alternativa C.", "correta": "C) Apenas duas proposições estão corretas.", "erradas": ["A) Incorreta porque I e II são verdadeiras.", "B) Incorreta porque há duas, não uma, proposições corretas.", "D) Incorreta porque III e IV são falsas.", "E) Incorreta porque III e IV não são verdadeiras."], "fundamento": "Lei Complementar nº 101/2000, arts. 16, 17, 18 e 23.", "pegadinha": "Q400 reúne três detalhes clássicos: encargos sociais entram na despesa com pessoal; redução ocorre em dois quadrimestres; pelo menos um terço no primeiro.", "cobranca": "LRF — despesa pública e pessoal."}'::jsonb WHERE id='2164725';
UPDATE questoes SET resolution='{"regra": "O Relatório de Gestão Fiscal (RGF), previsto nos arts. 54 e 55 da LRF, é emitido ao final de cada quadrimestre e contém, entre outros comparativos, a despesa total com pessoal e os limites legais.", "passos": ["O art. 55, I, determina que o RGF contenha comparativo com os limites da LRF.", "Entre esses montantes está a despesa total com pessoal, inclusive distinguindo inativos e pensionistas.", "O Anexo de Riscos Fiscais integra a LDO, não o RGF.", "A apuração da Receita Corrente Líquida aparece em outros demonstrativos, mas não é o quadro que a alternativa B descreve como conteúdo obrigatório do RGF."], "calculo": "Não há cálculo.", "correta": "B) O RGF conterá um quadro comparativo entre a despesa total com pessoal e os limites da despesa com pessoal estabelecidos na LRF.", "erradas": ["A) Incorreta: a LRF prevê emissão ao final de cada quadrimestre, sem essa dispensa por população inferior a 30 mil habitantes.", "C) Incorreta: o Anexo de Riscos Fiscais integra o projeto de LDO.", "D) Incorreta como descrição do conteúdo do RGF: a alternativa confunde o RGF com demonstrativos da RCL."], "fundamento": "Lei Complementar nº 101/2000, arts. 54 e 55.", "pegadinha": "RGF = gestão fiscal e limites; Riscos Fiscais = LDO/Anexo de Riscos Fiscais.", "cobranca": "LRF — Relatório de Gestão Fiscal."}'::jsonb WHERE id='1058731';
UPDATE questoes SET resolution='{"regra": "A concessão ou ampliação de incentivo ou benefício tributário que implique renúncia de receita deve observar os requisitos do art. 14 da LRF, inclusive estimativa do impacto no exercício de início e nos dois seguintes.", "passos": ["A alternativa A reproduz o prazo previsto no art. 14: exercício em que iniciar a vigência e os dois seguintes.", "B está errada porque despesa obrigatória de caráter continuado exige obrigação por período superior a dois exercícios.", "C está errada porque, para Estados, o limite global é 60% da RCL, não 50%.", "D está errada porque a LRF não exclui genericamente o aumento de despesa com inativos da disciplina de pessoal."], "calculo": "Não há cálculo.", "correta": "A) Estimativa do impacto no exercício de início da vigência e nos dois seguintes.", "erradas": ["B) “Até dois exercícios” é incompatível com o conceito legal, que exige período superior a dois exercícios.", "C) Estados: 60% da RCL; União: 50%; Municípios: 60%.", "D) A formulação não corresponde à regra da LRF."], "fundamento": "LRF, arts. 14, 17 e 19.", "pegadinha": "Decore a sequência do art. 14: exercício de início + dois seguintes.", "cobranca": "LRF — renúncia de receita e despesa obrigatória continuada."}'::jsonb WHERE id='1058835';
UPDATE questoes SET resolution='{"regra": "Os três itens reproduzem conceitos dos arts. 11, 16 e 17 da LRF.", "passos": ["I: correta. A instituição, previsão e efetiva arrecadação de todos os tributos da competência do ente são requisitos essenciais da responsabilidade fiscal.", "II: correta. A despesa adequada à LOA deve ter dotação específica e suficiente ou estar abrangida por crédito genérico, observados os limites do exercício.", "III: correta. Compatibilidade com PPA e LDO exige conformidade com diretrizes, objetivos, prioridades e metas, sem infringir suas disposições."], "calculo": "Não há cálculo.", "correta": "E) Todas as assertivas estão corretas.", "erradas": ["A) Incorreta: II e III também estão corretas.", "B) Incorreta: I e III também estão corretas.", "C) Incorreta: I e II também estão corretas.", "D) Incorreta: III também está correta."], "fundamento": "Lei Complementar nº 101/2000, arts. 11, 16 e 17.", "pegadinha": "A FAFIPA pode trocar “adequada à LOA” por “compatível com PPA/LDO”; são conceitos diferentes e cumulativos.", "cobranca": "LRF — receita, adequação e compatibilidade da despesa."}'::jsonb WHERE id='1335710';
UPDATE questoes SET resolution='{"regra": "A LRF disciplina RPPS, apuração da despesa com pessoal e limites por ente. A despesa com pessoal é apurada em regime de competência, e os Tribunais de Contas alertam quando o montante ultrapassa 90% do limite.", "passos": ["I: verdadeira. O art. 69 exige caráter contributivo e equilíbrio financeiro e atuarial para RPPS.", "II: falsa. A apuração soma o mês de referência e os onze anteriores, mas adota regime de competência, não de caixa.", "III: falsa. O limite global dos Municípios é 60% da RCL, não 70%.", "IV: verdadeira. O alerta ocorre quando a despesa ultrapassa 90% do limite, nos termos do art. 59, §1º, II.", "Logo, I e IV estão corretas."], "calculo": "Não há cálculo.", "correta": "D) I e IV, apenas.", "erradas": ["A) Desconsidera I.", "B) Inclui II, que é falsa porque o regime é de competência.", "C) Inclui II, além de excluir I.", "E) III é falsa: o limite municipal é 60%."], "fundamento": "LRF, arts. 59, §1º, II; 18, §2º; 19, III; 69.", "pegadinha": "A troca “competência” por “caixa” é uma pegadinha clássica da LRF.", "cobranca": "LRF — despesa com pessoal e RPPS."}'::jsonb WHERE id='1335927';
UPDATE questoes SET resolution='{"regra": "A LRF considera aumento de despesa a prorrogação de despesa criada por prazo determinado; o limite municipal de pessoal é 60% da RCL; a apuração de pessoal segue regime de competência; e a operação de crédito não pode superar as despesas de capital, ressalvada a exceção constitucional.", "passos": ["I: verdadeira, conforme art. 17, §7º.", "II: verdadeira: Municípios têm limite global de 60% da RCL.", "III: falsa: o art. 18, §2º, determina regime de competência, não caixa.", "IV: falsa: a chamada regra de ouro impede, em regra, que o montante previsto de operações de crédito supere as despesas de capital, ressalvadas as condições constitucionais.", "Portanto, apenas I e II estão corretas."], "calculo": "Não há cálculo.", "correta": "A) Apenas as assertivas I e II estão corretas.", "erradas": ["B) III e IV são falsas.", "C) Inclui III, que usa regime de caixa.", "D) Não são todas corretas porque III e IV estão erradas."], "fundamento": "LRF, arts. 17 e 19; Constituição Federal, art. 167, III.", "pegadinha": "Em questões antigas, confira a redação da regra de ouro e não confunda com a apuração da despesa com pessoal.", "cobranca": "LRF — despesa com pessoal e regra de ouro."}'::jsonb WHERE id='1054362';
UPDATE questoes SET resolution='{"regra": "A LRF exige instituição, previsão e efetiva arrecadação dos tributos de competência do ente e veda transferências voluntárias ao ente que não observe esse requisito quanto aos impostos.", "passos": ["A alternativa A é a INCORRETA porque afirma que a realização de transferências voluntárias é autorizada para o ente que não observa os requisitos de instituição, previsão e arrecadação dos impostos.", "O art. 11, parágrafo único, estabelece justamente a vedação.", "B reproduz o conceito de empresa estatal dependente.", "C reproduz o conceito de empresa controlada.", "D reproduz a definição de responsabilidade na gestão fiscal do art. 1º, §1º."], "calculo": "Não há cálculo.", "correta": "A) é a alternativa INCORRETA.", "erradas": ["B) Está de acordo com o art. 2º, III.", "C) Está de acordo com o art. 2º, II.", "D) Está de acordo com o art. 1º, §1º."], "fundamento": "LRF, arts. 1º, 2º e 11.", "pegadinha": "A palavra “autorizada” inverte uma regra de proibição: a LRF veda a transferência voluntária nessa hipótese.", "cobranca": "LRF — conceitos e requisitos essenciais."}'::jsonb WHERE id='591948';
UPDATE questoes SET resolution='{"regra": "O RREO é instrumento de transparência da execução orçamentária e é exigido para os entes da Federação, não apenas para a União. A LRF também limita pessoal e disciplina ARO e renúncia de receita.", "passos": ["A alternativa A é a INCORRETA: o RREO não é elaborado apenas pela União.", "A alternativa B está correta quanto ao limite global de 60% da RCL para Estados e Municípios.", "C está de acordo com a vedação de ARO no último ano de mandato.", "D está alinhada ao art. 14 quanto à estimativa do impacto da renúncia."], "calculo": "Não há cálculo.", "correta": "A) é a alternativa NÃO correta.", "erradas": ["B) Correta: Estados e Municípios têm limite de 60% da RCL.", "C) Correta: ARO é vedada no último ano de mandato.", "D) Correta quanto à estimativa de impacto no exercício de início e nos dois seguintes."], "fundamento": "LRF, arts. 19, 38, 52 e 14.", "pegadinha": "RREO = execução orçamentária e é amplo; RGF = gestão fiscal e limites.", "cobranca": "LRF — RREO, pessoal, ARO e renúncia."}'::jsonb WHERE id='563617';
UPDATE questoes SET resolution='{"regra": "A LRF pressupõe ação planejada e transparente e exige responsabilidade na geração de despesas, mas não significa que todo aumento de gasto possa ocorrer sem indicação de recursos e adequação orçamentária.", "passos": ["A alternativa A é a INCORRETA.", "A LRF estabelece mecanismos de adequação orçamentária, estimativa de impacto e compensação em situações previstas.", "As demais alternativas descrevem objetivos ou princípios compatíveis com a responsabilidade fiscal."], "calculo": "Não há cálculo.", "correta": "A) Cada aumento de gasto não precisa vir de uma fonte de financiamento correlata.", "erradas": ["B) Compatível com a preocupação da LRF com equilíbrio e responsabilidade entre mandatos.", "C) Compatível com o objetivo de preservar a situação fiscal.", "D) Compatível com a aplicação responsável dos recursos públicos.", "E) Reproduz a ação planejada e transparente do art. 1º, §1º."], "fundamento": "LRF, especialmente arts. 1º, 15 e 16.", "pegadinha": "A questão troca “responsabilidade fiscal” por liberdade para gastar; é justamente o contrário.", "cobranca": "LRF — responsabilidade na gestão fiscal."}'::jsonb WHERE id='923860';
UPDATE questoes SET resolution='{"regra": "A Lei Complementar nº 101/2000 estabelece normas de finanças públicas voltadas à responsabilidade na gestão fiscal, e não normas de gestão florestal.", "passos": ["A alternativa A está correta: a LRF alcança União, Estados, DF e Municípios.", "B é a INCORRETA porque atribui à LRF objeto estranho à sua finalidade.", "C apresenta a definição legal de ente da Federação.", "D está alinhada à regra de nulidade de ato que provoque aumento de despesa com pessoal sem observar as exigências legais."], "calculo": "Não há cálculo.", "correta": "B) A Lei Complementar nº 101/2000 estabelece normas de gestão florestal.", "erradas": ["A) Correta.", "C) Correta.", "D) Correta quanto à nulidade do ato nas hipóteses legais."], "fundamento": "LRF, arts. 1º e 2º; art. 21.", "pegadinha": "A prova troca “finanças públicas” por “gestão florestal”, expressão estranha ao objeto da LRF.", "cobranca": "LRF — disposições preliminares."}'::jsonb WHERE id='955101';
UPDATE questoes SET resolution='{"regra": "As quatro afirmativas estão de acordo com a LRF: prorrogação de despesa por prazo determinado é aumento de despesa; transferência voluntária tem conceito legal; recursos transferidos não podem ser usados em finalidade diversa; e renúncia de receita inclui as modalidades listadas no art. 14.", "passos": ["I: verdadeira, art. 17, §7º.", "II: verdadeira, art. 25.", "III: verdadeira, conforme a disciplina das transferências voluntárias.", "IV: verdadeira, art. 14, §1º.", "Logo, todas as afirmativas estão corretas."], "calculo": "Não há cálculo.", "correta": "D) Todas as alternativas estão corretas.", "erradas": ["A) Incorreta: II, III e IV também são verdadeiras.", "B) Incorreta: II e III também são verdadeiras.", "C) Incorreta: I também é verdadeira."], "fundamento": "LRF, arts. 14, 17 e 25.", "pegadinha": "A lista do art. 14 é extensa: anistia, remissão, subsídio, crédito presumido, isenção não geral, alteração de alíquota/base com redução discriminada e outros benefícios.", "cobranca": "LRF — transferência voluntária e renúncia de receita."}'::jsonb WHERE id='955104';
UPDATE questoes SET resolution='{"regra": "Créditos adicionais são autorizações de despesa não computadas ou insuficientemente dotadas na LOA. Suplementares reforçam dotação; especiais atendem despesas sem dotação específica; extraordinários atendem despesas urgentes e imprevisíveis.", "passos": ["A alternativa B reproduz a regra do art. 45 da Lei 4.320: os créditos têm vigência no exercício em que forem abertos, ressalvados especiais e extraordinários nos casos legais.", "A está errada porque descreve créditos extraordinários como se fossem especiais.", "C está errada porque a definição de despesa sem dotação específica é de crédito especial.", "D está errada: especiais são autorizados por lei e abertos por decreto executivo.", "E está errada: a abertura de extraordinários segue o instrumento próprio e não a regra descrita."], "calculo": "Não há cálculo.", "correta": "B) Os créditos adicionais terão vigência adstrita ao exercício financeiro em que forem abertos, salvo expressa disposição legal em contrário, quanto aos especiais e extraordinários.", "erradas": ["A) Urgência e imprevisibilidade caracterizam créditos extraordinários.", "C) Despesa sem dotação específica caracteriza crédito especial.", "D) Abertura por decreto é do Executivo, após autorização legal quando exigida.", "E) A alternativa simplifica incorretamente a disciplina dos extraordinários."], "fundamento": "Lei nº 4.320/1964, arts. 40 a 46.", "pegadinha": "Especial = sem dotação; extraordinário = urgente e imprevisível; suplementar = reforço de dotação.", "cobranca": "Créditos adicionais."}'::jsonb WHERE id='2416287';
UPDATE questoes SET resolution='{"regra": "Superávit financeiro é fonte para abertura de créditos adicionais e é apurado no Balanço Patrimonial do exercício anterior, considerando a diferença positiva entre ativo financeiro e passivo financeiro, conjugada com os saldos dos créditos adicionais transferidos e as operações de crédito a eles vinculadas.", "passos": ["A alternativa C é a INCORRETA porque afirma que o superávit financeiro é apurado no Balanço Financeiro.", "A Lei 4.320/1964, art. 43, §2º, vincula a apuração ao Balanço Patrimonial.", "A, B, D e E estão de acordo com a disciplina dos créditos adicionais."], "calculo": "Não há cálculo.", "correta": "C) é a alternativa INCORRETA.", "erradas": ["A) Correta: suplementares e especiais são autorizados por lei e abertos por decreto executivo.", "B) Correta: especiais atendem despesas sem dotação específica.", "D) Correta: a LOA pode conter autorização para abertura de suplementares até determinado limite.", "E) Correta quanto à dispensa de indicação prévia da fonte para abertura de extraordinários."], "fundamento": "Lei nº 4.320/1964, arts. 40, 41, 42 e 43, especialmente art. 43, §2º.", "pegadinha": "Superávit financeiro = Balanço Patrimonial, não Balanço Financeiro.", "cobranca": "Créditos adicionais — fontes de recursos."}'::jsonb WHERE id='2715346';
UPDATE questoes SET resolution='{"regra": "No Balanço Orçamentário, receitas são classificadas em correntes e de capital, e despesas também. O resultado da execução orçamentária é a diferença entre receitas realizadas e despesas empenhadas.", "passos": ["Receitas correntes = Serviços 375.000 + Transferências correntes 1.890.000 = R$ 2.265.000.", "Receitas de capital = Operações de crédito 225.000 + ingressos de investimentos 1.730.000 = R$ 1.955.000.", "Despesas correntes = Despesas operacionais 677.000 + pessoal e encargos 1.280.000 = R$ 1.957.000.", "Despesas de capital = Amortização 288.000 + obras 840.000 + veículos 90.000 = R$ 1.218.000.", "Receita total = 4.220.000; despesa total = 3.175.000; resultado = superávit de R$ 1.045.000.", "Assim, I, III e IV são verdadeiras; II e V são falsas."], "calculo": "Resultado = 4.220.000 − 3.175.000 = R$ 1.045.000. Despesa de capital = 288.000 + 840.000 + 90.000 = R$ 1.218.000.", "correta": "D) I, III e IV, apenas.", "erradas": ["A) Inclui II, mas receitas correntes somam R$ 2.265.000.", "B) Não inclui III.", "C) Inclui V, mas despesas de capital somam R$ 1.218.000."], "fundamento": "MCASP — Balanço Orçamentário; Lei nº 4.320/1964, arts. 101 e 102.", "pegadinha": "“Ingressos de investimentos” são receita de capital; amortização da dívida é despesa de capital.", "cobranca": "Balanço Orçamentário — classificação e resultado."}'::jsonb WHERE id='2746486';
UPDATE questoes SET resolution='{"regra": "O resultado da execução orçamentária no Balanço Orçamentário é calculado pela diferença entre receita realizada/arrecadada e despesa empenhada.", "passos": ["Receita arrecadada no exercício = R$ 1.985.000.", "Despesa empenhada = R$ 2.115.000.", "Resultado = 1.985.000 − 2.115.000 = −R$ 130.000.", "Portanto, houve déficit orçamentário de R$ 130.000.", "Reabertura de crédito, pagamento de restos e depósitos extraorçamentários não entram nessa diferença do BO como receita/despesa orçamentária do exercício."], "calculo": "R$ 1.985.000 − R$ 2.115.000 = −R$ 130.000.", "correta": "B) um déficit de R$ 130.000,00.", "erradas": ["A) R$ 40.000 não corresponde à diferença entre receita arrecadada e despesa empenhada.", "C) Não houve superávit.", "D) R$ 100.000 desconsidera parte do resultado.", "E) O resultado não é nulo."], "fundamento": "Lei nº 4.320/1964, arts. 35 e 102; estrutura do Balanço Orçamentário no MCASP.", "pegadinha": "Não misture pagamentos de restos a pagar ou depósitos de terceiros com o resultado orçamentário do exercício.", "cobranca": "Balanço Orçamentário — resultado da execução."}'::jsonb WHERE id='3680407';
UPDATE questoes SET resolution='{"regra": "No Balanço Orçamentário, receitas são classificadas em correntes e de capital, e despesas em correntes e de capital. O resultado da execução é a diferença entre receitas realizadas e despesas empenhadas.", "passos": ["Receitas correntes: transferências correntes (2.250.000) + serviços (1.380.000) = R$ 3.630.000.", "Receitas de capital: operações de crédito (1.200.000) + o item “ingressos de investimentos” precisa ser interpretado segundo a classificação efetivamente usada no enunciado.", "Despesas correntes: despesas operacionais (360.000) + pessoal e encargos (890.400) = R$ 1.250.400.", "Despesas de capital: veículos (170.000) + obras/infraestrutura (2.820.000) + amortização (950.000) = R$ 3.940.000.", "Com os valores textualmente disponíveis, o resultado não reproduz a alternativa B. A questão deve ser conferida na fonte original, especialmente o item “Ingressos de investimentos R$ 3.500.000”, cuja natureza está ambígua na extração."], "calculo": "Receitas correntes = R$ 3.630.000; despesas correntes = R$ 1.250.400. O conjunto dos dados extraídos não permite validar com segurança o resultado de R$ 3.139.600 do gabarito.", "correta": "B) II, III e IV, apenas — gabarito registrado no caderno, mas com necessidade de conferência do enunciado original.", "erradas": ["A) Não pode ser confirmada sem resolver a natureza do item “ingressos de investimentos”.", "C) Não é possível validar todas as cinco afirmações com segurança a partir da extração.", "D) A combinação depende do tratamento do item ambíguo.", "E) Também não pode ser validada com os dados extraídos."], "fundamento": "MCASP 11ª edição — Balanço Orçamentário e classificação por categoria econômica; Lei nº 4.320/1964.", "pegadinha": "Questões de Balanço Orçamentário exigem classificar cada receita e despesa antes de somar. Aqui, a extração apresenta uma rubrica ambígua; não se deve inventar sua classificação.", "cobranca": "Balanço Orçamentário — classificação e resultado da execução."}'::jsonb WHERE id='2153502';
UPDATE questoes SET resolution='{"regra": "O Balanço Orçamentário evidencia as receitas detalhadas por categoria econômica e origem e as despesas por categoria econômica e grupo de natureza, além dos valores de previsão/dotação e execução.", "passos": ["A descrição cita previsão inicial, previsão atualizada, receita realizada e saldo da receita.", "Para despesas, cita dotação, empenho, liquidação, pagamento e saldo da dotação.", "Esse conjunto de informações pertence ao Balanço Orçamentário."], "calculo": "Não há cálculo.", "correta": "D) No Balanço Orçamentário.", "erradas": ["A) DVP evidencia variações patrimoniais, não a execução orçamentária descrita.", "B) DFC evidencia fluxos de caixa.", "C) Balanço Patrimonial evidencia posição patrimonial.", "E) Balanço Financeiro evidencia ingressos e dispêndios financeiros."], "fundamento": "MCASP 11ª edição — Balanço Orçamentário; NBC TSP 13.", "pegadinha": "Previsão/dotação + receita realizada + empenho/liquidação/pagamento = Balanço Orçamentário.", "cobranca": "Contabilidade Pública — demonstrações contábeis."}'::jsonb WHERE id='2156869';
UPDATE questoes SET resolution='{"regra": "No Balanço Orçamentário, o resultado da execução orçamentária é a diferença entre receitas realizadas e despesas empenhadas.", "passos": ["Receitas correntes: 32.200 + 27.300 + 66.500 + 300.000 + 1.250.250 + 388.770 + 55.600 = R$ 2.120.620.", "Receitas de capital: 500.000 + 500.000 + 120.000 = R$ 1.120.000.", "Total das receitas = R$ 3.240.620.", "Despesas correntes: 37.600 + 999.990 = R$ 1.037.590.", "Despesas de capital: 240.200 + 330.400 + 270.800 = R$ 841.400.", "Total das despesas = R$ 1.878.990.", "Resultado = 3.240.620 − 1.878.990 = R$ 1.361.630."], "calculo": "R$ 3.240.620 − R$ 1.878.990 = R$ 1.361.630,00.", "correta": "D) Resultado da execução orçamentária de R$ 1.361.630,00.", "erradas": ["A) Despesas correntes incluem juros e encargos da dívida, totalizando R$ 1.037.590.", "B) Receitas correntes totalizam R$ 2.120.620, não R$ 2.065.020.", "C) Despesas de capital totalizam R$ 841.400, não R$ 879.000.", "E) Receitas de capital totalizam R$ 1.120.000, não R$ 1.175.600."], "fundamento": "MCASP 11ª edição — Balanço Orçamentário; Lei nº 4.320/1964.", "pegadinha": "Não misture juros da dívida com amortização: juros são despesa corrente; amortização é despesa de capital.", "cobranca": "Balanço Orçamentário — classificação e cálculo."}'::jsonb WHERE id='1741119';
UPDATE questoes SET resolution='{"regra": "Receitas correntes e de capital e despesas correntes e de capital devem ser classificadas antes da soma.", "passos": ["Receitas correntes: transferências correntes = R$ 6.800.000.", "Receitas de capital: alienação de bens (120.000) + operações de crédito (750.000) = R$ 870.000.", "Despesas correntes: pessoal (2.720.000) + juros/encargos (36.000) = R$ 2.756.000.", "Despesas de capital: investimentos (670.000) + amortização (480.000) + inversões financeiras (85.000) = R$ 1.235.000.", "Assim, a afirmação de que despesas correntes totalizam R$ 3.200.000 é incorreta."], "calculo": "Despesas correntes = 2.720.000 + 36.000 = R$ 2.756.000.", "correta": "C) O total das despesas correntes foi de R$ 3.200.000 — INCORRETA.", "erradas": ["A) Correta: receitas de capital = R$ 870.000.", "B) Correta: despesas de capital = R$ 1.235.000.", "D) Correta: receitas correntes = R$ 6.800.000."], "fundamento": "Lei nº 4.320/1964 e MCASP — classificação por categoria econômica.", "pegadinha": "Juros e encargos da dívida são despesa corrente; amortização da dívida é despesa de capital.", "cobranca": "Balanço Orçamentário — classificação de receitas e despesas."}'::jsonb WHERE id='1972631';
UPDATE questoes SET resolution='{"regra": "O Balanço Orçamentário exige classificação por categoria econômica e permite apurar o resultado da execução.", "passos": ["Receitas correntes = 10.070 + 4.640 + 50.680 + 385.770 = R$ 451.160. Portanto, I (R$ 446.520) é falsa.", "Receitas de capital = 360 + 5.080 + 140 = R$ 5.580. II é verdadeira.", "Despesas correntes = 131.610 + 2.580 = R$ 134.190. III é verdadeira.", "Despesas de capital = 6.610 + 5.200 + 110 = R$ 11.920. IV (R$ 5.200) é falsa.", "Resultado = 456.740 − 146.110 = R$ 310.630. V é verdadeira."], "calculo": "Resultado = (451.160 + 5.580) − (134.190 + 11.920) = R$ 310.630.", "correta": "D) II, III e V, apenas.", "erradas": ["A) Inclui I, que é falsa.", "B) Inclui IV, que é falsa.", "C) Inclui IV e omite V.", "E) I e IV estão incorretas."], "fundamento": "MCASP 11ª edição — Balanço Orçamentário; Lei nº 4.320/1964.", "pegadinha": "Amortização de empréstimos recebida é receita de capital; amortização da dívida paga é despesa de capital.", "cobranca": "Balanço Orçamentário — cálculo e classificação."}'::jsonb WHERE id='2165654';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar a classificação legal dos créditos adicionais.", "rule": "Lei 4.320/1964, art. 41: suplementares reforçam dotação; especiais atendem despesas sem dotação específica; extraordinários atendem despesas urgentes e imprevisíveis, nos casos legais.", "reasoning": ["A define corretamente os suplementares.", "B define corretamente os especiais.", "C define corretamente os extraordinários.", "Logo, A, B e C estão corretas."], "calculation": "", "correct_answer": "E — As alternativas A, B e C estão corretas.", "why_wrong": "D é falsa porque há classificações corretas nas alternativas anteriores.", "basis": "Lei nº 4.320/1964, art. 41.", "fafipa_trap": "Trocar “sem dotação específica” por “dotação insuficiente”: dotação insuficiente é caso típico de crédito suplementar; ausência de dotação é especial.", "verification": null}'::jsonb WHERE id='916292';
UPDATE questoes SET resolution='{"what_it_tests": "Reconhecer as três espécies de créditos adicionais.", "rule": "Suplementares, especiais e extraordinários.", "reasoning": ["Suplementares: reforço de dotação.", "Especiais: despesas para as quais não haja dotação específica.", "Extraordinários: despesas urgentes e imprevisíveis nas hipóteses legais."], "calculation": "", "correct_answer": "D — Suplementares, Especiais e Extraordinários.", "why_wrong": "A, B, C e E usam categorias que não correspondem à classificação do art. 41 da Lei 4.320/1964.", "basis": "Lei nº 4.320/1964, art. 41.", "fafipa_trap": "“Ordinários”, “condicionais” e “orçados” não são espécies de créditos adicionais.", "verification": null}'::jsonb WHERE id='916312';
UPDATE questoes SET resolution='{"what_it_tests": "Julgar as definições I, II e III de créditos adicionais.", "rule": "Suplementar = reforço de dotação; especial = despesa sem dotação específica; extraordinário = despesa urgente e imprevisível.", "reasoning": ["I está errado: descreve crédito especial, não suplementar.", "II está errado: descreve crédito suplementar, não especial.", "III está correto."], "calculation": "", "correct_answer": "C — III, apenas.", "why_wrong": "A e D incluem I, que está errado. B exclui III, que está correto. E considera todos corretos.", "basis": "Lei nº 4.320/1964, art. 41.", "fafipa_trap": "As definições de suplementar e especial são facilmente invertidas.", "verification": null}'::jsonb WHERE id='1335911';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular o resultado da execução orçamentária pela diferença entre receitas realizadas e despesas empenhadas.", "rule": "Resultado da execução orçamentária = receitas realizadas − despesas empenhadas.", "reasoning": ["Receitas = 5.220.100 + 1.740.300 + 740.900 + 450.300 = R$ 8.151.600.", "Despesas = 4.400.200 + 1.340.700 + 30.000 = R$ 5.770.900.", "Resultado = 8.151.600 − 5.770.900 = R$ 2.380.700."], "calculation": "Receitas = 5.220.100 + 1.740.300 + 740.900 + 450.300 = R$ 8.151.600.", "correct_answer": "D — R$ 2.380.700,00.", "why_wrong": "As demais alternativas decorrem de somas parciais ou de confrontos incorretos.", "basis": "Balanço Orçamentário/resultado da execução orçamentária, confrontando receitas realizadas e despesas empenhadas.", "fafipa_trap": "Não usar despesas pagas quando o enunciado fornece despesas empenhadas.", "verification": null}'::jsonb WHERE id='1335894';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar o conteúdo evidenciado pelo Balanço Orçamentário.", "rule": "O Balanço Orçamentário evidencia receitas e despesas previstas em confronto com as realizadas.", "reasoning": ["A descreve o Balanço Financeiro, pois mistura ingressos e pagamentos extraorçamentários.", "B não corresponde à definição legal do BO.", "C e D são incompletas/incorretas.", "E reproduz a definição do Balanço Orçamentário."], "calculation": "", "correct_answer": "E — As receitas e despesas previstas em confronto com as realizadas.", "why_wrong": "A é característica do Balanço Financeiro; C e D não contemplam o confronto entre previsão/fixação e execução.", "basis": "Lei nº 4.320/1964, art. 102.", "fafipa_trap": "Não confundir BO com BF: o primeiro é orçamentário; o segundo evidencia ingressos e dispêndios orçamentários e extraorçamentários.", "verification": null}'::jsonb WHERE id='1336843';
UPDATE questoes SET resolution='{"what_it_tests": "Apurar o superávit financeiro disponível como fonte para abertura de crédito especial.", "rule": "Superávit financeiro é a diferença positiva entre Ativo Financeiro e Passivo Financeiro, conforme o balanço patrimonial do exercício anterior, observadas as deduções legalmente pertinentes.", "reasoning": ["Ativo Financeiro = R$ 1.200.", "Passivo Financeiro = R$ 900.", "Superávit financeiro = 1.200 − 900 = R$ 300.", "O saldo não utilizado do crédito especial informado não altera, por si só, o cálculo básico do superávit financeiro apresentado no enunciado."], "calculation": "Ativo Financeiro = R$ 1.200.", "correct_answer": "D — R$ 300,00.", "why_wrong": "A usa a diferença entre ativo total e passivo total. B soma valores sem fundamento. C usa apenas a diferença entre ativo total e passivo financeiro.", "basis": "Lei nº 4.320/1964, art. 43, § 1º, I, e § 2º.", "fafipa_trap": "Não confundir superávit financeiro com patrimônio líquido ou com o resultado patrimonial.", "verification": null}'::jsonb WHERE id='1054734';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular o resultado da execução orçamentária confrontando receitas realizadas e despesas empenhadas.", "rule": "Resultado = receitas orçamentárias realizadas − despesas orçamentárias empenhadas.", "reasoning": ["Receitas = 488.800 + 133.300 + 22.200 + 444.300 = R$ 1.088.600.", "Despesas = 210.110 + 32.320 + 27.990 + 279.620 + 101.100 = R$ 651.140.", "Resultado matemático = 1.088.600 − 651.140 = R$ 437.460.", "O gabarito registrado é D (R$ 437.560), diferença de R$ 100 em relação aos valores extraídos."], "calculation": "Receitas = 488.800 + 133.300 + 22.200 + 444.300 = R$ 1.088.600.", "correct_answer": "D — R$ 437.560,00 (gabarito registrado), porém há inconsistência de R$ 100 com a soma dos números apresentados no texto extraído.", "why_wrong": "A, B e C não correspondem ao confronto integral das receitas e despesas.", "basis": "Confronto de receitas realizadas e despesas empenhadas no Balanço Orçamentário.", "fafipa_trap": "Antes de aceitar o gabarito, refazer a soma de cada grupo. Aqui a aritmética do texto extraído não reproduz o valor oficial registrado.", "verification": "Verificar no PDF/questão original antes de considerar o gabarito definitivo."}'::jsonb WHERE id='825570';
UPDATE questoes SET resolution='{"what_it_tests": "Determinar o resultado orçamentário a partir da receita arrecadada e da despesa empenhada.", "rule": "Para o resultado da execução orçamentária, confrontam-se receitas realizadas com despesas empenhadas.", "reasoning": ["Receita realizada/arrecadada = R$ 90.000.", "Despesa empenhada = R$ 110.000.", "Resultado = 90.000 − 110.000 = −R$ 20.000.", "Portanto, há déficit orçamentário de R$ 20.000."], "calculation": "Receita realizada/arrecadada = R$ 90.000.", "correct_answer": "C — Deficitário em R$ 20.000,00.", "why_wrong": "A usa diferença de R$ 10 mil, provavelmente confundindo com outra coluna. B e D indicam superávit, incompatível com receita menor que despesa empenhada.", "basis": "Balanço Orçamentário e confronto entre receita realizada e despesa empenhada.", "fafipa_trap": "Não usar a despesa paga de R$ 80 mil para calcular o resultado da execução orçamentária.", "verification": null}'::jsonb WHERE id='1054724';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular o resultado orçamentário usando receitas arrecadadas e despesas empenhadas.", "rule": "Resultado orçamentário = receitas realizadas − despesas empenhadas. Ingressos extraorçamentários não integram a receita orçamentária.", "reasoning": ["Receita arrecadada = R$ 185.000.", "Despesa empenhada = R$ 145.000.", "Resultado = 185.000 − 145.000 = R$ 40.000.", "Logo, o resultado é superavitário em R$ 40.000."], "calculation": "Receita arrecadada = R$ 185.000.", "correct_answer": "B — Superavitário em R$ 40.000,00.", "why_wrong": "A e C apresentam déficit; D usa valor que não resulta do confronto correto. O depósito de terceiros de R$ 25 mil é extraorçamentário e não entra no resultado.", "basis": "Lei nº 4.320/1964 e estrutura do Balanço Orçamentário.", "fafipa_trap": "Depósitos de terceiros não são receitas orçamentárias.", "verification": null}'::jsonb WHERE id='1054728';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar o crédito adicional aplicável a despesas urgentes e imprevisíveis decorrentes de calamidade pública.", "rule": "Crédito extraordinário atende despesas urgentes e imprevisíveis em situações como guerra, comoção interna ou calamidade pública.", "reasoning": ["O enunciado descreve calamidade pública.", "As despesas são urgentes e imprevisíveis.", "Isso corresponde ao crédito extraordinário."], "calculation": "", "correct_answer": "C — Crédito Extraordinário.", "why_wrong": "A é suplementar, para reforço de dotação. D é especial, para despesa sem dotação específica. B não é espécie legal de crédito adicional.", "basis": "Lei nº 4.320/1964, art. 41, III.", "fafipa_trap": "A palavra “calamidade” é a pista central para extraordinário quando associada a despesa urgente e imprevisível.", "verification": null}'::jsonb WHERE id='563456';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar a afirmação correta sobre créditos suplementares e especiais.", "rule": "Suplementares reforçam dotação e são autorizados por lei e abertos por decreto executivo; suplementares e especiais dependem de recursos disponíveis e justificativa.", "reasoning": ["A está correta quanto à finalidade e à abertura, conforme a Lei 4.320/1964.", "B descreve crédito extraordinário, não especial.", "C descreve especial, não extraordinário.", "D contraria o art. 43, que exige recursos disponíveis e justificativa."], "calculation": "", "correct_answer": "A — Os créditos suplementares são destinados a reforço de dotação orçamentária, são autorizados por lei e abertos por decreto executivo.", "why_wrong": "B e C trocam as finalidades das espécies. D ignora os requisitos de recursos disponíveis e exposição justificativa.", "basis": "Lei nº 4.320/1964, arts. 41–43.", "fafipa_trap": "Memorizar a tríade: suplementar = reforça; especial = cria dotação específica; extraordinário = urgente/imprevisível.", "verification": null}'::jsonb WHERE id='938403';
UPDATE questoes SET resolution='{"what_it_tests": "Relacionar cada espécie de crédito adicional à sua finalidade.", "rule": "Extraordinário = urgente e imprevisível; especial = sem dotação específica; suplementar = reforço de dotação.", "reasoning": ["I = Suplementares.", "II = Especiais.", "III = Extraordinários.", "As três descrições aparecem na ordem III, II, I: primeiro extraordinários, depois especiais, depois suplementares."], "calculation": "I = Suplementares.", "correct_answer": "D — III, II, I.", "why_wrong": "As demais sequências trocam pelo menos uma espécie de crédito.", "basis": "Lei nº 4.320/1964, art. 41.", "fafipa_trap": "Resolver primeiro cada definição isoladamente e só depois montar a sequência.", "verification": null}'::jsonb WHERE id='3013708';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar a demonstração contábil descrita no enunciado.", "rule": "O Balanço Orçamentário evidencia receitas e despesas previstas em confronto com as realizadas, detalhando execução e saldos.", "reasoning": ["A é DVP.", "B é Balanço Patrimonial.", "C é Balanço Financeiro.", "D corresponde exatamente ao Balanço Orçamentário."], "calculation": "", "correct_answer": "D — Balanço Orçamentário.", "why_wrong": "As demais demonstrações têm objetos diferentes.", "basis": "Lei nº 4.320/1964, art. 102, e estrutura do MCASP.", "fafipa_trap": "O detalhamento por previsão, dotação, empenho, liquidação e pagamento caracteriza o BO.", "verification": null}'::jsonb WHERE id='938382';
UPDATE questoes SET resolution='{"what_it_tests": "Julgar a afirmação sobre créditos suplementares.", "rule": "Crédito suplementar é destinado a reforço de dotação; despesas urgentes e imprevisíveis em calamidade correspondem a crédito extraordinário.", "reasoning": ["A frase diz que suplementar atende despesas urgentes e imprevisíveis.", "Essa finalidade pertence ao extraordinário.", "Portanto, a afirmação é falsa."], "calculation": "", "correct_answer": "E — Errado.", "why_wrong": "Não há alternativa C/E textual no enunciado, mas o gabarito registrado como E corresponde a “Errado” no formato Certo/Errado do caderno.", "basis": "Lei nº 4.320/1964, art. 41.", "fafipa_trap": "Suplementar não significa urgente; significa reforço de uma dotação já existente.", "verification": null}'::jsonb WHERE id='3133093';
UPDATE questoes SET resolution='{"what_it_tests": "Julgar a afirmação sobre créditos extraordinários.", "rule": "Crédito extraordinário é para despesas urgentes e imprevisíveis; reforço de dotação é finalidade do suplementar.", "reasoning": ["A frase atribui ao extraordinário a finalidade de reforço de dotação.", "Isso descreve crédito suplementar.", "Logo, a afirmação é falsa."], "calculation": "", "correct_answer": "E — Errado.", "why_wrong": "O gabarito registrado E corresponde ao julgamento “Errado”.", "basis": "Lei nº 4.320/1964, art. 41.", "fafipa_trap": "Inverter suplementar e extraordinário é uma pegadinha recorrente.", "verification": null}'::jsonb WHERE id='3133099';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular o resultado da execução orçamentária da Prefeitura Velho Oeste.", "rule": "Resultado da execução = receitas realizadas − despesas empenhadas.", "reasoning": ["Receitas realizadas = R$ 950.200.", "Despesas empenhadas = R$ 807.400.", "Resultado = 950.200 − 807.400 = R$ 142.800.", "O resultado é superavitário."], "calculation": "Receitas realizadas = R$ 950.200.", "correct_answer": "D — R$ 142.800,00.", "why_wrong": "A, B e C não correspondem ao confronto total entre receitas realizadas e despesas empenhadas. E representa resultado negativo, contrário aos dados.", "basis": "Balanço Orçamentário e dados apresentados no enunciado.", "fafipa_trap": "Não usar o saldo da dotação de R$ 67.600 como resultado da execução; esse é outro indicador.", "verification": null}'::jsonb WHERE id='953131';
UPDATE questoes SET resolution='{"what_it_tests": "Julgar as quatro afirmativas sobre LRF e créditos adicionais.", "rule": "I é compatível com o art. 5º da LRF; II reproduz a definição legal de créditos adicionais; III troca as espécies de créditos; IV reproduz o requisito do art. 43 para suplementares e especiais.", "reasoning": ["I = verdadeira.", "II = verdadeira.", "III = falsa: suplementar reforça; especial atende despesa sem dotação específica; extraordinário atende urgentes/imprevisíveis.", "IV = verdadeira.", "Logo, apenas III é falsa."], "calculation": "I = verdadeira.", "correct_answer": "B — Apenas a afirmativa III é falsa.", "why_wrong": "A considera III verdadeira. C considera todas falsas. D afirma que I e III são verdadeiras, mas III é falsa.", "basis": "Lei Complementar nº 101/2000, art. 5º, e Lei nº 4.320/1964, arts. 41 e 43.", "fafipa_trap": "Separar a análise da LRF (I) da classificação da Lei 4.320 (III) e do requisito de recursos (IV).", "verification": null}'::jsonb WHERE id='923128';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar a alternativa incorreta sobre recursos para abertura de créditos suplementares e especiais.", "rule": "Art. 43, §1º, da Lei 4.320/1964: são recursos, entre outros, superávit financeiro, excesso de arrecadação e anulação de dotações/créditos autorizados em lei.", "reasoning": ["A está correta: exige recursos disponíveis e exposição justificativa.", "B corresponde ao superávit financeiro, fonte de recursos.", "C não descreve recurso: descreve a finalidade do crédito extraordinário.", "D corresponde ao excesso de arrecadação.", "E corresponde à anulação parcial ou total de dotações ou créditos adicionais."], "calculation": "", "correct_answer": "C — Os recursos destinados a despesas urgentes e imprevistas...", "why_wrong": "A, B, D e E correspondem às regras/fontes de recursos previstas na Lei 4.320/1964.", "basis": "Lei nº 4.320/1964, arts. 42 e 43.", "fafipa_trap": "Não confundir “fonte de recursos” com “finalidade do crédito extraordinário”.", "verification": null}'::jsonb WHERE id='942404';
UPDATE questoes SET resolution='{"what_it_tests": "Classificar o depósito de caução recebido como garantia contratual.", "rule": "Ingressos extraorçamentários são recursos de terceiros que ingressam no caixa do ente sem representar receita orçamentária própria. A caução contratual a ser devolvida ao fornecedor não constitui receita do Município.", "reasoning": ["A caução é recebida apenas como garantia da execução do contrato.", "O Município deverá devolvê-la ao término da obrigação, corrigida conforme o caso.", "Como não representa recurso definitivamente incorporado ao patrimônio público como receita, o ingresso é extraorçamentário."], "calculation": "Não há cálculo.", "correct_answer": "C — receita extraorçamentária.", "why_wrong": "A e D tratariam o ingresso como receita corrente, o que não ocorre com caução de terceiros. B também é incorreta porque não se trata de transferência de capital.", "basis": "Lei nº 4.320/1964; conceito de ingressos extraorçamentários e tratamento de depósitos/cauções de terceiros no MCASP.", "fafipa_trap": "Confundir “dinheiro entrou no caixa” com “receita orçamentária”. Nem todo ingresso financeiro é receita.", "verification": null}'::jsonb WHERE id='3460652';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular Restos a Pagar Processados e Não Processados a partir dos estágios da despesa.", "rule": "Despesa empenhada e não paga pode ser inscrita em Restos a Pagar. A parcela liquidada e não paga é processada; a parcela empenhada ainda não liquidada é não processada.", "reasoning": ["Empenhado: R$ 4.500.000.", "Liquidado: R$ 3.800.000.", "Pago: R$ 2.500.000.", "RPP = 3.800.000 − 2.500.000 = R$ 1.300.000.", "RPNP = 4.500.000 − 3.800.000 = R$ 700.000.", "Total de RP = 1.300.000 + 700.000 = R$ 2.000.000."], "calculation": "RPP = R$ 1.300.000; RPNP = R$ 700.000; total = R$ 2.000.000.", "correct_answer": "D — R$ 2.000.000, sendo R$ 1.300.000 processados e R$ 700.000 não processados.", "why_wrong": "A, B e C apresentam classificação ou valores incompatíveis com a diferença entre empenho, liquidação e pagamento.", "basis": "Lei nº 4.320/1964, art. 36; MCASP, tratamento dos Restos a Pagar.", "fafipa_trap": "Não calcular RPNP como empenhado menos pago: primeiro separam-se as despesas liquidadas das ainda não liquidadas.", "verification": null}'::jsonb WHERE id='3598379';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular Restos a Pagar Não Processados.", "rule": "RPNP corresponde à despesa empenhada, mas ainda não liquidada, ao final do exercício.", "reasoning": ["Despesas empenhadas = R$ 1.020.000.", "Despesas liquidadas = R$ 960.000.", "Diferença = 1.020.000 − 960.000 = R$ 60.000.", "O fato de haver R$ 910.000 pagos não altera o cálculo específico do RPNP."], "calculation": "RPNP = R$ 60.000.", "correct_answer": "C — R$ 60.000,00.", "why_wrong": "A, B e D não correspondem à diferença entre empenho e liquidação.", "basis": "Lei nº 4.320/1964, art. 36; MCASP.", "fafipa_trap": "Para RPNP, use empenhado − liquidado; para RPP, use liquidado − pago.", "verification": null}'::jsonb WHERE id='3599132';
UPDATE questoes SET resolution='{"what_it_tests": "Distinguir Restos a Pagar Processados, Não Processados a Liquidar e Não Processados em Liquidação.", "rule": "Despesa liquidada e não paga = RPP. Despesa empenhada ainda sem liquidação = RPNP. Quando o fato gerador da obrigação já ocorreu, mas a liquidação ainda está em análise, caracteriza-se RPNP em liquidação conforme o tratamento aplicável.", "reasoning": ["Situação 1: os uniformes foram recebidos e conferidos; a obrigação foi liquidada, faltando pagar → RPP.", "Situação 2: serviço parcialmente executado, com medições apresentadas e liquidação ainda em análise → RPNP em liquidação.", "Situação 3: medicamentos ainda não foram entregues → RPNP a liquidar.", "A sequência corresponde à alternativa B."], "calculation": "Não há cálculo.", "correct_answer": "B — Situação 1 RPP; Situação 2 RPNP em liquidação; Situação 3 RPNP a liquidar.", "why_wrong": "As demais alternativas trocam a situação de despesas já liquidadas, em liquidação ou ainda sem ocorrência do fato gerador.", "basis": "MCASP, tratamento de Restos a Pagar e estágios da despesa.", "fafipa_trap": "“Empenhado” não significa automaticamente “processado”. O ponto decisivo é o estágio da liquidação.", "verification": null}'::jsonb WHERE id='3930710';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular RPNP e RPP considerando despesa empenhada, liquidada, paga e empenhos cancelados.", "rule": "RPNP = empenhos válidos não liquidados; RPP = despesas liquidadas não pagas. Empenhos cancelados não permanecem como obrigação a inscrever.", "reasoning": ["Despesa empenhada no exercício = R$ 165.000.", "Empenhos cancelados = R$ 3.750 → empenho válido = R$ 161.250.", "Despesa liquidada = R$ 143.750.", "RPNP = 161.250 − 143.750 = R$ 17.500.", "Despesa paga = R$ 141.250.", "RPP = 143.750 − 141.250 = R$ 2.500.", "ARO e depósito caução não alteram esse cálculo dos restos a pagar."], "calculation": "RPNP = R$ 17.500; RPP = R$ 2.500.", "correct_answer": "D — R$ 17.500,00 e R$ 2.500,00.", "why_wrong": "As demais combinações não descontam corretamente os empenhos cancelados ou confundem a parcela liquidada com a não liquidada.", "basis": "Lei nº 4.320/1964, art. 36; MCASP.", "fafipa_trap": "Não incluir caução de fornecedor nem ARO como se fossem despesas empenhadas do exercício.", "verification": null}'::jsonb WHERE id='4003282';
UPDATE questoes SET resolution='{"what_it_tests": "Memorizar o período usado para apuração da Receita Corrente Líquida.", "rule": "A LRF, art. 2º, §3º, determina a soma das receitas arrecadadas no mês de referência e nos onze anteriores, excluídas as duplicidades.", "reasoning": ["Mês de referência = 1 mês.", "Somam-se os onze meses anteriores.", "Total considerado = 12 meses."], "calculation": "1 mês de referência + 11 anteriores = 12 meses.", "correct_answer": "D — Onze.", "why_wrong": "A, B, C e E apresentam quantidade de meses diferente da literalidade do art. 2º, §3º, da LRF.", "basis": "Lei Complementar nº 101/2000, art. 2º, §3º.", "fafipa_trap": "A redação pergunta “nos ___ anteriores”: a resposta é 11, não 12, porque o mês de referência já está incluído separadamente.", "verification": null}'::jsonb WHERE id='3995682';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar conceitos constitucionais do PPA, LDO e LOA.", "rule": "O PPA estabelece diretrizes, objetivos e metas regionalizadas para despesas de capital e programas continuados. A CF também prevê que nenhum investimento cuja execução ultrapasse um exercício pode ser iniciado sem inclusão no PPA ou lei que autorize essa inclusão.", "reasoning": ["A é falsa: a LOA compreende orçamento fiscal, de investimento das empresas e da seguridade social, não “orçamento programa”.", "B é falsa: alterações na legislação tributária são matéria da LDO, não uma exigência de conteúdo da LOA como formulada.", "C é compatível com o art. 167, §1º, da Constituição.", "D também reproduz o conceito constitucional do PPA.", "E é falsa: o PPA tem vigência de quatro anos, mas não coincide simplesmente com o mandato; começa no segundo ano do mandato e termina no primeiro ano do mandato seguinte."], "calculation": "Não há cálculo.", "correct_answer": "D — o PPA estabelece diretrizes, objetivos e metas da Administração Pública de forma regionalizada.", "why_wrong": "A, B e E contêm erros conceituais. A questão traz C e D como afirmações compatíveis com o texto constitucional; considerando o gabarito registrado, a resposta esperada é D.", "basis": "Constituição Federal, arts. 165 e 167, §1º.", "fafipa_trap": "Cuidado com a duração do PPA: quatro anos, mas atravessando dois mandatos.", "verification": "Há duas alternativas com redação compatível com dispositivos constitucionais (C e D). O gabarito registrado é D; conferir a fonte original para verificar se houve diferença textual ou contextual na versão integral."}'::jsonb WHERE id='2416291';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular o Resultado Patrimonial e separar VPA de VPD na DVP.", "rule": "Resultado patrimonial = VPA − VPD. VPA inclui impostos, taxas, transferências recebidas, exploração de bens/serviços e juros recebidos; VPD inclui pessoal, juros pagos, perdas, benefícios, uso de serviços/material, depreciação e transferências concedidas.", "reasoning": ["VPA = 48.000 + 360.000 + 36.000 + 1.740.000 + 330.000 + 1.450.000 = R$ 3.964.000.", "VPD = 1.760.000 + 62.000 + 30.000 + 477.000 + 220.000 + 240.000 + 120.000 + 280.000 + 144.000 = R$ 3.333.000.", "Resultado = 3.964.000 − 3.333.000 = R$ 631.000.", "Logo, I, II e III estão corretas."], "calculation": "Resultado = R$ 631.000; VPA = R$ 3.964.000; VPD = R$ 3.333.000.", "correct_answer": "A — I, II e III.", "why_wrong": "B, C e D excluem uma ou mais afirmações que são confirmadas pelos cálculos.", "basis": "MCASP/DCASP — Demonstração das Variações Patrimoniais.", "fafipa_trap": "Não confundir receita orçamentária com VPA: a DVP trabalha com variações patrimoniais, independentemente da execução orçamentária.", "verification": null}'::jsonb WHERE id='2746487';
UPDATE questoes SET resolution='{"what_it_tests": "Interpretar os componentes do Balanço Financeiro e calcular receitas/despesas e resultado financeiro.", "rule": "No Balanço Financeiro, receitas e despesas orçamentárias são apresentadas separadamente dos ingressos/dispêndios extraorçamentários, transferências e saldos em espécie. O resultado financeiro pode ser obtido pela variação do saldo em espécie entre o início e o fim do exercício, quando ambos são conhecidos.", "reasoning": ["A Receita Orçamentária, em regra, inclui receitas correntes e de capital efetivamente arrecadadas; a classificação de “ingressos de investimentos” e das transferências precisa ser observada conforme a nomenclatura da questão.", "O enunciado extraído contém classificações que não permitem reconstruir com segurança todas as parcelas usadas nas afirmações II–IV apenas pelo texto disponível.", "O gabarito registrado é C (II, III e IV), mas a afirmação I de R$ 1.820.000 não é reproduzível de forma segura com os dados textuais extraídos."], "calculation": "Não é seguro fechar todos os cálculos a partir da extração disponível.", "correct_answer": "C — II, III e IV, conforme o gabarito registrado.", "why_wrong": "A, B e D não correspondem ao gabarito registrado. A justificativa matemática completa precisa ser conferida no documento original, pois a extração pode ter perdido a estrutura das rubricas.", "basis": "MCASP — Balanço Financeiro; Lei nº 4.320/1964, art. 103.", "fafipa_trap": "Não tratar automaticamente toda entrada de caixa como receita orçamentária. A classificação no BF depende da natureza do ingresso.", "verification": "Conferir o quadro original/PDF antes de usar esta questão como modelo de cálculo."}'::jsonb WHERE id='2746485';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular resultado financeiro no Balanço Financeiro a partir dos fluxos e saldos.", "rule": "O Balanço Financeiro evidencia ingressos e dispêndios e os saldos em espécie anterior e seguinte. O resultado financeiro do exercício corresponde à variação do saldo em espécie: saldo final − saldo inicial, quando ambos estão disponíveis.", "reasoning": ["Saldo inicial = R$ 290.000, conforme a afirmação III.", "Saldo final = R$ 440.000, conforme o enunciado.", "Resultado financeiro = 440.000 − 290.000 = R$ 150.000.", "Assim, III e IV são compatíveis entre si e correspondem à alternativa D.", "As afirmações I e II dependem da classificação das rubricas orçamentárias; o gabarito registrado não as considera corretas."], "calculation": "R$ 440.000 − R$ 290.000 = R$ 150.000.", "correct_answer": "D — III e IV, apenas.", "why_wrong": "A, B, C e E incluem pelo menos uma das afirmações I ou II, que não integram o conjunto correto indicado pelo gabarito.", "basis": "MCASP — Balanço Financeiro; Lei nº 4.320/1964, art. 103.", "fafipa_trap": "Não confundir saldo final de caixa com resultado financeiro; o resultado é a variação entre os saldos inicial e final.", "verification": null}'::jsonb WHERE id='3680411';
UPDATE questoes SET resolution='{"what_it_tests": "Interpretar o Balanço Financeiro e relacionar saldo inicial, saldo final e resultado financeiro.", "rule": "Resultado financeiro do exercício = saldo em espécie para o exercício seguinte − saldo em espécie do exercício anterior.", "reasoning": ["Saldo final informado = R$ 440.000.", "O gabarito considera saldo inicial = R$ 290.000.", "Diferença = R$ 150.000.", "Portanto III e IV são as afirmações corretas no conjunto apresentado."], "calculation": "R$ 440.000 − R$ 290.000 = R$ 150.000.", "correct_answer": "D — III e IV, apenas.", "why_wrong": "A, B, C e E incluem I ou II, que não compõem o conjunto indicado pelo gabarito.", "basis": "MCASP — Balanço Financeiro; Lei nº 4.320/1964, art. 103.", "fafipa_trap": "A questão pode induzir ao cálculo de todas as rubricas; primeiro identifique que o resultado financeiro pode ser obtido diretamente pela variação dos saldos em espécie.", "verification": "A afirmação do saldo inicial (R$ 290.000) não aparece claramente entre os dados transcritos; confirmar no original."}'::jsonb WHERE id='3998522';
UPDATE questoes SET resolution='{"what_it_tests": "Diferenciar LDO, PPA e LOA.", "rule": "LDO estabelece metas e prioridades e orienta a LOA; PPA organiza diretrizes, objetivos e metas de programas de duração continuada e despesas de capital; LOA estima receitas e fixa despesas.", "reasoning": ["I descreve a LDO.", "II descreve o PPA.", "III descreve a LOA.", "A sequência correta é LDO – PPA – LOA."], "calculation": "Não há cálculo.", "correct_answer": "E — I: LDO; II: PPA; III: LOA.", "why_wrong": "A, B, C e D trocam as funções dos instrumentos de planejamento.", "basis": "Constituição Federal, art. 165.", "fafipa_trap": "Memorize a lógica: PPA = planejamento plurianual; LDO = ponte/orientação; LOA = execução anual.", "verification": null}'::jsonb WHERE id='2153560';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar prazos constitucionais de encaminhamento e devolução dos projetos de PPA, LDO e LOA.", "rule": "ADCT, art. 35, §2º: PPA e LOA têm prazo de envio de quatro meses antes do encerramento do primeiro exercício financeiro e devolução até o encerramento da sessão legislativa; LDO é enviada até oito meses e meio antes e devolvida até o encerramento do primeiro período da sessão legislativa.", "reasoning": ["I é falsa: a afirmação sobre erradicação da desigualdade inter-regional em 10 anos não corresponde ao texto constitucional aplicável.", "II é verdadeira: prazo do PPA.", "III é verdadeira: prazo da LDO.", "IV é verdadeira: prazo da LOA.", "Logo, II, III e IV estão corretas."], "calculation": "Não há cálculo.", "correct_answer": "C — II, III e IV, apenas.", "why_wrong": "A, B e D incluem a assertiva I; E exclui a assertiva III, que está correta.", "basis": "Constituição Federal/ADCT, art. 35, §2º.", "fafipa_trap": "Os prazos da LDO são diferentes dos prazos de PPA e LOA: 8 meses e meio para envio e primeiro período da sessão legislativa para devolução.", "verification": null}'::jsonb WHERE id='2415465';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular o Resultado Patrimonial da DVP.", "rule": "Resultado patrimonial = VPA − VPD. Transferências intergovernamentais recebidas e prestação de serviços são VPA; pessoal e material de consumo são VPD.", "reasoning": ["VPA = 1.380.000 + 2.250.000 = R$ 3.630.000.", "VPD = 890.400 + 360.000 = R$ 1.250.400.", "Resultado = 3.630.000 − 1.250.400 = R$ 2.379.600."], "calculation": "R$ 3.630.000 − R$ 1.250.400 = R$ 2.379.600.", "correct_answer": "B — R$ 2.379.600,00.", "why_wrong": "A, C, D e E resultam de somas ou diferenças incorretas entre VPA e VPD.", "basis": "MCASP/DCASP — Demonstração das Variações Patrimoniais.", "fafipa_trap": "Não subtrair cada despesa da receita isoladamente; primeiro separe VPA e VPD e depois faça o confronto.", "verification": null}'::jsonb WHERE id='2153505';
COMMIT;
